contracts/PrivateAirdrop.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZkIdentity {
    function registerScope(uint256 scope) external;
    function verify(uint256 root, uint256 nullifier, uint256 scope, uint256 signalHash, uint256 minLevel, uint256[8] calldata proof)
        external view returns (bool);
}

/// @title PrivateAirdrop: one claim per person, to an address that is not linked to the person (testnet)
/// @notice docs/future/zk-identity.md. Pays `amount` (native coin) once per nullifier of `scope` to the recipient the
///   proof is bound to. The signal is keccak256(recipient, fee) >> 8, so whoever submits the transaction (the person
///   from a fresh address, or any relayer who is paid `fee`) cannot change where the coins go.
///   Uniqueness is the registry's: one claim per registered identity of level >= minLevel.
contract PrivateAirdrop {
    IZkIdentity public immutable registry;
    uint256 public immutable scope;
    uint256 public immutable minLevel;
    uint256 public immutable amount;
    mapping(uint256 => bool) public nullifierUsed;
    uint256 public claims;

    event Claimed(uint256 indexed nullifier, address indexed recipient, address relayer, uint256 fee);
    event Funded(address from, uint256 value);

    error AlreadyClaimed();
    error BadProof();
    error BadFee();
    error Empty();
    error PayFailed();

    constructor(IZkIdentity registry_, uint256 scope_, uint256 minLevel_, uint256 amount_) payable {
        registry = registry_;
        scope = scope_;
        minLevel = minLevel_;
        amount = amount_;
        registry_.registerScope(scope_);
    }

    receive() external payable {
        emit Funded(msg.sender, msg.value);
    }

    /// The signal a claim's proof must carry.
    function signalOf(address recipient, uint256 fee) public pure returns (uint256) {
        return uint256(keccak256(abi.encode(recipient, fee))) >> 8;
    }

    function claim(address recipient, uint256 fee, uint256 root, uint256 nullifier, uint256[8] calldata proof) external {
        if (nullifierUsed[nullifier]) revert AlreadyClaimed();
        if (fee > amount) revert BadFee();
        if (address(this).balance < amount) revert Empty();
        if (!registry.verify(root, nullifier, scope, signalOf(recipient, fee), minLevel, proof)) revert BadProof();
        nullifierUsed[nullifier] = true;
        claims++;
        emit Claimed(nullifier, recipient, msg.sender, fee);
        (bool ok, ) = recipient.call{value: amount - fee}("");
        if (!ok) revert PayFailed();
        if (fee != 0) {
            (ok, ) = msg.sender.call{value: fee}("");
            if (!ok) revert PayFailed();
        }
    }
}

contracts/PrivatePoll.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZkIdentityPoll {
    function registerScope(uint256 scope) external;
    function verify(uint256 root, uint256 nullifier, uint256 scope, uint256 signalHash, uint256 minLevel, uint256[8] calldata proof)
        external view returns (bool);
}

/// @title PrivatePoll: one anonymous vote per person per poll (testnet)
/// @notice docs/future/zk-identity.md. Each poll is a scope of ZkIdentityRegistry (chosen by its creator, unique in the
///   registry). A vote carries a proof bound to (scope, option), so a relayer cannot change the choice; the nullifier
///   refuses a second vote by the same identity, and is unrelated to the same person's nullifiers in other polls.
///   Tallies are public as votes come in (no hiding of partial results; see the doc for commit-reveal / MACI).
contract PrivatePoll {
    IZkIdentityPoll public immutable registry;

    struct Poll {
        address creator;
        uint8 options;
        uint8 minLevel;
        uint64 endsAt;
        bytes32 question; // hash of the question text (kept off chain)
    }

    mapping(uint256 => Poll) public polls;
    mapping(uint256 => mapping(uint256 => uint256)) public tally;   // scope => option => votes
    mapping(uint256 => mapping(uint256 => bool)) public nullifierUsed; // scope => nullifier => voted

    event PollCreated(uint256 indexed scope, address indexed creator, bytes32 question, uint8 options, uint8 minLevel, uint64 endsAt);
    event Voted(uint256 indexed scope, uint256 indexed nullifier, uint8 option);

    error BadPoll();
    error NoPoll();
    error Ended();
    error BadOption();
    error AlreadyVoted();
    error BadProof();

    constructor(IZkIdentityPoll registry_) {
        registry = registry_;
    }

    function createPoll(uint256 scope, bytes32 question, uint8 options, uint8 minLevel, uint64 endsAt) external {
        if (options < 2 || minLevel == 0 || endsAt <= block.timestamp) revert BadPoll();
        registry.registerScope(scope); // reverts if the scope is taken
        polls[scope] = Poll({creator: msg.sender, options: options, minLevel: minLevel, endsAt: endsAt, question: question});
        emit PollCreated(scope, msg.sender, question, options, minLevel, endsAt);
    }

    function signalOf(uint256 scope, uint8 option) public pure returns (uint256) {
        return uint256(keccak256(abi.encode(scope, option))) >> 8;
    }

    function vote(uint256 scope, uint8 option, uint256 root, uint256 nullifier, uint256[8] calldata proof) external {
        Poll storage p = polls[scope];
        if (p.creator == address(0)) revert NoPoll();
        if (block.timestamp > p.endsAt) revert Ended();
        if (option >= p.options) revert BadOption();
        if (nullifierUsed[scope][nullifier]) revert AlreadyVoted();
        if (!registry.verify(root, nullifier, scope, signalOf(scope, option), p.minLevel, proof)) revert BadProof();
        nullifierUsed[scope][nullifier] = true;
        tally[scope][option]++;
        emit Voted(scope, nullifier, option);
    }
}

contracts/ProvenVerdicts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The model-bound Groth16 verifier (contracts/NeuroScoreVerifier.sol, generated from the zk ceremony; not edited here).
interface IModelProofVerifier {
    function MODEL_HASH() external view returns (bytes32);
    function verifyModelProof(uint256[2] calldata a, uint256[2][2] calldata b, uint256[2] calldata c, uint256 commitment, uint256 margin)
        external view returns (bool);
}

/// What ProvenVerdicts reads from NeuroScore (contracts/NeuroScore.sol): the pinned model and its evaluator.
interface IPinnedScorer {
    struct Model {
        bytes32 hash;
        bytes32 modelId;
        uint16 nFeatures;
        int64 low;
        int64 medium;
        int64 high;
        uint64 activatedAt;
    }
    function model(uint32 v) external view returns (Model memory);
    function modelBytes(bytes32 hash) external view returns (bytes memory);
    function evaluateAt(uint32 v, bytes calldata features) external view returns (int256 score, uint8 level);
}

/// What ProvenVerdicts reads from NeuroJobs (contracts/NeuroJobs.sol): a settled k-of-n verdict on a feature job.
interface IFeatureJobs {
    function getJob(uint256 id) external view returns (address requester, uint64 created, uint8 status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat);
    function assurance(uint256 id) external view returns (uint8 agreedBy, uint8 state, uint64 challengeUntil, bool settled);
}

/// @title ProvenVerdicts: Neuro risk verdicts that come with a zero-knowledge proof of the model run
/// @notice docs/future/proven-verdicts.md. A bonded runner posts, for a token:
///           - the token's feature vector (`features`, 133 x u32, the profile "zfeat/1": every value is a pure
///             function of the token's runtime bytecode, zetaphy-network/src/zkverdict/features.js), and
///           - a Groth16 proof (the existing circuit, zetaphy-neuro/ml/onchain/zk/) that a committed vector yields
///             margin Z under the pinned model H. The verifier supplies H itself (verifyModelProof).
///         The score is computed HERE from the proven margin (score = trunc(calibA * Z / scale) + calibB, the
///         pinned model's calibration), so a runner cannot state another score than the one proven.
///
///         What binds the proof to the posted features and the features to the token (all permissionless):
///           1. the token's code hash (EXTCODEHASH) is recorded when the verdict lands;
///           2. challengeScore(id, features): anyone re-runs the pinned model on the posted features on-chain
///              (NeuroScore.evaluateAt). A different score means the proof was made for other features than the
///              posted ones (or, for an unproven claim, that the claim is wrong): the runner is slashed, the verdict
///              overturned. No trust in anything but the model bytes;
///           3. contest(id) + resolveContest(id, jobId): the posted features are not the token's. Anyone recomputes
///              zfeat/1 from the code with that hash; the dispute is settled by a NeuroJobs k-of-n job on chain
///              "zetaphy" with target featureTarget(id) ("zfeat/1:<token>:<codehash>"), whose verdict is
///              keccak256(the packed features). A settled result different from the posted hash slashes the runner.
///         Proof mode (governance): Optional = unproven claims are accepted with a lower weight; Required = they
///         are refused and old ones read as unknown. A verifier for another model is refused at construction:
///         a new model is a new circuit, a new ceremony, a new verifier and a new ProvenVerdicts.
///         Testnet: until the public phase-2 ceremony is final, the verifier comes from a one-machine rehearsal,
///         whose operator could forge proofs. Score = a statistical estimate, never a finding about a project.
contract ProvenVerdicts {
    enum ProofMode { Optional, Required }
    enum Status { None, Live, Contested, Overturned }

    struct Verdict {
        address token;
        uint64 time;
        uint8 level;      // 0 none, 1 low, 2 medium, 3 high (the pinned model's thresholds)
        bool proven;
        Status status;
        address runner;
        int64 score;      // calibrated logit x 1e7 (p = sigmoid(score / 1e7)), as NeuroScore
        bytes32 featuresHash; // keccak256 of the posted features (packed u32 big-endian)
        bytes32 codeHash;     // EXTCODEHASH of the token when the verdict landed
        bytes32 proofHash;    // keccak256(abi.encode(a, b, c, commitment, margin)); 0 for a claim
    }

    struct Contest {
        address challenger;
        uint64 openedAt;
        uint128 bond;
    }

    struct Runner {
        uint128 bond;
        uint64 unbondAt;  // 0 while active
        uint64 heldUntil; // the bond stays until every verdict it posted is out of its challenge window
        uint32 contested; // open contests on its verdicts (the bond stays while > 0)
        bool active;
    }

    /// One proven verdict (submit / submitBatch).
    struct Proof {
        address token;
        bytes32 modelId;  // must be the pinned model's id
        bytes features;
        uint256[2] a;
        uint256[2][2] b;
        uint256[2] c;
        uint256 commitment;
        uint256 margin;   // Z + 2^40 (the circuit's public output)
    }

    uint16 public constant PROVEN_WEIGHT = 3;
    uint16 public constant CLAIM_WEIGHT = 1;
    /// Share of a runner's bond lost when a verdict of theirs is overturned; half to the challenger, half burned.
    uint16 public constant SLASH_BPS = 5000;
    /// Share of the contest bond the challenger gets back when its contest times out without a settled job.
    uint16 public constant EXPIRE_REFUND_BPS = 8000;
    uint256 public constant MARGIN_OFFSET = 1 << 40;
    bytes32 public constant FEATURE_CHAIN = "zetaphy";
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;

    address public immutable governance;
    IModelProofVerifier public immutable verifier;
    IPinnedScorer public immutable scorer;
    IFeatureJobs public immutable jobs;
    uint32 public immutable scorerVersion;
    bytes32 public immutable modelHash;
    bytes32 public immutable modelId;
    uint16 public immutable nFeatures;
    int256 public immutable scale;
    int256 public immutable calibA;
    int256 public immutable calibB;
    int64 public immutable levelLow;
    int64 public immutable levelMedium;
    int64 public immutable levelHigh;
    uint256 public immutable runnerBond;
    uint256 public immutable contestBond;
    uint64 public immutable challengeWindow;
    uint64 public immutable contestTimeout;
    uint64 public immutable unbondDelay;

    ProofMode public proofMode;
    Verdict[] private _verdicts;
    mapping(uint256 => Contest) public contests;
    mapping(address => uint256) public latestOf; // token -> newest verdict id + 1 (0 = none)
    mapping(bytes32 => bool) public proofUsed;   // keccak256(token, proofHash)
    mapping(address => Runner) public runners;
    mapping(address => uint256) public credit;

    event ProofModeSet(ProofMode mode);
    event Registered(address indexed runner, uint256 bond);
    event UnbondRequested(address indexed runner, uint64 at);
    event Proven(uint256 indexed id, address indexed token, address indexed runner, int64 score, uint8 level, bytes32 featuresHash, bytes32 codeHash);
    /// The proof and the features of verdict `id` (what a browser re-verifies: zetaphy-hub/zkverdict-core.js).
    event ProofData(uint256 indexed id, address indexed token, uint256[2] a, uint256[2][2] b, uint256[2] c, uint256 commitment, uint256 margin, bytes features);
    event Claimed(uint256 indexed id, address indexed token, address indexed runner, int64 score, uint8 level, bytes32 featuresHash,
        bytes32 codeHash, bytes features);
    event Overturned(uint256 indexed id, address indexed by, uint8 why, int256 trueScore, bytes32 trueFeaturesHash); // why: 1 score, 2 features
    event Slashed(address indexed runner, uint256 amount, address indexed challenger);
    event Contested(uint256 indexed id, address indexed challenger, uint256 bond);
    event ContestUpheld(uint256 indexed id, uint256 jobId);
    event ContestExpired(uint256 indexed id);

    error NotGovernance();
    error ModelMismatch();
    error BadValue();
    error NotRunner();
    error WrongModel(bytes32 modelId);
    error BadFeatures();
    error NoCode(address token);
    error InvalidProof(uint256 index);
    error ProofUsed(uint256 index);
    error ProofRequired();
    error Unknown();
    error NotWrong();
    error Closed();
    error Busy();
    error NotSettled(uint256 jobId);
    error WrongJob(uint256 jobId);
    error TooEarly();
    error Nothing();

    /// @param scorer_ NeuroScore; its model `version_` must be the one `verifier_` was generated for (same hash H).
    constructor(address governance_, IModelProofVerifier verifier_, IPinnedScorer scorer_, uint32 version_, IFeatureJobs jobs_,
        uint256 runnerBond_, uint256 contestBond_, uint64 challengeWindow_, uint64 contestTimeout_, uint64 unbondDelay_) {
        if (governance_ == address(0) || runnerBond_ == 0 || contestBond_ == 0 || challengeWindow_ == 0 || contestTimeout_ == 0
            || unbondDelay_ < challengeWindow_) revert BadValue();
        IPinnedScorer.Model memory m = scorer_.model(version_);
        if (m.hash == bytes32(0) || verifier_.MODEL_HASH() != m.hash) revert ModelMismatch();
        bytes memory b = scorer_.modelBytes(m.hash);
        if (b.length < 24 || keccak256(b) != m.hash) revert ModelMismatch();
        governance = governance_;
        verifier = verifier_;
        scorer = scorer_;
        jobs = jobs_;
        scorerVersion = version_;
        modelHash = m.hash;
        modelId = m.modelId;
        nFeatures = m.nFeatures;
        levelLow = m.low;
        levelMedium = m.medium;
        levelHigh = m.high;
        // NSM1 header: scale u32 at 8, calibA i32 at 16, calibB i32 at 20 (zetaphy-neuro/ml/onchain/fixed.js)
        scale = int256(uint256(_be(b, 8, 4)));
        calibA = int256(int32(uint32(_be(b, 16, 4))));
        calibB = int256(int32(uint32(_be(b, 20, 4))));
        if (scale <= 0) revert ModelMismatch();
        runnerBond = runnerBond_;
        contestBond = contestBond_;
        challengeWindow = challengeWindow_;
        contestTimeout = contestTimeout_;
        unbondDelay = unbondDelay_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- governance ----

    function setProofMode(ProofMode mode) external onlyGov {
        proofMode = mode;
        emit ProofModeSet(mode);
    }

    // ---- runners ----

    function register() external payable {
        Runner storage r = runners[msg.sender];
        uint256 b = uint256(r.bond) + msg.value;
        if (b < runnerBond) revert BadValue();
        r.bond = uint128(b);
        r.active = true;
        r.unbondAt = 0;
        emit Registered(msg.sender, b);
    }

    function requestUnbond() external {
        Runner storage r = runners[msg.sender];
        if (!r.active) revert NotRunner();
        r.active = false;
        r.unbondAt = uint64(block.timestamp) + unbondDelay;
        emit UnbondRequested(msg.sender, r.unbondAt);
    }

    function withdrawBond() external {
        Runner storage r = runners[msg.sender];
        if (r.active || r.unbondAt == 0 || block.timestamp < r.unbondAt || block.timestamp < r.heldUntil || r.contested != 0) revert TooEarly();
        uint256 b = r.bond;
        if (b == 0) revert Nothing();
        r.bond = 0;
        _pay(msg.sender, b);
    }

    function withdraw() external {
        uint256 c = credit[msg.sender];
        if (c == 0) revert Nothing();
        credit[msg.sender] = 0;
        _pay(msg.sender, c);
    }

    // ---- verdicts ----

    /// A proven verdict: the proof is checked by the model-bound verifier, the score is computed from its margin.
    function submit(Proof calldata p) external returns (uint256 id) {
        _runner();
        return _submit(p, 0);
    }

    /// Several proven verdicts in one transaction (one runner). Reverts as a whole if any proof is invalid.
    function submitBatch(Proof[] calldata ps) external returns (uint256 first) {
        _runner();
        if (ps.length == 0) revert BadValue();
        first = _verdicts.length;
        for (uint256 i = 0; i < ps.length; ++i) _submit(ps[i], i);
    }

    /// An unproven verdict (Optional mode only), weighted lower; challengeScore slashes a wrong one.
    function claim(address token, bytes calldata features, int64 score) external returns (uint256 id) {
        _runner();
        if (proofMode == ProofMode.Required) revert ProofRequired();
        if (features.length != uint256(nFeatures) * 4) revert BadFeatures();
        bytes32 codeHash = _codeHash(token);
        bytes32 fh = keccak256(features);
        uint8 level = _level(score);
        id = _push(Verdict(token, uint64(block.timestamp), level, false, Status.Live, msg.sender, score, fh, codeHash, bytes32(0)));
        uint256 cur = latestOf[token];
        // a claim never hides a live proven verdict for the same code
        if (cur == 0 || !_verdicts[cur - 1].proven || _verdicts[cur - 1].status != Status.Live || _verdicts[cur - 1].codeHash != codeHash) {
            latestOf[token] = id + 1;
        }
        emit Claimed(id, token, msg.sender, score, level, fh, codeHash, features);
    }

    function _submit(Proof calldata p, uint256 index) private returns (uint256 id) {
        if (p.modelId != modelId) revert WrongModel(p.modelId);
        if (p.features.length != uint256(nFeatures) * 4) revert BadFeatures();
        if (p.margin >= 2 * MARGIN_OFFSET) revert InvalidProof(index);
        if (!verifier.verifyModelProof(p.a, p.b, p.c, p.commitment, p.margin)) revert InvalidProof(index);
        bytes32 ph = keccak256(abi.encode(p.a, p.b, p.c, p.commitment, p.margin));
        bytes32 key = keccak256(abi.encode(p.token, ph));
        if (proofUsed[key]) revert ProofUsed(index);
        proofUsed[key] = true;
        bytes32 codeHash = _codeHash(p.token);
        int64 score = scoreOfMargin(p.margin);
        uint8 level = _level(score);
        bytes32 fh = keccak256(p.features);
        id = _push(Verdict(p.token, uint64(block.timestamp), level, true, Status.Live, msg.sender, score, fh, codeHash, ph));
        latestOf[p.token] = id + 1;
        emit Proven(id, p.token, msg.sender, score, level, fh, codeHash);
        _emitProof(id, p);
    }

    function _emitProof(uint256 id, Proof calldata p) private {
        emit ProofData(id, p.token, p.a, p.b, p.c, p.commitment, p.margin, p.features);
    }

    // ---- challenges ----

    /// Anyone: re-runs the pinned model on the posted features (their preimage). A different score overturns the
    /// verdict and slashes its runner. For a proven verdict this means the proof was for other features.
    function challengeScore(uint256 id, bytes calldata features) external {
        Verdict storage v = _get(id);
        if (v.status == Status.Overturned) revert Closed();
        if (keccak256(features) != v.featuresHash) revert BadFeatures();
        (int256 s,) = scorer.evaluateAt(scorerVersion, features);
        if (s == int256(v.score)) revert NotWrong();
        _overturn(id, v, msg.sender, 1, s, v.featuresHash);
    }

    /// Anyone, inside the challenge window, with `contestBond`: "the posted features are not the token's".
    /// Settled by resolveContest with a NeuroJobs feature job, or expires after contestTimeout.
    function contest(uint256 id) external payable {
        Verdict storage v = _get(id);
        if (v.status != Status.Live) revert Closed();
        if (block.timestamp >= uint256(v.time) + challengeWindow) revert Closed();
        if (msg.value != contestBond) revert BadValue();
        v.status = Status.Contested;
        contests[id] = Contest(msg.sender, uint64(block.timestamp), uint128(msg.value));
        runners[v.runner].contested += 1;
        emit Contested(id, msg.sender, msg.value);
    }

    /// Anyone: settles a contest with a settled NeuroJobs job on chain "zetaphy" whose target is featureTarget(id).
    /// Its verdict (keccak256 of the zfeat/1 features k-of-n runners computed) decides.
    function resolveContest(uint256 id, uint256 jobId) external {
        Verdict storage v = _get(id);
        if (v.status != Status.Contested) revert Closed();
        if (address(jobs) == address(0)) revert NotSettled(jobId);
        (, , , bool settled) = jobs.assurance(jobId);
        if (!settled) revert NotSettled(jobId);
        (, , uint8 status, bytes32 chain, string memory target, , bytes32 result, , , ) = jobs.getJob(jobId);
        if (status != 2 || chain != FEATURE_CHAIN || keccak256(bytes(target)) != keccak256(bytes(featureTarget(id)))) revert WrongJob(jobId);
        Contest memory c = contests[id];
        delete contests[id];
        runners[v.runner].contested -= 1;
        if (result == v.featuresHash) {
            v.status = Status.Live;
            credit[v.runner] += c.bond; // the contest was wrong: its bond goes to the runner
            emit ContestUpheld(id, jobId);
        } else {
            credit[c.challenger] += c.bond;
            v.status = Status.Live; // the contest is closed above; _overturn only slashes
            _overturn(id, v, c.challenger, 2, 0, result);
        }
    }

    /// Anyone, after contestTimeout without a settled job: the verdict stands, the challenger gets most of its bond back.
    function expireContest(uint256 id) external {
        Verdict storage v = _get(id);
        if (v.status != Status.Contested) revert Closed();
        Contest memory c = contests[id];
        if (block.timestamp < uint256(c.openedAt) + contestTimeout) revert TooEarly();
        delete contests[id];
        runners[v.runner].contested -= 1;
        v.status = Status.Live;
        uint256 back = (uint256(c.bond) * EXPIRE_REFUND_BPS) / 10_000;
        credit[c.challenger] += back;
        credit[v.runner] += c.bond - back;
        emit ContestExpired(id);
    }

    function _overturn(uint256 id, Verdict storage v, address by, uint8 why, int256 trueScore, bytes32 trueFh) private {
        if (v.status == Status.Contested) {
            // a score challenge during a contest: the contest ends, its bond goes back
            Contest memory c = contests[id];
            delete contests[id];
            runners[v.runner].contested -= 1;
            credit[c.challenger] += c.bond;
        }
        v.status = Status.Overturned;
        Runner storage r = runners[v.runner];
        uint256 cut = (uint256(r.bond) * SLASH_BPS) / 10_000;
        r.bond -= uint128(cut);
        if (r.bond < runnerBond) r.active = false;
        uint256 toChallenger = cut / 2;
        credit[by] += toChallenger;
        emit Overturned(id, by, why, trueScore, trueFh);
        emit Slashed(v.runner, cut, by);
        if (cut - toChallenger > 0) _pay(BURN, cut - toChallenger);
    }

    // ---- views ----

    /// The token's newest verdict: known (live or contested, and not an unproven claim in Required mode), score,
    /// level, proven, weight (PROVEN_WEIGHT / CLAIM_WEIGHT / 0), settled (out of its challenge window, no contest),
    /// and its id.
    function verdictOf(address token) external view returns (bool known, int64 score, uint8 level, bool proven, uint16 weight, bool settled, uint256 id) {
        uint256 k = latestOf[token];
        if (k == 0) return (false, 0, 0, false, 0, false, 0);
        id = k - 1;
        Verdict storage v = _verdicts[id];
        if (v.status == Status.Overturned) return (false, 0, 0, v.proven, 0, true, id);
        if (!v.proven && proofMode == ProofMode.Required) return (false, v.score, v.level, false, 0, false, id);
        known = true;
        score = v.score;
        level = v.level;
        proven = v.proven;
        weight = v.proven ? PROVEN_WEIGHT : CLAIM_WEIGHT;
        settled = v.status == Status.Live && block.timestamp >= uint256(v.time) + challengeWindow;
    }

    function verdict(uint256 id) external view returns (Verdict memory) {
        return _get(id);
    }

    function count() external view returns (uint256) {
        return _verdicts.length;
    }

    /// Score from a proven margin (Z + 2^40) with the pinned model's calibration (as NeuroScore._eval).
    function scoreOfMargin(uint256 margin) public view returns (int64) {
        int256 z = int256(margin) - int256(MARGIN_OFFSET);
        int256 s = (calibA * z) / scale + calibB;
        if (s > type(int64).max || s < type(int64).min) revert BadValue();
        return int64(s);
    }

    /// The NeuroJobs target that settles a contest of verdict `id`: "zfeat/1:<token>:<code hash>", lower-case hex.
    function featureTarget(uint256 id) public view returns (string memory) {
        Verdict storage v = _get(id);
        return string.concat("zfeat/1:", _hex(abi.encodePacked(v.token)), ":", _hex(abi.encodePacked(v.codeHash)));
    }

    // ---- internals ----

    function _runner() private {
        Runner storage r = runners[msg.sender];
        if (!r.active) revert NotRunner();
        uint64 until = uint64(block.timestamp) + challengeWindow;
        if (until > r.heldUntil) r.heldUntil = until;
    }

    function _push(Verdict memory v) private returns (uint256 id) {
        _verdicts.push(v);
        return _verdicts.length - 1;
    }

    function _get(uint256 id) private view returns (Verdict storage) {
        if (id >= _verdicts.length) revert Unknown();
        return _verdicts[id];
    }

    function _codeHash(address token) private view returns (bytes32 h) {
        if (token.code.length == 0) revert NoCode(token);
        h = token.codehash;
    }

    function _level(int256 s) private view returns (uint8) {
        if (s >= levelHigh) return 3;
        if (s >= levelMedium) return 2;
        if (s >= levelLow) return 1;
        return 0;
    }

    function _be(bytes memory b, uint256 off, uint256 len) private pure returns (uint256 x) {
        for (uint256 i = 0; i < len; ++i) x = (x << 8) | uint8(b[off + i]);
    }

    function _hex(bytes memory b) private pure returns (string memory) {
        bytes16 h = "0123456789abcdef";
        bytes memory out = new bytes(2 + 2 * b.length);
        out[0] = "0";
        out[1] = "x";
        for (uint256 i = 0; i < b.length; ++i) {
            out[2 + 2 * i] = h[uint8(b[i]) >> 4];
            out[3 + 2 * i] = h[uint8(b[i]) & 0x0f];
        }
        return string(out);
    }

    function _pay(address to, uint256 amount) private {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "pay failed");
    }
}

contracts/QuantumRescue.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The chain's security precompile (0x…0901, zetaphy-chain evmd/zetaphy_secprecompile.go).
interface IZetaphySecurity {
    function qday() external view returns (uint64 height, uint64 revealDelay, bool active);
    function migration(address account) external view
        returns (bool migrated, address controller, address pendingController, uint64 finalHeight, bool exposed);
}

interface IRescueERC20 {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title QuantumRescue: a pre-commitment today, a post-quantum rescue after Q-day (testnet)
/// @notice The chain's own Q-day rule (docs/SECURITY-CORE.md) freezes every secp256k1 account that is
///         neither quantum-locked nor "never used" once Q-day passes: a quantum computer could forge
///         its signatures, so the chain stops accepting them. This contract gives such accounts a way
///         out that they prepare TODAY, while their ECDSA key is still trustworthy:
///
///           1. today      commit(c) from the classical address, c = commitmentOf(address, keccak256(pqPublicKey), secret)
///                         (only a hash: nothing about the ML-DSA key or the secret is public)
///           2. after QDAY reveal(address, pqPublicKey, secret, mlDsaSignature) - anyone may relay it;
///                         the address is then "rescued" to the ML-DSA-44 account of that key
///                         (sha256("zetaphy/mldsa44\0" ‖ pk)[0:20], the chain's native PQ address)
///
///         A commitment only counts once it is `maturity` blocks old, and only if it matured before
///         Q-day: someone who breaks the key shortly before Q-day cannot displace an older commitment.
///         Q-day is the chain's (governance-set, read from 0x…0901 qday()), or this contract's own
///         governance-set height if that is earlier or the precompile does not exist (another EVM chain).
///
///         What a rescue gives today, on-chain:
///           - controllerOf(address): any contract can honour it (QDayGuard pattern, see classicalTrusted());
///           - an escrow: protocol payouts to a frozen address (airdrops, bridge releases, refunds) are
///             sent here with depositFor() and the rescued ML-DSA controller claims them;
///         and, as a governance-voted chain step (designed, docs/future/quantum-safe-settlement.md),
///         MsgQDayRescue turns a rescue into the chain's quantum lock (the whole account, its 0x address).
contract QuantumRescue {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint256 public constant PK_BYTES = 1312;   // ML-DSA-44 (native PQ accounts are ML-DSA-44)
    uint64 public constant MIN_NOTICE = 100;   // blocks, like gov.sh qday (QDAY_MIN_NOTICE)

    address public immutable security;         // 0x…0901 on ZETAPHY; anything without code elsewhere
    uint64 public immutable maturity;          // blocks before a (new) commitment counts
    address public governance;                 // a timelock
    uint64 public localQday;                   // 0 = none; the earlier of this and the chain's Q-day applies

    struct Slot {
        bytes32 active;    // the commitment in force
        bytes32 pending;   // a newer one (or 0 = cancel), in force from pendingAt + maturity
        uint64 pendingAt;  // 0 = no pending change
    }
    mapping(address => Slot) private slots;
    mapping(address => address) public controllerOf;   // rescued classical address -> ML-DSA-44 account
    mapping(address => bytes32) public rescueKeyHash;  // keccak256 of the revealed ML-DSA public key
    mapping(address => mapping(address => uint256)) public escrow; // classical => token (0 = native) => amount
    uint256 private locked = 1;

    event Committed(address indexed account, bytes32 commitment, uint64 countsFrom);
    event Rescued(address indexed account, address indexed controller, bytes32 keyHash);
    event Deposited(address indexed account, address indexed token, address indexed from, uint256 amount);
    event Claimed(address indexed account, address indexed token, address to, uint256 amount);
    event LocalQdaySet(uint64 height);
    event GovernanceSet(address governance);

    error QdayPassed();
    error QdayNotYet();
    error AlreadyRescued();
    error NoCommitment();
    error WrongReveal();
    error BadKey();
    error BadSignature();
    error NotAllowed();
    error OnlyGovernance();
    error TooSoon();
    error Insufficient();
    error TransferFailed();
    error Reentrant();
    error BadParams();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrant();
        locked = 2;
        _;
        locked = 1;
    }

    constructor(address security_, address governance_, uint64 maturity_) {
        if (governance_ == address(0) || maturity_ == 0) revert BadParams();
        security = security_;
        governance = governance_;
        maturity = maturity_;
    }

    // ------------------------------------------------------------------ Q-day

    /// The Q-day height in force: the earlier non-zero one of the chain's and this contract's (0 = none).
    function qdayHeight() public view returns (uint64 h) {
        h = localQday;
        if (security != address(0)) {
            // a precompile has no code; an address with neither code nor precompile answers empty
            (bool ok, bytes memory ret) = security.staticcall(abi.encodeWithSelector(IZetaphySecurity.qday.selector));
            if (ok && ret.length >= 96) {
                (uint64 chainH,,) = abi.decode(ret, (uint64, uint64, bool));
                if (chainH != 0 && (h == 0 || chainH < h)) h = chainH;
            }
        }
    }

    function qdayReached() public view returns (bool) {
        uint64 h = qdayHeight();
        return h != 0 && block.number >= h;
    }

    /// Contract-level Q-day for this contract (e.g. on a chain without the chain rule): at least
    /// MIN_NOTICE blocks ahead, or 0 to remove it. The chain's own Q-day still applies if earlier.
    function setLocalQday(uint64 h) external {
        if (msg.sender != governance) revert OnlyGovernance();
        if (h != 0 && h < block.number + MIN_NOTICE) revert TooSoon();
        localQday = h;
        emit LocalQdaySet(h);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert OnlyGovernance();
        if (g == address(0)) revert BadParams();
        governance = g;
        emit GovernanceSet(g);
    }

    /// QDayGuard: may a contract still trust `account`'s own (ECDSA) authority, i.e. msg.sender == account?
    /// Before Q-day yes. After it only if the chain says the account is quantum-locked / migrated (then the
    /// call can only come from its ML-DSA-44 controller through MsgEVMCall as_owner) - on any other chain no.
    function classicalTrusted(address account) public view returns (bool) {
        if (!qdayReached()) return true;
        return _chainMigrated(account);
    }

    function _chainMigrated(address account) private view returns (bool) {
        if (security == address(0)) return false;
        (bool ok, bytes memory ret) = security.staticcall(abi.encodeWithSelector(IZetaphySecurity.migration.selector, account));
        if (!ok || ret.length < 160) return false;
        (bool migrated,,,,) = abi.decode(ret, (bool, address, address, uint64, bool));
        return migrated;
    }

    // ------------------------------------------------------------------ commit (before Q-day)

    /// The commitment for `account`: hides the ML-DSA key and the secret until the reveal.
    function commitmentOf(address account, bytes32 pqKeyHash, bytes32 secret) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumRescue v1", block.chainid, address(this), account, pqKeyHash, secret));
    }

    /// Record (or replace, or with 0 cancel) the caller's commitment. A change counts `maturity` blocks later;
    /// until then the previous commitment stays in force.
    function commit(bytes32 c) external {
        if (qdayReached()) revert QdayPassed();
        if (controllerOf[msg.sender] != address(0)) revert AlreadyRescued();
        Slot storage s = slots[msg.sender];
        _promote(s);
        s.pending = c;
        s.pendingAt = uint64(block.number);
        emit Committed(msg.sender, c, uint64(block.number) + maturity);
    }

    function _promote(Slot storage s) private {
        if (s.pendingAt != 0 && block.number >= uint256(s.pendingAt) + maturity) {
            s.active = s.pending;
            s.pending = bytes32(0);
            s.pendingAt = 0;
        }
    }

    /// The commitment that counts for `account`: the newest one that matured before Q-day (or before now).
    function effectiveCommitment(address account) public view returns (bytes32) {
        Slot storage s = slots[account];
        uint256 bound = block.number;
        if (qdayReached()) bound = qdayHeight();
        if (s.pendingAt != 0 && uint256(s.pendingAt) + maturity <= bound) return s.pending;
        return s.active;
    }

    /// (active, pending, pendingAt) for wallets and the hub.
    function slotOf(address account) external view returns (bytes32, bytes32, uint64) {
        Slot storage s = slots[account];
        return (s.active, s.pending, s.pendingAt);
    }

    // ------------------------------------------------------------------ reveal (after Q-day)

    /// The chain's native ML-DSA-44 account of a public key.
    function pqAddress(bytes calldata pk) public pure returns (address) {
        return address(bytes20(sha256(abi.encodePacked("zetaphy/mldsa44\x00", pk))));
    }

    /// What the ML-DSA key signs to rescue `account` (when it does not send the reveal itself).
    function rescueDigest(address account, address controller) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumRescue reveal", block.chainid, address(this), account, controller));
    }

    /// After Q-day: prove the commitment and that the ML-DSA key is held (a signature, or the native PQ
    /// account sends this itself through MsgEVMCall). Anyone may relay: the controller follows from the key.
    function reveal(address account, bytes calldata pk, bytes32 secret, bytes calldata sig) external {
        if (!qdayReached()) revert QdayNotYet();
        if (controllerOf[account] != address(0)) revert AlreadyRescued();
        if (pk.length != PK_BYTES) revert BadKey();
        bytes32 c = effectiveCommitment(account);
        if (c == bytes32(0)) revert NoCommitment();
        bytes32 kh = keccak256(pk);
        if (c != commitmentOf(account, kh, secret)) revert WrongReveal();
        address ctrl = pqAddress(pk);
        if (msg.sender != ctrl && !_pqValid(rescueDigest(account, ctrl), pk, sig)) revert BadSignature();
        controllerOf[account] = ctrl;
        rescueKeyHash[account] = kh;
        delete slots[account];
        emit Rescued(account, ctrl, kh);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(uint8(44), d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    // ------------------------------------------------------------------ escrow for frozen / rescued accounts

    /// Pay native ZETAPHY to `account` through the rescue escrow (e.g. a payout after Q-day to a frozen address).
    function depositFor(address account) external payable {
        if (account == address(0) || msg.value == 0) revert BadParams();
        escrow[account][address(0)] += msg.value;
        emit Deposited(account, address(0), msg.sender, msg.value);
    }

    /// Pay an ERC-20 to `account` through the escrow (counts what actually arrived).
    function depositTokenFor(address token, address account, uint256 amount) external nonReentrant {
        if (account == address(0) || amount == 0 || token.code.length == 0) revert BadParams();
        uint256 before = IRescueERC20(token).balanceOf(address(this));
        _call(token, abi.encodeWithSelector(IRescueERC20.transferFrom.selector, msg.sender, address(this), amount));
        uint256 got = IRescueERC20(token).balanceOf(address(this)) - before;
        escrow[account][token] += got;
        emit Deposited(account, token, msg.sender, got);
    }

    /// Take escrowed funds out: the rescued ML-DSA controller, or the account itself while its key is still
    /// trusted (before Q-day, or after it when the chain says it is quantum-locked).
    function claim(address account, address token, uint256 amount, address to) external nonReentrant {
        address ctrl = controllerOf[account];
        bool ok = (ctrl != address(0) && msg.sender == ctrl) || (msg.sender == account && classicalTrusted(account));
        if (!ok) revert NotAllowed();
        if (to == address(0)) revert BadParams();
        uint256 bal = escrow[account][token];
        if (amount > bal) revert Insufficient();
        escrow[account][token] = bal - amount;
        emit Claimed(account, token, to, amount);
        if (token == address(0)) {
            (bool sent,) = to.call{value: amount}("");
            if (!sent) revert TransferFailed();
        } else {
            _call(token, abi.encodeWithSelector(IRescueERC20.transfer.selector, to, amount));
        }
    }

    function _call(address token, bytes memory data) private {
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || abi.decode(ret, (uint256)) != 1))) revert TransferFailed();
    }
}

contracts/QuantumWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title QuantumWallet: a smart wallet a quantum computer cannot drain (stage 5)
/// @notice Every action needs an ML-DSA signature (FIPS 204, post-quantum),
///         checked by ZETAPHY's precompile at 0x…0900. Two modes:
///           - hybrid: ECDSA AND ML-DSA must both sign (today's security, plus
///             protection if ECDSA is ever broken)
///           - post-quantum only: no ECDSA key at all (ecdsaOwner = 0)
///         Anyone may submit a signed action and pay its gas (a relay), so the
///         owner needs no other account. Keys rotate only through the wallet
///         itself, i.e. with the current keys' signatures.
contract QuantumWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    address public ecdsaOwner;   // 0 = post-quantum only
    uint8 public variant;        // 44 or 65 (ML-DSA parameter set)
    bytes32 public pqKeyHash;    // keccak256 of the ML-DSA public key (the key itself rides in calldata)
    uint256 public nonce;

    /// The signatures for one action. pqPublicKey must hash to pqKeyHash;
    /// ecdsaSig is ignored in post-quantum-only mode.
    struct Auth {
        bytes pqPublicKey;
        bytes pqSig;
        bytes ecdsaSig;
    }

    event Executed(uint256 indexed nonce, address indexed to, uint256 value);
    event KeysChanged(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    error Expired();
    error BadEcdsa();
    error BadPq();
    error WrongKey();
    error BadVariant();
    error OnlySelf();
    error CallFailed(bytes reason);

    constructor(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) payable {
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    receive() external payable {}

    /// The 32 bytes both keys sign for one action.
    function digest(address to, uint256 value, bytes calldata data, uint256 deadline) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumWallet", block.chainid, address(this), nonce, to, value, keccak256(data), deadline));
    }

    function execute(address to, uint256 value, bytes calldata data, uint256 deadline, Auth calldata auth)
        external returns (bytes memory)
    {
        if (block.timestamp > deadline) revert Expired();
        _authorize(digest(to, value, data, deadline), auth);
        uint256 n = nonce++;
        (bool ok, bytes memory ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit Executed(n, to, value);
        return ret;
    }

    function _authorize(bytes32 d, Auth calldata auth) private view {
        if (ecdsaOwner != address(0) && _recover(d, auth.ecdsaSig) != ecdsaOwner) revert BadEcdsa();
        if (keccak256(auth.pqPublicKey) != pqKeyHash) revert WrongKey();
        if (!_pqValid(d, auth.pqPublicKey, auth.pqSig)) revert BadPq();
    }

    /// Rotate keys or switch mode; callable only by execute() on this wallet.
    function setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) private {
        if ((variant_ != 44 && variant_ != 65) || pqKeyHash_ == bytes32(0)) revert BadVariant();
        ecdsaOwner = ecdsaOwner_;
        variant = variant_;
        pqKeyHash = pqKeyHash_;
        emit KeysChanged(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(variant, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

/// @title QuantumWalletFactory: wallets at an address known before they exist
/// @notice The address depends only on the keys, so funds can be sent to a
///         wallet before it is deployed, and anyone can deploy it later.
contract QuantumWalletFactory {
    event Created(address indexed wallet, address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    function create(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external returns (address w) {
        w = address(new QuantumWallet{salt: _salt(ecdsaOwner, variant, pqKeyHash)}(ecdsaOwner, variant, pqKeyHash));
        emit Created(w, ecdsaOwner, variant, pqKeyHash);
    }

    function predict(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external view returns (address) {
        bytes32 h = keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt(ecdsaOwner, variant, pqKeyHash),
            keccak256(abi.encodePacked(type(QuantumWallet).creationCode, abi.encode(ecdsaOwner, variant, pqKeyHash)))));
        return address(uint160(uint256(h)));
    }

    function _salt(address e, uint8 v, bytes32 k) private pure returns (bytes32) {
        return keccak256(abi.encode(e, v, k));
    }
}

contracts/RedBlueArena.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title RedBlueArena: an open red-vs-blue round for Neuro (testnet sandbox)
/// @notice TESTNET ONLY, and the "scams" never leave a sandbox: red entries are deployed
///         only on the runners' throwaway in-memory devnet, never on a public chain.
///
///         Red submits a scam token (a manifest: Solidity source + the owner's trap steps)
///         that should get past Neuro; blue submits a detector (a rule spec). Both commit
///         keccak256(arena, round, side, author, contentHash, salt) before `commitEnd`, so
///         neither side can tailor its entry to the other's, and reveal the content hash,
///         salt and a URI after it.
///
///         Judging needs no single trusted runner:
///           - k-of-n: up to `seats` runners (governance-approved AND bonded with `runnerBond`)
///             take a seat by committing keccak256(arena, round, runner, resultKey, salt) before
///             `resultCommitEnd`, so nobody can copy another runner's result; they reveal the
///             full result (bitmaps + blue scores) before `judgeEnd`;
///           - the sandbox is pinned: the round names `sandbox`, the hash of the runner
///             environment (zetaphy-neuro/ml/redteam/sandbox.js: the EVM interpreter and solc
///             versions, the fixed block environment, Neuro's model, the benign reference set),
///             and every runner's result commits to it, so honest runners agree byte for byte;
///           - `finalize` (anyone, after judgeEnd): the result `quorum` (more than half the
///             seats) runners revealed is the round's result. Runners that revealed another
///             result or never revealed lose `slashBps` of their bond to the runners who agreed.
///             No quorum: the round is void (unrevealed seats are still slashed);
///           - a challenge window follows: anyone may `challenge` with `challengeBond`, naming the
///             result it says is right. Governance (the timelock) re-runs the deterministic sandbox
///             and decides: upheld -> the challenger's result replaces it, the runners who posted
///             the wrong one are slashed and the challenger gets its bond back plus half of that;
///             rejected -> the challenge bond goes to the round's agreeing runners. A challenge
///             governance never answers lapses after `appealWindow`: the bond comes back.
///         Then `settle` pays:
///           - red: every valid evading entry gets an equal share of the red pool; valid
///             entries get their bond back; invalid or unrevealed entries lose it;
///           - blue: entries with a positive score share the blue pool by score; revealed
///             entries get their bond back; unrevealed ones lose it;
///           - runners: `runnerFeeBps` of the pools, plus the slashed bonds, split among the
///             runners whose revealed result is the final one.
///         Lost bonds and unpaid pools carry over to the next round. If the round is void,
///         revealed entries get their bonds back.
contract RedBlueArena {
    uint256 public constant MAX_RED = 128;
    uint256 public constant MAX_BLUE = 32;
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_SEATS = 9;

    struct Round {
        uint64 commitEnd;
        uint64 revealEnd;
        uint64 judgeEnd;     // end of the runners' result reveals
        bool judged;
        bool settled;
        uint128 redPool;
        uint128 bluePool;
        uint256 redValid;    // bit i: red entry i is a working scam
        uint256 redEvaded;   // bit i: ...and Neuro missed it
    }

    /// The runners' side of a round (kept apart from Round so both getters stay small).
    struct Judging {
        uint64 resultCommitEnd;
        uint64 challengeEnd;
        bool finalized;
        bool challenged;
        bool challengeResolved;
        uint8 seated;
        address challenger;
        bytes32 sandbox;     // hash of the pinned runner environment
        bytes32 resultKey;   // the final result's key
        bytes32 challengeKey;
        uint128 slashPool;   // slashed runner bonds of this round, for the agreeing runners
    }

    struct Entry {
        address author;
        bool revealed;
        bytes32 commitment;
        bytes32 contentHash;
        string uri;
    }

    struct Result {
        bool known;
        uint256 redValid;
        uint256 redEvaded;
        int32[] blueScore;
    }

    struct RunnerStake {
        uint128 bond;
        uint64 unbondAt;     // 0: bonded; else when the bond can be withdrawn
    }

    address public governance;
    uint128 public redBond = 1 ether;
    uint128 public blueBond = 1 ether;
    uint8 public quorum = 2;               // k: agreeing runners needed (> seats / 2)
    uint8 public seats = 3;                // n: runner seats per round
    uint128 public runnerBond = 10 ether;
    uint16 public slashBps = 5_000;        // of runnerBond, per wrong / missing result
    uint16 public runnerFeeBps = 500;      // of the round's pools, for the agreeing runners
    uint128 public challengeBond = 5 ether;
    uint32 public challengeWindow = 1 days;
    uint32 public appealWindow = 7 days;
    uint32 public unbondDelay = 14 days;
    uint256 public carry;          // lost bonds and unpaid pools, for the next round
    uint256 public roundCount;

    mapping(address => bool) public runners;
    mapping(address => RunnerStake) public stakes;
    mapping(address => uint256) public activeSeats; // open rounds a runner sits in (cannot unbond meanwhile)
    mapping(uint256 => Round) public rounds;
    mapping(uint256 => Judging) public judging;
    mapping(uint256 => Entry[]) private _red;
    mapping(uint256 => Entry[]) private _blue;
    mapping(uint256 => int32[]) private _blueScore;
    mapping(uint256 => address[]) private _seats;
    mapping(uint256 => mapping(address => bytes32)) public resultCommitments;
    mapping(uint256 => mapping(address => bytes32)) public revealedKey;
    mapping(uint256 => mapping(bytes32 => uint8)) public votes;
    mapping(uint256 => mapping(bytes32 => Result)) private _results;
    mapping(address => uint256) public owed;

    event RoundOpened(uint256 indexed round, uint64 commitEnd, uint64 revealEnd, uint64 judgeEnd, uint256 redPool, uint256 bluePool);
    event RoundSandbox(uint256 indexed round, uint64 resultCommitEnd, bytes32 sandbox);
    event Committed(uint256 indexed round, uint8 side, uint256 index, address indexed author);
    event Revealed(uint256 indexed round, uint8 side, uint256 index, bytes32 contentHash, string uri);
    event ResultCommitted(uint256 indexed round, address indexed runner);
    event ResultRevealed(uint256 indexed round, address indexed runner, bytes32 key, uint8 votes);
    event Judged(uint256 indexed round, uint256 redValid, uint256 redEvaded, int32[] blueScore);
    event RunnerSlashed(uint256 indexed round, address indexed runner, uint256 amount, bool revealed);
    event Challenged(uint256 indexed round, address indexed challenger, bytes32 key);
    event ChallengeResolved(uint256 indexed round, bool upheld, bytes32 key);
    event Settled(uint256 indexed round, bool void, uint256 redPaid, uint256 bluePaid, uint256 carried);
    event RunnerSet(address indexed runner, bool on);
    event RunnerBonded(address indexed runner, uint256 bond);
    event RunnerUnbonding(address indexed runner, uint64 at);
    event ParamsSet(uint128 redBond, uint128 blueBond, uint8 quorum);
    event RunnerParamsSet(uint8 seats, uint128 runnerBond, uint16 slashBps, uint16 runnerFeeBps, uint128 challengeBond, uint32 challengeWindow, uint32 appealWindow);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotRunner();
    error BadInput();
    error WrongPhase();
    error Full();
    error BadReveal();
    error AlreadyPosted();
    error NothingOwed();
    error SendFailed();
    error LowBond();
    error Busy();

    constructor(address governance_) {
        governance = governance_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setRunner(address r, bool on) external onlyGov { runners[r] = on; emit RunnerSet(r, on); }
    function setParams(uint128 rb, uint128 bb, uint8 q) external onlyGov {
        if (q == 0 || uint256(q) * 2 <= seats || q > seats) revert BadInput();
        (redBond, blueBond, quorum) = (rb, bb, q);
        emit ParamsSet(rb, bb, q);
    }
    /// n seats, the runner bond, the slash, the runners' fee and the challenge rules. quorum must stay > n/2.
    function setRunnerParams(uint8 n, uint128 bond, uint16 slash, uint16 fee, uint128 cBond, uint32 cWindow, uint32 aWindow) external onlyGov {
        if (n == 0 || n > MAX_SEATS || uint256(quorum) * 2 <= n || quorum > n || slash > 10_000 || fee > 2_000 || cWindow == 0 || aWindow == 0) revert BadInput();
        (seats, runnerBond, slashBps, runnerFeeBps, challengeBond, challengeWindow, appealWindow) = (n, bond, slash, fee, cBond, cWindow, aWindow);
        emit RunnerParamsSet(n, bond, slash, fee, cBond, cWindow, aWindow);
    }

    /// Opens a round with msg.value (+ the carry) as bounties; redShareBps of it for red. `sandbox` is the
    /// hash of the runner environment every result must be computed in.
    function openRound(uint64 commitEnd, uint64 revealEnd, uint64 resultCommitEnd, uint64 judgeEnd, uint16 redShareBps, bytes32 sandbox)
        external payable onlyGov returns (uint256 id)
    {
        if (commitEnd <= block.timestamp || revealEnd <= commitEnd || resultCommitEnd <= revealEnd || judgeEnd <= resultCommitEnd || redShareBps > 10_000 || sandbox == bytes32(0)) revert BadInput();
        uint256 total = msg.value + carry;
        carry = 0;
        uint128 red = uint128((total * redShareBps) / 10_000);
        id = ++roundCount;
        Round storage r = rounds[id];
        (r.commitEnd, r.revealEnd, r.judgeEnd) = (commitEnd, revealEnd, judgeEnd);
        (r.redPool, r.bluePool) = (red, uint128(total - red));
        (judging[id].resultCommitEnd, judging[id].sandbox) = (resultCommitEnd, sandbox);
        emit RoundOpened(id, commitEnd, revealEnd, judgeEnd, red, total - red);
        emit RoundSandbox(id, resultCommitEnd, sandbox);
    }

    // ------------------------------------------------------------------ runner bonds

    function bondRunner() external payable {
        RunnerStake storage s = stakes[msg.sender];
        s.bond += uint128(msg.value);
        s.unbondAt = 0;
        emit RunnerBonded(msg.sender, s.bond);
    }

    function requestUnbond() external {
        if (activeSeats[msg.sender] != 0) revert Busy();
        uint64 at = uint64(block.timestamp) + unbondDelay;
        stakes[msg.sender].unbondAt = at;
        emit RunnerUnbonding(msg.sender, at);
    }

    function withdrawBond() external {
        RunnerStake storage s = stakes[msg.sender];
        if (s.unbondAt == 0 || block.timestamp < s.unbondAt || activeSeats[msg.sender] != 0) revert WrongPhase();
        uint256 a = s.bond;
        if (a == 0) revert NothingOwed();
        s.bond = 0;
        s.unbondAt = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }

    // ------------------------------------------------------------------ entries

    function commitmentOf(uint256 round, uint8 side, address author, bytes32 contentHash, bytes32 salt) public view returns (bytes32) {
        return keccak256(abi.encode(address(this), round, side, author, contentHash, salt));
    }

    /// side 0 = red (a scam token), 1 = blue (a detector). The bond is the side's bond.
    function commit(uint256 round, uint8 side, bytes32 commitment) external payable returns (uint256 index) {
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || block.timestamp >= r.commitEnd) revert WrongPhase();
        if (side > 1 || commitment == bytes32(0) || msg.value != (side == 0 ? redBond : blueBond)) revert BadInput();
        Entry[] storage list = side == 0 ? _red[round] : _blue[round];
        if (list.length >= (side == 0 ? MAX_RED : MAX_BLUE)) revert Full();
        list.push(Entry(msg.sender, false, commitment, bytes32(0), ""));
        index = list.length - 1;
        emit Committed(round, side, index, msg.sender);
    }

    function reveal(uint256 round, uint8 side, uint256 index, bytes32 contentHash, bytes32 salt, string calldata uri) external {
        Round storage r = rounds[round];
        if (block.timestamp < r.commitEnd || block.timestamp >= r.revealEnd) revert WrongPhase();
        if (side > 1 || bytes(uri).length == 0 || bytes(uri).length > MAX_URI) revert BadInput();
        Entry storage e = (side == 0 ? _red[round] : _blue[round])[index];
        if (e.revealed || e.author != msg.sender || e.commitment != commitmentOf(round, side, msg.sender, contentHash, salt)) revert BadReveal();
        e.revealed = true;
        e.contentHash = contentHash;
        e.uri = uri;
        emit Revealed(round, side, index, contentHash, uri);
    }

    function counts(uint256 round) external view returns (uint256 red, uint256 blue) {
        return (_red[round].length, _blue[round].length);
    }

    function entry(uint256 round, uint8 side, uint256 index) external view returns (address author, bool revealed, bytes32 contentHash, string memory uri) {
        Entry storage e = (side == 0 ? _red[round] : _blue[round])[index];
        return (e.author, e.revealed, e.contentHash, e.uri);
    }

    function blueScores(uint256 round) external view returns (int32[] memory) {
        return _blueScore[round];
    }

    function seatsOf(uint256 round) external view returns (address[] memory) {
        return _seats[round];
    }

    function resultOf(uint256 round, bytes32 key) external view returns (bool known, uint256 redValid, uint256 redEvaded, int32[] memory blueScore) {
        Result storage x = _results[round][key];
        return (x.known, x.redValid, x.redEvaded, x.blueScore);
    }

    // ------------------------------------------------------------------ judging: k-of-n commit-reveal

    /// The key of a result: the sandbox it was computed in, the bitmaps and the blue scores.
    function resultKey(bytes32 sandbox, uint256 redValid, uint256 redEvaded, int32[] memory blueScore) public pure returns (bytes32) {
        return keccak256(abi.encode(sandbox, redValid, redEvaded, blueScore));
    }

    function resultCommitmentOf(uint256 round, address runner, bytes32 key, bytes32 salt) public view returns (bytes32) {
        return keccak256(abi.encode(address(this), round, runner, key, salt));
    }

    /// A bonded, approved runner takes one of the round's seats with its sealed result.
    function commitResult(uint256 round, bytes32 commitment) external {
        if (!runners[msg.sender]) revert NotRunner();
        RunnerStake storage s = stakes[msg.sender];
        if (s.bond < runnerBond || s.unbondAt != 0) revert LowBond();
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || block.timestamp < r.revealEnd || block.timestamp >= judging[round].resultCommitEnd) revert WrongPhase();
        if (resultCommitments[round][msg.sender] != bytes32(0)) revert AlreadyPosted();
        if (judging[round].seated >= seats) revert Full();
        if (commitment == bytes32(0)) revert BadInput();
        resultCommitments[round][msg.sender] = commitment;
        _seats[round].push(msg.sender);
        judging[round].seated++;
        activeSeats[msg.sender]++;
        emit ResultCommitted(round, msg.sender);
    }

    function revealResult(uint256 round, uint256 redValid, uint256 redEvaded, int32[] calldata blueScore, bytes32 salt) external {
        Round storage r = rounds[round];
        if (block.timestamp < judging[round].resultCommitEnd || block.timestamp >= r.judgeEnd) revert WrongPhase();
        bytes32 c = resultCommitments[round][msg.sender];
        if (c == bytes32(0) || revealedKey[round][msg.sender] != bytes32(0)) revert BadReveal();
        _checkResult(round, redValid, redEvaded, blueScore);
        bytes32 key = resultKey(judging[round].sandbox, redValid, redEvaded, blueScore);
        if (resultCommitmentOf(round, msg.sender, key, salt) != c) revert BadReveal();
        revealedKey[round][msg.sender] = key;
        Result storage x = _results[round][key];
        if (!x.known) (x.known, x.redValid, x.redEvaded, x.blueScore) = (true, redValid, redEvaded, blueScore);
        uint8 v = ++votes[round][key];
        emit ResultRevealed(round, msg.sender, key, v);
    }

    function _checkResult(uint256 round, uint256 redValid, uint256 redEvaded, int32[] calldata blueScore) private view {
        Entry[] storage reds = _red[round];
        Entry[] storage blues = _blue[round];
        if (blueScore.length != blues.length || (redEvaded & ~redValid) != 0) revert BadInput();
        uint256 revealedMask;
        for (uint256 i; i < reds.length; i++) if (reds[i].revealed) revealedMask |= (uint256(1) << i);
        if ((redValid & ~revealedMask) != 0) revert BadInput();
        for (uint256 i; i < blues.length; i++) if (!blues[i].revealed && blueScore[i] > 0) revert BadInput();
    }

    /// Anyone, after the reveals: the result `quorum` runners revealed wins; the others are slashed.
    function finalize(uint256 round) external {
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || judging[round].finalized || block.timestamp < r.judgeEnd) revert WrongPhase();
        judging[round].finalized = true;
        address[] storage list = _seats[round];
        bytes32 best;
        uint8 bestVotes;
        for (uint256 i; i < list.length; i++) {
            bytes32 k = revealedKey[round][list[i]];
            if (k != bytes32(0) && votes[round][k] > bestVotes) (best, bestVotes) = (k, votes[round][k]);
        }
        bool judged = bestVotes >= quorum;
        for (uint256 i; i < list.length; i++) {
            address a = list[i];
            activeSeats[a]--;
            bytes32 k = revealedKey[round][a];
            // never revealed: always slashed; revealed another result: slashed only when a quorum agreed
            if (k == bytes32(0) || (judged && k != best)) _slash(round, a, k != bytes32(0));
        }
        if (judged) {
            _adopt(round, best);
            judging[round].challengeEnd = uint64(block.timestamp) + challengeWindow;
        }
    }

    function _adopt(uint256 round, bytes32 key) private {
        Round storage r = rounds[round];
        Result storage x = _results[round][key];
        (r.judged, judging[round].resultKey, r.redValid, r.redEvaded) = (true, key, x.redValid, x.redEvaded);
        _blueScore[round] = x.blueScore;
        emit Judged(round, x.redValid, x.redEvaded, x.blueScore);
    }

    function _slash(uint256 round, address runner, bool revealed) private {
        RunnerStake storage s = stakes[runner];
        uint256 cut = (uint256(runnerBond) * slashBps) / 10_000;
        if (cut > s.bond) cut = s.bond;
        s.bond -= uint128(cut);
        judging[round].slashPool += uint128(cut);
        emit RunnerSlashed(round, runner, cut, revealed);
    }

    // ------------------------------------------------------------------ the challenge path

    /// Anyone, during the challenge window: says the judged result is wrong and names the right one.
    function challenge(uint256 round, uint256 redValid, uint256 redEvaded, int32[] calldata blueScore) external payable {
        Round storage r = rounds[round];
        if (!r.judged || judging[round].challenged || block.timestamp >= judging[round].challengeEnd) revert WrongPhase();
        if (msg.value != challengeBond) revert BadInput();
        _checkResult(round, redValid, redEvaded, blueScore);
        bytes32 key = resultKey(judging[round].sandbox, redValid, redEvaded, blueScore);
        if (key == judging[round].resultKey) revert BadInput();
        Result storage x = _results[round][key];
        if (!x.known) (x.known, x.redValid, x.redEvaded, x.blueScore) = (true, redValid, redEvaded, blueScore);
        Judging storage j = judging[round];
        (j.challenged, j.challenger, j.challengeKey) = (true, msg.sender, key);
        emit Challenged(round, msg.sender, key);
    }

    /// Governance (the timelock), after re-running the pinned sandbox: upheld replaces the result.
    function resolveChallenge(uint256 round, bool upheld) external onlyGov {
        Round storage r = rounds[round];
        if (!judging[round].challenged || judging[round].challengeResolved || r.settled) revert WrongPhase();
        judging[round].challengeResolved = true;
        if (upheld) {
            bytes32 wrong = judging[round].resultKey;
            address[] storage list = _seats[round];
            uint256 before = judging[round].slashPool;
            for (uint256 i; i < list.length; i++) if (revealedKey[round][list[i]] == wrong) _slash(round, list[i], true);
            uint256 half = (judging[round].slashPool - before) / 2;
            judging[round].slashPool -= uint128(half);
            owed[judging[round].challenger] += challengeBond + half;
            _adopt(round, judging[round].challengeKey);
        } else {
            judging[round].slashPool += challengeBond;
        }
        emit ChallengeResolved(round, upheld, judging[round].resultKey);
    }

    /// A challenge governance did not answer within appealWindow lapses: the bond comes back, the result stands.
    function expireChallenge(uint256 round) external {
        if (!judging[round].challenged || judging[round].challengeResolved || block.timestamp < uint256(judging[round].challengeEnd) + appealWindow) revert WrongPhase();
        judging[round].challengeResolved = true;
        owed[judging[round].challenger] += challengeBond;
        emit ChallengeResolved(round, false, judging[round].resultKey);
    }

    // ------------------------------------------------------------------ payout

    function settle(uint256 round) external {
        Round storage r = rounds[round];
        Judging storage j = judging[round];
        if (!j.finalized || r.settled) revert WrongPhase();
        if (r.judged && (block.timestamp < j.challengeEnd || (j.challenged && !j.challengeResolved))) revert WrongPhase();
        r.settled = true;
        uint256 left = uint256(r.redPool) + r.bluePool;
        uint256 redPaid;
        uint256 bluePaid;
        if (!r.judged) {
            Entry[] storage reds = _red[round];
            Entry[] storage blues = _blue[round];
            for (uint256 i; i < reds.length; i++) _back(reds[i], redBond, reds[i].revealed);
            for (uint256 i; i < blues.length; i++) _back(blues[i], blueBond, blues[i].revealed);
            carry += j.slashPool;
        } else {
            // the agreeing runners' fee comes off the top of both pools
            uint256 feeRed = (uint256(r.redPool) * runnerFeeBps) / 10_000;
            uint256 feeBlue = (uint256(r.bluePool) * runnerFeeBps) / 10_000;
            redPaid = _payRed(round, r.redPool - feeRed);
            bluePaid = _payBlue(round, r.bluePool - feeBlue);
            _payRunners(round, feeRed + feeBlue + j.slashPool);
            left -= feeRed + feeBlue;
        }
        left -= redPaid + bluePaid;
        carry += left;
        emit Settled(round, !r.judged, redPaid, bluePaid, left);
    }

    function _payRed(uint256 round, uint256 pool) private returns (uint256 paid) {
        Round storage r = rounds[round];
        Entry[] storage reds = _red[round];
        uint256 evaders = _popcount(r.redEvaded);
        for (uint256 i; i < reds.length; i++) {
            _back(reds[i], redBond, (r.redValid >> i) & 1 == 1);
            if ((r.redEvaded >> i) & 1 == 1) {
                uint256 share = pool / evaders;
                owed[reds[i].author] += share;
                paid += share;
            }
        }
    }

    function _payBlue(uint256 round, uint256 pool) private returns (uint256 paid) {
        Entry[] storage blues = _blue[round];
        int32[] storage sc = _blueScore[round];
        uint256 total;
        for (uint256 i; i < sc.length; i++) if (sc[i] > 0) total += uint256(int256(sc[i]));
        for (uint256 i; i < blues.length; i++) {
            _back(blues[i], blueBond, blues[i].revealed);
            if (total > 0 && sc[i] > 0) {
                uint256 share = (pool * uint256(int256(sc[i]))) / total;
                owed[blues[i].author] += share;
                paid += share;
            }
        }
    }

    /// Splits `amount` (the runners' fee + the slashed bonds) among the runners whose revealed result is the
    /// final one; nobody agreeing: it carries over.
    function _payRunners(uint256 round, uint256 amount) private {
        address[] storage list = _seats[round];
        uint256 n;
        for (uint256 i; i < list.length; i++) if (revealedKey[round][list[i]] == judging[round].resultKey) n++;
        if (n == 0) { carry += amount; return; }
        uint256 each = amount / n;
        for (uint256 i; i < list.length; i++) if (revealedKey[round][list[i]] == judging[round].resultKey) owed[list[i]] += each;
        carry += amount - each * n;
    }

    function _back(Entry storage e, uint256 bond, bool ok) private {
        if (ok) owed[e.author] += bond;
        else carry += bond;
    }

    function _popcount(uint256 x) private pure returns (uint256 c) {
        for (; x != 0; x &= x - 1) c++;
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingOwed();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }
}

contracts/RewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IFundable {
    function fund() external payable;
}

/// @title RewardVault: releases the ZETAPHY reward pool at 10% a year
/// @notice The 500,000,000 ZETAPHY set aside for runners and validators sit
///         here instead of in a key-holder's account. Every day, anyone can
///         call `release()`, which pays out the share of the remaining pool
///         that has vested: 10% of what is left per year, in daily steps
///         (0.9^(1/365) is kept each day), so the pool lasts for decades.
///
///         There is NO withdraw function. Governance can only choose who
///         receives the releases (e.g. NeuroJobs' reward pool, a validator
///         rewards contract), and a change only takes effect DELAY after it
///         is announced, so everyone can see it coming. Nobody can make the
///         vault pay faster than the schedule.
///
///         Money vests from when it arrives (RV-1): the vault keeps the balance
///         that has been vesting since the last checkpoint (`_vesting`) and what
///         has vested but is not paid yet (`_due`). Every deposit through
///         `receive()` and every release first moves what vested since the last
///         checkpoint into `_due`, then counts the new balance as vesting from
///         today. Coins that arrive without `receive()` (selfdestruct) start
///         vesting at the next checkpoint. Fund the vault with a call that
///         forwards gas (receive() does a checkpoint), not a 2300-gas transfer.
contract RewardVault {
    uint256 private constant RAY = 1e27;
    /// 0.9^(1/365) in RAY: keep^365 = 0.9 (to 1e-25)
    uint256 public constant DAILY_KEEP = 999711382710977687364396358;
    uint256 public constant DELAY = 7 days;
    uint256 public constant MAX_SHARES = 8;

    struct Share {
        address to;
        uint16 bps;      // out of 10,000
        bool callFund;   // pay through `fund()` (NeuroJobs, ComputeMarket) instead of a plain transfer
    }

    uint64 public immutable start;
    uint64 public releasedDays;
    address public governance;
    Share[] private _shares;
    Share[] private _pending;
    uint64 public pendingAt; // 0 = nothing pending
    uint256 private _vesting; // balance vesting since day `releasedDays` (excludes _due)
    uint256 private _due;     // vested, not paid out yet
    bool private _paying;     // inside release(): recipients are being called

    event Released(uint256 day, uint256 amount);
    event Paid(address indexed to, uint256 amount, bool ok);
    event SharesProposed(uint64 effectiveAt);
    event SharesApplied();
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadShares();
    error TooEarly();

    constructor(address governance_, Share[] memory shares_) {
        governance = governance_;
        start = uint64(block.timestamp);
        _check(shares_);
        for (uint256 i = 0; i < shares_.length; i++) _shares.push(shares_[i]);
    }

    /// Deposits start vesting today, not at the last release (RV-1).
    receive() external payable {
        if (!_paying) _checkpoint();
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- schedule ----

    function daysElapsed() public view returns (uint256) {
        return (block.timestamp - start) / 1 days;
    }

    /// What `release()` would pay right now.
    function releasable() public view returns (uint256) {
        if (_paying) return 0;
        uint256 n = daysElapsed() - releasedDays;
        return _due + (n == 0 ? 0 : _vested(_vesting, n));
    }

    /// Pays out everything vested since the last release. Anyone may call it.
    function release() public returns (uint256 amount) {
        if (_paying) return 0; // a recipient re-entering: nothing more
        _checkpoint();         // before any external call
        amount = _due;
        if (amount == 0) return 0;
        _due = 0;
        _paying = true;
        emit Released(releasedDays, amount);
        uint256 left = amount;
        for (uint256 i = 0; i < _shares.length; i++) {
            Share memory s = _shares[i];
            uint256 part = i + 1 == _shares.length ? left : (amount * s.bps) / 10_000;
            left -= part;
            bool ok;
            if (s.callFund) {
                (ok, ) = s.to.call{value: part}(abi.encodeCall(IFundable.fund, ()));
            } else {
                (ok, ) = s.to.call{value: part}("");
            }
            // A recipient that refuses keeps nothing: the amount stays in the
            // vault (and keeps vesting); a broken recipient cannot block others.
            emit Paid(s.to, ok ? part : 0, ok);
        }
        _paying = false;
        // what a recipient refused (or sent back) is still here: it vests again from today
        _vesting = address(this).balance;
    }

    // ---- recipients ----

    function shares() external view returns (Share[] memory) {
        return _shares;
    }

    function pendingShares() external view returns (Share[] memory) {
        return _pending;
    }

    /// Announces new recipients; they apply DELAY later.
    function proposeShares(Share[] calldata next) external onlyGovernance {
        _check(next);
        delete _pending;
        for (uint256 i = 0; i < next.length; i++) _pending.push(next[i]);
        pendingAt = uint64(block.timestamp + DELAY);
        emit SharesProposed(pendingAt);
    }

    function cancelShares() external onlyGovernance {
        delete _pending;
        pendingAt = 0;
    }

    /// After the delay, anyone may switch to the announced recipients.
    /// What vested before the switch is paid to the old ones first.
    function applyShares() external {
        // not from inside release() (a recipient): the list being paid never changes under it
        if (_paying || pendingAt == 0 || block.timestamp < pendingAt) revert TooEarly();
        // Take the pending list first: a recipient called during release()
        // must not be able to apply it a second time.
        Share[] memory next = _pending;
        delete _pending;
        pendingAt = 0;
        release();
        delete _shares;
        for (uint256 i = 0; i < next.length; i++) _shares.push(next[i]);
        emit SharesApplied();
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- internals ----

    function _vested(uint256 bal, uint256 n) private pure returns (uint256) {
        return bal - (bal * _rpow(DAILY_KEEP, n)) / RAY;
    }

    /// Moves what vested since the last checkpoint into _due; everything else held (including money that
    /// just arrived) vests from today.
    function _checkpoint() private {
        uint256 today = daysElapsed();
        uint256 n = today - releasedDays;
        if (n != 0) {
            _due += _vested(_vesting, n);
            releasedDays = uint64(today);
        }
        _vesting = address(this).balance - _due;
    }

    function _check(Share[] memory s) private pure {
        if (s.length == 0 || s.length > MAX_SHARES) revert BadShares();
        uint256 total;
        for (uint256 i = 0; i < s.length; i++) {
            if (s[i].to == address(0) || s[i].bps == 0) revert BadShares();
            total += s[i].bps;
        }
        if (total != 10_000) revert BadShares();
    }

    /// x^n in RAY fixed point (exponentiation by squaring, rounding half up).
    function _rpow(uint256 x, uint256 n) private pure returns (uint256 z) {
        z = n % 2 != 0 ? x : RAY;
        for (n /= 2; n != 0; n /= 2) {
            x = (x * x + RAY / 2) / RAY;
            if (n % 2 != 0) z = (z * x + RAY / 2) / RAY;
        }
    }
}

contracts/RiskForecasts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRiskPair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112, uint112, uint32);
}

interface IRiskFlags {
    function isAddressFlagged(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractFlagged(address who) external view returns (bool, uint8);
}

interface IForesightResolver {
    function openEvent(bytes32 topic, uint64 commitEnd, uint64 revealEnd) external returns (uint256);
    function closeCommits(uint256 id) external;
    function resolve(uint256 id, uint8 outcome) external;
}

/// @title RiskForecasts: testnet risk forecasts on tokens, resolved from on-chain facts
/// @notice TESTNET ONLY. Stakes are testnet ZETAPHY, which has no value; this is a
///         forecasting tool that turns people's and models' judgement into labelled
///         data for Neuro, not a product to make money with.
///
///         A forecast question is one of:
///           - LiquidityDrop: "the other side of token X's pool loses at least N% of
///             what it held when the question was opened, before the deadline"
///           - Flagged: "token X is flagged in the ThreatRegistry before the deadline"
///         Forecasters back Yes or No with a testnet stake until the question closes
///         (and never while the condition already holds). The answer comes only from
///         chain state: anyone may `poke` a question, which reads the pair's reserves or
///         the ThreatRegistry; a drop counts once it has held for `confirmDelay` (so a
///         flash swap or a single-block dip is not enough). `propose` then states the
///         answer the facts give, and a dispute window lets anyone post a bond to send it
///         to governance (e.g. the pool moved for an honest migration, or the flag was a
///         mistake). Accurate forecasters share the stakes of the inaccurate side; a void
///         question refunds everyone.
///
///         When a ForesightRegistry is set, every question is also a Foresight event, so
///         models' committed probabilities are scored (Brier) against the same answer.
contract RiskForecasts {
    enum Kind { LiquidityDrop, Flagged }
    enum Status { None, Open, Proposed, Disputed, Final }
    enum Answer { None, No, Yes, Void }

    struct Question {
        address token;
        address pair;
        Kind kind;
        uint16 dropBps;       // LiquidityDrop: the drop that makes the answer Yes
        uint64 createdAt;
        uint64 closeAt;       // forecasts until
        uint64 deadline;      // the condition must be seen by then
        uint112 baseReserve;  // the pool's other side when opened
        address creator;
    }

    struct State {
        Status status;
        Answer proposed;
        Answer answer;
        uint64 seenAt;        // first poke that saw the condition (0: not holding)
        bool confirmed;       // seen again at least confirmDelay later, before the deadline (+ confirmDelay)
        uint64 proposedAt;
        address disputer;
        uint128 yes;
        uint128 no;
        uint256 foresightId;
    }

    uint256 public constant BPS = 10_000;
    uint64 public constant MIN_HORIZON = 1 hours;
    uint64 public constant MAX_HORIZON = 180 days;

    address public governance;
    IRiskFlags public threats;
    IForesightResolver public foresight;
    uint64 public confirmDelay = 1 hours;
    uint64 public disputeWindow = 1 days;
    uint64 public revealWindow = 1 days;      // Foresight reveal period after forecasts close
    uint128 public disputeBond = 10 ether;
    uint128 public minStake = 0.01 ether;
    uint112 public minReserve = 1 ether;      // smaller pools are too easy to move

    uint256 public count;
    mapping(uint256 => Question) public questions;
    mapping(uint256 => State) public states;
    mapping(uint256 => mapping(address => uint128)) public yesOf;
    mapping(uint256 => mapping(address => uint128)) public noOf;
    mapping(uint256 => mapping(address => bool)) public claimed;
    mapping(address => uint256) public owed;

    event Opened(uint256 indexed id, address indexed token, address pair, Kind kind, uint16 dropBps, uint64 closeAt, uint64 deadline, uint112 baseReserve, uint256 foresightId);
    event Forecast(uint256 indexed id, address indexed who, bool yes, uint256 amount);
    event Seen(uint256 indexed id, bool holding, bool confirmed, uint256 reserve);
    event Proposed(uint256 indexed id, Answer answer);
    event Disputed(uint256 indexed id, address indexed by, uint256 bond);
    event Finalized(uint256 indexed id, Answer answer, bool byGovernance);
    event Claimed(uint256 indexed id, address indexed who, uint256 amount);
    event ParamsSet(uint64 confirmDelay, uint64 disputeWindow, uint64 revealWindow, uint128 disputeBond, uint128 minStake, uint112 minReserve);
    event GovernanceSet(address governance);

    error NotGovernance();
    error BadParams();
    error BadPair();
    error AlreadyTrue();
    error WrongStatus();
    error ForecastsClosed();
    error StakeTooSmall();
    error NotYet();
    error TooLate();
    error BadBond();
    error NothingToClaim();
    error SendFailed();

    constructor(address governance_, IRiskFlags threats_, IForesightResolver foresight_) {
        governance = governance_;
        threats = threats_;
        foresight = foresight_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov {
        governance = g;
        emit GovernanceSet(g);
    }

    function setParams(uint64 confirm, uint64 disputeFor, uint64 reveal, uint128 bond, uint128 stake, uint112 reserve) external onlyGov {
        if (disputeFor < 1 hours || disputeFor > 30 days || confirm > 7 days || reveal < 1 hours || reveal > 30 days || stake == 0) revert BadParams();
        (confirmDelay, disputeWindow, revealWindow, disputeBond, minStake, minReserve) = (confirm, disputeFor, reveal, bond, stake, reserve);
        emit ParamsSet(confirm, disputeFor, reveal, bond, stake, reserve);
    }

    // ------------------------------------------------------------------ open

    /// @param horizon  seconds from now to the deadline
    /// @param window   seconds from now during which forecasts are taken (<= horizon)
    function open(address token, address pair, Kind kind, uint16 dropBps, uint64 horizon, uint64 window) external returns (uint256 id) {
        if (horizon < MIN_HORIZON || horizon > MAX_HORIZON || window == 0 || window > horizon || token == address(0)) revert BadParams();
        uint112 base;
        if (kind == Kind.LiquidityDrop) {
            if (dropBps < 1000 || dropBps > BPS) revert BadParams();
            base = _otherReserve(token, pair);
            if (base < minReserve) revert BadPair();
        } else {
            if (address(threats) == address(0)) revert BadParams();
            if (_flagged(token)) revert AlreadyTrue();
            dropBps = 0;
        }
        id = ++count;
        uint64 nowT = uint64(block.timestamp);
        questions[id] = Question(token, pair, kind, dropBps, nowT, nowT + window, nowT + horizon, base, msg.sender);
        State storage s = states[id];
        s.status = Status.Open;
        if (address(foresight) != address(0)) {
            s.foresightId = foresight.openEvent(keccak256(abi.encode(address(this), id)), nowT + window, nowT + window + revealWindow);
        }
        emit Opened(id, token, pair, kind, dropBps, nowT + window, nowT + horizon, base, s.foresightId);
    }

    // ------------------------------------------------------------------ forecast

    function forecast(uint256 id, bool yes) external payable {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open || block.timestamp >= q.closeAt) revert ForecastsClosed();
        if (msg.value < minStake || msg.value > type(uint128).max) revert StakeTooSmall();
        // never while the answer is already being decided
        if (s.seenAt != 0 || _holds(q)) revert AlreadyTrue();
        if (yes) { yesOf[id][msg.sender] += uint128(msg.value); s.yes += uint128(msg.value); }
        else { noOf[id][msg.sender] += uint128(msg.value); s.no += uint128(msg.value); }
        emit Forecast(id, msg.sender, yes, msg.value);
    }

    // ------------------------------------------------------------------ resolve from chain facts

    /// Reads the chain for a question (anyone; a keeper runs it on a schedule).
    function poke(uint256 id) public {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open || s.confirmed) return;
        uint64 nowT = uint64(block.timestamp);
        bool holding = _holds(q);
        uint256 reserve = q.kind == Kind.LiquidityDrop ? _otherReserve(q.token, q.pair) : 0;
        if (holding) {
            if (s.seenAt == 0) {
                if (nowT <= q.deadline) {
                    s.seenAt = nowT;
                    // forecasts and Foresight commits stop the moment it is seen
                    if (s.foresightId != 0 && nowT < q.closeAt) foresight.closeCommits(s.foresightId);
                    if (nowT < q.closeAt) q.closeAt = nowT;
                }
            }
            if (s.seenAt != 0 && nowT >= s.seenAt + _confirmFor(q)) s.confirmed = true;
        } else if (s.seenAt != 0) {
            s.seenAt = 0; // it did not hold: start again
        }
        emit Seen(id, holding, s.confirmed, reserve);
    }

    /// States the answer the facts give: Yes once confirmed, No once the deadline (+ confirm time) passed without it.
    function propose(uint256 id) external {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open) revert WrongStatus();
        poke(id);
        Answer a;
        if (s.confirmed) a = Answer.Yes;
        else if (block.timestamp > q.deadline + _confirmFor(q) && s.seenAt == 0) a = Answer.No;
        else revert NotYet(); // (past that time, the poke above either confirmed a holding condition or reset it)
        s.status = Status.Proposed;
        s.proposed = a;
        s.proposedAt = uint64(block.timestamp);
        emit Proposed(id, a);
    }

    function dispute(uint256 id) external payable {
        State storage s = states[id];
        if (s.status != Status.Proposed) revert WrongStatus();
        if (block.timestamp >= s.proposedAt + disputeWindow) revert TooLate();
        if (msg.value != disputeBond) revert BadBond();
        s.status = Status.Disputed;
        s.disputer = msg.sender;
        emit Disputed(id, msg.sender, msg.value);
    }

    /// Governance answers a disputed question. The bond goes back if the proposed answer changed, else to governance.
    function settleDispute(uint256 id, Answer a) external onlyGov {
        State storage s = states[id];
        if (s.status != Status.Disputed) revert WrongStatus();
        if (a == Answer.None) revert BadParams();
        owed[a != s.proposed ? s.disputer : governance] += disputeBond;
        _final(id, a, true);
    }

    function finalize(uint256 id) external {
        State storage s = states[id];
        if (s.status != Status.Proposed) revert WrongStatus();
        if (block.timestamp < s.proposedAt + disputeWindow) revert NotYet();
        _final(id, s.proposed, false);
    }

    function _final(uint256 id, Answer a, bool byGov) private {
        State storage s = states[id];
        s.status = Status.Final;
        s.answer = a;
        if (s.foresightId != 0) foresight.resolve(s.foresightId, uint8(a));
        emit Finalized(id, a, byGov);
    }

    // ------------------------------------------------------------------ pay out

    /// What `who` gets back from a final question.
    function payoutOf(uint256 id, address who) public view returns (uint256) {
        State storage s = states[id];
        if (s.status != Status.Final || claimed[id][who]) return 0;
        uint256 y = yesOf[id][who];
        uint256 n = noOf[id][who];
        uint256 total = uint256(s.yes) + s.no;
        if (s.answer == Answer.Void) return y + n;
        uint256 winStake = s.answer == Answer.Yes ? y : n;
        uint256 winTotal = s.answer == Answer.Yes ? s.yes : s.no;
        if (winTotal == 0) return y + n; // nobody was right: everyone gets their stake back
        return (winStake * total) / winTotal;
    }

    function claim(uint256 id, address who) external {
        uint256 amount = payoutOf(id, who);
        if (amount == 0) revert NothingToClaim();
        claimed[id][who] = true;
        owed[who] += amount;
        emit Claimed(id, who, amount);
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingToClaim();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }

    // ------------------------------------------------------------------ facts

    function _confirmFor(Question storage q) private view returns (uint64) {
        return q.kind == Kind.Flagged ? 0 : confirmDelay; // a flag already took a quorum of runners
    }

    function _holds(Question storage q) private view returns (bool) {
        if (q.kind == Kind.Flagged) return _flagged(q.token);
        uint256 r = _otherReserve(q.token, q.pair);
        return r * BPS <= uint256(q.baseReserve) * (BPS - q.dropBps);
    }

    function _flagged(address token) private view returns (bool) {
        if (address(threats) == address(0)) return false;
        (bool a,) = threats.isAddressFlagged(block.chainid, token);
        if (a) return true;
        (bool c,) = threats.isContractFlagged(token);
        return c;
    }

    /// The reserve of the pool's other token (the liquidity a holder of `token` can sell into).
    function _otherReserve(address token, address pair) private view returns (uint112) {
        if (pair.code.length == 0) revert BadPair();
        address t0 = IRiskPair(pair).token0();
        address t1 = IRiskPair(pair).token1();
        if (t0 != token && t1 != token) revert BadPair();
        (uint112 r0, uint112 r1,) = IRiskPair(pair).getReserves();
        return t0 == token ? r1 : r0;
    }

    /// The other side's reserve now (for pages and keepers).
    function reserveNow(uint256 id) external view returns (uint256) {
        Question storage q = questions[id];
        return q.kind == Kind.LiquidityDrop ? _otherReserve(q.token, q.pair) : 0;
    }

    function holdsNow(uint256 id) external view returns (bool) {
        return _holds(questions[id]);
    }
}

contracts/SaphanAccounts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan accounts: one account address on every Saphan chain, controlled from ZETAPHY
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited.
///
///         SaphanAccountFactory sits at the same address on every Saphan chain (deployed by one fresh key as its
///         first transaction there, so CREATE gives the same address whatever its constructor arguments). Each user
///         (an address on ZETAPHY, the "owner") has one SaphanAccount per chain, made with CREATE2 (salt = owner,
///         init code = SaphanAccount + owner): the same factory and the same init code give the same address on every
///         chain. src/saphanaccounts.js derives it off-chain. Anyone may deploy it (deploy(owner)); it is the
///         owner's either way.
///
///         Who controls it:
///           - on ZETAPHY (the home chain): the owner, directly (execute);
///           - on any other chain: only the owner's calls from ZETAPHY through that chain's Saphan Gateway:
///             ZetaphyGateway.withdrawAndCall(target = the account, data = abi.encode(Call[])). The SaphanSourceGateway
///             there calls account.onSaphanCall(77390, owner, data) with the ETH, after the route's checks; the
///             account checks the Gateway, the chain and the owner, then runs the calls (all or none: a failure makes
///             the Gateway refund the ETH to revertTo, normally the account itself).
///         The owner's key is never used on the other chains: a contract owner on ZETAPHY (a multisig, a
///         QuantumWallet) controls its accounts everywhere the same way, and the same address on another chain
///         controlled by someone else has no power over them.

interface IAccountFactory {
    function homeChainId() external view returns (uint256);
    function gateway() external view returns (address);
}

/// SaphanSourceGateway.claim: ETH of failed calls, paid to the caller.
interface IAccountGateway {
    function claim() external;
}

contract SaphanAccount {
    struct Call {
        address target;
        uint256 value;
        bytes data;
    }

    address public immutable factory;
    address public immutable owner;   // on ZETAPHY
    uint256 private entered;

    event Executed(uint256 calls, uint256 srcChainId);
    event Received(uint256 srcChainId, address sender, address token, uint256 amount);

    error NotOwner();
    error NotGateway();
    error CallFailed(uint256 index, bytes reason);
    error Reentered();

    constructor(address owner_) {
        factory = msg.sender;
        owner = owner_;
    }

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    /// On ZETAPHY: the owner runs calls from the account.
    function execute(Call[] calldata calls) external payable nonReentrant {
        if (msg.sender != owner || block.chainid != IAccountFactory(factory).homeChainId()) revert NotOwner();
        _run(calls);
        emit Executed(calls.length, block.chainid);
    }

    /// On another chain: the owner's calls from ZETAPHY, through this chain's SaphanSourceGateway (ISaphanReceiver).
    function onSaphanCall(uint256 srcChainId, address sender, bytes calldata data) external payable nonReentrant {
        address gw = IAccountFactory(factory).gateway();
        if (gw == address(0) || msg.sender != gw) revert NotGateway();
        if (srcChainId != IAccountFactory(factory).homeChainId() || sender != owner) revert NotOwner();
        _run(abi.decode(data, (Call[])));
        emit Executed(0, srcChainId);
    }

    /// Anyone: ETH the Gateway keeps for this account (a failed call with revertTo = this account) comes into the
    /// account. It cannot happen inside a Gateway call (the Gateway is locked then), so it is its own transaction.
    function pullRefunds() external nonReentrant {
        address gw = IAccountFactory(factory).gateway();
        if (gw == address(0)) revert NotGateway();
        IAccountGateway(gw).claim();
    }

    /// A refund of a call this account made through the Gateway (ISaphanReceiver): the ETH stays here.
    function onSaphanRevert(address, uint256, bytes calldata) external payable {
        address gw = IAccountFactory(factory).gateway();
        if (gw == address(0) || msg.sender != gw) revert NotGateway();
    }

    /// On ZETAPHY, money sent here from another chain through a ZetaphyGateway (ISaphanCallee): the tokens stay
    /// here; no call runs (only the owner runs calls).
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256 amount, bytes calldata) external {
        emit Received(srcChainId, sender, token, amount);
    }

    /// The callers checked who asks (owner on ZETAPHY, owner through the Gateway elsewhere); checked again here.
    function _run(Call[] memory calls) private {
        if (msg.sender != owner && msg.sender != IAccountFactory(factory).gateway()) revert NotOwner();
        for (uint256 i = 0; i < calls.length; i++) {
            (bool ok, bytes memory reason) = calls[i].target.call{value: calls[i].value}(calls[i].data);
            if (!ok) revert CallFailed(i, reason);
        }
    }

    receive() external payable {}
}

/// @title SaphanAccountFactory: makes SaphanAccounts at their derived address (the same on every chain)
contract SaphanAccountFactory is IAccountFactory {
    uint256 public immutable homeChainId;   // ZETAPHY (77390 on testnet)
    address public immutable gateway;       // this chain's SaphanSourceGateway (zero on ZETAPHY)

    event Deployed(address indexed owner, address account);

    constructor(uint256 homeChainId_, address gateway_) {
        require(homeChainId_ != 0 && (block.chainid == homeChainId_) == (gateway_ == address(0)), "config");
        homeChainId = homeChainId_;
        gateway = gateway_;
    }

    /// keccak256 of the account's init code: SaphanAccount's creation code followed by abi.encode(owner).
    function accountCodeHash(address owner) public pure returns (bytes32) {
        return keccak256(bytes.concat(type(SaphanAccount).creationCode, abi.encode(owner)));
    }

    /// The owner's account on this chain (and on every chain with this factory address).
    function accountOf(address owner) public view returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), bytes32(uint256(uint160(owner))), accountCodeHash(owner))))));
    }

    /// Anyone: deploys the owner's account here (once; afterwards it returns the address).
    function deploy(address owner) external returns (address account) {
        require(owner != address(0), "owner");
        account = accountOf(owner);
        if (account.code.length > 0) return account;
        address made = address(new SaphanAccount{salt: bytes32(uint256(uint160(owner)))}(owner));
        require(made == account, "derive");
        emit Deployed(owner, account);
    }
}

contracts/SaphanBitVM.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// BtcLightClient as this contract sees it (contracts/BtcLightClient.sol: proof of work, heaviest chain, confirmations).
interface IBitVMSpvClient {
    function verifyTx(bytes calldata rawTx, bytes32 blockHash, uint256 index, bytes32[] calldata siblings, uint256 minConfirmations)
        external view returns (bytes32 txid);
}

/// The BTC route's bridged token on ZETAPHY (BridgedToken: 18 decimals, 1 sat = 10^10 units).
interface IBitVMToken {
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanBtcWithdrawals: optimistic BTC withdrawals, a BitVM2-style claim / challenge / slash game
/// @notice PROTOTYPE, testnet only, not audited (docs/SAPHAN-PR6.md, item S7). There is NO Bitcoin script here and no
///         peg-out on Bitcoin: the game runs on ZETAPHY, and the "disprove" step is simplified to "prove the payment
///         by SPV or lose the bond". What it shows is the shape of BitVM2's operator flow:
///
///           1. request(amount, btcScript): a holder of the bridged BTC token escrows it here and names where the BTC
///              should go on Bitcoin (a scriptPubKey).
///           2. An operator (anyone who bonded ZTPHY here) FRONTS the BTC from its own coins: a Bitcoin transaction
///              with an output paying btcScript at least the requested sats, and an OP_RETURN that commits to the
///              withdrawal and to itself: "ZTPHYW" || withdrawal id (8 bytes, big-endian) || operator (20 bytes).
///              Then claim(id, txid, vout): it asks to be reimbursed with the escrowed tokens.
///           3. During CHALLENGE_WINDOW anyone who sees that txid:vout does not exist, does not pay the script, or
///              does not carry that commitment may challenge(id), posting challengeBond.
///           4. A challenged operator answers within RESPONSE_WINDOW with prove(): the raw transaction, its block and
///              Merkle branch; BtcLightClient checks the proof of work and minConfirmations. Proven: the operator is
///              reimbursed and takes the challenger's bond. Not proven in time: slash(id) by anyone: the holder gets
///              the escrow back plus half the operator's per-claim bond, the challenger its bond plus the other half.
///           5. Not challenged: finalize(id) after the window reimburses the operator.
///
///         Safety properties (tests: test/saphanbitvm.test.js):
///           - a holder either gets the escrow back or the operator had to be able to prove the BTC payment (or no
///             watcher looked: the optimistic assumption, ONE honest watcher is enough);
///           - the OP_RETURN binds the payment to one withdrawal AND one operator: another operator cannot claim a
///             payment it did not make, and one payment serves one withdrawal (paymentUsed);
///           - each claim locks bondPerClaim of the operator's bond until it is settled: an operator cannot withdraw
///             a bond that a pending claim could still lose; unlocked bond can be withdrawn at once.
///         Payouts are pulled (withdraw()); every parameter is fixed at deploy; there is no owner, admin or pause.
///         What a real BitVM2 adds: the reimbursement comes from a Bitcoin peg UTXO through pre-signed transactions,
///         and the disprove runs as a Bitcoin script (the SNARK verifier split into chunks). Not here.
contract SaphanBtcWithdrawals {
    enum State { None, Requested, Claimed, Challenged, Paid, Slashed, Cancelled }

    struct Withdrawal {
        address holder;
        uint64 sats;
        uint64 requestedAt;
        State state;
        address operator;
        uint64 claimEnds;     // end of the challenge window
        uint64 respondBy;     // end of the response window (when challenged)
        uint32 vout;
        address challenger;
        bytes32 scriptHash;   // keccak256 of the destination scriptPubKey
        bytes32 txid;         // the claimed payment (internal byte order, as BtcLightClient returns it)
        uint256 amount;       // escrowed token units (sats x 10^10)
    }

    uint256 public constant SATS_TO_WEI = 1e10;
    bytes6 public constant TAG = "ZTPHYW";

    IBitVMSpvClient public immutable client;
    IBitVMToken public immutable token;
    uint256 public immutable minConfirmations;
    uint256 public immutable bondPerClaim;      // native ZTPHY locked per open claim
    uint256 public immutable challengeBond;     // native ZTPHY a challenger posts
    uint64 public immutable claimTtl;           // after this, an unclaimed request can be cancelled
    uint64 public immutable challengeWindow;
    uint64 public immutable responseWindow;
    uint64 public immutable minSats;

    Withdrawal[] internal ws;
    mapping(address => uint256) public bonded;       // native, per operator
    mapping(address => uint256) public lockedBond;   // part of bonded held by open claims
    mapping(address => uint256) public owedNative;   // pull payouts
    mapping(address => uint256) public owedToken;    // pull payouts
    mapping(bytes32 => bool) public paymentUsed;     // keccak256(txid, vout)
    uint256 public escrowed;                         // tokens held for open requests
    uint256 public tokenLiabilities;                 // escrowed + every owedToken: what the token balance must cover
    uint256 private unlocked = 1;

    event Requested(uint256 indexed id, address indexed holder, uint256 amount, uint64 sats, bytes btcScript);
    event Cancelled(uint256 indexed id);
    event Bonded(address indexed operator, uint256 amount);
    event Unbonded(address indexed operator, uint256 amount);
    event Claimed(uint256 indexed id, address indexed operator, bytes32 txid, uint32 vout, uint64 claimEnds);
    event Challenged(uint256 indexed id, address indexed challenger, uint64 respondBy);
    event Proven(uint256 indexed id, address indexed operator);
    event Reimbursed(uint256 indexed id, address indexed operator, uint256 amount);
    event Slashed(uint256 indexed id, address indexed operator, address indexed challenger, uint256 bond);
    event Withdrawn(address indexed who, uint256 native, uint256 tokens);

    error BadAmount();
    error BadScript();
    error BadState(State s);
    error NotHolder();
    error TooEarly(uint64 at);
    error TooLate(uint64 at);
    error NoBond(uint256 free);
    error BadBond();
    error PaymentUsed();
    error BadPayment(uint256 code); // 1 truncated 2 vout 3 wrong script 4 too little 5 no commitment 6 txid
    error TokenFailed();
    error PayFailed();
    error Reentrancy();
    error Nothing();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    constructor(IBitVMSpvClient client_, IBitVMToken token_, uint256 minConfirmations_, uint256 bondPerClaim_, uint256 challengeBond_,
        uint64 claimTtl_, uint64 challengeWindow_, uint64 responseWindow_, uint64 minSats_)
    {
        require(address(client_) != address(0) && address(token_) != address(0) && minConfirmations_ >= 1 && bondPerClaim_ > 0
            && challengeBond_ > 0 && claimTtl_ > 0 && challengeWindow_ >= 1 hours && responseWindow_ >= 1 hours && minSats_ > 0, "config");
        client = client_;
        token = token_;
        minConfirmations = minConfirmations_;
        bondPerClaim = bondPerClaim_;
        challengeBond = challengeBond_;
        claimTtl = claimTtl_;
        challengeWindow = challengeWindow_;
        responseWindow = responseWindow_;
        minSats = minSats_;
    }

    // ---------------------------------------------------------------- holders

    /// Escrows `amount` of the bridged BTC token (a whole number of sats) for BTC sent to `btcScript` on Bitcoin.
    function request(uint256 amount, bytes calldata btcScript) external nonReentrant returns (uint256 id) {
        if (amount == 0 || amount % SATS_TO_WEI != 0 || amount / SATS_TO_WEI < minSats || amount / SATS_TO_WEI > type(uint64).max) revert BadAmount();
        if (btcScript.length == 0 || btcScript.length > 80 || btcScript[0] == 0x6a) revert BadScript(); // never an OP_RETURN
        id = ws.length;
        ws.push(Withdrawal({ holder: msg.sender, sats: uint64(amount / SATS_TO_WEI), requestedAt: uint64(block.timestamp), state: State.Requested,
            operator: address(0), claimEnds: 0, respondBy: 0, vout: 0, challenger: address(0), scriptHash: keccak256(btcScript),
            txid: bytes32(0), amount: amount }));
        escrowed += amount;
        tokenLiabilities += amount;
        emit Requested(id, msg.sender, amount, uint64(amount / SATS_TO_WEI), btcScript);
        // the whole amount must arrive (no fee-on-transfer): the balance covers every liability after the pull
        if (!token.transferFrom(msg.sender, address(this), amount) || token.balanceOf(address(this)) < tokenLiabilities) revert TokenFailed();
    }

    /// The holder, when no operator claimed within claimTtl: the escrow comes back (withdraw()).
    function cancel(uint256 id) external {
        Withdrawal storage w = ws[id];
        if (w.holder != msg.sender) revert NotHolder();
        if (w.state != State.Requested) revert BadState(w.state);
        if (block.timestamp < uint256(w.requestedAt) + claimTtl) revert TooEarly(w.requestedAt + claimTtl);
        w.state = State.Cancelled;
        escrowed -= w.amount;
        owedToken[msg.sender] += w.amount;
        emit Cancelled(id);
    }

    // ---------------------------------------------------------------- operators

    function bond() external payable {
        if (msg.value == 0) revert BadBond();
        bonded[msg.sender] += msg.value;
        emit Bonded(msg.sender, msg.value);
    }

    /// Takes back bond that no open claim holds (to owedNative; withdraw()).
    function unbond(uint256 amount) external {
        uint256 free = bonded[msg.sender] - lockedBond[msg.sender];
        if (amount == 0 || amount > free) revert NoBond(free);
        bonded[msg.sender] -= amount;
        owedNative[msg.sender] += amount;
        emit Unbonded(msg.sender, amount);
    }

    /// The operator says it paid withdrawal `id` on Bitcoin in txid:vout (with the OP_RETURN commitment). Locks
    /// bondPerClaim of its bond and opens the challenge window.
    function claim(uint256 id, bytes32 txid, uint32 vout) external {
        Withdrawal storage w = ws[id];
        if (w.state != State.Requested) revert BadState(w.state);
        uint256 free = bonded[msg.sender] - lockedBond[msg.sender];
        if (free < bondPerClaim) revert NoBond(free);
        bytes32 p = keccak256(abi.encode(txid, vout));
        if (paymentUsed[p]) revert PaymentUsed();
        paymentUsed[p] = true;
        lockedBond[msg.sender] += bondPerClaim;
        w.state = State.Claimed;
        w.operator = msg.sender;
        w.txid = txid;
        w.vout = vout;
        w.claimEnds = uint64(block.timestamp) + challengeWindow;
        emit Claimed(id, msg.sender, txid, vout, w.claimEnds);
    }

    // ---------------------------------------------------------------- watchers

    /// Anyone, during the challenge window, posting exactly challengeBond.
    function challenge(uint256 id) external payable {
        Withdrawal storage w = ws[id];
        if (w.state != State.Claimed) revert BadState(w.state);
        if (block.timestamp >= w.claimEnds) revert TooLate(w.claimEnds);
        if (msg.value != challengeBond) revert BadBond();
        w.state = State.Challenged;
        w.challenger = msg.sender;
        w.respondBy = uint64(block.timestamp) + responseWindow;
        emit Challenged(id, msg.sender, w.respondBy);
    }

    /// Anyone (usually the operator): the payment, proven by SPV. Allowed while claimed (it settles at once) or
    /// challenged before respondBy. The operator is reimbursed; a challenger's bond goes to the operator.
    function prove(uint256 id, bytes calldata rawTx, bytes32 blockHash, uint256 index, bytes32[] calldata siblings) external {
        Withdrawal storage w = ws[id];
        if (w.state == State.Challenged) {
            if (block.timestamp > w.respondBy) revert TooLate(w.respondBy);
        } else if (w.state != State.Claimed) revert BadState(w.state);
        checkPayment(rawTx, w.vout, w.sats, w.scriptHash, id, w.operator);
        address op = w.operator;
        if (w.state == State.Challenged) owedNative[op] += challengeBond;
        emit Proven(id, op);
        _reimburse(id, w);
        // the SPV proof last (a view of the immutable light client; a wrong proof reverts everything above)
        if (client.verifyTx(rawTx, blockHash, index, siblings, minConfirmations) != w.txid) revert BadPayment(6);
    }

    /// Anyone, after the challenge window of an unchallenged claim: the operator is reimbursed.
    function finalize(uint256 id) external {
        Withdrawal storage w = ws[id];
        if (w.state != State.Claimed) revert BadState(w.state);
        if (block.timestamp < w.claimEnds) revert TooEarly(w.claimEnds);
        _reimburse(id, w);
    }

    /// Anyone, after an unanswered challenge: the operator loses bondPerClaim (half to the challenger, half to the
    /// holder), the challenger gets its bond back, the holder gets the escrow back.
    function slash(uint256 id) external {
        Withdrawal storage w = ws[id];
        if (w.state != State.Challenged) revert BadState(w.state);
        if (block.timestamp <= w.respondBy) revert TooEarly(w.respondBy);
        w.state = State.Slashed;
        address op = w.operator;
        uint256 b = bondPerClaim;
        lockedBond[op] -= b;
        bonded[op] -= b;
        escrowed -= w.amount;
        owedToken[w.holder] += w.amount;
        owedNative[w.holder] += b - b / 2;
        owedNative[w.challenger] += challengeBond + b / 2;
        emit Slashed(id, op, w.challenger, b);
    }

    function _reimburse(uint256 id, Withdrawal storage w) private {
        w.state = State.Paid;
        address op = w.operator;
        lockedBond[op] -= bondPerClaim;
        escrowed -= w.amount;
        owedToken[op] += w.amount;
        emit Reimbursed(id, op, w.amount);
    }

    /// Pays the caller everything it is owed (native and tokens).
    function withdraw() external nonReentrant {
        uint256 n = owedNative[msg.sender];
        uint256 t = owedToken[msg.sender];
        if (n == 0 && t == 0) revert Nothing();
        owedNative[msg.sender] = 0;
        owedToken[msg.sender] = 0;
        tokenLiabilities -= t;
        emit Withdrawn(msg.sender, n, t);
        if (t != 0 && !token.transfer(msg.sender, t)) revert TokenFailed();
        if (n != 0) {
            (bool ok, ) = msg.sender.call{value: n}("");
            if (!ok) revert PayFailed();
        }
    }

    // ---------------------------------------------------------------- views

    function count() external view returns (uint256) { return ws.length; }

    function withdrawal(uint256 id) external view returns (Withdrawal memory) { return ws[id]; }

    /// The OP_RETURN payload an operator's payment must carry for withdrawal `id`.
    function commitment(uint256 id, address operator) public pure returns (bytes memory) {
        return abi.encodePacked(TAG, bytes8(bytes32(id << 192)), operator); // the low 8 bytes of id, big-endian (ids < 2^64)
    }

    /// Checks a raw (non-witness) Bitcoin transaction: output `vout` pays the script with keccak256 `scriptHash`
    /// at least `sats`, and some output is OP_RETURN <commitment(id, operator)> (34 bytes). Reverts with BadPayment.
    function checkPayment(bytes calldata t, uint32 vout, uint64 sats, bytes32 scriptHash, uint256 id, address operator) public pure {
        (uint64 value, bytes32 h, bool committed) = _scan(t, vout, keccak256(abi.encodePacked(bytes2(0x6a22), commitment(id, operator))));
        if (h != scriptHash) revert BadPayment(3);
        if (value < sats) revert BadPayment(4);
        if (!committed) revert BadPayment(5);
    }

    /// Output `vout`'s value and script hash, and whether another output's script hashes to `want`.
    function _scan(bytes calldata t, uint32 vout, bytes32 want) private pure returns (uint64 value, bytes32 h, bool committed) {
        uint256 p = _skipInputs(t);
        uint256 outs;
        (outs, p) = _varint(t, p);
        if (vout >= outs) revert BadPayment(2);
        for (uint256 i = 0; i < outs; i++) {
            (uint64 v, bytes32 sh, uint256 next) = _output(t, p);
            p = next;
            if (i == vout) { value = v; h = sh; }
            else if (sh == want) committed = true;
        }
        if (p + 4 != t.length) revert BadPayment(1);      // locktime, nothing after
    }

    /// Where the outputs start (after the version and the inputs).
    function _skipInputs(bytes calldata t) private pure returns (uint256 p) {
        uint256 n;
        (n, p) = _varint(t, 4);                           // version, then the input count
        for (uint256 i = 0; i < n; i++) {
            uint256 len;
            (len, p) = _varint(t, p + 36);                // outpoint, then the script length
            p += len + 4;                                 // script, sequence
        }
    }

    /// One output at `p`: its value, the keccak256 of its script, where the next output starts.
    function _output(bytes calldata t, uint256 p) private pure returns (uint64 value, bytes32 h, uint256 next) {
        if (p + 8 > t.length) revert BadPayment(1);
        value = _le64(t, p);
        uint256 len;
        (len, p) = _varint(t, p + 8);
        if (p + len > t.length) revert BadPayment(1);
        h = keccak256(t[p:p + len]);
        next = p + len;
    }

    function _varint(bytes calldata t, uint256 p) private pure returns (uint256 v, uint256 q) {
        if (p >= t.length) revert BadPayment(1);
        uint8 f = uint8(t[p]);
        if (f < 0xfd) return (f, p + 1);
        uint256 size = f == 0xfd ? 2 : f == 0xfe ? 4 : 8;
        if (p + 1 + size > t.length) revert BadPayment(1);
        for (uint256 i = 0; i < size; i++) v = v | (uint256(uint8(t[p + 1 + i])) << (8 * i));
        q = p + 1 + size;
    }

    function _le64(bytes calldata t, uint256 p) private pure returns (uint64 v) {
        for (uint256 i = 0; i < 8; i++) v = v | (uint64(uint8(t[p + i])) << uint64(8 * i));
    }
}

contracts/SaphanBundles.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan bundles: calls across several routes that all run, or are all refunded
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited.
///
///         A bundle gathers money from several chains on ZETAPHY, then runs every step in ONE ZETAPHY transaction:
///           1. create(legs, plan, deadline): each leg is money the bundle waits for, from a source chain through its
///              ZetaphyGateway (depositAndCall with target = this contract, data = abi.encode(id, leg)), or on ZETAPHY
///              itself (fund). The plan is fixed now (its hash is stored): calls on ZETAPHY (tokens to a target, then
///              target.onSaphanBundle) and calls to other chains (ZetaphyGateway.withdrawAndCall). It must spend
///              exactly what the legs bring, token by token.
///           2. Each leg's delivery is proven by the route itself: a Gateway call is attested by the route's lanes
///              (its deposit address is the call's hash), and the tokens must really be here (balance check), so a
///              fake "gateway" cannot fund a leg.
///           3. execute(id, plan): anyone, once every leg is in and before the deadline. Every step runs or none does
///              (a failing step reverts the whole transaction; the bundle stays funded and can be run again).
///              Calls to other chains carry the Gateway's call hash (event OutSent): track or refund them there.
///           4. Past the deadline without execute: refund(id); each funded leg is owed back to its refundTo on
///              ZETAPHY (claim, a pull). A leg that arrives too late is refused, so the Gateway refunds it on its chain.
///         No signer, no admin: the escrow follows the bundle's own rules.

interface IBundleToken {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function approve(address spender, uint256 v) external returns (bool);
}

interface IBundleGateway {
    function token() external view returns (address);
    function withdrawAndCall(address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo)
        external payable returns (bytes32);
}

/// What a contract on ZETAPHY implements to be a step of a bundle (it must check msg.sender is SaphanBundles).
interface ISaphanBundleTarget {
    function onSaphanBundle(bytes32 id, address creator, address token, uint256 amount, bytes calldata data) external;
}

contract SaphanBundles {
    struct Leg {
        uint256 srcChainId;   // where the money comes from (block.chainid for a leg funded here)
        address gateway;      // ZetaphyGateway of that route; zero: funded here with fund()
        address token;        // what arrives on ZETAPHY (token(X) for a route)
        address sender;       // who must send it (on its chain; zero: anyone)
        uint256 amount;       // what the leg brings (more is owed back to refundTo)
        address refundTo;     // on ZETAPHY: who gets the leg back when the bundle does not run
    }

    /// A step on ZETAPHY: `amount` of `token` to `target`, then target.onSaphanBundle(id, creator, token, amount, data).
    struct Action {
        address target;
        address token;
        uint256 amount;
        uint64 gasLimit;
        bytes data;
    }

    /// A step to another chain: ZetaphyGateway.withdrawAndCall with data = abi.encode(id, creator, data).
    struct Out {
        address gateway;
        address token;        // must be the Gateway's token
        address target;
        uint256 amount;
        uint256 maxFee;
        uint64 gasLimit;
        address revertTo;     // on that chain: who gets the money when the call fails there
        bytes data;
    }

    struct Plan {
        Action[] actions;
        Out[] outs;
    }

    enum Status { None, Open, Funded, Executed, Refunded }

    struct Bundle {
        address creator;
        uint64 deadline;
        Status status;
        uint8 legCount;
        uint8 fundedCount;
        bytes32 planHash;
    }

    bytes32 public constant TAG = keccak256("saphan/bundle/v1");
    uint256 public constant MAX_LEGS = 8;
    uint256 public constant MAX_STEPS = 8;
    uint64 public constant MAX_DURATION = 30 days;

    mapping(bytes32 => Bundle) public bundles;
    mapping(bytes32 => mapping(uint256 => Leg)) public legs;
    mapping(bytes32 => mapping(uint256 => bool)) public legFunded;
    /// Tokens this contract holds for bundles and refunds (what arrives beyond it is a new leg's money).
    mapping(address => uint256) public accounted;
    /// token -> who -> refunds and excess, taken with claim(token).
    mapping(address => mapping(address => uint256)) public owed;
    uint256 public nonce;
    uint256 private entered;

    event Created(bytes32 indexed id, address indexed creator, uint64 deadline, Leg[] legs, Plan plan);
    event LegFunded(bytes32 indexed id, uint256 indexed leg, uint256 srcChainId, address sender, uint256 received);
    event Executed(bytes32 indexed id, address indexed executor);
    event OutSent(bytes32 indexed id, uint256 indexed step, bytes32 callHash);
    event Refunded(bytes32 indexed id);
    event Claimed(address indexed who, address indexed token, uint256 amount);

    error BadBundle(uint256 code);
    error NotOpen();
    error TooLate();
    error TooEarly();
    error WrongLeg();
    error Short(uint256 have, uint256 need);
    error WrongPlan();
    error Fee();
    error PayFailed();
    error Reentered();

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    function planHash(Plan calldata plan) public pure returns (bytes32) { return keccak256(abi.encode(TAG, plan)); }

    /// Opens a bundle. Every token the legs bring is spent exactly by the plan.
    function create(Leg[] calldata legs_, Plan calldata plan, uint64 deadline) external returns (bytes32 id) {
        if (legs_.length == 0 || legs_.length > MAX_LEGS) revert BadBundle(0);
        uint256 steps = plan.actions.length + plan.outs.length;
        if (steps == 0 || steps > MAX_STEPS) revert BadBundle(1);
        if (deadline <= block.timestamp || deadline > block.timestamp + MAX_DURATION) revert BadBundle(2);
        for (uint256 i = 0; i < legs_.length; i++) {
            Leg calldata l = legs_[i];
            if (l.amount == 0 || l.token == address(0) || l.refundTo == address(0)) revert BadBundle(10 + i);
            if (l.gateway == address(0) && l.srcChainId != block.chainid) revert BadBundle(10 + i);
            _spentEqualsBrought(legs_, plan, l.token);
        }
        for (uint256 i = 0; i < plan.actions.length; i++) {
            Action calldata a = plan.actions[i];
            if (a.target == address(0) || a.target == address(this) || a.amount == 0) revert BadBundle(20 + i);
            _spentEqualsBrought(legs_, plan, a.token);
        }
        for (uint256 i = 0; i < plan.outs.length; i++) {
            Out calldata o = plan.outs[i];
            if (o.gateway == address(0) || o.target == address(0) || o.revertTo == address(0) || o.amount == 0 || o.maxFee > o.amount) revert BadBundle(30 + i);
            _spentEqualsBrought(legs_, plan, o.token);
        }
        id = keccak256(abi.encode(TAG, block.chainid, address(this), msg.sender, nonce++));
        bundles[id] = Bundle(msg.sender, deadline, Status.Open, uint8(legs_.length), 0, planHash(plan));
        for (uint256 i = 0; i < legs_.length; i++) legs[id][i] = legs_[i];
        emit Created(id, msg.sender, deadline, legs_, plan);
    }

    function _spentEqualsBrought(Leg[] calldata legs_, Plan calldata plan, address token) private pure {
        uint256 brought = 0;
        uint256 spent = 0;
        for (uint256 i = 0; i < legs_.length; i++) if (legs_[i].token == token) brought += legs_[i].amount;
        for (uint256 i = 0; i < plan.actions.length; i++) if (plan.actions[i].token == token) spent += plan.actions[i].amount;
        for (uint256 i = 0; i < plan.outs.length; i++) if (plan.outs[i].token == token) spent += plan.outs[i].amount;
        if (brought != spent) revert BadBundle(40);
    }

    /// A leg from another chain: called by that route's ZetaphyGateway, after it handed this contract the tokens.
    /// data = abi.encode(bundle id, leg index). Reverting (late, already funded, wrong leg) makes the Gateway refund it.
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256, bytes calldata data) external nonReentrant {
        (bytes32 id, uint256 i) = abi.decode(data, (bytes32, uint256));
        Leg storage l = _openLeg(id, i);
        if (l.gateway == address(0) || msg.sender != l.gateway || l.srcChainId != srcChainId || token != l.token
            || (l.sender != address(0) && l.sender != sender)) revert WrongLeg();
        // the tokens must be here: what this contract holds beyond what it owes is this leg's
        uint256 received = IBundleToken(token).balanceOf(address(this)) - accounted[token];
        _funded(id, i, l, received, srcChainId, sender);
    }

    /// A leg funded on ZETAPHY: its sender (or anyone, when the leg names none) pays it (approve this contract first).
    function fund(bytes32 id, uint256 i) external nonReentrant {
        Leg storage l = _openLeg(id, i);
        if (l.gateway != address(0) || (l.sender != address(0) && l.sender != msg.sender)) revert WrongLeg();
        IBundleToken t = IBundleToken(l.token);
        uint256 need = accounted[l.token] + l.amount;
        _funded(id, i, l, l.amount, block.chainid, msg.sender);
        if (!t.transferFrom(msg.sender, address(this), l.amount)) revert PayFailed();
        uint256 have = t.balanceOf(address(this));
        if (have < need) revert Short(have, need); // a token that delivers less than it says
    }

    function _openLeg(bytes32 id, uint256 i) private view returns (Leg storage) {
        Bundle storage b = bundles[id];
        if (b.status != Status.Open) revert NotOpen();
        if (block.timestamp > b.deadline) revert TooLate();
        if (i >= b.legCount || legFunded[id][i]) revert WrongLeg();
        return legs[id][i];
    }

    function _funded(bytes32 id, uint256 i, Leg storage l, uint256 received, uint256 srcChainId, address sender) private {
        if (received < l.amount) revert Short(received, l.amount);
        legFunded[id][i] = true;
        accounted[l.token] += received;
        if (received > l.amount) owed[l.token][l.refundTo] += received - l.amount;
        Bundle storage b = bundles[id];
        b.fundedCount += 1;
        if (b.fundedCount == b.legCount) b.status = Status.Funded;
        emit LegFunded(id, i, srcChainId, sender, received);
    }

    /// Anyone, once every leg is in and before the deadline: runs the whole plan, all or nothing.
    /// msg.value: the Mailbox fees of the calls to other chains (fees[i] for outs[i], ZetaphyGateway.quoteWithdraw);
    /// what the Gateways give back comes back to the caller.
    function execute(bytes32 id, Plan calldata plan, uint256[] calldata fees) external payable nonReentrant {
        Bundle storage b = bundles[id];
        if (b.status != Status.Funded) revert NotOpen();
        if (block.timestamp > b.deadline) revert TooLate();
        if (planHash(plan) != b.planHash || fees.length != plan.outs.length) revert WrongPlan();
        uint256 total = 0;
        for (uint256 i = 0; i < fees.length; i++) total += fees[i];
        uint256 paid = msg.value;
        if (paid != total) revert Fee();
        // effects first: the bundle is spent
        b.status = Status.Executed;
        _spend(id, b.legCount);
        address creator = b.creator;
        uint256 before = address(this).balance - paid;
        _actions(id, creator, plan.actions);
        for (uint256 i = 0; i < plan.outs.length; i++) {
            Out calldata o = plan.outs[i];
            if (IBundleGateway(o.gateway).token() != o.token) revert WrongPlan();
            if (!IBundleToken(o.token).approve(o.gateway, o.amount)) revert PayFailed();
            // fees[i], written as its share of what the caller paid (paid == total): only the caller's own ether
            // ever goes to a Gateway; this contract holds none of its own
            bytes32 h = IBundleGateway(o.gateway).withdrawAndCall{value: paid * fees[i] / (total == 0 ? 1 : total)}(o.target,
                abi.encode(id, creator, o.data), o.amount, o.maxFee, o.gasLimit, o.revertTo);
            emit OutSent(id, i, h);
        }
        emit Executed(id, msg.sender);
        uint256 change = address(this).balance - before;
        if (change > 0) {
            (bool ok, ) = msg.sender.call{value: change}("");
            if (!ok) revert PayFailed();
        }
    }

    /// The legs' tokens leave the escrow (the plan spends exactly them).
    function _spend(bytes32 id, uint256 legCount) private {
        for (uint256 i = 0; i < legCount; i++) {
            Leg storage l = legs[id][i];
            accounted[l.token] -= l.amount;
        }
    }

    /// The steps on ZETAPHY: tokens to each target, then its call (a revert undoes the whole execute).
    function _actions(bytes32 id, address creator, Action[] calldata actions) private {
        for (uint256 i = 0; i < actions.length; i++) {
            Action calldata a = actions[i];
            if (!IBundleToken(a.token).transfer(a.target, a.amount)) revert PayFailed();
            ISaphanBundleTarget(a.target).onSaphanBundle{gas: a.gasLimit}(id, creator, a.token, a.amount, a.data);
        }
    }

    /// Anyone, after the deadline of a bundle that did not run: each funded leg is owed back to its refundTo.
    function refund(bytes32 id) external {
        Bundle storage b = bundles[id];
        if (b.status != Status.Open && b.status != Status.Funded) revert NotOpen();
        if (block.timestamp <= b.deadline) revert TooEarly();
        b.status = Status.Refunded;
        for (uint256 i = 0; i < b.legCount; i++) {
            if (!legFunded[id][i]) continue;
            Leg storage l = legs[id][i];
            owed[l.token][l.refundTo] += l.amount;
        }
        emit Refunded(id);
    }

    /// The caller's refunds and excess in `token`.
    function claim(address token) external nonReentrant {
        uint256 v = owed[token][msg.sender];
        if (v == 0) revert WrongLeg();
        owed[token][msg.sender] = 0;
        accounted[token] -= v;
        emit Claimed(msg.sender, token, v);
        if (!IBundleToken(token).transfer(msg.sender, v)) revert PayFailed();
    }

    /// The Gateways give back what the Mailbox did not take.
    receive() external payable {}
}

contracts/SaphanChallenges.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SaphanChallenges: anyone can stop a bad bridge transfer before it mints, and the lanes that vouched for it pay
/// @notice One per route (its BridgeAirlock), on ZETAPHY. Testnet only, not audited (docs/SAPHAN-SAFETY.md).
///
///         Challenge  anyone, with a bond, names a transfer that is not released yet. The airlock HOLDS it (its release
///                    waits; the airlock's challenger role can only delay, like a marker).
///         Vote       Neuro runners (NeuroJobs workers that are active, with a clean track record) vote uphold or reject
///                    within votingPeriod.
///         Upheld     (quorum of uphold votes) the airlock VETOES the transfer for good: nothing mints. The challenger
///                    gets the bond back, and the bonds of the lanes that attested the transfer are slashed: half to the
///                    challenger, half to the reserve (insurance).
///         Rejected   (quorum of reject votes, or the period ends without an upheld quorum) the hold is lifted and the
///                    challenger's bond goes to the transfer's ZETAPHY recipient, for the delay.
///
///         Lane bonds: the operator of a lane (the key behind lane2, or a NeuroLane's controller) bonds it here; a bond
///         leaves only after UNBOND_DELAY (longer than any open challenge), and can be slashed until then.
///         Every payout is pulled by its owner (claim); governance moves the reserve to an insurance pool.

interface IChallengeAirlock {
    function transfers(bytes32 id) external view returns (uint64 readyFrom, uint8 attestations, bool released, bool vetoed, uint64 readyEpoch, bool held);
    function attestedBy(bytes32 id, address lane) external view returns (bool);
    function lanes() external view returns (address[] memory);
    function isLane(address lane) external view returns (bool);
    function hold(bytes32 id) external;
    function unhold(bytes32 id) external;
    function veto(bytes32 id, string calldata reason) external;
}

interface IChallengeRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

contract SaphanChallenges {
    enum State { None, Open, Upheld, Rejected }

    struct Challenge {
        address challenger;
        address recipient;      // the transfer's ZETAPHY recipient (gets the bond when the challenge fails)
        uint128 bond;
        uint64 deadline;
        uint16 upheld;
        uint16 rejected;
        State state;
    }

    struct LaneBond {
        address operator;
        uint128 amount;
        uint64 unlockAt;        // 0: bonded; else when the operator may take it
    }

    IChallengeAirlock public immutable airlock;
    IChallengeRunners public immutable runners;
    address public governance;
    uint256 public challengeBond;
    uint64 public votingPeriod;
    uint16 public quorum;
    uint32 public minAgreed;
    uint64 public constant UNBOND_DELAY = 14 days;
    uint64 public constant MAX_VOTING = 7 days;

    mapping(bytes32 => Challenge) public challenges;
    mapping(bytes32 => mapping(address => bool)) public voted;
    mapping(address => LaneBond) public laneBonds;
    /// What each address may take (claim): returned bonds, rewards, compensation.
    mapping(address => uint256) public credit;
    /// Slashed bonds kept for insurance (moved by governance, e.g. into HackInsurance).
    uint256 public reserve;
    uint256 public openCount;

    event Opened(bytes32 indexed id, address indexed challenger, address indexed recipient, uint256 bond, uint64 deadline, string reason);
    event Voted(bytes32 indexed id, address indexed runner, bool uphold);
    event Resolved(bytes32 indexed id, bool upheld, uint256 slashed);
    event Slashed(bytes32 indexed id, address indexed lane, uint256 amount);
    event LaneBonded(address indexed lane, address indexed operator, uint256 amount);
    event UnbondRequested(address indexed lane, uint64 unlockAt);
    event LaneUnbonded(address indexed lane, uint256 amount);
    event Claimed(address indexed who, uint256 amount);
    event ReservePaid(address indexed to, uint256 amount);
    event ParamsSet(uint256 challengeBond, uint64 votingPeriod, uint16 quorum, uint32 minAgreed);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotRunner();
    error Bond(uint256 needed);
    error WrongState();
    error TooLate();
    error TooEarly();
    error Twice();
    error NotOperator();
    error NotLane();
    error Nothing();
    error PayFailed();
    error Params();

    uint256 private entered;
    modifier nonReentrant() { require(entered == 0, "reentered"); entered = 1; _; entered = 0; }
    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    constructor(IChallengeAirlock airlock_, IChallengeRunners runners_, address governance_, uint256 bond_, uint64 votingPeriod_, uint16 quorum_, uint32 minAgreed_) {
        require(address(airlock_) != address(0) && address(runners_) != address(0) && governance_ != address(0), "config");
        airlock = airlock_;
        runners = runners_;
        governance = governance_;
        _setParams(bond_, votingPeriod_, quorum_, minAgreed_);
    }

    function _setParams(uint256 bond_, uint64 votingPeriod_, uint16 quorum_, uint32 minAgreed_) private {
        if (bond_ == 0 || votingPeriod_ < 1 hours || votingPeriod_ > MAX_VOTING || quorum_ == 0) revert Params();
        challengeBond = bond_;
        votingPeriod = votingPeriod_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        emit ParamsSet(bond_, votingPeriod_, quorum_, minAgreed_);
    }

    /// Governance; never while a challenge is open (the rules of an open challenge do not change under it).
    function setParams(uint256 bond_, uint64 votingPeriod_, uint16 quorum_, uint32 minAgreed_) external onlyGov {
        if (openCount != 0) revert WrongState();
        _setParams(bond_, votingPeriod_, quorum_, minAgreed_);
    }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    // ---------------------------------------------------------------- challenges

    /// Anyone: holds a transfer that lanes attested but the airlock has not released, with the bond (msg.value).
    function open(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount, string calldata reason)
        external payable returns (bytes32 id)
    {
        if (msg.value != challengeBond) revert Bond(challengeBond);
        id = keccak256(abi.encode(srcChainId, srcContract, srcNonce, sender, to, amount)); // = BridgeAirlock.transferId
        Challenge storage c = challenges[id];
        if (c.state != State.None) revert Twice(); // one challenge per transfer, ever
        uint64 deadline = uint64(block.timestamp) + votingPeriod;
        challenges[id] = Challenge(msg.sender, to, uint128(msg.value), deadline, 0, 0, State.Open);
        openCount += 1;
        // last: the airlock refuses (and this whole call reverts) unless lanes attested it and it is not released or vetoed
        airlock.hold(id);
        emit Opened(id, msg.sender, to, msg.value, deadline, reason);
    }

    /// A Neuro runner's vote (active, at least minAgreed agreed jobs, no more rejected than agreed); once per challenge.
    function vote(bytes32 id, bool uphold) external {
        Challenge storage c = challenges[id];
        if (c.state != State.Open) revert WrongState();
        if (block.timestamp > c.deadline) revert TooLate();
        if (msg.sender == c.challenger) revert NotRunner();
        if (voted[id][msg.sender]) revert Twice();
        voted[id][msg.sender] = true;
        if (uphold) c.upheld += 1; else c.rejected += 1;
        emit Voted(id, msg.sender, uphold);
        // who may vote, checked last (a read of NeuroJobs; a vote from anyone else reverts whole)
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    /// Anyone: settles a challenge once a quorum agrees, or after its deadline (no upheld quorum then = rejected).
    function resolve(bytes32 id) external nonReentrant {
        Challenge storage c = challenges[id];
        if (c.state != State.Open) revert WrongState();
        bool upheld = c.upheld >= quorum;
        bool rejected = !upheld && (c.rejected >= quorum || block.timestamp > c.deadline);
        if (!upheld && !rejected) revert TooEarly();
        openCount -= 1;
        uint256 slashed;
        if (upheld) {
            c.state = State.Upheld;
            credit[c.challenger] += c.bond;
            // the lanes that vouched for it lose their bonds: half to the challenger, half to the reserve
            address[] memory ls = airlock.lanes();
            for (uint256 i = 0; i < ls.length; i++) {
                if (!airlock.attestedBy(id, ls[i])) continue;
                LaneBond storage b = laneBonds[ls[i]];
                uint256 v = b.amount;
                if (v == 0) continue;
                b.amount = 0;
                slashed += v;
                emit Slashed(id, ls[i], v);
            }
            credit[c.challenger] += slashed / 2;
            reserve += slashed - slashed / 2;
            emit Resolved(id, true, slashed);
            airlock.veto(id, "Saphan challenge upheld");
        } else {
            c.state = State.Rejected;
            credit[c.recipient] += c.bond;
            emit Resolved(id, false, 0);
            airlock.unhold(id);
        }
    }

    // ---------------------------------------------------------------- lane bonds

    /// A lane's operator bonds it (the first bonder of a lane is its operator; only the operator adds).
    function bondLane(address lane) external payable {
        if (msg.value == 0) revert Nothing();
        LaneBond storage b = laneBonds[lane];
        if (b.operator == address(0)) b.operator = msg.sender;
        if (b.operator != msg.sender) revert NotOperator();
        b.amount += uint128(msg.value);
        b.unlockAt = 0;
        emit LaneBonded(lane, msg.sender, msg.value);
        if (!airlock.isLane(lane)) revert NotLane(); // checked last (a read of the airlock): not a lane, the whole call reverts
    }

    /// The operator starts leaving: the bond can still be slashed until UNBOND_DELAY has passed.
    function requestUnbond(address lane) external {
        LaneBond storage b = laneBonds[lane];
        if (b.operator != msg.sender) revert NotOperator();
        b.unlockAt = uint64(block.timestamp) + UNBOND_DELAY;
        emit UnbondRequested(lane, b.unlockAt);
    }

    function unbond(address lane) external nonReentrant {
        LaneBond storage b = laneBonds[lane];
        if (b.operator != msg.sender) revert NotOperator();
        if (b.unlockAt == 0 || block.timestamp < b.unlockAt) revert TooEarly();
        uint256 v = b.amount;
        if (v == 0) revert Nothing();
        b.amount = 0;
        b.unlockAt = 0;
        credit[msg.sender] += v;
        emit LaneUnbonded(lane, v);
    }

    // ---------------------------------------------------------------- payouts

    /// What the caller is owed (bonds back, rewards, compensation, unbonded lane bonds).
    function claim() external nonReentrant {
        uint256 v = credit[msg.sender];
        if (v == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
        emit Claimed(msg.sender, v);
    }

    /// Governance moves slashed bonds to insurance (e.g. HackInsurance's pool): credited there, taken with claim().
    function payReserve(address to, uint256 amount) external onlyGov {
        if (amount == 0 || amount > reserve) revert Nothing();
        reserve -= amount;
        credit[to] += amount;
        emit ReservePaid(to, amount);
    }
}

contracts/SaphanCheckpointer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ICheckpointToken {
    function totalSupply() external view returns (uint256);
}

interface ICheckpointMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
}

/// @title SaphanCheckpointer: ZETAPHY's heartbeat to one route's lockbox (the escape hatch's clock)
/// @notice On ZETAPHY, one per route. Anyone calls beat() (at most once per MIN_INTERVAL, paying the Mailbox fee):
///         it sends HyperlaneLockBoxV2 a heartbeat through ZETAPHY's Mailbox (our validators sign it like a release).
///         While heartbeats arrive, the lockbox stays out of escape; if ZETAPHY stops (halted, censored, cut off) for
///         the lockbox's ESCAPE_AFTER, holders can leave on the source chain (docs/SAPHAN-SAFETY.md).
///         No admin; everything it may do is fixed at deploy. Testnet only, not audited.
contract SaphanCheckpointer {
    bytes32 public constant HEARTBEAT_TAG = keccak256("saphan/heartbeat/v1");
    uint64 public constant MIN_INTERVAL = 1 hours;

    ICheckpointMailbox public immutable mailbox;   // ZETAPHY's Mailbox
    uint32 public immutable destinationDomain;     // the source chain's Hyperlane domain
    bytes32 public immutable recipient;            // the route's HyperlaneLockBoxV2 there
    ICheckpointToken public immutable token;       // token(X): its supply rides on every heartbeat (proof of reserves)
    uint64 public seq;
    uint64 public lastAt;

    event Beat(uint64 indexed seq, bytes32 messageId);

    error TooSoon(uint64 next);
    error Fee(uint256 needed);

    constructor(ICheckpointMailbox mailbox_, uint32 destinationDomain_, bytes32 recipient_, ICheckpointToken token_) {
        require(address(mailbox_) != address(0) && recipient_ != bytes32(0) && address(token_) != address(0), "config");
        token = token_;
        mailbox = mailbox_;
        destinationDomain = destinationDomain_;
        recipient = recipient_;
    }

    /// The heartbeat body (192 bytes), as the lockbox reads it: with token(X)'s total supply now.
    function body(uint64 n) public view returns (bytes memory) {
        return abi.encode(HEARTBEAT_TAG, block.chainid, address(this), n, uint64(block.timestamp), token.totalSupply());
    }

    function quote() external view returns (uint256) { return mailbox.quoteDispatch(destinationDomain, recipient, body(seq + 1)); }

    /// Anyone: one heartbeat. msg.value: exactly the Mailbox fee (quote()).
    function beat() external payable returns (bytes32 messageId) {
        if (block.timestamp < uint256(lastAt) + MIN_INTERVAL) revert TooSoon(lastAt + MIN_INTERVAL);
        uint64 n = seq + 1;
        seq = n;
        lastAt = uint64(block.timestamp);
        bytes memory b = body(n);
        uint256 fee = mailbox.quoteDispatch(destinationDomain, recipient, b);
        if (msg.value != fee) revert Fee(fee);
        messageId = mailbox.dispatch{value: fee}(destinationDomain, recipient, b);
        emit Beat(n, messageId);
    }
}

contracts/SaphanGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan Gateway: call contracts across chains in one transaction, with automatic refunds
/// @notice Two contracts per source chain X, on top of the existing route (HyperlaneLockBoxV2 on X; HyperlaneLane,
///         BridgeAirlock, BridgeGuard and HyperlaneOutbox on ZETAPHY), none of which changes:
///
///         X -> ZETAPHY  SaphanSourceGateway.depositAndCall(target, data, ...) locks ETH in the route's lockbox
///                       to a DEPOSIT ADDRESS that is derived from the whole call (CREATE2 of ZetaphyGateway,
///                       salt = the call's hash). The route mints token(X) to that address after its usual checks
///                       (two independent lanes, quarantine, Neuro, threat registry, daily limits). Anyone then
///                       hands the call to ZetaphyGateway.execute, which empties the address (a one-shot CREATE2,
///                       so each call runs once), pays the executor its fee in token(X) and calls
///                       target.onSaphanCall. If the call fails, the tokens go back to X (to revertTo, optionally
///                       calling its onSaphanRevert), or stay on ZETAPHY for abortTo when the way back is closed.
///         ZETAPHY -> X  ZetaphyGateway.withdrawAndCall(target, data, ...) burns token(X) through the route's
///                       outbox toward a deposit address of SaphanSourceGateway on X. After the lockbox's delay
///                       and checks it is paid ETH (anyone claims the release); anyone then runs
///                       SaphanSourceGateway.execute: executor fee in
///                       ETH, then target.onSaphanCall; if that fails, the ETH is kept for revertTo (claim()).
///
///         Why a derived address and not a second message: the lanes that attest the transfer attest the address,
///         and so the call itself (its hash). A call cannot be swapped or replayed without breaking keccak256, and
///         the Gateway adds no new signer, relayer or admin to trust.
///
///         Gas: the executor's fee (maxFee, set by the caller) comes out of the amount, in what moved (token(X) on
///         ZETAPHY, ETH on X): the user needs no gas coin on the destination chain.
///         Testnet only, not audited.

interface ISaphanToken {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

interface ISaphanLockBox {
    function lock(address to, uint256 amount) external payable returns (bytes32);
    function quoteLock(address to, uint256 amount) external view returns (uint256);
    function claim(bytes32 id) external;
}

interface ISaphanOutbox {
    function send(address to, uint256 amount) external payable returns (bytes32);
    function quoteSend(address to, uint256 amount) external view returns (uint256);
}

interface ISaphanAirlock {
    function release(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external;
}

/// What a contract on ZETAPHY implements to be called from another chain (it must check msg.sender is the Gateway).
interface ISaphanCallee {
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256 amount, bytes calldata data) external;
}

/// What a contract on a source chain implements to be called from ZETAPHY (it must check msg.sender is the Gateway).
interface ISaphanReceiver {
    function onSaphanCall(uint256 srcChainId, address sender, bytes calldata data) external payable;
    function onSaphanRevert(address sender, uint256 nonce, bytes calldata message) external payable;
}

/// @notice The deposit address of one call: deployed once (CREATE2, salt = the call's hash) by the Gateway that owns
///         it; its constructor hands everything it holds (`token`, or ETH when token is zero) to that Gateway.
///         Once deployed it accepts nothing more, so a call can never run twice.
contract SaphanDepositAddress {
    constructor(address token) {
        if (token == address(0)) {
            (bool ok, ) = msg.sender.call{value: address(this).balance}("");
            require(ok, "sweep");
        } else {
            uint256 b = ISaphanToken(token).balanceOf(address(this));
            if (b > 0) require(ISaphanToken(token).transfer(msg.sender, b), "sweep");
        }
    }
}

/// Shared by both Gateways: the call formats, their hashes and deposit addresses.
abstract contract SaphanCalls {
    /// X -> ZETAPHY: a call made on X (depositAndCall).
    struct InCall {
        uint256 srcChainId;   // X
        address srcGateway;   // SaphanSourceGateway on X
        uint256 nonce;        // its count of calls
        address sender;       // who called on X
        address target;       // the contract on ZETAPHY
        uint256 amount;       // ETH locked = token(X) minted to the deposit address
        uint256 maxFee;       // the executor's fee, in token(X)
        uint64 gasLimit;      // gas the target gets
        address revertTo;     // on X: who gets the refund when the call fails (zero: no way back, abortTo keeps it)
        bool callOnRevert;    // the refund calls revertTo.onSaphanRevert(sender, nonce, revertMessage)
        address abortTo;      // on ZETAPHY: who may claim the tokens when the refund cannot be sent
        bytes data;
        bytes revertMessage;
    }

    /// ZETAPHY -> X: a call made on ZETAPHY (withdrawAndCall), or the refund of a failed InCall (kind REVERT).
    struct OutCall {
        uint256 dstChainId;   // X
        address dstGateway;   // SaphanSourceGateway on X
        address srcGateway;   // ZetaphyGateway
        uint256 nonce;        // ZetaphyGateway's count of out calls
        address sender;       // who called on ZETAPHY (for a refund: who called on X)
        address target;       // the contract on X (for a refund: revertTo)
        uint256 amount;       // token(X) burned = ETH paid to the deposit address on X
        uint256 maxFee;       // the executor's fee, in ETH
        uint64 gasLimit;
        address revertTo;     // on X: who gets the ETH when the call fails
        uint8 kind;           // CALL or REVERT
        bytes data;           // CALL: the call's data; REVERT: abi.encode(the InCall's nonce, its revertMessage)
    }

    uint8 internal constant CALL = 0;
    uint8 internal constant REVERT = 1;
    bytes32 public constant IN_TAG = keccak256("saphan/gateway/in/v1");
    bytes32 public constant OUT_TAG = keccak256("saphan/gateway/out/v1");
    /// Gas kept back for what follows the target's call (fee transfer, refund, events).
    uint256 internal constant RESERVE = 120_000;

    uint256 private entered;

    error Reentered();
    error WrongGateway();
    error NotFunded(uint256 have, uint256 need);
    error LowGas(uint256 need);
    error NotSelf();
    error BadCall();
    error PayFailed();
    error Fee(uint256 needed);

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    function hashIn(InCall calldata p) public pure returns (bytes32) { return keccak256(abi.encode(IN_TAG, p)); }
    function hashOut(OutCall memory p) public pure returns (bytes32) { return keccak256(abi.encode(OUT_TAG, p)); }

    /// The deposit address `gateway` derives for a call hash, for a token (zero = ETH). The init code is the creation
    /// code followed by the token as one 32-byte word (= abi.encode(token), the constructor's argument).
    function depositAddressOf(address gateway, bytes32 callHash, address token) public pure returns (address) {
        bytes32 code = keccak256(abi.encodePacked(type(SaphanDepositAddress).creationCode, uint256(uint160(token))));
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), gateway, callHash, code)))));
    }

    /// Empties this Gateway's deposit address of a call into the Gateway (once: a second time reverts).
    function _sweep(bytes32 callHash, address token) internal {
        bytes memory code = abi.encodePacked(type(SaphanDepositAddress).creationCode, uint256(uint160(token)));
        address at;
        assembly { at := create2(0, add(code, 0x20), mload(code), callHash) }
        if (at == address(0)) revert BadCall(); // used already
    }

    /// The executor cannot starve the target: enough gas for it and what follows, checked before it runs.
    function _gasFor(uint64 gasLimit) internal view {
        uint256 need = uint256(gasLimit) + uint256(gasLimit) / 63 + RESERVE;
        if (gasleft() < need) revert LowGas(need);
    }

    /// ETH to the caller (its change, its fee, what it claims): the Gateways pay no one else directly.
    function _payCaller(uint256 v) internal {
        if (v == 0) return;
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
    }
}

/// @title ZetaphyGateway: the ZETAPHY side, one per source chain X (its token, airlock and outbox)
contract ZetaphyGateway is SaphanCalls {
    ISaphanToken public immutable token;     // token(X), minted by the route's BridgeGuard
    ISaphanOutbox public immutable outbox;   // HyperlaneOutbox(X): burns token(X), releases ETH on X
    ISaphanAirlock public immutable airlock; // BridgeAirlock(X)
    address public immutable lockbox;        // HyperlaneLockBoxV2 on X (the airlock's source contract)
    uint256 public immutable remoteChainId;  // X
    address public immutable deployer;
    address public remote;                   // SaphanSourceGateway on X (set once, then fixed)
    uint256 public outNonce;
    /// Tokens kept on ZETAPHY for whoever a failed call names as abortTo (claimAborted).
    mapping(address => uint256) public aborted;

    event RemoteSet(address remote);
    event Executed(bytes32 indexed callHash, uint256 indexed nonce, address indexed target, uint256 amount, uint256 fee, address executor);
    event CallFailed(bytes32 indexed callHash, bytes reason);
    event Reverted(bytes32 indexed callHash, address indexed revertTo, uint256 amount, bool withCall, bytes32 outHash);
    event Aborted(bytes32 indexed callHash, address indexed abortTo, uint256 amount);
    event AbortClaimed(address indexed who, uint256 amount);
    event OutCallDispatched(bytes32 indexed callHash, bytes32 messageId);
    /// Every call toward X (a withdrawAndCall, or a refund that calls revertTo back): what the executor on X runs.
    event OutCallSent(bytes32 indexed callHash, uint256 indexed nonce, address indexed sender, address depositAddress, OutCall call);

    constructor(ISaphanToken token_, ISaphanOutbox outbox_, ISaphanAirlock airlock_, address lockbox_, uint256 remoteChainId_) {
        require(address(token_) != address(0) && address(outbox_) != address(0) && address(airlock_) != address(0)
            && lockbox_ != address(0) && remoteChainId_ != 0, "config");
        token = token_;
        outbox = outbox_;
        airlock = airlock_;
        lockbox = lockbox_;
        remoteChainId = remoteChainId_;
        deployer = msg.sender;
    }

    /// Once, by the deployer: the Gateway on X (deployed after this one, it names this one).
    function setRemote(address r) external {
        require(msg.sender == deployer && remote == address(0) && r != address(0), "remote");
        remote = r;
        emit RemoteSet(r);
    }

    function depositAddress(InCall calldata p) external view returns (address) { return depositAddressOf(address(this), hashIn(p), address(token)); }

    /// Anyone, once the route minted the call's tokens to its deposit address: runs the call. With `release`, it first
    /// asks the airlock to release the lock (the lockbox's nonce `lockNonce`, from its Locked event) when nobody did yet;
    /// the airlock reverts unless every check of the route passes (a wrong nonce names a transfer that is not there).
    /// msg.value: only for a refund to X (the Mailbox fee, in ZTPHY); the rest comes back to the executor.
    function execute(InCall calldata p, bool release, uint256 lockNonce) external payable nonReentrant returns (bool ok) {
        if (remote == address(0) || p.srcChainId != remoteChainId || p.srcGateway != remote) revert WrongGateway();
        if (p.target == address(0) || p.amount == 0 || p.maxFee > p.amount) revert BadCall();
        bytes32 h = hashIn(p);
        address at = depositAddressOf(address(this), h, address(token));
        if (release && token.balanceOf(at) < p.amount) airlock.release(p.srcChainId, lockbox, lockNonce, p.srcGateway, at, p.amount);
        uint256 have = token.balanceOf(at);
        if (have < p.amount) revert NotFunded(have, p.amount); // never deploy (and burn) an address before its tokens came
        _gasFor(p.gasLimit);
        _sweep(h, address(token));
        uint256 extra = have - p.amount;              // tokens someone else sent to the address go with the call's own
        uint256 fee = p.maxFee;
        uint256 rest = p.amount - fee + extra;
        if (fee > 0 && !token.transfer(msg.sender, fee)) revert PayFailed();
        uint256 before = address(this).balance - msg.value;
        try this.deliverIn(p, rest) {
            ok = true;
            emit Executed(h, p.nonce, p.target, rest, fee, msg.sender);
        } catch (bytes memory reason) {
            emit CallFailed(h, reason);
            _refund(p, h, rest, address(this).balance - before);
        }
        _payCaller(address(this).balance - before); // what the Mailbox did not take
    }

    /// Only the Gateway itself (so a failing call undoes its token transfer): tokens to the target, then its call.
    function deliverIn(InCall calldata p, uint256 amount) external {
        if (msg.sender != address(this)) revert NotSelf();
        if (!token.transfer(p.target, amount)) revert PayFailed();
        ISaphanCallee(p.target).onSaphanCall{gas: p.gasLimit}(p.srcChainId, p.sender, address(token), amount, p.data);
    }

    /// A failed InCall: back to X through the outbox (plainly, or as a REVERT call to revertTo's onSaphanRevert);
    /// kept for abortTo when there is no way back (no revertTo, or the outbound route refuses: closed, paused, limit).
    function _refund(InCall calldata p, bytes32 h, uint256 amount, uint256 value) private {
        address abortTo = p.abortTo == address(0) ? p.sender : p.abortTo;
        if (p.revertTo != address(0)) {
            address to = p.revertTo;
            bytes32 oh = bytes32(0);
            if (p.callOnRevert) {
                OutCall memory o = OutCall(remoteChainId, remote, address(this), outNonce++, p.sender, p.revertTo, amount, 0, p.gasLimit,
                    p.revertTo, REVERT, abi.encode(p.nonce, p.revertMessage));
                oh = hashOut(o);
                to = depositAddressOf(remote, oh, address(0));
                emit OutCallSent(oh, o.nonce, p.sender, to, o);
            }
            uint256 fee = outbox.quoteSend(to, amount);
            if (value < fee) revert Fee(fee); // the executor pays the way back; run again with it
            try outbox.send{value: fee}(to, amount) returns (bytes32) {
                emit Reverted(h, p.revertTo, amount, p.callOnRevert, oh);
                return;
            } catch {} // the outbound route refused: keep the tokens here
        }
        aborted[abortTo] += amount;
        emit Aborted(h, abortTo, amount);
    }

    /// Tokens kept for the caller by failed calls.
    function claimAborted() external nonReentrant {
        uint256 v = aborted[msg.sender];
        require(v > 0, "nothing");
        aborted[msg.sender] = 0;
        if (!token.transfer(msg.sender, v)) revert PayFailed();
        emit AbortClaimed(msg.sender, v);
    }

    /// ZETAPHY -> X: burns `amount` of token(X) from the caller (approve this Gateway first) and has the lockbox on X
    /// pay a deposit address of the Gateway there, which then calls `target` (or pays revertTo when that fails).
    /// msg.value: the Mailbox fee in ZTPHY (quoteWithdraw); the rest comes back.
    function withdrawAndCall(address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo)
        external payable nonReentrant returns (bytes32 h)
    {
        if (remote == address(0)) revert WrongGateway();
        if (target == address(0) || revertTo == address(0) || amount == 0 || maxFee > amount) revert BadCall();
        OutCall memory o = OutCall(remoteChainId, remote, address(this), outNonce++, msg.sender, target, amount, maxFee, gasLimit, revertTo, CALL, data);
        h = hashOut(o);
        address at = depositAddressOf(remote, h, address(0));
        if (!token.transferFrom(msg.sender, address(this), amount)) revert PayFailed();
        uint256 before = address(this).balance - msg.value;
        bytes32 messageId = outbox.send{value: msg.value}(at, amount); // burns this Gateway's tokens through the guard's outbound route
        emit OutCallSent(h, o.nonce, msg.sender, at, o);
        emit OutCallDispatched(h, messageId);
        _payCaller(address(this).balance - before); // the outbox's change
    }

    /// The Mailbox fee of a withdrawAndCall.
    function quoteWithdraw(uint256 amount) external view returns (uint256) { return outbox.quoteSend(address(1), amount); }

    /// The OutCall a withdrawAndCall made (what the executor on X needs), rebuilt from its event and inputs.
    function outCall(uint256 nonce, address sender, address target, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo,
        uint8 kind, bytes calldata data) external view returns (OutCall memory)
    {
        return OutCall(remoteChainId, remote, address(this), nonce, sender, target, amount, maxFee, gasLimit, revertTo, kind, data);
    }

    receive() external payable {}
}

/// @title SaphanSourceGateway: the side on a source chain X (its HyperlaneLockBoxV2)
contract SaphanSourceGateway is SaphanCalls {
    ISaphanLockBox public immutable lockbox;
    address public immutable remote;          // ZetaphyGateway(X) on ZETAPHY
    address public immutable remoteToken;     // token(X) on ZETAPHY
    uint256 public immutable zetaphyChainId;  // 77390
    uint256 public nonce;
    /// ETH of failed calls, kept for their revertTo (claim).
    mapping(address => uint256) public owed;

    event DepositAndCall(bytes32 indexed callHash, uint256 indexed nonce, address indexed sender, address depositAddress, InCall call);
    event Executed(bytes32 indexed callHash, address indexed target, uint256 amount, uint256 fee, address executor);
    event CallFailed(bytes32 indexed callHash, bytes reason);
    event Owed(address indexed to, uint256 amount);
    event Dispatched(address indexed depositAddress, bytes32 messageId);

    constructor(ISaphanLockBox lockbox_, address remote_, address remoteToken_, uint256 zetaphyChainId_) {
        require(address(lockbox_) != address(0) && remote_ != address(0) && remoteToken_ != address(0) && zetaphyChainId_ != 0, "config");
        lockbox = lockbox_;
        remote = remote_;
        remoteToken = remoteToken_;
        zetaphyChainId = zetaphyChainId_;
    }

    /// The InCall a depositAndCall with these inputs makes now (for quotes and wallets).
    function inCall(address sender, address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit,
        address revertTo, bool callOnRevert, address abortTo, bytes calldata revertMessage) public view returns (InCall memory)
    {
        return InCall(block.chainid, address(this), nonce, sender, target, amount, maxFee, gasLimit, revertTo, callOnRevert, abortTo, data, revertMessage);
    }

    function _hashInMem(InCall memory p) private pure returns (bytes32) { return keccak256(abi.encode(IN_TAG, p)); }

    /// The lockbox's Mailbox fee for a depositAndCall of `amount` (pay amount + this).
    function quoteDeposit(uint256 amount) external view returns (uint256) { return lockbox.quoteLock(address(1), amount); }

    /// X -> ZETAPHY: locks `amount` of ETH for a call of `target` on ZETAPHY. msg.value = amount + the Mailbox fee
    /// (quoteDeposit); the rest comes back. revertTo defaults to the caller; abortTo (on ZETAPHY) too.
    function depositAndCall(address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo,
        bool callOnRevert, address abortTo, bytes calldata revertMessage) external payable nonReentrant returns (bytes32 h)
    {
        if (target == address(0) || amount == 0 || maxFee > amount) revert BadCall();
        InCall memory p = InCall(block.chainid, address(this), nonce++, msg.sender, target, amount, maxFee, gasLimit,
            revertTo == address(0) ? msg.sender : revertTo, callOnRevert, abortTo == address(0) ? msg.sender : abortTo, data, revertMessage);
        h = _hashInMem(p);
        address at = depositAddressOf(remote, h, remoteToken);
        _lock(at, amount);
        emit DepositAndCall(h, p.nonce, msg.sender, at, p);
    }

    /// Locks `amount` to `at` (the Mailbox fee from msg.value); the caller gets its change, never ETH owed to others.
    function _lock(address at, uint256 amount) private {
        uint256 fee = lockbox.quoteLock(at, amount);
        if (msg.value < amount + fee) revert Fee(amount + fee);
        uint256 before = address(this).balance - msg.value;
        bytes32 messageId = lockbox.lock{value: amount + fee}(at, amount);
        emit Dispatched(at, messageId);
        _payCaller(address(this).balance - before);
    }

    function depositAddress(OutCall calldata o) external view returns (address) { return depositAddressOf(address(this), hashOut(o), address(0)); }

    /// Anyone, once the lockbox paid the call's deposit address (anyone claims the queued release from the lockbox
    /// first, once it is due): runs the call. When it fails, the ETH waits for revertTo (claim()).
    /// Effects before interactions: the refund is recorded first, and the delivered call cancels it as its own first
    /// step; a failing call undoes that cancel with the rest of itself, so the refund stands.
    function execute(OutCall calldata o) external nonReentrant returns (bool ok) {
        if (o.dstChainId != block.chainid || o.dstGateway != address(this) || o.srcGateway != remote) revert WrongGateway();
        if (o.target == address(0) || o.revertTo == address(0) || o.amount == 0 || o.maxFee > o.amount || o.kind > REVERT) revert BadCall();
        bytes32 h = hashOut(o);
        address at = depositAddressOf(address(this), h, address(0));
        uint256 have = at.balance;
        if (have < o.amount) revert NotFunded(have, o.amount);
        _gasFor(o.gasLimit);
        uint256 fee = o.maxFee;
        uint256 rest = have - fee;            // all of the address's ETH moves (the sweep below takes `have`)
        owed[o.revertTo] += rest;             // the refund, unless the call goes through
        _sweep(h, address(0));
        _payCaller(fee);
        try this.deliverOut{value: rest}(o) {
            ok = true;
            emit Executed(h, o.target, rest, fee, msg.sender);
        } catch (bytes memory reason) {
            emit CallFailed(h, reason);
            emit Owed(o.revertTo, rest);
        }
    }

    /// Only the Gateway itself: cancels the call's refund, then the target's call with the ETH (a failure undoes both).
    function deliverOut(OutCall calldata o) external payable {
        if (msg.sender != address(this)) revert NotSelf();
        owed[o.revertTo] -= msg.value;
        if (o.kind == CALL) {
            ISaphanReceiver(o.target).onSaphanCall{value: msg.value, gas: o.gasLimit}(zetaphyChainId, o.sender, o.data);
        } else {
            (uint256 n, bytes memory m) = abi.decode(o.data, (uint256, bytes));
            ISaphanReceiver(o.target).onSaphanRevert{value: msg.value, gas: o.gasLimit}(o.sender, n, m);
        }
    }

    /// ETH of failed calls, kept for their revertTo.
    function claim() external nonReentrant {
        uint256 v = owed[msg.sender];
        require(v > 0, "nothing");
        owed[msg.sender] = 0;
        _payCaller(v);
    }

    receive() external payable {}
}

contracts/SaphanIntents.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan intents: "I give A, I want at least B on chain Y by time T", filled by solvers, gated by Neuro
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited.
///
///   SaphanIntents (ZETAPHY) holds the A of every intent in escrow (token(X) of a route, or any ERC-20 on ZETAPHY).
///     open(order) on ZETAPHY, or from chain X in one transaction: SaphanSourceGateway.depositAndCall with
///     target = this contract and data = abi.encode(order).
///   A solver pays the recipient B from its own money on chain Y (SaphanFillRelay.fill: the ETH goes to the recipient
///     at once) and is repaid the A on ZETAPHY once the fill is proven:
///       - by the fill's own message: SaphanFillRelay sends it through Y's Hyperlane Mailbox; the Mailbox on ZETAPHY
///         checks the ISM (the Hyperlane validators that already attest the routes' transfers) before handle();
///       - or optimistically, faster: claimFill with a bond; with no challenge within challengeWindow, settle() repays.
///         A challenge (with its own bond) leaves only the fill's message to decide: if it does not come within
///         disputePeriod the claim was false and the solver's bond goes to the challenger.
///     Fills on ZETAPHY itself (Y = ZETAPHY, B an ERC-20) are atomic: fillLocal pays the recipient and repays the
///     solver in one transaction.
///   Neuro gates fills: when the intent opens, the recipient is looked up in NeuroScore (Neuro's on-chain risk model)
///     and the ThreatRegistry. High risk, held or enforced: the intent is refused (from X the Gateway refunds it).
///     Medium risk: fills count only after riskDelay (notBefore), so watchers and guardians get time. A solver the
///     ThreatRegistry holds cannot fill or claim.
///   Unfilled past deadline + grace: refund() owes A back to refundTo (pull). The grace lets a fill made just before
///     the deadline still arrive.
///   Every payout is a pull (claim / withdrawBonds); no admin; the deployer only names each chain's relay, once.

interface IIntentToken {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

/// NeuroScore.scoreOf: level 1 low, 2 medium, 3 high (thresholds set with the model by governance).
interface IIntentScores {
    function scoreOf(address who) external view returns (bool known, int256 score, uint8 level);
}

/// ThreatRegistry's views (Reason as its uint8 value).
interface IIntentThreats {
    function isAddressHeld(uint256 chainId, address who) external view returns (bool, uint8);
    function isAddressEnforced(uint256 chainId, address who) external view returns (bool, uint8);
}

interface IIntentMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256);
}

contract SaphanIntents {
    struct Order {
        address tokenIn;      // what the user gives, on ZETAPHY (token(X) when it came from chain X)
        uint256 amountIn;     // A
        uint32 dstDomain;     // chain Y (its Hyperlane domain = its chain id); ZETAPHY's own id: filled here
        address tokenOut;     // Y = ZETAPHY: the ERC-20 wanted; another chain: zero (its native coin)
        address recipient;    // on Y
        uint256 minOut;       // B
        uint64 deadline;      // T (a fill must happen by then)
        address refundTo;     // on ZETAPHY: who gets A back when nobody fills
    }

    enum Status { None, Open, Claimed, Filled, Refunded }

    struct Intent {
        Order order;
        Status status;
        uint64 notBefore;     // risk delay: fills count from then on
        address solver;       // an optimistic claim: who claims to have filled
        address repayTo;
        uint64 claimedAt;
        address challenger;
    }

    bytes32 public constant TAG = keccak256("saphan/intent/v1");
    uint64 public constant MAX_DURATION = 30 days;
    uint8 public constant MEDIUM = 2;
    uint8 public constant HIGH = 3;

    IIntentScores public immutable scores;     // NeuroScore (zero: no score check)
    IIntentThreats public immutable threats;   // ThreatRegistry (zero: no flag check)
    address public immutable mailbox;          // the Mailbox on ZETAPHY
    /// Hyperlane reads it: the ISM for fill messages (e.g. a routing ISM over each chain's Hyperlane validators).
    address public immutable interchainSecurityModule;
    uint256 public immutable claimBond;        // ZTPHY a solver puts up per optimistic claim
    uint256 public immutable challengeBond;    // ZTPHY a challenger puts up
    uint64 public immutable challengeWindow;
    uint64 public immutable disputePeriod;     // how long a challenged claim waits for the fill's message
    uint64 public immutable grace;             // after the deadline, before a refund
    uint64 public immutable riskDelay;         // medium risk: fills count only after this
    address public immutable deployer;

    mapping(uint32 => bytes32) public relays;  // SaphanFillRelay per chain (set once each)
    mapping(bytes32 => Intent) private _intents;
    uint256 public nonce;
    mapping(address => uint256) public accounted;                    // tokens held for intents and payouts
    mapping(address => mapping(address => uint256)) public owed;     // token -> who -> amount (claim)
    mapping(address => uint256) public bonds;                        // ZTPHY owed (withdrawBonds)
    uint256 private entered;

    event RelaySet(uint32 indexed domain, bytes32 relay);
    event Opened(bytes32 indexed id, address indexed owner, uint256 srcChainId, Order order, uint64 notBefore);
    event Filled(bytes32 indexed id, address indexed solver, address repayTo, uint256 amountOut, bool proven);
    event FillRejected(bytes32 indexed id, address indexed solver, uint32 origin);
    event ClaimMade(bytes32 indexed id, address indexed solver, address repayTo);
    event Challenged(bytes32 indexed id, address indexed challenger);
    event Slashed(bytes32 indexed id, address indexed solver, address indexed to, uint256 amount);
    event Refunded(bytes32 indexed id, address refundTo, uint256 amount);
    event Claimed(address indexed who, address indexed token, uint256 amount);

    error BadOrder(uint256 code);
    error Risky(uint8 level);
    error SolverHeld();
    error WrongStatus();
    error TooEarly();
    error TooLate();
    error Bond(uint256 needed);
    error NotMailbox();
    error NoValue();
    error WrongSender();
    error Short(uint256 have, uint256 need);
    error Nothing();
    error PayFailed();
    error Reentered();

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    constructor(IIntentScores scores_, IIntentThreats threats_, address mailbox_, address ism_, uint256 claimBond_, uint256 challengeBond_,
        uint64 challengeWindow_, uint64 disputePeriod_, uint64 grace_, uint64 riskDelay_)
    {
        require(mailbox_ != address(0) && claimBond_ > 0 && challengeBond_ > 0 && challengeWindow_ > 0 && disputePeriod_ > challengeWindow_, "config");
        scores = scores_;
        threats = threats_;
        mailbox = mailbox_;
        interchainSecurityModule = ism_;
        claimBond = claimBond_;
        challengeBond = challengeBond_;
        challengeWindow = challengeWindow_;
        disputePeriod = disputePeriod_;
        grace = grace_;
        riskDelay = riskDelay_;
        deployer = msg.sender;
    }

    /// Once per chain, by the deployer: the SaphanFillRelay there (deployed after this contract, it names this one).
    function setRelay(uint32 domain, address relay) external {
        require(msg.sender == deployer && relays[domain] == bytes32(0) && relay != address(0) && domain != uint32(block.chainid), "relay");
        relays[domain] = bytes32(uint256(uint160(relay)));
        emit RelaySet(domain, relays[domain]);
    }

    function intentOf(bytes32 id) external view returns (Intent memory) { return _intents[id]; }

    // ---- risk (Neuro) ----

    /// When fills to `recipient` on `domain` may count: now, now + riskDelay (medium risk), or never (reverts Risky).
    function riskGate(address recipient, uint32 domain) public view returns (uint64 notBefore) {
        if (address(threats) != address(0)) {
            (bool held, ) = threats.isAddressHeld(domain, recipient);
            (bool enforced, ) = threats.isAddressEnforced(domain, recipient);
            if (held || enforced) revert Risky(HIGH);
        }
        notBefore = uint64(block.timestamp);
        if (address(scores) != address(0)) {
            (bool known, , uint8 level) = scores.scoreOf(recipient);
            if (known && level >= HIGH) revert Risky(level);
            if (known && level == MEDIUM) notBefore += riskDelay;
        }
    }

    function _solverOk(address solver) private view {
        if (address(threats) == address(0)) return;
        (bool held, ) = threats.isAddressHeld(block.chainid, solver);
        if (held) revert SolverHeld();
    }

    // ---- opening ----

    /// Opens an intent with the caller's tokens (approve this contract for amountIn of tokenIn first).
    function open(Order calldata o) external nonReentrant returns (bytes32 id) {
        uint64 notBefore = _check(o);
        uint256 need = accounted[o.tokenIn] + o.amountIn;
        id = _open(o, notBefore, msg.sender, block.chainid, o.amountIn);
        if (!IIntentToken(o.tokenIn).transferFrom(msg.sender, address(this), o.amountIn)) revert PayFailed();
        uint256 have = IIntentToken(o.tokenIn).balanceOf(address(this));
        if (have < need) revert Short(have, need);
    }

    /// From chain X through its ZetaphyGateway (data = abi.encode(order)), after the Gateway handed over the tokens.
    /// Reverting (risky recipient, bad order, tokens missing) makes the Gateway refund the user on X.
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256, bytes calldata data) external nonReentrant {
        Order memory o = abi.decode(data, (Order));
        if (token != o.tokenIn) revert BadOrder(0);
        uint64 notBefore = _check(o);
        uint256 received = IIntentToken(token).balanceOf(address(this)) - accounted[token];
        if (received < o.amountIn) revert Short(received, o.amountIn);
        _open(o, notBefore, sender, srcChainId, received);
    }

    /// The checks of an order and its risk gate: when fills may count (reverts when the order cannot open).
    function check(Order calldata o) external view returns (uint64 notBefore) { return _check(o); }

    function _check(Order memory o) private view returns (uint64) {
        if (o.tokenIn == address(0) || o.amountIn == 0 || o.recipient == address(0) || o.minOut == 0 || o.refundTo == address(0)) revert BadOrder(1);
        if (o.deadline <= block.timestamp || o.deadline > block.timestamp + MAX_DURATION) revert BadOrder(2);
        if (o.dstDomain == uint32(block.chainid)) { if (o.tokenOut == address(0)) revert BadOrder(3); }
        else if (o.tokenOut != address(0) || relays[o.dstDomain] == bytes32(0)) revert BadOrder(4);
        return riskGate(o.recipient, o.dstDomain);
    }

    function _open(Order memory o, uint64 notBefore, address owner, uint256 srcChainId, uint256 received) private returns (bytes32 id) {
        id = keccak256(abi.encode(TAG, block.chainid, address(this), nonce++));
        Intent storage it = _intents[id];
        it.order = o;
        it.status = Status.Open;
        it.notBefore = notBefore;
        accounted[o.tokenIn] += received;
        if (received > o.amountIn) owed[o.tokenIn][o.refundTo] += received - o.amountIn;
        emit Opened(id, owner, srcChainId, o, notBefore);
    }

    // ---- fills ----

    /// Y = ZETAPHY: the solver pays the recipient `amountOut` (>= minOut) of tokenOut and is owed A at once.
    function fillLocal(bytes32 id, uint256 amountOut, address repayTo) external nonReentrant {
        Intent storage it = _intents[id];
        Order storage o = it.order;
        if (it.status != Status.Open || o.dstDomain != uint32(block.chainid)) revert WrongStatus();
        if (block.timestamp < it.notBefore) revert TooEarly();
        if (block.timestamp > o.deadline) revert TooLate();
        if (amountOut < o.minOut || repayTo == address(0)) revert BadOrder(5);
        _solverOk(msg.sender);
        riskGate(o.recipient, o.dstDomain); // still not risky now
        _repay(id, it, repayTo);
        emit Filled(id, msg.sender, repayTo, amountOut, true);
        if (!IIntentToken(o.tokenOut).transferFrom(msg.sender, o.recipient, amountOut)) revert PayFailed();
    }

    /// The Mailbox, after the ISM checked it: a fill made on chain `origin` by its SaphanFillRelay.
    /// A fill that does not match an open intent is consumed and rejected (it never blocks the Mailbox).
    function handle(uint32 origin, bytes32 sender, bytes calldata body) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (sender == bytes32(0) || sender != relays[origin]) revert WrongSender();
        (bytes32 id, address recipient, uint256 amount, uint64 filledAt, address solver, address repayTo) =
            abi.decode(body, (bytes32, address, uint256, uint64, address, address));
        Intent storage it = _intents[id];
        Order storage o = it.order;
        bool ok = (it.status == Status.Open || it.status == Status.Claimed) && o.dstDomain == origin && o.recipient == recipient
            && amount >= o.minOut && filledAt <= o.deadline && filledAt >= it.notBefore && repayTo != address(0);
        if (!ok) { emit FillRejected(id, solver, origin); return; }
        if (it.status == Status.Claimed) {
            if (it.solver == solver) {
                bonds[solver] += claimBond;                                  // the claim was true
                if (it.challenger != address(0)) bonds[solver] += challengeBond; // and the challenge was not
            } else _slash(id, it, it.challenger != address(0) ? it.challenger : solver); // someone else filled: the claim was false
        }
        _repay(id, it, repayTo);
        emit Filled(id, solver, repayTo, amount, true);
    }

    function _repay(bytes32, Intent storage it, address repayTo) private {
        it.status = Status.Filled;
        it.solver = address(0);
        it.challenger = address(0);
        owed[it.order.tokenIn][repayTo] += it.order.amountIn;
    }

    /// The claimer's bond goes to `to` (with its own challenge bond back when `to` is the challenger).
    function _slash(bytes32 id, Intent storage it, address to) private {
        uint256 v = claimBond + (to == it.challenger ? challengeBond : 0);
        bonds[to] += v;
        emit Slashed(id, it.solver, to, claimBond);
    }

    // ---- optimistic claims ----

    /// A solver that filled on chain Y claims it now, with `claimBond` (msg.value, exactly), instead of waiting for
    /// the fill's message. Repaid by settle() after challengeWindow unless someone challenges.
    function claimFill(bytes32 id, address repayTo) external payable {
        Intent storage it = _intents[id];
        if (msg.value != claimBond) revert Bond(claimBond);
        if (it.status != Status.Open || it.order.dstDomain == uint32(block.chainid) || repayTo == address(0)) revert WrongStatus();
        if (block.timestamp < it.notBefore) revert TooEarly();
        if (block.timestamp > uint256(it.order.deadline) + grace) revert TooLate();
        _solverOk(msg.sender);
        it.status = Status.Claimed;
        it.solver = msg.sender;
        it.repayTo = repayTo;
        it.claimedAt = uint64(block.timestamp);
        emit ClaimMade(id, msg.sender, repayTo);
    }

    /// Anyone, within challengeWindow, with `challengeBond`: "this claim is false". Only the fill's message can then
    /// repay the solver.
    function challenge(bytes32 id) external payable {
        Intent storage it = _intents[id];
        if (msg.value != challengeBond) revert Bond(challengeBond);
        if (it.status != Status.Claimed || it.challenger != address(0)) revert WrongStatus();
        if (block.timestamp > uint256(it.claimedAt) + challengeWindow) revert TooLate();
        it.challenger = msg.sender;
        emit Challenged(id, msg.sender);
    }

    /// Anyone, after an unchallenged window: the claim stands; the solver is repaid and gets its bond back.
    function settle(bytes32 id) external {
        Intent storage it = _intents[id];
        if (it.status != Status.Claimed || it.challenger != address(0)) revert WrongStatus();
        if (block.timestamp <= uint256(it.claimedAt) + challengeWindow) revert TooEarly();
        bonds[it.solver] += claimBond;
        emit Filled(id, it.solver, it.repayTo, 0, false);
        _repay(id, it, it.repayTo);
    }

    /// Anyone, when a challenged claim saw no fill message within disputePeriod: the claim was false. The solver's
    /// bond goes to the challenger, and the intent is open again.
    function timeout(bytes32 id) external {
        Intent storage it = _intents[id];
        if (it.status != Status.Claimed || it.challenger == address(0)) revert WrongStatus();
        if (block.timestamp <= uint256(it.claimedAt) + disputePeriod) revert TooEarly();
        _slash(id, it, it.challenger);
        it.status = Status.Open;
        it.solver = address(0);
        it.challenger = address(0);
    }

    // ---- refunds and payouts ----

    /// Anyone, after deadline + grace with no fill: A is owed back to refundTo.
    function refund(bytes32 id) external {
        Intent storage it = _intents[id];
        if (it.status != Status.Open) revert WrongStatus();
        if (block.timestamp <= uint256(it.order.deadline) + grace) revert TooEarly();
        it.status = Status.Refunded;
        owed[it.order.tokenIn][it.order.refundTo] += it.order.amountIn;
        emit Refunded(id, it.order.refundTo, it.order.amountIn);
    }

    /// The caller's repayments and refunds in `token`.
    function claim(address token) external nonReentrant {
        uint256 v = owed[token][msg.sender];
        if (v == 0) revert Nothing();
        owed[token][msg.sender] = 0;
        accounted[token] -= v;
        emit Claimed(msg.sender, token, v);
        if (!IIntentToken(token).transfer(msg.sender, v)) revert PayFailed();
    }

    /// The caller's bonds (back, or won) in ZTPHY.
    function withdrawBonds() external nonReentrant {
        uint256 v = bonds[msg.sender];
        if (v == 0) revert Nothing();
        bonds[msg.sender] = 0;
        emit Claimed(msg.sender, address(0), v);
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
    }
}

/// @title SaphanFillRelay: on chain Y, a solver pays an intent's recipient and tells SaphanIntents through Hyperlane
contract SaphanFillRelay {
    IIntentMailbox public immutable mailbox;  // Y's Mailbox
    uint32 public immutable zetaphyDomain;
    bytes32 public immutable intents;         // SaphanIntents on ZETAPHY
    mapping(bytes32 => address) public filledBy; // each intent is filled once here

    event Fill(bytes32 indexed id, address indexed solver, address indexed recipient, uint256 amount, address repayTo, bytes32 messageId);

    error Filled();
    error Fee(uint256 needed);
    error PayFailed();

    constructor(IIntentMailbox mailbox_, uint32 zetaphyDomain_, address intents_) {
        require(address(mailbox_) != address(0) && intents_ != address(0), "config");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        intents = bytes32(uint256(uint160(intents_)));
    }

    function body(bytes32 id, address recipient, uint256 amount, address solver, address repayTo) public view returns (bytes memory) {
        return abi.encode(id, recipient, amount, uint64(block.timestamp), solver, repayTo);
    }

    /// The Mailbox fee of a fill (pay amount + this).
    function quote(bytes32 id, address recipient, uint256 amount, address repayTo) external view returns (uint256) {
        return mailbox.quoteDispatch(zetaphyDomain, intents, body(id, recipient, amount, msg.sender, repayTo));
    }

    /// The solver: pays `recipient` `amount` now (msg.value = amount + the Mailbox fee, exactly) and sends the
    /// proof of it to ZETAPHY, where `repayTo` will be owed the intent's A. Check the intent first (intentOf on
    /// ZETAPHY: open, this recipient, amount >= minOut, before its deadline and after notBefore): a fill that does
    /// not match is rejected there and not repaid.
    function fill(bytes32 id, address recipient, uint256 amount, address repayTo) external payable returns (bytes32 messageId) {
        if (filledBy[id] != address(0)) revert Filled();
        filledBy[id] = msg.sender;
        bytes memory b = body(id, recipient, amount, msg.sender, repayTo);
        uint256 fee = mailbox.quoteDispatch(zetaphyDomain, intents, b);
        if (msg.value != amount + fee) revert Fee(amount + fee);
        messageId = mailbox.dispatch{value: fee}(zetaphyDomain, intents, b);
        emit Fill(id, msg.sender, recipient, amount, repayTo, messageId);
        (bool ok, ) = recipient.call{value: msg.value - fee}("");
        if (!ok) revert PayFailed();
    }
}

contracts/SaphanLiquidity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// HyperlaneLockBoxV2 as this contract sees it: its daily release limit, which a guardian may only lower.
interface ILiquidityLockbox {
    function dailyLimit() external view returns (uint256);
    function lowerDailyLimit(uint256 v) external;
}

/// @title SaphanLiquidityBounds: route limits that follow observed flows, inside bounds governance set
/// @notice Saphan PR 6, item S9 (docs/SAPHAN-PR6.md). Testnet only, not audited.
///
///         Governance (the chain's ZetaphyTimelock: every change waits its delay) sets, per route, the band a route's
///         daily release limit may move in: [min, max], the largest step per update (maxStepBps of the current
///         target) and the shortest time between updates (minInterval). The rebalancer (a key governance names: the
///         off-chain policy in src/saphanliquidity.js runs with it; an LLM may only hint, the policy is deterministic)
///         moves the route's TARGET inside that band, one bounded step at a time. Whatever the rebalancer's key does,
///         the target stays in [min, max] and moves at most maxStepBps per minInterval.
///
///         What the target does on chain: this contract is a GUARDIAN of the route's lockbox, and guardians can only
///         reduce risk. applyDown(route) (anyone) lowers the lockbox's daily limit to the target when the target is
///         lower. Raising a limit stays with the lockbox's governance (its timelock, 48 h): the policy prints the
///         proposal (src/saphanliquidity.js raiseProposal), and governance never has to accept it.
///         The rebalancer may also drop a target to `min` at once (an incident: emergencyMin), never raise it at once.
///
///         No other power: this contract calls nothing but lowerDailyLimit, holds no money, has no upgrade.
contract SaphanLiquidityBounds {
    struct Bounds {
        address lockbox;      // the route's HyperlaneLockBoxV2 (this contract must be one of its guardians)
        uint128 min;          // wei per day
        uint128 max;
        uint16 maxStepBps;    // largest change per update, in bps of the current target
        uint32 minInterval;   // seconds between updates
    }

    struct Target {
        uint128 value;
        uint64 updatedAt;
        bytes32 hint;         // hash of the policy input (flows, LLM hint) that produced it: anyone can recompute it
    }

    uint16 public constant MAX_STEP_BPS = 5000;
    uint32 public constant MIN_INTERVAL = 1 hours;

    address public immutable governance;
    address public rebalancer;
    mapping(bytes32 => Bounds) public bounds;
    mapping(bytes32 => Target) public target;

    event BoundsSet(bytes32 indexed route, address lockbox, uint128 min, uint128 max, uint16 maxStepBps, uint32 minInterval);
    event RebalancerSet(address rebalancer);
    event TargetSet(bytes32 indexed route, uint128 from, uint128 to, bytes32 hint);
    event AppliedDown(bytes32 indexed route, uint256 from, uint256 to);

    error NotGovernance();
    error NotRebalancer();
    error NoRoute();
    error BadBounds();
    error OutOfBounds(uint128 min, uint128 max);
    error StepTooBig(uint256 most);
    error TooSoon(uint64 at);
    error NothingToLower();

    constructor(address governance_) {
        require(governance_ != address(0), "governance");
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyRebalancer() { if (msg.sender != rebalancer) revert NotRebalancer(); _; }

    /// Governance: a route's band. The target is pulled into the new band at once.
    function setBounds(bytes32 route, address lockbox, uint128 min, uint128 max, uint16 maxStepBps, uint32 minInterval) external onlyGov {
        if (lockbox == address(0) || min > max || max == 0 || maxStepBps == 0 || maxStepBps > MAX_STEP_BPS || minInterval < MIN_INTERVAL) revert BadBounds();
        bounds[route] = Bounds(lockbox, min, max, maxStepBps, minInterval);
        Target storage t = target[route];
        uint128 v = t.value < min ? min : t.value > max ? max : t.value;
        if (v != t.value) { emit TargetSet(route, t.value, v, bytes32(0)); t.value = v; }
        emit BoundsSet(route, lockbox, min, max, maxStepBps, minInterval);
    }

    /// Governance: who runs the policy (zero: nobody; the targets stay as they are).
    function setRebalancer(address r) external onlyGov {
        rebalancer = r;
        emit RebalancerSet(r);
    }

    /// The rebalancer: a new target for `route`, inside the band, at most one step from the current one.
    function propose(bytes32 route, uint128 value, bytes32 hint) external onlyRebalancer {
        Bounds memory b = bounds[route];
        if (b.lockbox == address(0)) revert NoRoute();
        Target storage t = target[route];
        if (t.updatedAt != 0 && block.timestamp < uint256(t.updatedAt) + b.minInterval) revert TooSoon(t.updatedAt + b.minInterval);
        if (value < b.min || value > b.max) revert OutOfBounds(b.min, b.max);
        uint256 step = maxStep(route);
        uint256 diff = value > t.value ? value - t.value : t.value - value;
        if (diff > step) revert StepTooBig(step);
        emit TargetSet(route, t.value, value, hint);
        t.value = value;
        t.updatedAt = uint64(block.timestamp);
        t.hint = hint;
    }

    /// The rebalancer, in an incident: the target drops to the band's minimum at once (no step, no interval).
    function emergencyMin(bytes32 route) external onlyRebalancer {
        Bounds memory b = bounds[route];
        if (b.lockbox == address(0)) revert NoRoute();
        Target storage t = target[route];
        emit TargetSet(route, t.value, b.min, keccak256("emergency"));
        t.value = b.min;
        t.updatedAt = uint64(block.timestamp);
    }

    /// Anyone: when the target is below the lockbox's daily limit, lowers the limit to it (a guardian call).
    function applyDown(bytes32 route) external {
        Bounds memory b = bounds[route];
        if (b.lockbox == address(0)) revert NoRoute();
        uint256 cur = ILiquidityLockbox(b.lockbox).dailyLimit();
        uint256 v = target[route].value;
        if (v >= cur) revert NothingToLower();
        emit AppliedDown(route, cur, v);
        ILiquidityLockbox(b.lockbox).lowerDailyLimit(v);
    }

    /// The largest change the next propose() may make (a target of 0 may move up to maxStepBps of max).
    function maxStep(bytes32 route) public view returns (uint256) {
        Bounds memory b = bounds[route];
        uint256 v = target[route].value;
        uint256 base = v > 0 ? v : b.max;
        return base * b.maxStepBps / 10000;
    }
}

contracts/SaphanOffline.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// HyperlaneOutbox (contracts/HyperlaneLockBoxV2.sol): burns the route's token from the caller through the guard and
/// sends the release to the source chain's lockbox.
interface IOfflineOutbox {
    function guard() external view returns (address);
    function quoteSend(address to, uint256 amount) external view returns (uint256);
    function send(address to, uint256 amount) external payable returns (bytes32 messageId);
}

interface IOfflineGuard {
    function token() external view returns (address);
}

interface IOfflineToken {
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function transfer(address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanOfflineTransfers: a bridge transfer signed offline, relayed by anyone later
/// @notice Saphan PR 6, item H (docs/SAPHAN-PR6.md). Testnet only, not audited. The pattern of ZetaphyOfflineOrders
///         (EIP-712, a QR code or text payload, a nonce bitmap, the relayer paid a fee the signer chose), for the
///         way out of ZETAPHY: "send `amount` of route R's token to `to` on R's source chain".
///
///         Online once: the holder approves this contract for the route's token (token(X) on ZETAPHY).
///         Offline: it signs Transfer{from, outbox, to, amount, relayerFee, nonce, deadline} (no network; the hub or
///         `node scripts/saphan.js offline sign`), and hands the text / QR (src/saphanoffline.js, "ZSPH1:...") to
///         anyone. Later, whoever is online calls relay(): this contract pulls amount + relayerFee from the signer,
///         pays the relayer its fee in the token, and calls the outbox's send(to, amount) with the Mailbox fee the
///         relayer pays in ZTPHY (anything above the quote is returned to the relayer). From there it is an ordinary
///         transfer: the guard's limits, pause and vaccine, the lockbox's delay, veto and daily limit all apply.
///
///         The relayer cannot change anything signed (outbox = the route and so the chain, recipient, amount, fee);
///         a nonce is spent before any call out; cancel(nonce) burns one. The token is the outbox guard's token
///         (read on chain, not trusted from the payload). No owner, no fee of its own, no upgrade; nonReentrant.
contract SaphanOfflineTransfers {
    struct Transfer {
        address from;
        address outbox;       // the route (HyperlaneOutbox on ZETAPHY): which source chain and which token
        address to;           // the receiver on the source chain
        uint256 amount;       // token units that arrive (burned here, released there)
        uint256 relayerFee;   // token units to whoever relays, on top of amount
        uint256 nonce;
        uint256 deadline;
    }

    bytes32 public constant TRANSFER_TYPEHASH = keccak256(
        "Transfer(address from,address outbox,address to,uint256 amount,uint256 relayerFee,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    uint256 private constant HALF_N = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    mapping(address => mapping(uint256 => uint256)) public nonceBitmap;
    uint256 private unlocked = 1;

    /// The amount, receiver and chain are in the outbox's Sent event of the same transaction (messageId).
    event Relayed(address indexed from, uint256 indexed nonce, address indexed outbox, address relayer, uint256 relayerFee, bytes32 messageId);
    event NonceCancelled(address indexed from, uint256 wordPos, uint256 mask);

    error Expired();
    error NonceUsed();
    error BadSignature();
    error BadTransfer();
    error Fee(uint256 needed);
    error TokenFailed();
    error PayFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY Saphan Offline"), keccak256("1"), block.chainid, address(this)));
    }

    function transferHash(Transfer calldata t) public pure returns (bytes32) {
        return keccak256(abi.encode(TRANSFER_TYPEHASH, t.from, t.outbox, t.to, t.amount, t.relayerFee, t.nonce, t.deadline));
    }

    function digest(Transfer calldata t) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), transferHash(t)));
    }

    function isNonceUsed(address from, uint256 nonce) public view returns (bool) {
        return nonceBitmap[from][nonce >> 8] & (1 << (nonce & 0xff)) != 0;
    }

    function cancel(uint256 nonce) external {
        uint256 mask = 1 << (nonce & 0xff);
        nonceBitmap[msg.sender][nonce >> 8] |= mask;
        emit NonceCancelled(msg.sender, nonce >> 8, mask);
    }

    /// The Mailbox fee relay() needs for `t` now (msg.value of relay).
    function quote(Transfer calldata t) external view returns (uint256) {
        return IOfflineOutbox(t.outbox).quoteSend(t.to, t.amount);
    }

    /// Anyone online: carries a signed transfer to its route. msg.value >= quote(t); the rest comes back.
    function relay(Transfer calldata t, bytes calldata sig) external payable nonReentrant returns (bytes32 messageId) {
        if (block.timestamp > t.deadline) revert Expired();
        if (t.amount == 0 || t.to == address(0) || t.outbox.code.length == 0) revert BadTransfer();
        if (_recover(digest(t), sig) != t.from) revert BadSignature();
        uint256 bit = 1 << (t.nonce & 0xff);
        uint256 word = nonceBitmap[t.from][t.nonce >> 8];
        if (word & bit != 0) revert NonceUsed();
        nonceBitmap[t.from][t.nonce >> 8] = word | bit;

        IOfflineOutbox outbox = IOfflineOutbox(t.outbox);
        uint256 fee = outbox.quoteSend(t.to, t.amount);
        if (msg.value < fee) revert Fee(fee);
        _pull(t);

        // exactly the quote (the outbox quotes the same body in the same transaction, so it returns no change; this
        // contract has no receive(): a change would revert the whole relay)
        messageId = outbox.send{value: fee}(t.to, t.amount); // burns `amount` from this contract (the guard's outbound route): nothing is kept here
        emit Relayed(t.from, t.nonce, t.outbox, msg.sender, t.relayerFee, messageId);
        uint256 change = msg.value - fee;
        if (change != 0) {
            (bool ok, ) = msg.sender.call{value: change}("");
            if (!ok) revert PayFailed();
        }
    }

    /// Pulls amount + relayerFee from the signer and pays the relayer its fee. The token is the outbox guard's
    /// BridgedToken (no fee on transfer); if less arrived, the fee transfer or the guard's burn of `amount` reverts.
    function _pull(Transfer calldata t) private {
        IOfflineToken token = IOfflineToken(IOfflineGuard(IOfflineOutbox(t.outbox).guard()).token());
        if (!token.transferFrom(t.from, address(this), t.amount + t.relayerFee)) revert TokenFailed();
        if (t.relayerFee != 0 && !token.transfer(msg.sender, t.relayerFee)) revert TokenFailed();
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address got) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > HALF_N || (v != 27 && v != 28)) revert BadSignature();
        got = ecrecover(d, v, r, s);
        if (got == address(0)) revert BadSignature();
    }
}

contracts/SaphanPrivacy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPrivacyPoseidon {
    function poseidon(uint256[2] calldata x) external pure returns (uint256);
}

/// ZkIdentityVerifier (Groth16, the identity circuit zetaphy-network/zkid/circuits/identity.circom; DEV setup).
interface IPrivacyVerifier {
    function verifyProof(uint256[2] calldata a, uint256[2][2] calldata b, uint256[2] calldata c, uint256[5] calldata pub)
        external view returns (bool);
}

interface IPrivacyToken {
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanPrivacyPool: optional private transfers of a bridged token, one fixed denomination per pool
/// @notice Saphan PR 6, item F (docs/SAPHAN-PR6.md). Testnet only, not audited. A REAL zero-knowledge proof, with a
///         DEV trusted setup: the Groth16 key of ZkIdentityVerifier was made by one party on one machine
///         (zetaphy-network/zkid/setup.js), who could forge proofs and drain every pool. Mainnet would need a public
///         multi-party phase-2 ceremony first.
///
///         It reuses the private-identity circuit unchanged (a Semaphore-style membership + nullifier proof):
///           deposit:  the depositor makes a note (secret, nullifierKey) offline and deposits its commitment
///                     C = Poseidon(secret, nullifierKey) with exactly `denomination` of `token` (e.g. 0.01 sepETH).
///                     The pool appends the leaf Poseidon(C, 1) to its own Poseidon Merkle tree (depth 20).
///           withdraw: later, from any address, a Groth16 proof that "some leaf of a root this pool had is
///                     Poseidon(Poseidon(secret, nullifierKey), level >= 1)", revealing only
///                     nullifier = Poseidon(nullifierKey, scope) (one withdrawal per note) and binding
///                     signal = keccak256(recipient, fee) >> 8 (a proof copied from the mempool cannot redirect the
///                     coins). The recipient gets denomination - fee, whoever submits gets fee (a relayer, so the
///                     recipient needs no gas and no link to the depositor).
///         Every pool has its own scope (from the chain id and its address), so a note's nullifier differs per pool.
///         What is hidden: which deposit a withdrawal spends (among all deposits of this pool). What is not: that an
///         address deposited, amounts (all equal), timing. The anonymity set is the pool's deposits: small on a testnet.
///         No owner, no fee of its own, no upgrade, no pause: it cannot be frozen or drained by anyone but note holders
///         (and the DEV key holder, see above).
contract SaphanPrivacyPool {
    uint256 public constant SNARK_FIELD = 21888242871839275222246405745257275088548364400416034343698204186575808495617;
    uint256 public constant DEPTH = 20;
    uint256 public constant LEVEL = 1;

    IPrivacyPoseidon public immutable poseidon;
    IPrivacyVerifier public immutable verifier;
    IPrivacyToken public immutable token;
    uint256 public immutable denomination;
    uint256 public immutable scope;

    uint256 public root;
    uint256 public leafCount;
    mapping(uint256 => bool) public rootSeen;          // every root this pool ever had (the tree only grows)
    mapping(uint256 => bool) public nullifierUsed;
    mapping(uint256 => bool) public commitmentUsed;
    uint256 public spent;                               // withdrawals so far (the pool owes (leafCount - spent) notes)
    uint256[21] private zeros;
    uint256[20] private filled;                         // the left node last written at each height
    uint256 private unlocked = 1;

    event Deposit(uint256 indexed commitment, uint256 leaf, uint256 index, uint256 root);
    event Withdrawal(uint256 indexed nullifier, address indexed recipient, address relayer, uint256 fee);

    error BadCommitment();
    error TreeFull();
    error UnknownRoot();
    error Spent();
    error BadFee();
    error BadProof();
    error TokenFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    constructor(IPrivacyPoseidon poseidon_, IPrivacyVerifier verifier_, IPrivacyToken token_, uint256 denomination_) {
        require(address(poseidon_) != address(0) && address(verifier_) != address(0) && address(token_) != address(0) && denomination_ > 0, "config");
        poseidon = poseidon_;
        verifier = verifier_;
        token = token_;
        denomination = denomination_;
        scope = uint256(keccak256(abi.encode("saphan/privacy-pool/v1", block.chainid, address(this)))) >> 8;
        uint256 z = 0;
        for (uint256 h = 0; h <= DEPTH; h++) {
            zeros[h] = z;
            if (h < DEPTH) filled[h] = z;
            z = poseidon_.poseidon([z, z]);
        }
        root = zeros[DEPTH];
        rootSeen[root] = true;
    }

    /// The signal a withdrawal's proof must carry (as PrivateAirdrop's).
    function signalOf(address recipient, uint256 fee) public pure returns (uint256) {
        return uint256(keccak256(abi.encode(recipient, fee))) >> 8;
    }

    function zeroAt(uint256 h) external view returns (uint256) { return zeros[h]; }

    /// Deposits one note: exactly `denomination` of the token (approve first).
    function deposit(uint256 commitment) external nonReentrant {
        if (commitment == 0 || commitment >= SNARK_FIELD || commitmentUsed[commitment]) revert BadCommitment();
        uint256 index = leafCount;
        if (index >= (1 << DEPTH)) revert TreeFull();
        commitmentUsed[commitment] = true;
        leafCount = index + 1;
        uint256 leaf = poseidon.poseidon([commitment, LEVEL]);
        uint256 node = leaf;
        uint256 i = index;
        for (uint256 h = 0; h < DEPTH; h++) {
            if (i & 1 == 0) {
                filled[h] = node;
                node = poseidon.poseidon([node, zeros[h]]);
            } else {
                node = poseidon.poseidon([filled[h], node]);
            }
            i >>= 1;
        }
        root = node;
        rootSeen[node] = true;
        emit Deposit(commitment, leaf, index, node);
        // the whole denomination must arrive (no fee-on-transfer): the balance covers every unspent note after the pull
        if (!token.transferFrom(msg.sender, address(this), denomination) || token.balanceOf(address(this)) < (leafCount - spent) * denomination) revert TokenFailed();
    }

    /// Withdraws one note to `recipient` (denomination - fee), paying `fee` to the caller.
    /// proof = [a0, a1, b00, b01, b10, b11, c0, c1] (zetaphy-hub/zkid-core.js proofWords).
    function withdraw(address recipient, uint256 fee, uint256 root_, uint256 nullifier, uint256[8] calldata proof) external nonReentrant {
        if (!rootSeen[root_]) revert UnknownRoot();
        if (nullifierUsed[nullifier]) revert Spent();
        if (fee > denomination || recipient == address(0)) revert BadFee();
        nullifierUsed[nullifier] = true;
        spent += 1;
        emit Withdrawal(nullifier, recipient, msg.sender, fee);
        // the proof (a view of the immutable verifier) before any token moves; a bad one reverts the marks above
        if (!verifier.verifyProof([proof[0], proof[1]], [[proof[2], proof[3]], [proof[4], proof[5]]], [proof[6], proof[7]],
            [root_, nullifier, scope, signalOf(recipient, fee), LEVEL])) revert BadProof();
        if (!token.transfer(recipient, denomination - fee)) revert TokenFailed();
        if (fee != 0 && !token.transfer(msg.sender, fee)) revert TokenFailed();
    }
}

contracts/SaphanProofs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan, proven releases: ZETAPHY -> source chain without trusting any validator
/// @notice Two contracts (docs/SAPHAN-PROOFS.md), testnet only, not audited:
///
///         ZETAPHY       SaphanProvableOutbox(X) sits in front of the route's HyperlaneOutbox (same send / quoteSend):
///                       it takes the tokens, has the outbox burn them and send the usual Hyperlane release, AND writes
///                       the very same release body into ZetaphyOutbox (the Merkle outbox whose root lives in ZETAPHY's
///                       state). The Gateway and wallets use it instead of the outbox.
///         source X      SaphanReleaseVerifier checks a release body against ZETAPHY's state: the ZetaphyOutbox root at
///                       a ZETAPHY block that StarkLightClient finalized (a STARK proof of > 2/3 of ZETAPHY's validators,
///                       ML-DSA-44 votes counted by its pq modes), the IAVL / multistore path to that block's app_hash,
///                       and the leaf's Merkle path. Then HyperlaneLockBoxV2.queueProven(body) queues it exactly as a
///                       Hyperlane message would (same id: whichever path comes first; the other is a replay).
///
///         With the lockbox's requireProof on (governance), the Hyperlane path no longer releases anything: outbound
///         money then moves on math alone (hash-based STARK, ML-DSA finality), no ECDSA signer anywhere in the way.

interface IProofOutbox {
    function send(address to, uint256 amount) external payable returns (bytes32);
    function quoteSend(address to, uint256 amount) external view returns (uint256);
    function body(uint256 n, address sender, address to, uint256 amount) external view returns (bytes memory);
    function nonce() external view returns (uint256);
    function destinationChainId() external view returns (uint256);
    function recipient() external view returns (bytes32);
}

interface IMerkleOutbox {
    function send(uint256 dstChainId, address receiver, bytes calldata payload) external returns (uint64);
}

interface IProofToken {
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

contract SaphanProvableOutbox {
    IProofOutbox public immutable outbox;        // the route's HyperlaneOutbox
    IMerkleOutbox public immutable merkleOutbox; // ZetaphyOutbox (provable from ZETAPHY's state)
    IProofToken public immutable token;          // token(X)
    address public immutable lockbox;            // HyperlaneLockBoxV2 on X (the receiver in every leaf)
    uint256 public immutable destinationChainId;

    event ProvableSent(uint256 indexed outboxNonce, uint64 indexed merkleNonce, address indexed from, address to, uint256 amount, bytes32 bodyHash);

    error PayFailed();
    error Fee(uint256 required);

    /// lockbox_ and destinationChainId_ must be the outbox's own (checked last, against the outbox).
    constructor(IProofOutbox outbox_, IMerkleOutbox merkleOutbox_, IProofToken token_, address lockbox_, uint256 destinationChainId_) {
        outbox = outbox_;
        merkleOutbox = merkleOutbox_;
        token = token_;
        lockbox = lockbox_;
        destinationChainId = destinationChainId_;
        require(lockbox_ != address(0) && outbox_.recipient() == bytes32(uint256(uint160(lockbox_)))
            && outbox_.destinationChainId() == destinationChainId_, "config");
    }

    function quoteSend(address to, uint256 amount) external view returns (uint256) { return outbox.quoteSend(to, amount); }

    /// Like HyperlaneOutbox.send (approve this contract for `amount` of token(X) first). msg.value: exactly the
    /// Mailbox fee (quoteSend); all of it goes on to the outbox, so this contract never holds ether.
    function send(address to, uint256 amount) external payable returns (bytes32 messageId) {
        uint256 fee = outbox.quoteSend(to, amount);
        if (msg.value != fee) revert Fee(fee);
        uint256 n = outbox.nonce();
        bytes memory b = outbox.body(n, address(this), to, amount); // the body the outbox is about to send
        uint64 m = merkleOutbox.send(destinationChainId, lockbox, b);
        emit ProvableSent(n, m, msg.sender, to, amount, keccak256(b));
        if (!token.transferFrom(msg.sender, address(this), amount)) revert PayFailed();
        messageId = outbox.send{value: fee}(to, amount);  // burns this contract's tokens; the same nonce n
    }
}


interface IProofLightClient {
    function appHashAt(uint64 height) external view returns (bytes32);
}

/// The pure proof functions of ZetaphyBridgeInbox (any deployed instance: they read no state).
interface IZetaphyProofs {
    struct InnerOp { bytes prefix; bytes suffix; }
    function outboxRoot(bytes32 leaf, uint64 index, bytes32[32] calldata sib, uint64 count) external pure returns (bytes32);
    function iavlRoot(bytes memory key, bytes32 value, bytes calldata leafPrefix, InnerOp[] calldata path) external pure returns (bytes32);
    function storeRoot(bytes memory name, bytes32 root, InnerOp[] calldata path) external pure returns (bytes32);
}

interface IProvenLockbox {
    function queueProven(bytes calldata body) external;
}

/// @title SaphanReleaseVerifier: on the source chain X, a release proven from ZETAPHY's state (see above)
contract SaphanReleaseVerifier {
    struct StateProof {
        bytes32 outboxRoot;                  // ZetaphyOutbox's slot 0 at that block
        bytes iavlLeafPrefix;
        IZetaphyProofs.InnerOp[] iavlPath;   // evm store, leaf to root
        IZetaphyProofs.InnerOp[] storePath;  // multistore, evm store root to app hash
    }

    bytes32 public constant LEAF_TAG = keccak256("zetaphy/outbox/v1");
    IProofLightClient public immutable lightClient;  // StarkLightClient: ZETAPHY finality on this chain
    IZetaphyProofs public immutable proofs;
    uint256 public immutable zetaphyChainId;
    address public immutable merkleOutbox;            // ZetaphyOutbox on ZETAPHY
    address public immutable provableSender;          // SaphanProvableOutbox(X) on ZETAPHY: the only sender it accepts
    IProvenLockbox public immutable lockbox;          // HyperlaneLockBoxV2 here

    event Proven(uint64 indexed merkleNonce, uint64 height, bytes32 bodyHash);

    error BadStateProof(uint256 step);
    error BadMessage();

    constructor(IProofLightClient lc, IZetaphyProofs proofs_, uint256 zetaphyChainId_, address merkleOutbox_, address provableSender_, IProvenLockbox lockbox_) {
        require(address(lc) != address(0) && address(proofs_) != address(0) && merkleOutbox_ != address(0) && provableSender_ != address(0)
            && address(lockbox_) != address(0), "config");
        lightClient = lc;
        proofs = proofs_;
        zetaphyChainId = zetaphyChainId_;
        merkleOutbox = merkleOutbox_;
        provableSender = provableSender_;
        lockbox = lockbox_;
    }

    /// Anyone: proves the release `body` (the leaf `nonce` of ZetaphyOutbox, sent by the provable outbox to this lockbox)
    /// at ZETAPHY block `height`, then queues it in the lockbox (each body once there).
    function prove(uint64 height, StateProof calldata sp, uint64 nonce, bytes calldata body, bytes32[32] calldata siblings, uint64 count) external {
        if (body.length != 256) revert BadMessage();
        bytes32 app = lightClient.appHashAt(height);
        if (app == bytes32(0)) revert BadStateProof(0);
        bytes32 evmRoot = proofs.iavlRoot(abi.encodePacked(uint8(2), merkleOutbox, bytes32(0)), sp.outboxRoot, sp.iavlLeafPrefix, sp.iavlPath);
        if (proofs.storeRoot("evm", evmRoot, sp.storePath) != app) revert BadStateProof(2);
        bytes32 leaf = sha256(abi.encode(LEAF_TAG, zetaphyChainId, merkleOutbox, nonce, provableSender, block.chainid, address(lockbox), sha256(body)));
        if (nonce >= count || proofs.outboxRoot(leaf, nonce, siblings, count) != sp.outboxRoot) revert BadStateProof(4);
        emit Proven(nonce, height, keccak256(body));
        lockbox.queueProven(body);
    }
}

