// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan cross-chain reads: "what is value V on chain X at block B"
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited. Three contracts and a library:
///
///   SaphanReads (ZETAPHY, one per source chain X) keeps the newest known answer to each question about X, with the
///     X block it is from. Answers come two ways, both without a new signer:
///       - lane answers: SaphanReadResponder on X runs a view call on X and sends the result, its block number and
///         time through X's Hyperlane Mailbox; the Mailbox on ZETAPHY checks the route's ISM (the Hyperlane
///         validators that already attest every transfer from X) before handle() records it;
///       - proven answers: a storage slot or account of X checked against X's state root at block B, given by a
///         light client of X (`stateRoots`), with the Merkle-Patricia proofs of eth_getProof (SaphanMpt). No light
///         client of an EVM chain runs on ZETAPHY yet: until one does, `stateRoots` is zero and only lane answers
///         are used (the verifier itself is complete and tested against an EVM's own proofs).
///     The caller pays: request*() posts a bounty in ZTPHY for an answer at block >= minBlock before a deadline;
///     whoever brought that answer collects it (pull). read*() refuses an answer older than the caller allows
///     (block below minBlock, or time older than maxAge): stale answers are never served.
///   SaphanReadResponder (source chain X): anyone asks it to answer a view call; the answerer pays the Mailbox fee.
///     It gives the call a fixed gas budget and checks it is there first, so nobody can make a call fail on purpose.
///   SaphanZetaphyReads (source chain X): the other way round, a storage slot of any ZETAPHY contract verified from
///     ZETAPHY's state at a height the STARK light client finalized (the SaphanReleaseVerifier pattern: IAVL path to
///     the evm store, multistore path to the app hash); a view a contract on X calls with the proof.

/// What a light client of chain X tells: X's state root (and block time) at a block it accepted. Zero: unknown.
interface IReadsStateRoots {
    function stateRootAt(uint64 blockNumber) external view returns (bytes32 stateRoot, uint64 timestamp);
}

interface IReadsMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256);
}

/// @notice Ethereum Merkle-Patricia proofs (the `accountProof` / `storageProof` of eth_getProof), checked in memory.
///         Proofs of absence (a path that ends in an empty branch slot or a diverging leaf / extension) give an empty
///         value. Nodes shorter than 32 bytes embedded in their parent are refused: with keccak-hashed 32-byte keys
///         they do not occur in practice, and refusing them keeps the walk simple.
library SaphanMpt {
    bytes32 internal constant EMPTY_TRIE = 0x56e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421; // keccak256(0x80)
    bytes32 internal constant EMPTY_CODE = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470; // keccak256("")

    error BadProof(uint256 step);

    /// The value at `key` (already hashed) under `root`; empty when the proof shows there is none.
    function get(bytes32 root, bytes32 key, bytes[] memory proof) internal pure returns (bytes memory) {
        bytes32 want = root;
        uint256 pos = 0;
        for (uint256 i = 0; i < proof.length; i++) {
            bytes memory node = proof[i];
            if (keccak256(node) != want) revert BadProof(i);
            (bool done, bytes memory value, bytes32 next, uint256 npos) = _step(node, key, pos, i);
            if (done) {
                if (i + 1 != proof.length) revert BadProof(i); // an answer must end the proof
                return value;
            }
            (want, pos) = (next, npos);
        }
        revert BadProof(proof.length); // the proof stops before an answer
    }

    /// One node of the walk: the answer (done), or the next node's hash and the key position after this node.
    function _step(bytes memory node, bytes32 key, uint256 pos, uint256 i)
        private pure returns (bool done, bytes memory value, bytes32 next, uint256 npos)
    {
        (uint256[2][17] memory it, uint256 n) = _node(node);
        if (n == 17) { // branch
            if (pos >= 64) revert BadProof(i);
            uint256[2] memory child = it[_nibble(key, pos)];
            if (child[1] == 0) return (true, "", 0, 0);   // an empty slot: no value
            if (child[1] != 32) revert BadProof(i);
            return (false, "", _word(node, child[0]), pos + 1);
        }
        if (n != 2) revert BadProof(i);
        (bool matched, uint256 plen, bool leaf) = _path(node, it[0][0], it[0][1], key, pos, i);
        if (!matched) return (true, "", 0, 0);            // the path leaves the key: no value
        if (leaf) return (true, pos + plen == 64 ? _slice(node, it[1][0], it[1][1]) : bytes(""), 0, 0);
        if (it[1][1] != 32) revert BadProof(i);           // extension: a hash
        return (false, "", _word(node, it[1][0]), pos + plen);
    }

    /// A leaf / extension path (hex-prefix encoded at node[p..p+l]) against the key from nibble `pos`.
    function _path(bytes memory node, uint256 p, uint256 l, bytes32 key, uint256 pos, uint256 i)
        private pure returns (bool matched, uint256 plen, bool leaf)
    {
        if (l == 0) revert BadProof(i);
        uint8 flag = uint8(node[p]) >> 4;
        if (flag > 3) revert BadProof(i);
        leaf = flag >= 2;
        uint256 skip = flag & 1 == 1 ? 1 : 2;
        plen = l * 2 - skip;
        for (uint256 j = 0; j < plen; j++) {
            uint256 k = j + skip;
            uint8 pn = k % 2 == 0 ? uint8(node[p + k / 2]) >> 4 : uint8(node[p + k / 2]) & 0x0f;
            if (pos + j >= 64 || pn != _nibble(key, pos + j)) return (false, plen, leaf);
        }
        matched = true;
    }

    /// An account of the state trie: (exists, nonce, balance, storage root, code hash).
    function account(bytes32 stateRoot, address who, bytes[] memory proof)
        internal pure returns (bool exists, uint256 nonce, uint256 balance, bytes32 storageRoot, bytes32 codeHash)
    {
        bytes memory v = get(stateRoot, keccak256(abi.encodePacked(who)), proof);
        if (v.length == 0) return (false, 0, 0, EMPTY_TRIE, EMPTY_CODE);
        (uint256[2][17] memory it, uint256 n) = _node(v);
        if (n != 4 || it[2][1] != 32 || it[3][1] != 32 || it[0][1] > 32 || it[1][1] > 32) revert BadProof(100);
        return (true, _uint(v, it[0][0], it[0][1]), _uint(v, it[1][0], it[1][1]), _word(v, it[2][0]), _word(v, it[3][0]));
    }

    /// A storage slot under an account's storage root (zero when absent).
    function slot(bytes32 storageRoot, bytes32 key, bytes[] memory proof) internal pure returns (uint256) {
        if (storageRoot == EMPTY_TRIE) { if (proof.length != 0) revert BadProof(200); return 0; }
        bytes memory v = get(storageRoot, keccak256(abi.encode(key)), proof);
        if (v.length == 0) return 0;
        (uint256 p, uint256 l, bool list) = _item(v, 0);
        if (list || l > 32 || p + l != v.length) revert BadProof(201);
        return _uint(v, p, l);
    }

    // ---- RLP ----

    /// The items of the list that is the whole of `b`: (payload offset, payload length) each; lists inside are refused.
    function _node(bytes memory b) private pure returns (uint256[2][17] memory it, uint256 n) {
        (uint256 p, uint256 l, bool list) = _item(b, 0);
        if (!list || p + l != b.length) revert BadProof(300);
        uint256 end = p + l;
        while (p < end) {
            if (n == 17) revert BadProof(301);
            (uint256 ip, uint256 il, bool inner) = _item(b, p);
            if (inner) revert BadProof(302); // an embedded node
            it[n] = [ip, il];
            n += 1;
            p = ip + il;
        }
        if (p != end) revert BadProof(303);
    }

    function _item(bytes memory b, uint256 off) private pure returns (uint256 p, uint256 len, bool list) {
        if (off >= b.length) revert BadProof(400);
        uint8 x = uint8(b[off]);
        if (x < 0x80) return (off, 1, false);
        if (x < 0xb8) { len = x - 0x80; p = off + 1; }
        else if (x < 0xc0) { uint256 ll = x - 0xb7; len = _be(b, off + 1, ll); p = off + 1 + ll; }
        else if (x < 0xf8) { len = x - 0xc0; p = off + 1; list = true; }
        else { uint256 ll = x - 0xf7; len = _be(b, off + 1, ll); p = off + 1 + ll; list = true; }
        if (p + len > b.length) revert BadProof(401);
    }

    function _be(bytes memory b, uint256 off, uint256 n) private pure returns (uint256 v) {
        if (n > 4 || off + n > b.length) revert BadProof(402);
        for (uint256 i = 0; i < n; i++) v = (v << 8) | uint8(b[off + i]);
    }

    function _uint(bytes memory b, uint256 p, uint256 l) private pure returns (uint256 v) {
        for (uint256 i = 0; i < l; i++) v = (v << 8) | uint8(b[p + i]);
    }

    function _word(bytes memory b, uint256 p) private pure returns (bytes32 w) {
        assembly { w := mload(add(add(b, 0x20), p)) }
    }

    function _slice(bytes memory b, uint256 p, uint256 l) private pure returns (bytes memory out) {
        out = new bytes(l);
        for (uint256 i = 0; i < l; i++) out[i] = b[p + i];
    }

    function _nibble(bytes32 key, uint256 i) private pure returns (uint8) {
        uint8 byt = uint8(key[i / 2]);
        return i % 2 == 0 ? byt >> 4 : byt & 0x0f;
    }
}

/// @title SaphanReads: answers about source chain X on ZETAPHY, each with the X block it is from
contract SaphanReads {
    bytes32 public constant CALL_TAG = keccak256("saphan/reads/call/v1");
    bytes32 public constant SLOT_TAG = keccak256("saphan/reads/slot/v1");
    bytes32 public constant ACCOUNT_TAG = keccak256("saphan/reads/account/v1");
    /// An answer may be at most this far ahead of ZETAPHY's clock (clocks of two chains differ a little).
    uint64 public constant MAX_SKEW = 5 minutes;
    /// The longest a request waits for its answer.
    uint64 public constant MAX_TTL = 7 days;
    /// The longest result kept (SaphanReadResponder sends no longer one).
    uint256 public constant MAX_RESULT = 1024;

    struct Answer {
        uint64 blockNumber;  // the X block the answer is from
        uint64 timestamp;    // that block's time
        uint64 arrivedAt;    // when it reached ZETAPHY
        bool ok;             // a view call: it did not revert
        address by;          // who brought it (the answerer on X, or the prover here): collects bounties
        bytes result;        // a view call: its return data; a slot: abi.encode(value); an account: abi.encode(nonce, balance, storageRoot, codeHash)
    }

    struct Request {
        address requester;
        uint64 minBlock;
        uint64 expires;
        bool done;
        bytes32 query;
        uint256 bounty;
    }

    uint256 public immutable remoteChainId;     // X
    uint32 public immutable originDomain;       // X's Hyperlane domain
    address public immutable mailbox;           // the Mailbox on ZETAPHY
    /// Hyperlane reads it (ISpecifiesInterchainSecurityModule): the route's ISM of Hyperlane's validators for X.
    address public immutable interchainSecurityModule;
    IReadsStateRoots public immutable stateRoots; // a light client of X; zero: no proven answers yet
    address public immutable deployer;
    bytes32 public responder;                   // SaphanReadResponder on X (set once, then fixed)

    mapping(bytes32 => Answer) private _answers;
    mapping(uint256 => Request) public requests;
    uint256 public requestCount;
    mapping(address => uint256) public credit;  // bounties collected, taken with claim()
    uint256 private entered;

    event ResponderSet(bytes32 responder);
    event Answered(bytes32 indexed query, uint64 blockNumber, uint64 timestamp, bool ok, address by, bool proven);
    event Ignored(bytes32 indexed query, uint64 blockNumber);
    event Requested(uint256 indexed id, bytes32 indexed query, uint64 minBlock, uint64 expires, uint256 bounty, uint8 kind, address target, bytes data);
    event Collected(uint256 indexed id, address indexed by, uint256 bounty);
    event Cancelled(uint256 indexed id);
    event Claimed(address indexed who, uint256 amount);

    error NotMailbox();
    error NoValue();
    error WrongOrigin();
    error WrongSender();
    error NoLightClient();
    error UnknownBlock();
    error Older();
    error BadAnswer();
    error NoAnswer();
    error Stale(uint64 blockNumber, uint64 timestamp);
    error CallReverted();
    error BadRequest();
    error NotReady();
    error PayFailed();
    error Reentered();

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    constructor(uint256 remoteChainId_, address mailbox_, uint32 originDomain_, address ism_, IReadsStateRoots stateRoots_) {
        require(remoteChainId_ != 0 && mailbox_ != address(0), "config");
        remoteChainId = remoteChainId_;
        mailbox = mailbox_;
        originDomain = originDomain_;
        interchainSecurityModule = ism_;
        stateRoots = stateRoots_;
        deployer = msg.sender;
    }

    /// Once, by the deployer: the responder on X (deployed after this contract, it names this one).
    function setResponder(address r) external {
        require(msg.sender == deployer && responder == bytes32(0) && r != address(0), "responder");
        responder = bytes32(uint256(uint160(r)));
        emit ResponderSet(responder);
    }

    // ---- questions ----

    function callQuery(address target, bytes calldata data) public view returns (bytes32) { return _callQuery(target, keccak256(data)); }
    function slotQuery(address account, bytes32 slot_) public view returns (bytes32) { return keccak256(abi.encode(SLOT_TAG, remoteChainId, account, slot_)); }
    function accountQuery(address account) public view returns (bytes32) { return keccak256(abi.encode(ACCOUNT_TAG, remoteChainId, account)); }
    function _callQuery(address target, bytes32 dataHash) private view returns (bytes32) { return keccak256(abi.encode(CALL_TAG, remoteChainId, target, dataHash)); }

    // ---- answers ----

    /// The Mailbox, after the ISM checked the message: a view call answered on X by the responder.
    /// A message that cannot be used (older than what is known, too far in the future) is consumed and ignored,
    /// so it never blocks the Mailbox.
    function handle(uint32 origin, bytes32 sender, bytes calldata body) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != originDomain) revert WrongOrigin();
        if (sender != responder || sender == bytes32(0)) revert WrongSender();
        (address target, bytes32 dataHash, uint64 blockNumber, uint64 timestamp, bool ok, bytes memory result, address by) =
            abi.decode(body, (address, bytes32, uint64, uint64, bool, bytes, address));
        bytes32 q = _callQuery(target, dataHash);
        if (!_record(q, blockNumber, timestamp, ok, result, by, false)) emit Ignored(q, blockNumber);
    }

    /// Anyone: a storage slot of `account` on X at `blockNumber`, proven against the light client's state root.
    function proveSlot(uint64 blockNumber, address account, bytes32 slot_, bytes[] calldata accountProof, bytes[] calldata storageProof)
        external returns (uint256 value)
    {
        (bytes32 root, uint64 ts) = _root(blockNumber);
        (, , , bytes32 storageRoot, ) = SaphanMpt.account(root, account, accountProof);
        value = SaphanMpt.slot(storageRoot, slot_, storageProof);
        if (!_record(slotQuery(account, slot_), blockNumber, ts, true, abi.encode(value), msg.sender, true)) revert Older();
    }

    /// Anyone: an account of X (nonce, balance, storage root, code hash) at `blockNumber`, proven the same way.
    function proveAccount(uint64 blockNumber, address account, bytes[] calldata accountProof) external {
        (bytes32 root, uint64 ts) = _root(blockNumber);
        (, uint256 nonce, uint256 balance, bytes32 storageRoot, bytes32 codeHash) = SaphanMpt.account(root, account, accountProof);
        if (!_record(accountQuery(account), blockNumber, ts, true, abi.encode(nonce, balance, storageRoot, codeHash), msg.sender, true)) revert Older();
    }

    function _root(uint64 blockNumber) private view returns (bytes32 root, uint64 ts) {
        if (address(stateRoots) == address(0)) revert NoLightClient();
        (root, ts) = stateRoots.stateRootAt(blockNumber);
        if (root == bytes32(0)) revert UnknownBlock();
    }

    /// Keeps an answer when it is newer than the one known (answers never go back in time).
    function _record(bytes32 q, uint64 blockNumber, uint64 timestamp, bool ok, bytes memory result, address by, bool proven) private returns (bool) {
        Answer storage a = _answers[q];
        if (a.arrivedAt != 0 && blockNumber <= a.blockNumber) return false;
        if (timestamp > block.timestamp + MAX_SKEW || result.length > MAX_RESULT) return false;
        _answers[q] = Answer(blockNumber, timestamp, uint64(block.timestamp), ok, by, result);
        emit Answered(q, blockNumber, timestamp, ok, by, proven);
        return true;
    }

    // ---- reading (stale answers refused) ----

    /// The newest answer, if it is from block >= minBlock and its time is at most maxAge seconds old.
    function read(bytes32 query, uint64 minBlock, uint64 maxAge) public view returns (bool ok, bytes memory result, uint64 blockNumber, uint64 timestamp) {
        Answer storage a = _answers[query];
        if (a.arrivedAt == 0) revert NoAnswer();
        if (a.blockNumber < minBlock || uint256(a.timestamp) + maxAge < block.timestamp) revert Stale(a.blockNumber, a.timestamp);
        return (a.ok, a.result, a.blockNumber, a.timestamp);
    }

    /// A view call's return data (reverts CallReverted when the call reverted on X).
    function readCall(address target, bytes calldata data, uint64 minBlock, uint64 maxAge) external view returns (bytes memory result, uint64 blockNumber, uint64 timestamp) {
        bool ok;
        (ok, result, blockNumber, timestamp) = read(callQuery(target, data), minBlock, maxAge);
        if (!ok) revert CallReverted();
    }

    function readSlot(address account, bytes32 slot_, uint64 minBlock, uint64 maxAge) external view returns (uint256 value, uint64 blockNumber, uint64 timestamp) {
        bytes memory r;
        (, r, blockNumber, timestamp) = read(slotQuery(account, slot_), minBlock, maxAge);
        value = abi.decode(r, (uint256));
    }

    function readBalance(address account, uint64 minBlock, uint64 maxAge) external view returns (uint256 balance, uint64 blockNumber, uint64 timestamp) {
        bytes memory r;
        (, r, blockNumber, timestamp) = read(accountQuery(account), minBlock, maxAge);
        (, balance, , ) = abi.decode(r, (uint256, uint256, bytes32, bytes32));
    }

    /// The newest answer as stored (no age check), for explorers.
    function answerOf(bytes32 query) external view returns (Answer memory) { return _answers[query]; }

    // ---- requests: the caller pays ----

    uint8 internal constant KIND_CALL = 0;
    uint8 internal constant KIND_SLOT = 1;
    uint8 internal constant KIND_ACCOUNT = 2;

    /// A bounty (msg.value) for an answer of `target.call(data)` on X at block >= minBlock, within ttl seconds.
    function requestCall(address target, bytes calldata data, uint64 minBlock, uint64 ttl) external payable returns (uint256) {
        return _request(callQuery(target, data), minBlock, ttl, KIND_CALL, target, data);
    }

    function requestSlot(address account, bytes32 slot_, uint64 minBlock, uint64 ttl) external payable returns (uint256) {
        return _request(slotQuery(account, slot_), minBlock, ttl, KIND_SLOT, account, abi.encode(slot_));
    }

    function requestAccount(address account, uint64 minBlock, uint64 ttl) external payable returns (uint256) {
        return _request(accountQuery(account), minBlock, ttl, KIND_ACCOUNT, account, "");
    }

    function _request(bytes32 q, uint64 minBlock, uint64 ttl, uint8 kind, address target, bytes memory data) private returns (uint256 id) {
        if (msg.value == 0 || ttl == 0 || ttl > MAX_TTL) revert BadRequest();
        id = requestCount++;
        uint64 expires = uint64(block.timestamp) + ttl;
        requests[id] = Request(msg.sender, minBlock, expires, false, q, msg.value);
        emit Requested(id, q, minBlock, expires, msg.value, kind, target, data);
    }

    /// Anyone, once an answer from block >= minBlock arrived before the request expired: its bringer gets the bounty.
    function collect(uint256 id) external {
        Request storage r = requests[id];
        Answer storage a = _answers[r.query];
        if (r.requester == address(0) || r.done) revert BadRequest();
        if (a.arrivedAt == 0 || a.blockNumber < r.minBlock || a.arrivedAt > r.expires) revert NotReady();
        r.done = true;
        credit[a.by] += r.bounty;
        emit Collected(id, a.by, r.bounty);
    }

    /// The requester, after an unanswered request expired: the bounty back (credited, then claim()).
    function cancel(uint256 id) external {
        Request storage r = requests[id];
        if (r.requester != msg.sender || r.done) revert BadRequest();
        if (block.timestamp <= r.expires) revert NotReady();
        r.done = true;
        credit[msg.sender] += r.bounty;
        emit Cancelled(id);
    }

    /// What the caller collected or got back.
    function claim() external nonReentrant {
        uint256 v = credit[msg.sender];
        if (v == 0) revert NotReady();
        credit[msg.sender] = 0;
        emit Claimed(msg.sender, v);
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
    }
}

/// @title SaphanReadResponder: on source chain X, answers view calls to SaphanReads on ZETAPHY through Hyperlane
contract SaphanReadResponder {
    /// The gas every view call gets (fixed, so an answerer cannot make a call fail by giving it less).
    uint256 public constant READ_GAS = 500_000;
    uint256 public constant MAX_RESULT = 1024;

    IReadsMailbox public immutable mailbox;   // X's Mailbox
    uint32 public immutable zetaphyDomain;
    bytes32 public immutable reads;           // SaphanReads(X) on ZETAPHY

    event Answer(bytes32 indexed messageId, address indexed target, bytes32 dataHash, uint64 blockNumber, address by);

    error Fee(uint256 needed);
    error LowGas();

    constructor(IReadsMailbox mailbox_, uint32 zetaphyDomain_, address reads_) {
        require(address(mailbox_) != address(0) && reads_ != address(0), "config");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        reads = bytes32(uint256(uint160(reads_)));
    }

    /// The message an answer of `target.call(data)` made now by `by` would carry (a result longer than MAX_RESULT
    /// counts as a failed call, so every answer fits).
    function body(address target, bytes calldata data, address by) public view returns (bytes memory) {
        if (gasleft() < READ_GAS + READ_GAS / 63 + 30_000) revert LowGas();
        (bool ok, bytes memory result) = target.staticcall{gas: READ_GAS}(data);
        if (result.length > MAX_RESULT) { ok = false; result = ""; }
        return abi.encode(target, keccak256(data), uint64(block.number), uint64(block.timestamp), ok, result, by);
    }

    function quote(address target, bytes calldata data) external view returns (uint256) {
        return mailbox.quoteDispatch(zetaphyDomain, reads, body(target, data, msg.sender));
    }

    /// Anyone: answers `target.call(data)` at this block. msg.value: exactly the Mailbox fee (quote).
    function answer(address target, bytes calldata data) external payable returns (bytes32 messageId) {
        bytes memory b = body(target, data, msg.sender);
        uint256 fee = mailbox.quoteDispatch(zetaphyDomain, reads, b);
        if (msg.value != fee) revert Fee(fee);
        messageId = mailbox.dispatch{value: fee}(zetaphyDomain, reads, b);
        emit Answer(messageId, target, keccak256(data), uint64(block.number), msg.sender);
    }
}

interface IReadsLightClient {
    function appHashAt(uint64 height) external view returns (bytes32);
}

/// ZetaphyBridgeInbox's pure proof functions (any deployed instance).
interface IReadsZetaphyProofs {
    struct InnerOp { bytes prefix; bytes suffix; }
    function iavlRoot(bytes memory key, bytes32 value, bytes calldata leafPrefix, InnerOp[] calldata path) external pure returns (bytes32);
    function storeRoot(bytes memory name, bytes32 root, InnerOp[] calldata path) external pure returns (bytes32);
}

/// @title SaphanZetaphyReads: on a source chain, a storage slot of a ZETAPHY contract proven from ZETAPHY's state
/// @notice A view: a contract on this chain calls verify() inside its own transaction with the proof (nothing is
///         stored, so every reader checks its own proof and decides how recent it must be).
contract SaphanZetaphyReads {
    IReadsLightClient public immutable lightClient; // StarkLightClient: ZETAPHY finality on this chain
    IReadsZetaphyProofs public immutable proofs;

    error BadStateProof(uint256 step);
    error Stale(uint64 height, uint64 minHeight);

    constructor(IReadsLightClient lc, IReadsZetaphyProofs proofs_) {
        require(address(lc) != address(0) && address(proofs_) != address(0), "config");
        lightClient = lc;
        proofs = proofs_;
    }

    /// Returns `value` when `account`'s storage `slot` holds it at ZETAPHY height `height` (final in the light client)
    /// and height >= minHeight; reverts otherwise. An existence proof: a slot never written cannot be shown this way.
    function verify(uint64 height, uint64 minHeight, address account, bytes32 slot, bytes32 value, bytes calldata leafPrefix,
        IReadsZetaphyProofs.InnerOp[] calldata iavlPath, IReadsZetaphyProofs.InnerOp[] calldata storePath) external view returns (bytes32)
    {
        if (height < minHeight) revert Stale(height, minHeight);
        bytes32 app = lightClient.appHashAt(height);
        if (app == bytes32(0)) revert BadStateProof(0);
        bytes32 evmRoot = proofs.iavlRoot(abi.encodePacked(uint8(2), account, slot), value, leafPrefix, iavlPath);
        if (proofs.storeRoot("evm", evmRoot, storePath) != app) revert BadStateProof(1);
        return value;
    }
}

contracts/SaphanRecovery.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRecoveryToken {
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanRecoveryClaims: pay back what an incident owed, from a Merkle root of owed balances
/// @notice Saphan PR 6, item S10 (docs/SAPHAN-PR6.md). Testnet only, not audited.
///
///         The guided recovery after an incident (`node scripts/saphan.js recovery ...`):
///           1. pause      guardians pause the route (lockbox, guard), as today;
///           2. snapshot   who is owed what, rebuilt by anyone from public events (src/saphanrecovery.js: balances of
///                         token(X) at the incident block, releases queued and not paid, locks never minted, minus
///                         what the attacker took if governance decides so). The SAME leaf and tree as the lockbox's
///                         escape hatch (src/saphansafety.js exitTree): leaf = keccak256(keccak256(abi.encode(account,
///                         owed))), sorted-pair Merkle tree;
///           3. claims     governance (the ZetaphyTimelock: its delay gives everyone time to check the root against
///                         their own rebuild) deploys this contract and calls start(root, total) once; anyone funds it
///                         (insurance, treasury, recovered funds); each account claims its line once, in full when the
///                         pool covers the total, else pro rata; after `claimPeriod`, sweep() sends what is left to
///                         `sweepTo` (e.g. the HackInsurance pool);
///           4. resume     governance unpauses the route (the CLI checks that the root was set and lists the calls).
///
///         The pool is fixed at start(): coins that arrive later are swept, so the order of claims never changes
///         anyone's share. Pull payment to the caller only; nonReentrant; no admin besides the one start() call.
contract SaphanRecoveryClaims {
    address public immutable governance;   // ZetaphyTimelock
    address public immutable token;        // address(0): the native coin
    address public immutable sweepTo;
    uint64 public immutable claimPeriod;

    bytes32 public root;
    uint256 public total;                  // the sum the root owes
    uint256 public pool;                   // what this contract held at start()
    uint256 public paid;
    uint64 public deadline;
    bool public swept;
    mapping(address => bool) public claimed;
    uint256 private unlocked = 1;

    event Funded(address indexed from, uint256 amount);
    event Started(bytes32 root, uint256 total, uint256 pool, uint64 deadline);
    event Claimed(address indexed account, uint256 owed, uint256 paid);
    event Swept(address to, uint256 amount);

    error NotGovernance();
    error AlreadyStarted();
    error NotStarted();
    error BadRoot();
    error AlreadyClaimed();
    error BadProof();
    error Closed();
    error StillOpen(uint64 deadline);
    error PayFailed();
    error Reentrancy();
    error WrongAsset();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    constructor(address governance_, address token_, address sweepTo_, uint64 claimPeriod_) {
        require(governance_ != address(0) && sweepTo_ != address(0) && claimPeriod_ >= 7 days, "config");
        governance = governance_;
        token = token_;
        sweepTo = sweepTo_;
        claimPeriod = claimPeriod_;
    }

    receive() external payable {
        if (token != address(0)) revert WrongAsset();
        emit Funded(msg.sender, msg.value);
    }

    /// Funds a token pool (approve first).
    function fund(uint256 amount) external nonReentrant {
        if (token == address(0)) revert WrongAsset();
        emit Funded(msg.sender, amount);
        if (!IRecoveryToken(token).transferFrom(msg.sender, address(this), amount)) revert PayFailed();
    }

    /// Governance, once: the root of what is owed and its total. The pool is what this contract holds now.
    function start(bytes32 root_, uint256 total_) external {
        if (msg.sender != governance) revert NotGovernance();
        if (root != bytes32(0)) revert AlreadyStarted();
        if (root_ == bytes32(0) || total_ == 0) revert BadRoot();
        root = root_;
        total = total_;
        pool = _held();
        deadline = uint64(block.timestamp) + claimPeriod;
        emit Started(root_, total_, pool, deadline);
    }

    /// What `owed` pays now: in full when the pool covers the total, else owed x pool / total.
    function payout(uint256 owed) public view returns (uint256) {
        return total <= pool ? owed : owed * pool / total;
    }

    /// The caller's line of the root, once, before the deadline.
    function claim(uint256 owed, bytes32[] calldata proof) external nonReentrant {
        if (root == bytes32(0)) revert NotStarted();
        if (block.timestamp > deadline || swept) revert Closed();
        if (claimed[msg.sender]) revert AlreadyClaimed();
        bytes32 node = keccak256(bytes.concat(keccak256(abi.encode(msg.sender, owed))));
        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 p = proof[i];
            node = node < p ? keccak256(abi.encode(node, p)) : keccak256(abi.encode(p, node));
        }
        if (node != root) revert BadProof();
        claimed[msg.sender] = true;
        uint256 amount = payout(owed);
        paid += amount;
        emit Claimed(msg.sender, owed, amount);
        if (token != address(0)) {
            if (!IRecoveryToken(token).transfer(msg.sender, amount)) revert PayFailed();
        } else {
            (bool ok, ) = msg.sender.call{value: amount}("");
            if (!ok) revert PayFailed();
        }
    }

    /// Anyone, after the deadline: what is left goes to sweepTo. Once.
    function sweep() external nonReentrant {
        if (root == bytes32(0)) revert NotStarted();
        if (block.timestamp <= deadline) revert StillOpen(deadline);
        if (swept) revert Closed();
        swept = true;
        uint256 left = _held();
        emit Swept(sweepTo, left);
        if (token != address(0)) {
            if (!IRecoveryToken(token).transfer(sweepTo, left)) revert PayFailed();
        } else {
            (bool ok, ) = sweepTo.call{value: left}("");
            if (!ok) revert PayFailed();
        }
    }

    function _held() private view returns (uint256) {
        return token == address(0) ? address(this).balance : IRecoveryToken(token).balanceOf(address(this));
    }

}

contracts/SaphanTokens.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY Saphan, token routes: tokens BORN on ZETAPHY go out to an EVM chain and come back
// (the reverse of the v2 ETH routes in HyperlaneLockBoxV2.sol). docs/SAPHAN-TOKENS.md.
//
//   ZETAPHY                                                     destination chain X (Sepolia, Base Sepolia, ...)
//   ZetaphyTokenVault(token, X) --lock: Hyperlane message---->  SaphanSyntheticToken(token, X) queues a mint,
//     escrows the token             (ISM on X: OUR validators   mints after the delay (veto, daily cap, supply cap, pause)
//                                    for origin ZETAPHY)
//     queues a release <-----------burn: Hyperlane message----- sendBack(): burns, dispatches
//     pays after the delay          (ISM on ZETAPHY: Hyperlane's validator(s) for origin X)
//     (veto, daily limit, pause, never more than it locked for X)
//
// One vault per (token, destination) and one synthetic per (token, destination): a hole on chain X (or in X's
// synthetic, or X's validators) can only ask vault(token, X) for a release, and that vault pays at most what was
// locked in it for X. It cannot reach another token's vault or another destination's escrow.
//
// Local copies of the Hyperlane v3 interfaces, checked against hyperlane-xyz/hyperlane-monorepo at commit
// 1aadbba0696ecf96ed4c06f78c978d08db22c0ad (as HyperlaneLockBoxV2.sol): IMailbox dispatch / quoteDispatch,
// IMessageRecipient.handle, ISpecifiesInterchainSecurityModule.interchainSecurityModule. Named apart from the
// other files' copies (the build compiles every file in one unit and names artifacts by contract).

interface ISaphanTokenMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface ISaphanTokenIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// ThreatRegistry's hold view for ZETAPHY addresses (as BridgeGuard uses it).
interface ISaphanTokenThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// @title SaphanTokenEndpoint: what both ends of a token route share
/// @notice Sending: the subclass takes the tokens (_take: the vault escrows, the synthetic burns), then this
///         dispatches a 288-byte body through the local Mailbox to the one remote contract:
///           abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to,
///                      uint256 amount, uint256 dstChainId, address dstContract, address originToken)
///         `originToken` is the token's address on ZETAPHY (the same on both ends), so a message of token A can
///         never be taken by token B's endpoint even if every other field matched.
///         Receiving: handle() takes a message only from the Mailbox (after the ISM this contract names, never the
///         Mailbox default, never zero), from the remote domain and the remote contract (sender), whose body names
///         the remote chain and contract as the source, this chain and contract as the destination, and this
///         route's origin token; each message once. It never pays at once: the payout is queued (Queued) and anyone
///         claims it after `delay`, while not vetoed, not paused and within the daily limit (over it, it waits for
///         the next UTC day); the subclass adds its own bound (_pay: the vault's backing, the synthetic's supply
///         cap). A message is never refused for a limit or a pause, so nothing depends on the relayer retrying.
///         Starts PAUSED (deployed closed): opening is governance's unpause, on both ends.
///         Roles: governance (a timelock: 48 h) unpauses, lifts vetoes, raises limits, changes the ISM; guardians
///         (a multisig) only reduce risk, at once: pause, veto, lower the daily limit, lengthen the delay.
abstract contract SaphanTokenEndpoint {
    struct Pending {
        address to;
        uint64 readyAt;      // zero: no such message
        bool done;
        bool vetoed;
        uint256 amount;
    }

    /// The message body (288 bytes, abi.encode of these fields in this order).
    struct Body {
        uint256 srcChainId;
        address srcContract;
        uint256 srcNonce;
        address sender;
        address to;
        uint256 amount;
        uint256 dstChainId;
        address dstContract;
        address originToken;
    }

    ISaphanTokenMailbox public immutable mailbox;
    uint32 public immutable remoteDomain;     // the other end's Hyperlane domain
    uint256 public immutable remoteChainId;   // the other end's EVM chain id, as it writes it into bodies
    bytes32 public immutable remote;          // the other end's contract (the only sender, the only recipient)
    address public immutable hook;            // zero = the Mailbox default hook
    address public immutable originToken;     // the token's address on ZETAPHY

    uint64 public constant MAX_DELAY = 30 days;
    uint256 public constant BODY_LENGTH = 288;

    address public governance;
    mapping(address => bool) public guardian;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule). Never zero.
    ISaphanTokenIsm public interchainSecurityModule;
    bool public paused;
    uint256 public dailyLimit;                // token units paid out (released / minted) per UTC day
    uint256 public paidToday;
    uint64 public day;
    uint64 public delay;                      // seconds between a message and its claim

    uint256 public nonce;                     // messages sent
    uint256 public received;                  // messages recorded (the relayer workflow compares it with the other end's nonce)
    mapping(bytes32 => Pending) public pending; // by keccak256(body)
    uint256 private entered = 1;

    event Sent(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount, bytes32 messageId);
    event Queued(bytes32 indexed id, uint256 indexed srcNonce, address sender, address indexed to, uint256 amount, uint64 readyAt);
    event Paid(bytes32 indexed id, address indexed to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by);
    event VetoLifted(bytes32 indexed id);
    event Paused(address indexed by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event DailyLimitSet(uint256 limit);
    event DelaySet(uint64 delay);

    error NotGovernance();
    error NotGuardian();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error WrongDestination();
    error WrongToken(address token);
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();
    error IsPaused();
    error NoMessage();
    error AlreadyDone();
    error IsVetoed();
    error NotReady(uint64 readyAt);
    error OverLimit(uint256 remaining);
    error PayFailed();
    error Fee(uint256 needed);
    error Reentered();

    /// Deploy settings shared by both ends (one tuple: fewer constructor arguments).
    struct Config {
        ISaphanTokenMailbox mailbox;
        uint32 remoteDomain;
        uint256 remoteChainId;
        bytes32 remote;
        address hook;
        address originToken;
        ISaphanTokenIsm ism;
        address governance;
        address guardian;
        uint256 dailyLimit;
        uint64 delay;
    }

    constructor(Config memory c) {
        require(address(c.mailbox) != address(0) && c.remote != bytes32(0) && c.remoteChainId != 0 && c.originToken != address(0)
            && address(c.ism) != address(0) && c.governance != address(0) && c.delay <= MAX_DELAY, "config");
        mailbox = c.mailbox;
        remoteDomain = c.remoteDomain;
        remoteChainId = c.remoteChainId;
        remote = c.remote;
        hook = c.hook;
        originToken = c.originToken;
        interchainSecurityModule = c.ism;
        governance = c.governance;
        dailyLimit = c.dailyLimit;
        delay = c.delay;
        paused = true;
        emit IsmSet(address(c.ism));
        emit GovernanceSet(c.governance);
        emit DailyLimitSet(c.dailyLimit);
        emit DelaySet(c.delay);
        emit Paused(msg.sender);
        if (c.guardian != address(0)) { guardian[c.guardian] = true; emit GuardianSet(c.guardian, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyGuardian() { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); _; }
    modifier nonReentrant() { if (entered != 1) revert Reentered(); entered = 2; _; entered = 1; }

    // ---------------------------------------------------------------- what the two ends do differently

    /// Takes `amount` from msg.sender for a send (the vault escrows it, the synthetic burns it).
    function _take(address from, uint256 amount) internal virtual;
    /// Pays a claimed message (the vault releases within its backing, the synthetic mints within its cap).
    function _pay(address to, uint256 amount) internal virtual;

    // ---------------------------------------------------------------- sending

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount, remoteChainId, address(uint160(uint256(remote))), originToken);
    }

    /// The Mailbox fee for the next send (msg.value of the send).
    function quote(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function _send(address to, uint256 amount) internal returns (bytes32 messageId) {
        if (paused) revert IsPaused();
        require(amount > 0 && to != address(0), "send");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < fee) revert Fee(fee);
        _take(msg.sender, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(remoteDomain, remote, b)
            : mailbox.dispatch{value: fee}(remoteDomain, remote, b, "", hook);
        emit Sent(n, msg.sender, to, amount, messageId);
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(remoteDomain, remote, b) : mailbox.quoteDispatch(remoteDomain, remote, b, "", hook);
    }

    // ---------------------------------------------------------------- receiving

    /// Called by the Mailbox after interchainSecurityModule verified the message.
    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != address(mailbox)) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != remoteDomain) revert WrongOrigin(origin);
        if (sender != remote) revert WrongSender(sender);
        if (b.length != BODY_LENGTH) revert BadBody();
        Body memory m = abi.decode(b, (Body));
        if (m.srcChainId != remoteChainId || bytes32(uint256(uint160(m.srcContract))) != remote) revert WrongSource();
        if (m.dstChainId != block.chainid || m.dstContract != address(this)) revert WrongDestination();
        if (m.originToken != originToken) revert WrongToken(m.originToken);
        if (m.to == address(0) || m.amount == 0) revert BadBody();
        bytes32 id = keccak256(b);
        if (pending[id].readyAt != 0) revert Replay(id);
        uint64 readyAt = uint64(block.timestamp) + delay;
        pending[id] = Pending(m.to, readyAt, false, false, m.amount);
        received += 1;
        emit Queued(id, m.srcNonce, m.sender, m.to, m.amount, readyAt);
    }

    /// Anyone: pays a queued message to its receiver once every check passes.
    function claim(bytes32 id) external nonReentrant {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        if (p.vetoed) revert IsVetoed();
        if (paused) revert IsPaused();
        if (block.timestamp < p.readyAt) revert NotReady(p.readyAt);
        uint64 today = uint64(block.timestamp / 1 days);
        if (day != today) { day = today; paidToday = 0; }
        uint256 amount = p.amount;
        if (paidToday + amount > dailyLimit) revert OverLimit(dailyLimit > paidToday ? dailyLimit - paidToday : 0);
        p.done = true;
        paidToday += amount;
        emit Paid(id, p.to, amount);
        _pay(p.to, amount);
    }

    /// What can still be paid out today.
    function remainingToday() external view returns (uint256) {
        uint256 used = day == uint64(block.timestamp / 1 days) ? paidToday : 0;
        return dailyLimit > used ? dailyLimit - used : 0;
    }

    // ---------------------------------------------------------------- guardians: only reduce risk, at once

    function pause() external onlyGuardian { paused = true; emit Paused(msg.sender); }

    /// Stops a queued payout that is not paid yet (during its delay, or while it waits for a limit).
    function veto(bytes32 id) external onlyGuardian {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        p.vetoed = true;
        emit Vetoed(id, msg.sender);
    }

    function lowerDailyLimit(uint256 v) external onlyGuardian {
        require(v < dailyLimit, "lower only");
        dailyLimit = v;
        emit DailyLimitSet(v);
    }

    function raiseDelay(uint64 d) external onlyGuardian {
        require(d > delay && d <= MAX_DELAY, "raise only");
        delay = d;
        emit DelaySet(d);
    }

    // ---------------------------------------------------------------- governance (a timelock)

    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    function liftVeto(bytes32 id) external onlyGov {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        p.vetoed = false;
        emit VetoLifted(id);
    }

    function setDailyLimit(uint256 v) external onlyGov { dailyLimit = v; emit DailyLimitSet(v); }

    function setDelay(uint64 d) external onlyGov {
        require(d <= MAX_DELAY, "delay");
        delay = d;
        emit DelaySet(d);
    }

    /// A new ISM (e.g. more validators, a higher threshold). Never zero.
    function setInterchainSecurityModule(ISaphanTokenIsm ism) external onlyGov {
        require(address(ism) != address(0), "ism");
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }
}

/// @title ZetaphyTokenVault: the ZETAPHY side of one token to one destination chain
/// @notice lock(to, amount) escrows `amount` of `originToken` (msg.value = quote(): the Mailbox fee) and sends a
///         mint to that destination's SaphanSyntheticToken. A release (a burn on the destination) is paid from this
///         vault only, after the delay, and never more than `locked` (everything locked here minus everything
///         released here): a compromise of one destination drains at most its own escrow, never another
///         destination's or another token's.
///         The token: any ERC-20 on ZETAPHY that governance adds (deploys a vault for), including the native coin
///         through its ERC-20 precompile (0xEeee…EEeE: approve, then lock). Refused: tokens that deliver less than
///         asked (fee-on-transfer: OddToken), that return false, or whose decimals() differ from the chain table's.
///         Not supported (governance must not add them): rebasing tokens, tokens with blocklists or admin
///         transfers (a vault's balance must only move through this contract). Transfers with no return value
///         (USDT style) are accepted.
///         Extra safety: `lockCap` bounds everything ever outstanding to this destination (and so the synthetic
///         supply that can exist); a ThreatRegistry (optional) holds a flagged sender (no lock) or receiver (the
///         release waits until the hold ends, as BridgeGuard's vaccine does).
contract ZetaphyTokenVault is SaphanTokenEndpoint {
    uint8 public immutable decimals;          // the token's, checked at deploy (the synthetic has the same)
    uint256 public locked;                    // backing: locked minus released
    uint256 public lockCap;                   // `locked` may never exceed this (governance raises, guardians lower)
    ISaphanTokenThreats public threats;       // zero: no hold check

    event LockCapSet(uint256 cap);
    event ThreatsSet(address registry);
    event ExcessRecovered(address indexed to, uint256 amount);

    error OddToken(uint256 received);
    error TransferFailed();
    error OverCap(uint256 cap);
    error OverBacking(uint256 locked);
    error Held(address who);

    /// `c.remote`: the destination's SaphanSyntheticToken; `c.originToken`: the token on ZETAPHY.
    constructor(Config memory c, uint8 decimals_, uint256 lockCap_, ISaphanTokenThreats threats_) SaphanTokenEndpoint(c) {
        address token_ = c.originToken;
        require(token_.code.length > 0 || token_ == 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE, "token");
        (bool ok, bytes memory ret) = token_.staticcall(abi.encodeWithSignature("decimals()"));
        require(ok && ret.length == 32 && abi.decode(ret, (uint256)) == decimals_, "decimals");
        decimals = decimals_;
        lockCap = lockCap_;
        threats = threats_;
        emit LockCapSet(lockCap_);
        emit ThreatsSet(address(threats_));
    }

    /// Escrows `amount` here and sends a mint of the same amount (same decimals) to `to` on the destination.
    function lock(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        if (_held(from)) revert Held(from);
        if (locked + amount > lockCap) revert OverCap(lockCap);
        uint256 before = _balance();
        _call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, address(this), amount));
        uint256 got = _balance() - before;
        if (got != amount) revert OddToken(got);
        locked += amount;
    }

    function _pay(address to, uint256 amount) internal override {
        if (_held(to)) revert Held(to);
        if (amount > locked) revert OverBacking(locked);
        locked -= amount;
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
    }

    function _balance() private view returns (uint256) {
        (bool ok, bytes memory ret) = originToken.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        if (!ok || ret.length < 32) revert TransferFailed();
        return abi.decode(ret, (uint256));
    }

    /// A token call that must succeed and, if it returns anything, return true.
    function _call(bytes memory data) private {
        (bool ok, bytes memory ret) = originToken.call(data);
        if (!ok || (ret.length != 0 && (ret.length < 32 || !abi.decode(ret, (bool))))) revert TransferFailed();
    }

    function _held(address who) private view returns (bool h) {
        ISaphanTokenThreats t = threats;
        if (address(t) == address(0)) return false;
        (h, ) = t.isContractHeld(who);
    }

    function lowerLockCap(uint256 v) external onlyGuardian {
        require(v < lockCap, "lower only");
        lockCap = v;
        emit LockCapSet(v);
    }

    function setLockCap(uint256 v) external onlyGov { lockCap = v; emit LockCapSet(v); }

    function setThreats(ISaphanTokenThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Tokens sent here without lock() are not backing; governance may send them on. Never touches `locked`.
    function recoverExcess(address to) external onlyGov nonReentrant {
        uint256 b = _balance();
        require(to != address(0) && b > locked, "no excess");
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, b - locked));
        if (_balance() < locked) revert OverBacking(locked);
        emit ExcessRecovered(to, b - locked);
    }
}

/// @title SaphanSyntheticToken: a ZETAPHY token on one destination chain (e.g. zZETAPHY on Base Sepolia)
/// @notice An ERC-20 that exists only through its vault on ZETAPHY: minted only for messages from ZETAPHY's
///         domain and that vault (verified by a multisig ISM of OUR validators for origin ZETAPHY), after the mint
///         delay, within the daily mint limit and the supply cap, while not vetoed or paused. sendBack(to, amount)
///         burns the caller's tokens and sends the release to the vault (msg.value = quote()).
///         Its value is exactly the vault's safety: one synthetic is a claim on one token locked in
///         ZetaphyTokenVault(token, this chain); if that vault, our validators or ZETAPHY fail, it can be worth
///         less or nothing.
contract SaphanSyntheticToken is SaphanTokenEndpoint {
    string public name;
    string public symbol;
    uint8 public immutable decimals;          // the origin token's
    uint256 public totalSupply;
    uint256 public supplyCap;                 // totalSupply may never exceed this (governance raises, guardians lower)
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event SupplyCapSet(uint256 cap);

    error OverCap(uint256 cap);

    /// `c.remote`: the ZetaphyTokenVault on ZETAPHY (domain c.remoteDomain, chain c.remoteChainId).
    constructor(string memory name_, string memory symbol_, uint8 decimals_, Config memory c, uint256 supplyCap_) SaphanTokenEndpoint(c) {
        require(bytes(name_).length > 0 && bytes(symbol_).length > 0 && decimals_ <= 36, "token");
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
        supplyCap = supplyCap_;
        emit SupplyCapSet(supplyCap_);
    }

    /// Burns `amount` of the caller's tokens and sends their release on ZETAPHY to `to`.
    function sendBack(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        require(balanceOf[from] >= amount, "balance");
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function _pay(address to, uint256 amount) internal override {
        if (totalSupply + amount > supplyCap) revert OverCap(supplyCap);
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v);
        return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v;
        balanceOf[to] += v;
        emit Transfer(f, to, v);
    }

    function lowerSupplyCap(uint256 v) external onlyGuardian {
        require(v < supplyCap, "lower only");
        supplyCap = v;
        emit SupplyCapSet(v);
    }

    function setSupplyCap(uint256 v) external onlyGov { supplyCap = v; emit SupplyCapSet(v); }
}

contracts/SignalBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SignalBoard: browsers find each other on the ZETAPHY chain itself (testnet)
/// @notice A public notice board for WebRTC signaling, so two browsers that hold
///         (or want) the same model can connect with no server of ours and no
///         third-party tracker: a browser posts a short-lived message under a
///         topic (e.g. sha256 of "zetaphy-signal/1|chunks|<manifest hash>"), others
///         read the board with eth_getLogs, and the offer/answer go to one
///         recipient, ENCRYPTED to that recipient's key and signed by the sender
///         (zetaphy-neuro/ai/browser/signal.js). The contract never reads the
///         payload: it only bounds it.
///
///         Nothing is stored but a rate counter: messages live in event logs.
///         "Expiry" is a field readers enforce (block time + at most MAX_TTL); the
///         log itself stays on chain forever, so payloads must be encrypted or
///         harmless (an announce reveals a session key, a topic and a time).
///
///         Limits: payload 1..MAX_PAYLOAD bytes; expiresAt in (now, now + MAX_TTL];
///         each sender at most MAX_PER_WINDOW posts per WINDOW seconds. A sender
///         address costs nothing to make, so the rate limit only bounds one key;
///         what bounds a flood is gas (testnet coins come from the faucet, which
///         is rate-limited per internet address) and readers' own caps.
///
///         No owner, no funds, no upgrade, nothing to govern.
contract SignalBoard {
    uint256 public constant MAX_PAYLOAD = 2048;
    uint256 public constant MAX_TTL = 600;
    uint256 public constant WINDOW = 60;
    uint256 public constant MAX_PER_WINDOW = 12;

    struct Rate {
        uint64 windowStart;
        uint32 count;
    }

    mapping(address => Rate) public rate;

    /// @param topic what the message is about (readers filter on it)
    /// @param to recipient's peer id (16 bytes, left-aligned) or 0 for everyone on the topic
    event Signal(bytes32 indexed topic, bytes32 indexed to, address indexed from, uint64 expiresAt, bytes payload);

    error NoTopic();
    error PayloadSize();
    error BadExpiry();
    error RateLimited();

    function post(bytes32 topic, bytes32 to, uint64 expiresAt, bytes calldata payload) external {
        if (topic == bytes32(0)) revert NoTopic();
        if (payload.length == 0 || payload.length > MAX_PAYLOAD) revert PayloadSize();
        if (expiresAt <= block.timestamp || expiresAt > block.timestamp + MAX_TTL) revert BadExpiry();
        Rate memory r = rate[msg.sender];
        if (block.timestamp >= uint256(r.windowStart) + WINDOW) {
            r.windowStart = uint64(block.timestamp);
            r.count = 0;
        }
        if (r.count >= MAX_PER_WINDOW) revert RateLimited();
        r.count += 1;
        rate[msg.sender] = r;
        emit Signal(topic, to, msg.sender, expiresAt, payload);
    }

    /// @notice Posts left for `who` in the current window.
    function remaining(address who) external view returns (uint256) {
        Rate memory r = rate[who];
        if (block.timestamp >= uint256(r.windowStart) + WINDOW) return MAX_PER_WINDOW;
        return MAX_PER_WINDOW - r.count;
    }
}

contracts/SimpleMultisig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SimpleMultisig: k-of-n owners for ZETAPHY admin roles (testnet)
/// @notice Holds governance of BridgeGuard / BridgeAirlock / StableGateway so
///         that no single key can change limits, prices or lanes. Any owner
///         proposes a call; it runs once `threshold` owners confirmed it.
///         Owners and the threshold change only through the multisig itself.
///         Changing them (setOwners) starts a new owner epoch: every proposal
///         made under an older owner set can no longer be confirmed or
///         executed (SM-1: a removed owner's confirmation must not count, and a
///         lowered threshold must not apply to old proposals). Re-propose it.
///         On mainnet prefer an audited Safe; this is small on purpose.
contract SimpleMultisig {
    struct Proposal {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint8 confirmations;
    }

    address[] public owners;
    mapping(address => bool) public isOwner;
    uint8 public threshold;
    Proposal[] public proposals;
    mapping(uint256 => mapping(address => bool)) public confirmed;
    uint256 public ownersEpoch;                      // bumped by every setOwners
    mapping(uint256 => uint256) public proposalEpoch; // proposal id -> owner epoch it was made in

    event Proposed(uint256 indexed id, address indexed by, address to, uint256 value);
    event Confirmed(uint256 indexed id, address indexed by);
    event Revoked(uint256 indexed id, address indexed by);
    event Executed(uint256 indexed id);

    error NotOwner();
    error BadConfig();
    error Done();
    error Twice();
    error NotEnough();
    error CallFailed(bytes reason);
    error Stale();

    constructor(address[] memory owners_, uint8 threshold_) {
        _setOwners(owners_, threshold_);
    }

    receive() external payable {}

    modifier onlyOwner() { if (!isOwner[msg.sender]) revert NotOwner(); _; }

    function propose(address to, uint256 value, bytes calldata data) external onlyOwner returns (uint256 id) {
        id = proposals.length;
        proposals.push(Proposal(to, value, data, false, 0));
        proposalEpoch[id] = ownersEpoch;
        emit Proposed(id, msg.sender, to, value);
        _confirm(id);
    }

    function confirm(uint256 id) external onlyOwner { _confirm(id); }

    function revoke(uint256 id) external onlyOwner {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (!confirmed[id][msg.sender]) revert NotEnough();
        confirmed[id][msg.sender] = false;
        p.confirmations -= 1;
        emit Revoked(id, msg.sender);
    }

    function execute(uint256 id) external onlyOwner returns (bytes memory) {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (proposalEpoch[id] != ownersEpoch) revert Stale();
        if (p.confirmations < threshold) revert NotEnough();
        p.executed = true;
        (bool ok, bytes memory ret) = p.to.call{value: p.value}(p.data);
        if (!ok) revert CallFailed(ret);
        emit Executed(id);
        return ret;
    }

    /// Change owners / threshold: only as a proposal executed by the multisig.
    function setOwners(address[] calldata owners_, uint8 threshold_) external {
        if (msg.sender != address(this)) revert NotOwner();
        for (uint256 i = 0; i < owners.length; i++) isOwner[owners[i]] = false;
        _setOwners(owners_, threshold_);
        ownersEpoch += 1;   // older proposals (and their confirmations) are void
    }

    function ownerCount() external view returns (uint256) { return owners.length; }
    function proposalCount() external view returns (uint256) { return proposals.length; }

    function _confirm(uint256 id) private {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (proposalEpoch[id] != ownersEpoch) revert Stale();
        if (confirmed[id][msg.sender]) revert Twice();
        confirmed[id][msg.sender] = true;
        p.confirmations += 1;
        emit Confirmed(id, msg.sender);
    }

    function _setOwners(address[] memory owners_, uint8 threshold_) private {
        if (threshold_ < 2 || threshold_ > owners_.length || owners_.length > 20) revert BadConfig();
        delete owners;
        for (uint256 i = 0; i < owners_.length; i++) {
            address o = owners_[i];
            if (o == address(0) || isOwner[o]) revert BadConfig();
            isOwner[o] = true;
            owners.push(o);
        }
        threshold = threshold_;
    }
}

contracts/StableGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20Permit {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
}

interface INeuroJobs {
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256);
    function getJob(uint256 id) external view returns (address requester, uint64 created, uint8 status, bytes32 chain,
        string memory target, uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat);
    function FAIL_BURN_BPS() external view returns (uint16);
    function credit(address) external view returns (uint256);
    function withdraw() external;
}

/// ZetaphyOracle's consumer surface: a USD price (18 decimals) or a revert.
interface IPriceOracle {
    function price(address asset) external view returns (uint256 value, uint256 updatedAt);
}

/// @title StableGateway: use the Neuro network paying only in a stablecoin
/// @notice A user who holds a stablecoin but no ZETAPHY signs a job request.
///         Anyone (a "relayer") submits it and pays the gas; in the same
///         transaction the gateway takes the user's stablecoin (the cost of
///         the ZETAPHY fee, plus the relayer's tip) and pays the job fee in
///         ZETAPHY from its own reserve.
///         Price: ZetaphyOracle.price(zetaAsset) (ZETAPHY in USD, guarded: TWAP of
///         the DEX, Pyth, deviation, staleness, circuit breaker), and for each
///         accepted stablecoin either its own oracle price or a $1 peg. When the
///         oracle has no valid price the request reverts (PriceUnavailable, with
///         the oracle's reason): never a silently wrong price.
///         TESTNET FALLBACK: a fixed price per token (stablecoin units per 1
///         ZETAPHY), used ONLY while governance switched testnetFixedPrices on
///         (TestnetFixedPricesSet event; priceSource() says so). It is not a
///         market price; it exists for testnet bring-up before the oracle has a
///         TWAP window, and is off by default.
///         Refunds stay in the paying currency (SG-1): the gateway is the job's
///         requester, so when a job fails or expires NeuroJobs credits the
///         ZETAPHY refund to the gateway (back into the reserve), and
///         `refund(jobId)` pays the user the same share of the stablecoin it
///         paid (cost x (1 - NeuroJobs' fail burn)). The reserve is never a
///         stablecoin -> ZETAPHY exchange.
///         Roles: the owner (the ZetaphyTimelock) sets everything and moves funds;
///         guardians (named by the owner) may pause requests at once.
contract StableGateway {
    INeuroJobs public immutable jobs;
    address public owner;
    mapping(address => bool) public guardian;
    bool public paused;

    IPriceOracle public oracle;
    /// The asset id of ZETAPHY in the oracle (the DEX's wrapped ZETAPHY).
    address public zetaAsset;

    struct TokenConfig {
        bool accepted;
        bool oraclePriced;   // false: counted as $1 (a USD stablecoin)
        uint8 decimals;
    }
    mapping(address => TokenConfig) public tokens;

    /// TESTNET ONLY: stablecoin base units per 1 ZETAPHY (1e18 wei), used only while testnetFixedPrices is on.
    bool public testnetFixedPrices;
    mapping(address => uint256) public testnetFixedPrice;
    mapping(address => uint256) public nonces;

    /// What each gateway-paid job cost its user, for the stablecoin refund of a failed job.
    struct PaidJob { address user; address token; uint128 cost; bool refunded; }
    mapping(uint256 => PaidJob) public paidJobs;
    uint8 private constant JOB_FAILED = 3; // NeuroJobs.Status.Failed

    bytes32 public constant REQUEST_TYPEHASH = keccak256(
        "JobRequest(address user,address token,bytes32 chain,string target,uint256 fee,uint256 tip,uint256 maxCost,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    struct JobRequest {
        address user;
        address token;
        bytes32 chain;
        string target;
        uint256 fee;      // ZETAPHY (wei) the job pays
        uint256 tip;      // stablecoin units to the relayer
        uint256 maxCost;  // the most stablecoin the user agrees to spend (cost + tip)
        uint256 nonce;
        uint256 deadline;
    }

    struct Permit { uint256 value; uint256 deadline; uint8 v; bytes32 r; bytes32 s; }

    event OracleSet(address oracle, address zetaAsset);
    event TokenSet(address indexed token, bool accepted, bool oraclePriced, uint8 decimals);
    event TestnetFixedPricesSet(bool on);
    event TestnetFixedPriceSet(address indexed token, uint256 pricePerZeta);
    event Paid(uint256 indexed jobId, address indexed user, address indexed token, uint256 cost, uint256 tip, address relayer);
    event OwnerChanged(address owner);
    event GuardianSet(address indexed who, bool on);
    event Paused(address indexed by);
    event Unpaused();
    event Refunded(uint256 indexed jobId, address indexed user, address indexed token, uint256 amount);

    error NotOwner();
    error NotGuardian();
    error GatewayPaused();
    error Expired();
    error BadNonce();
    error BadSignature();
    error NotAccepted();
    error TooExpensive();
    error ReserveLow();
    error NoPriceSource();
    error PriceUnavailable(bytes reason);
    error NotRefundable();

    constructor(INeuroJobs jobs_) {
        jobs = jobs_;
        owner = msg.sender;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    receive() external payable {} // ZETAPHY reserve top-up

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    function setOwner(address o) external onlyOwner {
        owner = o;
        emit OwnerChanged(o);
    }

    function setGuardian(address who, bool on) external onlyOwner {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// A guardian (or the owner) stops new requests at once; only the owner restarts them.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != owner) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused();
    }

    function setOracle(IPriceOracle o, address zetaAsset_) external onlyOwner {
        oracle = o;
        zetaAsset = zetaAsset_;
        emit OracleSet(address(o), zetaAsset_);
    }

    /// Accept (or stop accepting) a stablecoin; oraclePriced: its own oracle price, else $1.
    function setToken(address token, bool accepted, bool oraclePriced, uint8 decimals) external onlyOwner {
        require(decimals <= 30, "decimals");
        tokens[token] = TokenConfig(accepted, oraclePriced, decimals);
        emit TokenSet(token, accepted, oraclePriced, decimals);
    }

    /// TESTNET ONLY: switch the fixed prices on (they replace the oracle) or off.
    function setTestnetFixedPrices(bool on) external onlyOwner {
        testnetFixedPrices = on;
        emit TestnetFixedPricesSet(on);
    }

    /// TESTNET ONLY: stablecoin units per 1 ZETAPHY, used only while testnetFixedPrices is on.
    function setTestnetFixedPrice(address token, uint256 price) external onlyOwner {
        testnetFixedPrice[token] = price;
        emit TestnetFixedPriceSet(token, price);
    }

    /// Stablecoin proceeds go to the treasury the operator names.
    function sweep(address token, address to, uint256 amount) external onlyOwner {
        require(IERC20Permit(token).transfer(to, amount), "transfer failed");
    }

    function withdrawReserve(address payable to, uint256 amount) external onlyOwner {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "transfer failed");
    }

    /// Where quote() takes its price from.
    function priceSource() external view returns (string memory) {
        if (testnetFixedPrices) return "TESTNET FIXED PRICE (set by governance, not a market price)";
        if (address(oracle) == address(0)) return "none";
        return "ZetaphyOracle";
    }

    /// Stablecoin cost of a job fee, rounded up.
    function quote(address token, uint256 fee) public view returns (uint256) {
        TokenConfig memory t = tokens[token];
        if (!t.accepted) revert NotAccepted();
        if (testnetFixedPrices) {
            uint256 p = testnetFixedPrice[token];
            if (p == 0) revert NotAccepted();
            return (fee * p + 1e18 - 1) / 1e18;
        }
        if (address(oracle) == address(0)) revert NoPriceSource();
        uint256 zetaUsd = _price(zetaAsset);
        uint256 tokenUsd = t.oraclePriced ? _price(token) : 1e18;
        // fee (18 decimals) x ZETAPHY's USD price / the token's USD price, in the token's units, rounded up
        uint256 usd = fee * zetaUsd;                       // USD x 1e36
        uint256 den = tokenUsd * 1e18;
        return (usd * (10 ** uint256(t.decimals)) + den - 1) / den;
    }

    function _price(address asset) private view returns (uint256 v) {
        try oracle.price(asset) returns (uint256 value, uint256) { v = value; } catch (bytes memory reason) { revert PriceUnavailable(reason); }
        if (v == 0) revert PriceUnavailable("");
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function hashRequest(JobRequest calldata q) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(), keccak256(abi.encode(
            REQUEST_TYPEHASH, q.user, q.token, q.chain, keccak256(bytes(q.target)), q.fee, q.tip, q.maxCost, q.nonce, q.deadline))));
    }

    /// The user already approved this gateway for the stablecoin.
    function request(JobRequest calldata q, bytes calldata sig) external returns (uint256) {
        return _request(q, sig);
    }

    /// Same, with an EIP-2612 permit so the user needs no approve transaction (no gas at all).
    function requestWithPermit(JobRequest calldata q, bytes calldata sig, Permit calldata p) external returns (uint256) {
        // A failed permit is fine if an allowance already exists (e.g. someone front-ran the permit).
        try IERC20Permit(q.token).permit(q.user, address(this), p.value, p.deadline, p.v, p.r, p.s) {} catch {}
        return _request(q, sig);
    }

    function _request(JobRequest calldata q, bytes calldata sig) private returns (uint256 jobId) {
        if (paused) revert GatewayPaused();
        if (block.timestamp > q.deadline) revert Expired();
        if (q.nonce != nonces[q.user]) revert BadNonce();
        if (_recover(hashRequest(q), sig) != q.user) revert BadSignature();
        nonces[q.user] = q.nonce + 1;

        uint256 cost = quote(q.token, q.fee);
        if (cost + q.tip > q.maxCost) revert TooExpensive();
        if (address(this).balance < q.fee) revert ReserveLow();

        require(IERC20Permit(q.token).transferFrom(q.user, address(this), cost), "payment failed");
        if (q.tip > 0) require(IERC20Permit(q.token).transferFrom(q.user, msg.sender, q.tip), "tip failed");
        // the gateway is the requester: a failed job's ZETAPHY refund comes back to the reserve (SG-1)
        jobId = jobs.requestFor{value: q.fee}(address(this), q.chain, q.target);
        paidJobs[jobId] = PaidJob(q.user, q.token, uint128(cost), false);
        emit Paid(jobId, q.user, q.token, cost, q.tip, msg.sender);
    }

    /// A gateway-paid job failed (or expired unanswered): anyone may refund its user in the stablecoin it
    /// paid, the same share NeuroJobs refunds (cost minus the fail burn). The ZETAPHY NeuroJobs credited
    /// to the gateway is pulled back into the reserve.
    function refund(uint256 jobId) external returns (uint256 amount) {
        PaidJob storage p = paidJobs[jobId];
        if (p.user == address(0) || p.refunded) revert NotRefundable();
        p.refunded = true; // before any call (a revert below undoes it)
        (address requester, , uint8 status, , , , , , , ) = jobs.getJob(jobId);
        if (requester != address(this) || status != JOB_FAILED) revert NotRefundable();
        amount = (uint256(p.cost) * (10_000 - jobs.FAIL_BURN_BPS())) / 10_000;
        if (jobs.credit(address(this)) != 0) jobs.withdraw();
        emit Refunded(jobId, p.user, p.token, amount);
        if (amount > 0) require(IERC20Permit(p.token).transfer(p.user, amount), "refund failed");
    }

    function _recover(bytes32 digest, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(digest, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes("ZETAPHY StableGateway")), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/StarkLightClient.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// StarkVerifier's interface (contracts/StarkVerifier.sol; same structs).
interface IStarkLCVerifier {
    struct Pin {
        bytes32 root;
        uint8 logN;
        uint8 logBlowup;
    }

    struct Result {
        uint8 kind;
        uint64 height;
        bytes32 hash;
        uint8 nextLogN;
        uint8 nextLogBlowup;
        uint256 S;
        uint256 T;
        uint256 U;
        uint256 C;
        uint8 mode;
        uint256 revealed;
        uint256 revealsOffset;
        bytes32 revealsHash;
        bytes message;
        bool ok;
        bool pqMajority;
    }

    function verify(bytes calldata proof, Pin calldata pin, bytes calldata chainId, uint256 minSigBits, uint256 minStarkBits)
        external view returns (Result memory);
}

/// @title StarkLightClient: ZETAPHY finality on Ethereum from STARK light-client proofs (prototype)
/// @notice Holds ZETAPHY's validator set by its 32-byte set root, starting from a pinned genesis set,
///         and accepts:
///           - block proofs: "block H with hash X was signed by more than the chain's threshold of
///             the current set" (3S > 2T - 3U), plus the header's app_hash (state root) proven
///             against X (CometBFT header Merkle tree, field 10 of 14);
///           - handoff proofs: "the current set (more than 2/3 of ALL its power) signed the root of
///             the next epoch's set".
///         The STARK (validator-set accounting) is verified completely on chain by StarkVerifier at
///         submission. ML-DSA-44 signature validity is NOT proven by the Stage A STARK; it is covered:
///           - `submitChecked`: every revealed signature (modes all/sample) is verified now by the
///             ML-DSA verifier contract `mldsa`, and the claim is final at once (no trust; costs one
///             ML-DSA verification per revealed signer, millions of gas each in Solidity today);
///           - `submit` (optimistic): the claim waits `challengeWindow`; anyone who shows that one
///             revealed signature does not verify (`challenge`, a single non-interactive check)
///             rejects the claim and takes the submitter's bond. Trust: one honest watcher and
///             Ethereum liveness during the window;
///           - mode `none` (no reveals): only `trustedProver` may post it, and it is trusted for ML-DSA
///             validity (stated, not hidden). trustedProver = 0 disables mode none.
///         Two different final hashes for one height (or two set roots for one epoch) prove that more
///         than 1/3 of the stake equivocated: the client freezes (no app hash is served any more).
///         No admin: every parameter is fixed at deployment.
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract StarkLightClient {
    enum Status { None, Pending, Final, Rejected }

    struct Claim {
        uint8 kind;          // 0 block, 1 handoff
        Status status;
        uint8 mode;          // 0 none, 1 sample, 2 all
        uint8 nextLogN;
        uint8 nextLogBlowup;
        uint64 epoch;        // the set the proof was checked against
        uint64 height;       // block height, or the next epoch (handoff)
        uint64 submittedAt;
        address submitter;
        uint256 bond;
        bytes32 hash;        // block hash, or the next set root
        bytes32 appHash;     // blocks: the header's app_hash
        bytes32 revealsHash; // keccak256(G0, K0, G1, K1, ...) of the revealed rows
        bytes32 messageHash; // keccak256 of the message validators signed
    }

    IStarkLCVerifier public immutable verifier;
    /// ML-DSA-44 verifier: staticcall(pk[1312] || sig[2420] || message) returns uint256(1) when valid.
    address public immutable mldsa;
    uint64 public immutable challengeWindow;
    uint256 public immutable bond;
    uint256 public immutable minSigBits;
    uint256 public immutable minStarkBits;
    address public immutable trustedProver;
    bytes public chainId;

    uint64 public epoch;
    bytes32 public setRoot;
    uint8 public setLogN;
    uint8 public setLogBlowup;
    bool public frozen;

    Claim[] private claims;
    mapping(uint64 => bytes32) public finalBlockHash;
    mapping(uint64 => bytes32) public finalAppHash;
    mapping(uint64 => bytes32) public epochRoot;

    event Submitted(uint256 indexed id, uint8 kind, uint64 height, bytes32 hash, uint8 mode, uint256 revealed);
    event Challenged(uint256 indexed id, uint256 reveal, address challenger);
    event Finalized(uint256 indexed id, uint8 kind, uint64 height, bytes32 hash);
    event EpochAdvanced(uint64 epoch, bytes32 root);
    event Equivocation(uint256 indexed id, uint64 height, bytes32 known, bytes32 other);

    error Frozen();
    error WrongBond();
    error RuleFails();
    error WrongEpoch();
    error NoMajority();
    error BadAppHash();
    error ModeNotAllowed();
    error NotPending();
    error WindowOpen();
    error WindowClosed();
    error BadDispute();
    error SignatureValid();
    error SignatureInvalid(uint256 reveal);
    error Unknown();

    constructor(
        IStarkLCVerifier verifier_,
        address mldsa_,
        bytes memory chainId_,
        bytes32 genesisRoot,
        uint8 genesisLogN,
        uint8 genesisLogBlowup,
        uint64 challengeWindow_,
        uint256 bond_,
        uint256 minSigBits_,
        uint256 minStarkBits_,
        address trustedProver_
    ) {
        require(minStarkBits_ >= 80 && minSigBits_ >= 80 && challengeWindow_ > 0, "params");
        verifier = verifier_;
        mldsa = mldsa_;
        chainId = chainId_;
        setRoot = genesisRoot;
        setLogN = genesisLogN;
        setLogBlowup = genesisLogBlowup;
        epochRoot[0] = genesisRoot;
        challengeWindow = challengeWindow_;
        bond = bond_;
        minSigBits = minSigBits_;
        minStarkBits = minStarkBits_;
        trustedProver = trustedProver_;
    }

    // ------------------------------------------------------------------ submitting

    /// Optimistic: the STARK is checked now; signatures can be disputed for `challengeWindow`.
    /// `appHash` and its 4 header aunts are needed for block proofs (ignored for handoffs).
    function submit(bytes calldata proof, bytes32 appHash, bytes32[4] calldata aunts) external payable returns (uint256 id) {
        if (msg.value != bond) revert WrongBond();
        IStarkLCVerifier.Result memory r = _check(proof, appHash, aunts);
        id = _store(r, appHash, Status.Pending);
    }

    /// Final at once: every revealed ML-DSA-44 signature is verified now (modes all / sample).
    function submitChecked(bytes calldata proof, bytes32 appHash, bytes32[4] calldata aunts) external returns (uint256 id) {
        IStarkLCVerifier.Result memory r = _check(proof, appHash, aunts);
        if (r.mode == 0) revert ModeNotAllowed();
        uint256 off = r.revealsOffset;
        for (uint256 j = 0; j < r.revealed; j++) {
            uint256 sig = off + j * 3960 + 228;
            if (!_mldsaValid(proof[sig + 2420:sig + 2420 + 1312], proof[sig:sig + 2420], r.message)) revert SignatureInvalid(j);
        }
        id = _store(r, appHash, Status.Final);
        _apply(id);
    }

    function _check(bytes calldata proof, bytes32 appHash, bytes32[4] calldata aunts) private view returns (IStarkLCVerifier.Result memory r) {
        if (frozen) revert Frozen();
        bool trusted = trustedProver != address(0) && msg.sender == trustedProver;
        r = verifier.verify(proof, IStarkLCVerifier.Pin(setRoot, setLogN, setLogBlowup), chainId, trusted ? 0 : minSigBits, minStarkBits);
        if (r.mode == 0 && !trusted) revert ModeNotAllowed();
        if (r.kind == 0) {
            if (!r.ok) revert RuleFails();
            if (appHashRoot(appHash, aunts) != r.hash) revert BadAppHash();
        } else {
            if (r.height != epoch + 1) revert WrongEpoch();
            if (!r.pqMajority) revert NoMajority();
        }
    }

    function _store(IStarkLCVerifier.Result memory r, bytes32 appHash, Status status) private returns (uint256 id) {
        id = claims.length;
        claims.push(Claim({
            kind: r.kind, status: status, mode: r.mode, nextLogN: r.nextLogN, nextLogBlowup: r.nextLogBlowup,
            epoch: epoch, height: r.height, submittedAt: uint64(block.timestamp), submitter: msg.sender,
            bond: status == Status.Pending ? msg.value : 0, hash: r.hash, appHash: r.kind == 0 ? appHash : bytes32(0),
            revealsHash: r.revealsHash, messageHash: keccak256(r.message)
        }));
        emit Submitted(id, r.kind, r.height, r.hash, r.mode, r.revealed);
    }

    // ------------------------------------------------------------------ disputes and finality

    /// Anyone, during the window: reveal j of claim `id` is not a valid ML-DSA-44 signature.
    /// digests: (G, K) of every revealed row, as in the proof (their keccak is the claim's revealsHash);
    /// sig and pk: the revealed signature and key (from the submission's calldata); message: what was signed.
    function challenge(uint256 id, uint256 j, bytes32[] calldata digests, bytes calldata sig, bytes calldata pk, bytes calldata message) external {
        Claim storage c = claims[id];
        if (c.status != Status.Pending) revert NotPending();
        if (block.timestamp >= c.submittedAt + challengeWindow) revert WindowClosed();
        if (keccak256(abi.encodePacked(digests)) != c.revealsHash || 2 * j + 1 >= digests.length) revert BadDispute();
        if (keccak256(message) != c.messageHash || sig.length != 2420 || pk.length != 1312) revert BadDispute();
        if (_digest31("zetaphy/starklc/sig\x00", sig) != uint256(digests[2 * j]) || _digest31("zetaphy/starklc/pk\x00", pk) != uint256(digests[2 * j + 1])) revert BadDispute();
        if (_mldsaValid(pk, sig, message)) revert SignatureValid();
        c.status = Status.Rejected;
        uint256 b = c.bond;
        c.bond = 0;
        emit Challenged(id, j, msg.sender);
        if (b > 0) {
            (bool ok, ) = msg.sender.call{ value: b }("");
            require(ok, "bond");
        }
    }

    /// Anyone, after the window: the claim becomes final (and the bond goes back).
    function finalize(uint256 id) external {
        Claim storage c = claims[id];
        if (c.status != Status.Pending) revert NotPending();
        if (block.timestamp < c.submittedAt + challengeWindow) revert WindowOpen();
        c.status = Status.Final;
        _apply(id);
        uint256 b = c.bond;
        c.bond = 0;
        if (b > 0) {
            (bool ok, ) = c.submitter.call{ value: b }("");
            require(ok, "bond");
        }
    }

    function _apply(uint256 id) private {
        Claim storage c = claims[id];
        if (c.kind == 0) {
            bytes32 known = finalBlockHash[c.height];
            if (known != bytes32(0) && known != c.hash) { frozen = true; emit Equivocation(id, c.height, known, c.hash); return; }
            finalBlockHash[c.height] = c.hash;
            finalAppHash[c.height] = c.appHash;
        } else {
            bytes32 known = epochRoot[c.height];
            if (known != bytes32(0)) {
                if (known != c.hash) { frozen = true; emit Equivocation(id, c.height, known, c.hash); }
                return;
            }
            if (c.epoch != epoch || c.height != epoch + 1) revert WrongEpoch();
            epoch = c.height;
            setRoot = c.hash;
            setLogN = c.nextLogN;
            setLogBlowup = c.nextLogBlowup;
            epochRoot[c.height] = c.hash;
            emit EpochAdvanced(c.height, c.hash);
        }
        emit Finalized(id, c.kind, c.height, c.hash);
    }

    // ------------------------------------------------------------------ reading

    /// The final app hash of ZETAPHY block `height` (the state after block height - 1).
    function appHashAt(uint64 height) external view returns (bytes32 h) {
        if (frozen) revert Frozen();
        h = finalAppHash[height];
        if (h == bytes32(0)) revert Unknown();
    }

    function getClaim(uint256 id) external view returns (Claim memory) {
        return claims[id];
    }

    function claimCount() external view returns (uint256) {
        return claims.length;
    }

    /// CometBFT header hash from app_hash (field 10 of 14) and its aunts (bottom-up): the
    /// leaf is the protobuf BytesValue 0x0a 0x20 || app_hash, then 4 levels of the simple tree.
    function appHashRoot(bytes32 app, bytes32[4] calldata a) public pure returns (bytes32 h) {
        h = sha256(abi.encodePacked(uint8(0), uint8(0x0a), uint8(0x20), app));
        h = sha256(abi.encodePacked(uint8(1), h, a[0]));
        h = sha256(abi.encodePacked(uint8(1), a[1], h));
        h = sha256(abi.encodePacked(uint8(1), h, a[2]));
        h = sha256(abi.encodePacked(uint8(1), a[3], h));
    }

    function _mldsaValid(bytes memory pk, bytes memory sig, bytes memory message) private view returns (bool) {
        if (mldsa == address(0)) return false;
        (bool ok, bytes memory ret) = mldsa.staticcall(abi.encodePacked(pk, sig, message));
        return ok && ret.length == 32 && abi.decode(ret, (uint256)) == 1;
    }

    function _digest31(bytes memory tag, bytes calldata b) private pure returns (uint256) {
        return uint256(sha256(abi.encodePacked(tag, b))) >> 8;
    }
}

contracts/StarkVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title StarkVerifier: the ZETAPHY STARK light-client verifier (proof format v1) on the EVM
/// @notice A line-by-line port of zetaphy-network/src/starklc/verifier.js (DEEP-ALI + FRI over the
///         Stark252 field, SHA-256 Merkle commitments and Fiat-Shamir), using the SHA-256 precompile
///         (0x02) for every hash and the modexp precompile (0x05) for inversions. Stateless: it
///         takes the proof bytes exactly as `encodeProof` writes them and the pinned set
///         { root, logN, logBlowup }, and returns what was proven, or reverts ProofRejected(code).
///
///         What it does NOT do: verify ML-DSA-44 signatures. For revealed rows (modes `all` and
///         `sample`) it checks that each revealed signature and key hash to the committed G and K
///         values (so they are the certificate's signature and the set's key) and returns
///         `revealsHash` = keccak256(G0, K0, G1, K1, ...) and the signed message, so the caller
///         (StarkLightClient) can check the signatures itself or let anyone dispute one during a
///         challenge window. Mode `none` reveals nothing: the prover is trusted for ML-DSA validity.
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract StarkVerifier {
    uint256 internal constant P = 0x800000000000011000000000000000000000000000000000000000000000001;
    uint256 internal constant R256 = 0x7fffffffffffdf0ffffffffffffffffffffffffffffffffffffffffffffffe1; // 2^256 mod P
    uint256 internal constant INV2 = 0x400000000000008800000000000000000000000000000000000000000000001;
    uint256 internal constant INV3 = 0x2aaaaaaaaaaaab0555555555555555555555555555555555555555555555556;
    uint256 internal constant COSET = 3;
    uint256 internal constant REVEAL = 4 + 7 * 32 + 2420 + 1312; // u32 row, 7 fields, signature, key
    uint256 internal constant SIG = 2420;

    /// Reasons, in the order they are checked (also what the JS verifier's messages say):
    /// 1 malformed/trailing bytes/non-canonical field   2 not the pinned set's size or blowup
    /// 3 another chain   4 weak STARK parameters   5 public sums out of range
    /// 6 constraints do not hold at z   7 reveals out of order/range   8 samples wrong
    /// 9 revealed count != C (mode all)   10 unexpected reveals (mode none)
    /// 11 revealed row is not a signer   12 key is not the set's   13 signature is not the committed one
    /// 14 too few signature-check bits   15 FRI shape   16 proof of work missing
    /// 17 trace openings   18 set openings (wrong set root)   19 composition openings
    /// 20 FRI layer openings   21 FRI folding   22 FRI final polynomial
    error ProofRejected(uint256 code);

    struct Pin {
        bytes32 root;
        uint8 logN;
        uint8 logBlowup;
    }

    struct Result {
        uint8 kind;            // 0 block, 1 handoff
        uint64 height;         // block height, or the next epoch for a handoff
        bytes32 hash;          // block hash, or the next set root for a handoff
        uint8 nextLogN;
        uint8 nextLogBlowup;
        uint256 S;
        uint256 T;
        uint256 U;
        uint256 C;
        uint8 mode;            // 0 none, 1 sample, 2 all
        uint256 revealed;
        uint256 revealsOffset; // where the reveals start in the proof bytes (row u32, 7 fields, sig, key)
        bytes32 revealsHash;   // keccak256 of (G, K) per revealed row, in order
        bytes message;         // the bytes the validators signed (voteMessage / handoff message)
        bool ok;               // the chain's rule 3S > 2T - 3U
        bool pqMajority;       // 3S > 2T
    }

    /// Everything about one verification (calldata offsets are absolute).
    struct V {
        uint256 b; uint256 end;
        uint256 logBlowup; uint256 queries; uint256 grind; uint256 logFinalDeg; uint256 logN;
        uint256 N; uint256 L; uint256 half;
        uint256 stmt; uint256 stmtLen; uint256 chain; uint256 chainLen;
        uint256 S; uint256 T; uint256 U; uint256 C; uint256 mode; uint256 k;
        bytes32 traceRoot; bytes32 qRoot; uint256 ood;
        uint256 rev; uint256 nRev; uint256 samp; uint256 nSamp;
        uint256 fri; uint256 nFri; uint256 fin; uint256 nFin; uint256 nonce;
        uint256 nq; uint256 tl; uint256 sl; uint256 ql;
        uint256 tp; uint256 tpN; uint256 sp; uint256 spN; uint256 qp; uint256 qpN;
        uint256 layers;
        bytes32 setRoot; bytes32 st; uint256 ctr;
        uint256 z; uint256 wN; uint256 wL;
        uint256[] alphas; uint256[] gammas; uint256[] betas; uint256[] idx;
        uint256[] pts; uint256[] gsum;
    }

    // ------------------------------------------------------------------ entry point

    /// @param minSigBits the least signature-check security accepted (0 accepts mode none)
    /// @param minStarkBits the least conjectured STARK security (queries * logBlowup + grinding)
    function verify(bytes calldata proof, Pin calldata pin, bytes calldata chainId, uint256 minSigBits, uint256 minStarkBits)
        external view returns (Result memory r)
    {
        V memory v;
        uint256 b;
        assembly { b := proof.offset }
        v.b = b;
        v.end = b + proof.length;
        v.setRoot = pin.root;
        _parse(v);
        if (v.logN != pin.logN || v.logBlowup != pin.logBlowup) revert ProofRejected(2);
        if (keccak256(proof[v.chain - b:v.chain - b + v.chainLen]) != keccak256(chainId)) revert ProofRejected(3);
        if (v.queries * v.logBlowup + v.grind < minStarkBits || v.logFinalDeg > 10 || v.queries < 1 || v.grind > 40) revert ProofRejected(4);
        if (v.S >= 1 << 100 || v.T >= 1 << 100 || v.U >= 1 << 100 || v.C >= 1 << 100) revert ProofRejected(5);

        r.message = _message(v);
        _transcriptToOod(v, r.message);
        _checkComposition(v);
        (r.revealsHash) = _reveals(v, minSigBits);
        _deepAndFri(v);

        r.kind = uint8(_u(v.stmt, 1));
        r.height = uint64(_u(v.stmt + 2 + v.chainLen, 8));
        r.hash = bytes32(_w(v.stmt + 10 + v.chainLen));
        r.nextLogN = uint8(_u(v.stmt + 42 + v.chainLen, 1));
        r.nextLogBlowup = uint8(_u(v.stmt + 43 + v.chainLen, 1));
        (r.S, r.T, r.U, r.C) = (v.S, v.T, v.U, v.C);
        r.mode = uint8(v.mode);
        r.revealed = v.nRev;
        r.revealsOffset = v.rev - b;
        int256 need = 2 * int256(v.T) - 3 * int256(v.U);
        r.ok = need < 0 || 3 * int256(v.S) > need;
        r.pqMajority = 3 * v.S > 2 * v.T;
    }

    // ------------------------------------------------------------------ parsing

    function _parse(V memory v) private pure {
        unchecked {
            uint256 c = v.b;
            if (v.end - v.b < 64 || _u(c, 5) != 0x5a534c4301) revert ProofRejected(1); // "ZSLC" v1
            c += 5;
            (v.logBlowup, v.queries, v.grind, v.logFinalDeg, v.logN) = (_u(c, 1), _u(c + 1, 1), _u(c + 2, 1), _u(c + 3, 1), _u(c + 4, 1));
            if (v.logN < 3 || v.logN > 20 || v.logBlowup < 1 || v.logBlowup > 6) revert ProofRejected(1);
            v.N = 1 << v.logN;
            v.L = v.N << v.logBlowup;
            v.half = v.L / 2;
            c += 5;
            v.stmt = c;
            uint256 kind = _u(c, 1);
            v.chainLen = _u(c + 1, 1);
            v.chain = c + 2;
            c = v.chain + v.chainLen + 8 + 32;
            if (kind > 1 || (kind == 0 && _u(c, 2) != 0)) revert ProofRejected(1);
            c += 2;
            v.stmtLen = c - v.stmt;
            (v.S, v.T, v.U, v.C) = (_f(c), _f(c + 32), _f(c + 64), _f(c + 96));
            c += 128;
            v.mode = _u(c, 1);
            v.k = _u(c + 1, 2);
            if (v.mode > 2) revert ProofRejected(1);
            c += 3;
            v.traceRoot = bytes32(_w(c));
            v.qRoot = bytes32(_w(c + 32));
            c += 64;
            v.ood = c;
            c += 15 * 32;
            v.nRev = _u(c, 2);
            v.rev = c + 2;
            c = v.rev + v.nRev * REVEAL;
            v.nSamp = _u(c, 2);
            v.samp = c + 2;
            c = v.samp + 2 * v.nSamp;
            v.nFri = _u(c, 1);
            v.fri = c + 1;
            c = v.fri + 32 * v.nFri;
            v.nFin = _u(c, 1);
            v.fin = c + 1;
            c = v.fin + 32 * v.nFin;
            v.nonce = _u(c, 8);
            c += 8;
            v.nq = _u(c, 2);
            c += 2;
            v.tl = c; c += v.nq * 12 * 32;
            v.sl = c; c += v.nq * 8 * 32;
            v.ql = c; c += v.nq * 2 * 32;
            v.tpN = _u(c, 2); v.tp = c + 2; c = v.tp + 32 * v.tpN;
            v.spN = _u(c, 2); v.sp = c + 2; c = v.sp + 32 * v.spN;
            v.qpN = _u(c, 2); v.qp = c + 2; c = v.qp + 32 * v.qpN;
            v.layers = c;
            for (uint256 i = 0; i < v.nFri; i++) {
                if (c > v.end) revert ProofRejected(1);
                c += 2 + _u(c, 2) * 64;
                c += 2 + _u(c, 2) * 32;
            }
            if (c != v.end) revert ProofRejected(1);
        }
    }

    /// The bytes validators sign: "zetaphy/pq-vote\0" chain "\0" u64 height hash (a block), or
    /// "zetaphy/pq-setroot\0" chain "\0" u64 epoch root logN logBlowup (a handoff).
    function _message(V memory v) private pure returns (bytes memory) {
        uint256 kind = _u(v.stmt, 1);
        bytes memory chain = _cd(v.chain, v.chainLen);
        bytes memory rest = _cd(v.chain + v.chainLen, 40); // u64 height, hash
        if (kind == 0) return abi.encodePacked("zetaphy/pq-vote\x00", chain, "\x00", rest);
        return abi.encodePacked("zetaphy/pq-setroot\x00", chain, "\x00", rest, _cd(v.chain + v.chainLen + 40, 2));
    }

    // ------------------------------------------------------------------ transcript replay

    function _transcriptToOod(V memory v, bytes memory message) private view {
        v.st = sha256("zetaphy/starklc/v1\x00proof");
        bytes memory head = abi.encodePacked(
            uint8(1), uint8(v.logBlowup), uint8(v.queries), uint8(v.grind), uint8(v.logFinalDeg), uint8(v.logN),
            v.setRoot, _cd(v.stmt, v.stmtLen), message);
        head = abi.encodePacked(head, v.S, v.T, v.U, v.C, uint8(v.mode), uint64(v.k));
        _absorbMem(v, head);
        _absorb32(v, v.traceRoot);
        v.alphas = new uint256[](18);
        for (uint256 i = 0; i < 18; i++) v.alphas[i] = _field(v);
        _absorb32(v, v.qRoot);
        uint256 cosetPowL = _pow(COSET, v.L);
        uint256 z = _field(v);
        while (z == 0 || _pow(z, v.N) == 1 || _pow(z, v.L) == cosetPowL) z = _field(v);
        v.z = z;
        v.wN = _root(v.logN);
        v.wL = _root(v.logN + v.logBlowup);
        for (uint256 i = 0; i < 15; i++) _f(v.ood + 32 * i);
        _absorbCd(v, v.ood, 15 * 32);
    }

    function _checkComposition(V memory v) private view {
        uint256 o = v.ood;
        uint256[] memory a = v.alphas;
        uint256 z = v.z;
        uint256 wLast = _pow(v.wN, v.N - 1);
        uint256 acc = mulmod(addmod(_compAll(o, a), mulmod(_compTrans(o, a), _sub(z, wLast), P), P), _inv(_sub(_pow(z, v.N), 1)), P);
        uint256 invFirst = _inv(_sub(z, 1));
        uint256 invLast = _inv(_sub(z, wLast));
        // first row: CS, CT, CU, CC = 0
        for (uint256 j = 0; j < 4; j++) acc = addmod(acc, mulmod(a[9 + j], mulmod(_w(o + 64 + 32 * j), invFirst, P), P), P);
        // last row: CS = S, CT = T, CU = U, CC = C, P = 0
        acc = addmod(acc, mulmod(a[13], mulmod(_sub(_w(o + 64), v.S), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[14], mulmod(_sub(_w(o + 96), v.T), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[15], mulmod(_sub(_w(o + 128), v.U), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[16], mulmod(_sub(_w(o + 160), v.C), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[17], mulmod(_w(o + 416), invLast, P), P), P);
        if (acc != _w(o + 448)) revert ProofRejected(6);
    }


    /// Row constraints B(B-1), (1-B)G, BZ, Z(Z-1), ZK at z, mixed with alpha 0..4.
    function _compAll(uint256 o, uint256[] memory a) private pure returns (uint256 x) {
        uint256 B = _w(o);
        uint256 Z = _w(o + 384);
        x = mulmod(a[0], mulmod(B, addmod(B, P - 1, P), P), P);
        x = addmod(x, mulmod(a[1], mulmod(addmod(1, P - B, P), _w(o + 32), P), P), P);
        x = addmod(x, mulmod(a[2], mulmod(B, Z, P), P), P);
        x = addmod(x, mulmod(a[3], mulmod(Z, addmod(Z, P - 1, P), P), P), P);
        x = addmod(x, mulmod(a[4], mulmod(Z, _w(o + 352), P), P), P);
    }

    /// Transitions CS'=CS+BP, CT'=CT+P, CU'=CU+ZP, CC'=CC+B at z, mixed with alpha 5..8.
    function _compTrans(uint256 o, uint256[] memory a) private pure returns (uint256 y) {
        uint256 B = _w(o);
        uint256 Pw = _w(o + 416);
        y = mulmod(a[5], _sub(_sub(_w(o + 192), _w(o + 64)), mulmod(B, Pw, P)), P);
        y = addmod(y, mulmod(a[6], _sub(_sub(_w(o + 224), _w(o + 96)), Pw), P), P);
        y = addmod(y, mulmod(a[7], _sub(_sub(_w(o + 256), _w(o + 128)), mulmod(_w(o + 384), Pw, P)), P), P);
        y = addmod(y, mulmod(a[8], _sub(_sub(_w(o + 288), _w(o + 160)), B), P), P);
    }

    // ------------------------------------------------------------------ signature reveals

    function _reveals(V memory v, uint256 minSigBits) private view returns (bytes32 revealsHash) {
        unchecked {
            uint256 n = v.nRev;
            for (uint256 i = 0; i < n; i++) {
                uint256 row = _u(v.rev + i * REVEAL, 4);
                if (row >= v.N - 1 || (i > 0 && row <= _u(v.rev + (i - 1) * REVEAL, 4))) revert ProofRejected(7);
            }
            if (v.mode == 1) {
                if (v.k != v.nSamp) revert ProofRejected(8);
                bool[] memory used = new bool[](n);
                uint256 bound = v.S == 0 ? 1 : v.S;
                for (uint256 j = 0; j < v.k; j++) {
                    uint256 r = _below(v, bound);
                    uint256 ri = _u(v.samp + 2 * j, 2);
                    if (ri >= n) revert ProofRejected(8);
                    uint256 base = v.rev + ri * REVEAL + 4;
                    if (!(_f(base + 64) <= r && r < _f(base + 96))) revert ProofRejected(8);
                    used[ri] = true;
                }
                for (uint256 i = 0; i < n; i++) if (!used[i]) revert ProofRejected(8);
            } else if (v.mode == 2) {
                if (n != v.C) revert ProofRejected(9);
            } else if (n != 0 || v.nSamp != 0) {
                revert ProofRejected(10);
            }
            bytes memory digests = new bytes(64 * n);
            bytes memory rb = new bytes(232 * n);
            for (uint256 i = 0; i < n; i++) {
                uint256 base = v.rev + i * REVEAL;
                uint256 vals = base + 4;
                for (uint256 j = 0; j < 7; j++) _f(vals + 32 * j);
                if (_w(vals) != 1) revert ProofRejected(11);
                uint256 sigOff = vals + 224;
                uint256 K = _w(vals + 160);
                uint256 G = _w(vals + 32);
                if (_digest31("zetaphy/starklc/pk\x00", sigOff + SIG, 1312) != K) revert ProofRejected(12);
                if (_digest31("zetaphy/starklc/sig\x00", sigOff, SIG) != G) revert ProofRejected(13);
                assembly {
                    mstore(add(add(digests, 32), mul(i, 64)), G)
                    mstore(add(add(digests, 64), mul(i, 64)), K)
                    let d := add(add(rb, 32), mul(i, 232))
                    mstore(d, shl(192, shr(224, calldataload(base)))) // u64(row)
                    calldatacopy(add(d, 8), vals, 224)
                }
            }
            revealsHash = keccak256(digests);
            _absorbMem(v, rb);

            // signature-check security
            int256 need = 2 * int256(v.T) - 3 * int256(v.U);
            if (v.mode == 2 || need <= 0 || minSigBits == 0) return revealsHash;
            if (v.mode == 0 || 3 * v.S <= uint256(need)) revert ProofRejected(14);
            // k * (log2(3S) - log2(need)) >= minSigBits, with a lower bound in 1/65536 bits
            uint256 hi = _log2q(3 * v.S);
            uint256 lo = _log2q(uint256(need)) + 2;
            if (hi <= lo || v.k * (hi - lo) < minSigBits << 16) revert ProofRejected(14);
        }
    }

    // ------------------------------------------------------------------ DEEP + FRI

    function _deepAndFri(V memory v) private view {
        uint256 groups = 2 + 2 * v.nRev;
        uint256 terms = 15 + 7 * v.nRev;
        v.gammas = new uint256[](terms);
        for (uint256 i = 0; i < terms; i++) v.gammas[i] = _field(v);
        uint256 m = v.logN > v.logFinalDeg ? v.logN - v.logFinalDeg : 0;
        if (v.nFri != (m > 0 ? m - 1 : 0) || v.nFin != v.N >> m) revert ProofRejected(15);
        v.betas = new uint256[](m);
        for (uint256 i = 0; i < m; i++) {
            v.betas[i] = _field(v);
            if (i + 1 < m) _absorb32(v, bytes32(_w(v.fri + 32 * i)));
        }
        for (uint256 i = 0; i < v.nFin; i++) _f(v.fin + 32 * i);
        _absorbCd(v, v.fin, 32 * v.nFin);
