            if (n == 0 || n != leaves.length) return false;
            uint256[] memory ci = new uint256[](n);
            bytes32[] memory ch = new bytes32[](n);
            for (uint256 k = 0; k < n; k++) {
                if (ind[k] >= 1 << depth || (k > 0 && ind[k] <= ind[k - 1])) return false;
                ci[k] = ind[k];
                ch[k] = leaves[k];
            }
            uint256 used = 0;
            for (uint256 lvl = 0; lvl < depth; lvl++) {
                uint256 m = 0;
                for (uint256 k = 0; k < n; k++) {
                    uint256 i = ci[k];
                    bytes32 parent;
                    if (i & 1 == 0 && k + 1 < n && ci[k + 1] == i + 1) {
                        parent = _node(ch[k], ch[k + 1]);
                        k++;
                    } else {
                        if (used >= pn) return false;
                        bytes32 sib = bytes32(_w(p + 32 * used));
                        used++;
                        parent = i & 1 == 1 ? _node(sib, ch[k]) : _node(ch[k], sib);
                    }
                    ci[m] = i >> 1;
                    ch[m] = parent;
                    m++;
                }
                n = m;
            }
            return used == pn && n == 1 && ci[0] == 0 && ch[0] == root;
        }
    }

    function _node(bytes32 l, bytes32 r) private view returns (bytes32 h) {
        assembly {
            let fp := mload(0x40)
            mstore8(fp, 1)
            mstore(add(fp, 1), l)
            mstore(add(fp, 33), r)
            if iszero(staticcall(gas(), 2, fp, 65, 0, 32)) { revert(0, 0) }
            h := mload(0)
        }
    }

    function _leafCd(uint256 off, uint256 len) private view returns (bytes32 h) {
        assembly {
            let fp := mload(0x40)
            mstore8(fp, 0)
            calldatacopy(add(fp, 1), off, len)
            if iszero(staticcall(gas(), 2, fp, add(len, 1), 0, 32)) { revert(0, 0) }
            h := mload(0)
        }
    }

    function _digest31(bytes memory tag, uint256 off, uint256 len) private view returns (uint256 d) {
        assembly {
            let fp := mload(0x40)
            let tl := mload(tag)
            mcopy(fp, add(tag, 32), tl)
            calldatacopy(add(fp, tl), off, len)
            if iszero(staticcall(gas(), 2, fp, add(tl, len), 0, 32)) { revert(0, 0) }
            d := shr(8, mload(0))
        }
    }

    // ------------------------------------------------------------------ transcript

    function _absorbMem(V memory v, bytes memory data) private view {
        bytes32 s = v.st;
        bytes32 out;
        assembly {
            let fp := mload(0x40)
            let len := mload(data)
            mstore(fp, s)
            mcopy(add(fp, 32), add(data, 32), len)
            if iszero(staticcall(gas(), 2, fp, add(len, 32), 0, 32)) { revert(0, 0) }
            out := mload(0)
        }
        v.st = out;
        v.ctr = 0;
    }

    function _absorbCd(V memory v, uint256 off, uint256 len) private view {
        bytes32 s = v.st;
        bytes32 out;
        assembly {
            let fp := mload(0x40)
            mstore(fp, s)
            calldatacopy(add(fp, 32), off, len)
            if iszero(staticcall(gas(), 2, fp, add(len, 32), 0, 32)) { revert(0, 0) }
            out := mload(0)
        }
        v.st = out;
        v.ctr = 0;
    }

    function _absorb32(V memory v, bytes32 x) private pure {
        v.st = sha256(abi.encodePacked(v.st, x));
        v.ctr = 0;
    }

    function _squeeze(V memory v) private view returns (uint256 h) {
        bytes32 s = v.st;
        uint256 c = v.ctr;
        assembly {
            let fp := mload(0x40)
            mstore(fp, s)
            mstore(add(fp, 32), shl(224, c))
            if iszero(staticcall(gas(), 2, fp, 36, 0, 32)) { revert(0, 0) }
            h := mload(0)
        }
        v.ctr = c + 1;
    }

    /// A uniform field element: 512 bits reduced mod p.
    function _field(V memory v) private view returns (uint256) {
        uint256 hi = _squeeze(v);
        uint256 lo = _squeeze(v);
        return addmod(mulmod(hi, R256, P), lo % P, P);
    }

    /// A uniform integer in [0, n): 512 bits reduced mod n.
    function _below(V memory v, uint256 n) private view returns (uint256) {
        uint256 hi = _squeeze(v);
        uint256 lo = _squeeze(v);
        uint256 r = addmod(type(uint256).max % n, 1, n);
        return addmod(mulmod(hi, r, n), lo % n, n);
    }

    // ------------------------------------------------------------------ field

    function _sub(uint256 a, uint256 b) private pure returns (uint256) {
        return addmod(a, P - b, P);
    }

    function _pow(uint256 b, uint256 e) private pure returns (uint256 r) {
        unchecked {
            r = 1;
            while (e > 0) {
                if (e & 1 == 1) r = mulmod(r, b, P);
                b = mulmod(b, b, P);
                e >>= 1;
            }
        }
    }

    function _modexp(uint256 b, uint256 e) private view returns (uint256 r) {
        assembly {
            let fp := mload(0x40)
            mstore(fp, 32)
            mstore(add(fp, 32), 32)
            mstore(add(fp, 64), 32)
            mstore(add(fp, 96), b)
            mstore(add(fp, 128), e)
            mstore(add(fp, 160), P)
            if iszero(staticcall(gas(), 5, fp, 192, 0, 32)) { revert(0, 0) }
            r := mload(0)
        }
    }

    function _inv(uint256 a) private view returns (uint256) {
        if (a == 0) revert ProofRejected(6);
        return _modexp(a, P - 2);
    }

    /// A primitive 2^k-th root of unity: 3^((p-1) / 2^k).
    function _root(uint256 k) private view returns (uint256) {
        return _modexp(COSET, (P - 1) >> k);
    }

    /// Montgomery batch inversion in place (zeros are refused).
    function _batchInv(uint256[] memory xs) private view {
        uint256 n = xs.length;
        uint256[] memory pre = new uint256[](n);
        uint256 acc = 1;
        assembly {
            let x := add(xs, 32)
            let q := add(pre, 32)
            for { let i := 0 } lt(i, n) { i := add(i, 1) } {
                mstore(add(q, shl(5, i)), acc)
                acc := mulmod(acc, mload(add(x, shl(5, i))), P)
            }
        }
        uint256 ia = _inv(acc);
        assembly {
            let x := add(xs, 32)
            let q := add(pre, 32)
            for { let i := n } gt(i, 0) { i := sub(i, 1) } {
                let o := shl(5, sub(i, 1))
                let t := mulmod(mload(add(q, o)), ia, P)
                ia := mulmod(ia, mload(add(x, o)), P)
                mstore(add(x, o), t)
            }
        }
    }

    // ------------------------------------------------------------------ small helpers

    function _uniqueMod(uint256[] memory pos, uint256 h) private pure returns (uint256[] memory out) {
        unchecked {
            uint256[] memory tmp = new uint256[](pos.length);
            uint256 n = 0;
            for (uint256 q = 0; q < pos.length; q++) {
                uint256 x = pos[q] % h;
                uint256 i = 0;
                while (i < n && tmp[i] < x) i++;
                if (i < n && tmp[i] == x) continue;
                for (uint256 j = n; j > i; j--) tmp[j] = tmp[j - 1];
                tmp[i] = x;
                n++;
            }
            out = new uint256[](n);
            for (uint256 i = 0; i < n; i++) out[i] = tmp[i];
        }
    }

    function _indexOf(uint256[] memory a, uint256 x) private pure returns (uint256) {
        unchecked {
            for (uint256 i = 0; i < a.length; i++) if (a[i] == x) return i;
            revert ProofRejected(21);
        }
    }

    function _log2(uint256 x) private pure returns (uint256 r) {
        unchecked {
            while (x > 1) { x >>= 1; r++; }
        }
    }

    /// floor(log2(x) * 65536), a lower bound (x > 0).
    function _log2q(uint256 x) private pure returns (uint256 r) {
        unchecked {
            uint256 n = _log2(x);
            r = n << 16;
            uint256 y = n >= 127 ? x >> (n - 127) : x << (127 - n);
            for (uint256 bit = 1 << 15; bit > 0; bit >>= 1) {
                y = (y * y) >> 127;
                if (y >= 1 << 128) { r += bit; y >>= 1; }
            }
        }
    }

    function _u(uint256 off, uint256 nbytes) private pure returns (uint256 v) {
        assembly { v := shr(sub(256, mul(8, nbytes)), calldataload(off)) }
    }

    function _w(uint256 off) private pure returns (uint256 v) {
        assembly { v := calldataload(off) }
    }

    /// A canonical field element at `off` (or ProofRejected(1)).
    function _f(uint256 off) private pure returns (uint256 v) {
        assembly { v := calldataload(off) }
        if (v >= P) revert ProofRejected(1);
    }

    function _cd(uint256 off, uint256 len) private pure returns (bytes memory out) {
        out = new bytes(len);
        assembly { calldatacopy(add(out, 32), off, len) }
    }
}

contracts/TestStable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title TestStable: testnet-only stand-in for USDC / USDT on ZETAPHY testnet
/// @notice Worthless by design. Anyone can take 1,000 from the faucet once a
///         day. Real USDC arrives only through the bridge in stage 3.
///         ERC-20 + EIP-2612 permit, 6 decimals like USDC/USDT.
contract TestStable {
    string public name;
    string public symbol;
    uint8 public constant decimals = 6;
    uint256 public constant FAUCET_AMOUNT = 1_000 * 10 ** 6;
    uint256 public constant FAUCET_EVERY = 1 days;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public nonces;
    mapping(address => uint256) public lastFaucet;

    bytes32 public constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    function faucet() external {
        _drip(msg.sender);
    }

    /// Lets a relay pay the gas for someone who has no ZETAPHY yet.
    function faucetTo(address to) external {
        _drip(to);
    }

    function _drip(address to) private {
        require(to != address(0), "to zero");
        require(block.timestamp >= lastFaucet[to] + FAUCET_EVERY, "faucet: once a day");
        lastFaucet[to] = block.timestamp;
        totalSupply += FAUCET_AMOUNT;
        balanceOf[to] += FAUCET_AMOUNT;
        emit Transfer(address(0), to, FAUCET_AMOUNT);
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _move(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            require(a >= value, "allowance");
            allowance[from][msg.sender] = a - value;
        }
        _move(from, to, value);
        return true;
    }

    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        require(block.timestamp <= deadline, "permit: expired");
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(),
            keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))));
        require(uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0, "permit: bad s");
        address signer = ecrecover(digest, v, r, s);
        require(signer != address(0) && signer == owner, "permit: bad signature");
        allowance[owner][spender] = value;
        emit Approval(owner, spender, value);
    }

    function _move(address from, address to, uint256 value) private {
        require(to != address(0), "to zero");
        uint256 b = balanceOf[from];
        require(b >= value, "balance");
        unchecked { balanceOf[from] = b - value; }
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes(name)), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/ThreatRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// The parts of NeuroIdentity (ERC-8004 identity registry) this registry reads:
/// who has claimed the identity of a target ("eip155:<id>:0x<lowercase hex>").
interface IIdentityOwners {
    function agentOfTarget(bytes32 caip10Hash) external view returns (uint256);
    function ownerOf(uint256 agentId) external view returns (address);
}

/// @title ThreatRegistry: Neuro's immune system (stage 4)
/// @notice A flag here states a reproducible fact about code, not guilt: what
///         the code can do, or did in a reproducible test (Reason), with the
///         evidence that shows it (a Neuro reportHash or the hash of another
///         reproducible report, plus a short URI). Active, bonded NeuroJobs
///         runners with a track record vote to flag a key. At QUORUM distinct
///         votes the key is flagged, and every Neuro instance that reads this
///         registry warns about it, on every chain. A flag is cleared the same
///         way (QUORUM votes to clear).
///
///         Keys:
///           - a code fingerprint (Neuro's fp1: sha256 of the code with
///             addresses/immutables masked), so every copy of the code is found
///           - codeKey(h):         EVM code with extcodehash h on ZETAPHY
///           - addressKey(id, a):  address a on the chain with EVM id `id`
///         voteBatch lets a runner vote on a fingerprint together with the code
///         hashes and addresses it found for it, in one tx (one evidence for the
///         batch); each key still needs its own quorum. BridgeAirlock / BridgeGuard
///         hold (and, once enforced, refuse) flagged sources and recipients, and
///         the ZETAPHY wallet refuses to sign calls to code with an enforced flag.
///
///         Evidence: every flag vote carries one (reportHash != 0, uri at most
///         MAX_URI bytes); every vote's evidence is in its Voted event, and the
///         evidence of the round's first flag vote (the one whose reason the flag
///         shows) is stored: evidenceOf(key).
///
///         Right of reply: the parties behind a key may post responses (at most
///         MAX_RESPONSE bytes each) that wallets show next to the flag, each with
///         its author's address. Responses are kept per (key, author): an author
///         changes or removes (empty text) only its own, never another's; at most
///         MAX_RESPONSES per key (a new author past that replaces the oldest one,
///         never the governance-assigned responder's). responseAt(key, i) lists
///         them: the governance-assigned responder's first, then newest first;
///         responseOf(key) is responseAt(key, 0).
///         Who may answer for a key (respond / appeal, `mayAnswer`):
///           - addressKey(block.chainid, a) for an address a on ZETAPHY: a itself or,
///             for a contract, its current owner();
///           - addressKey(id, a) on any EVM chain (and on ZETAPHY): the owner of
///             the claimed ERC-8004 identity of "eip155:<id>:<a>" in NeuroIdentity
///             (optional: `identity`, zero = off);
///           - codeKey(h) and fp1 keys: ONLY the responder governance assigned to
///             the key (`responder`). Anyone can deploy a contract with the same
///             code and an owner() of their choosing, so code and fingerprint keys
///             have no on-chain owner to ask;
///           - any key: once governance assigned a responder, only it may answer
///             for that key (setResponder(key, 0) gives address keys back to the
///             routes above). Others' existing responses stay until their authors
///             remove them.
///         A response never changes the flag.
///
///         Appeal: whoever may answer for a flagged key (mayAnswer: so for code and
///         fp1 keys only their assigned responder) may appeal(key), paying
///         `appealBond` (appeals are off until governance sets a community fund).
///         That opens an appeal round, voted with voteAppeal, by runners who
///         neither voted for the flag nor backed it (voted/backed of the round that
///         set it, `flagRound`): fresh eyes. The appellant cannot vote in it.
///           - QUORUM appeal votes to clear: the flag is cleared, the bond is
///             refunded, and each runner who set the flag gets a strike
///             (`strikes`, a public record only: see below).
///           - QUORUM appeal votes to keep: the flag stands; the bond goes to the
///             community fund (not to the voters, so reviewers gain nothing by
///             keeping a flag).
///           - Neither within `appealWindow`: anyone may expireAppeal; the bond is
///             refunded (nobody reviewed it: not the appellant's fault).
///           - The flag cleared otherwise meanwhile (the normal clear vote,
///             governance protecting the key): the bond is refunded.
///         Funds are never pushed inside these calls: refunds are credited
///         (`owed`, taken with withdraw) and the fund's share with payFund, so
///         a failing receiver cannot block a vote. payFund pays the last non-zero
///         community fund governance set (`fundPayee`), so turning appeals off
///         (fund = 0) never sends kept bonds to address(0). Strikes slash nothing: the
///         runners' bonds are in NeuroJobs, and an automatic penalty would let a
///         colluding appeal quorum silence honest runners; governance and the
///         runners' tools can read them.
///
///         Checks on the runners (a small quorum must not freeze bridges or wallets):
///           - Warning, hold and enforcement. isFlagged / is*Flagged answer at
///             once (Neuro warns, the wallet shows a warning). is*Held answer true
///             once a flag is `holdDelay` old (a governance knob, e.g. 10 minutes,
///             below enforceDelay), or at once when it is fast (below) or a guardian
///             or governance called holdNow(key). Things that only HOLD (reversible:
///             BridgeAirlock's release, BridgeGuard's inbound queue and outbound)
///             read those, so two runners alone cannot freeze anyone's bridging
///             at once: governance and guardians get holdDelay to look. is*Enforced
///             answer true only once a flag is `enforceDelay` old; everything that
///             REFUSES (BridgeAirlock's ThreatFlagged, NeuroLane watchers, the
///             wallet's refusal) reads those.
///             What ends a hold: the flag cleared (QUORUM clear votes, or an upheld
///             appeal) or governance protecting the key. Nothing else does: a
///             source-chain LockBox has no refund path, so a held transfer waits
///             in BridgeAirlock (and a held mint in BridgeGuard's queue) until then.
///           - Fast lane. A flag is enforced at once (no enforceDelay) when
///             `fastQuorum` distinct runners stand behind it (a supermajority,
///             governance's knob, default 2 x quorum; runners can still add
///             their vote to a flag that is already standing), or when
///             governance or a guardian calls enforceNow(key) (which holds at once
///             too). Clearing (same quorum) or protecting the key lifts it as before.
///           - Protected keys. Governance (the chain's gov module through
///             MsgEVMCall, or a multisig) can protect keys, e.g. the bridge's
///             own contracts and code hashes or a common token's code. A
///             protected key cannot be flagged; protecting a flagged key clears it.
contract ThreatRegistry {
    IRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed; // verdicts a runner must have had accepted to vote

    /// What the code does, or did in a reproducible test. Never a claim about intent.
    enum Reason {
        None,
        CannotSellInSimulation,   // a simulated buy worked, the sell failed or returned almost nothing
        UnlimitedMint,            // an address can mint new tokens without a cap
        OwnerCanBlockTransfers,   // an owner/admin can stop holders from transferring or selling
        OwnerCanMoveHolderFunds,  // an owner/admin can move or burn tokens or funds held by others
        SameNameAsKnownToken,     // same name/symbol as a known token, at a different address
        SweepsApprovedTokens,     // in a test, moved tokens approved to it to an address the holder did not choose
        Other                     // another code fact: see the evidence
    }

    struct Entry {
        bool flagged;
        Reason reason;
        uint64 updatedAt;
        uint32 round;        // bumps on every flag/clear so old votes stop counting
        uint8 votes;
        bool fast;           // enforced at once (fastQuorum or enforceNow)
        uint8 support;       // distinct runners behind the standing flag
        uint64 fastAt;       // when it went fast
    }

    struct Evidence {
        bytes32 reportHash;  // Neuro reportHash, or the hash of another reproducible report
        address by;          // the runner who gave it
        uint64 at;
        string uri;          // where the report can be read (at most MAX_URI bytes)
    }

    struct Response {
        address by;
        uint64 at;
        uint256 chainId;     // the subject answered for (0: a governance-assigned responder)
        address account;
        string text;         // at most MAX_RESPONSE bytes
    }

    struct Appeal {
        address appellant;   // zero: no appeal open
        uint64 openedAt;
        uint32 flagRound;    // the round that set the flag: its voters and backers may not vote
        uint8 clearVotes;
        uint8 keepVotes;
        uint128 bond;
    }

    bytes16 private constant HEX = "0123456789abcdef";
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_RESPONSE = 500;
    uint256 public constant MAX_RESPONSES = 8;     // per key
    uint256 public constant MAX_APPEAL_BOND = 1000 ether;
    uint64 public constant MIN_APPEAL_WINDOW = 1 days;
    uint64 public constant MAX_APPEAL_WINDOW = 90 days;

    mapping(bytes32 => Entry) public entries;
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public voted;
    /// Runners who backed a standing flag after it was set (fast lane); kept apart
    /// from `voted`, which stays exactly the quorum that set it (ThreatReports pays those).
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public backed;
    bytes32[] public flaggedList;
    mapping(bytes32 => Evidence) private _evidence;
    /// Flag voters per round (at most quorum each): the runners an upheld appeal strikes.
    mapping(bytes32 => mapping(uint32 => address[])) private _flaggers;

    /// The chain's gov module (MsgEVMCall) or a multisig.
    address public governance;
    /// Seconds a flag waits before the is*Enforced views (which block) report it.
    uint64 public enforceDelay;
    uint64 public constant MAX_ENFORCE_DELAY = 30 days;
    /// Keys governance vouched for: never flagged.
    mapping(bytes32 => bool) public protectedKey;
    /// Distinct flag votes that enforce a standing flag at once (0: off).
    uint8 public fastQuorum;
    /// Guardians (set by governance) may enforceNow / holdNow; they cannot flag, clear or protect.
    mapping(address => bool) public guardian;
    /// Seconds a flag waits before the is*Held views (which hold bridging) report it.
    uint64 public holdDelay;
    /// A guardian's (or governance's) holdNow: the flag's round it holds at once, and when.
    struct HoldNow { uint32 round; uint64 at; }
    mapping(bytes32 => HoldNow) public heldNow;

    // ---- right of reply and appeal ----
    IIdentityOwners public identity;               // zero: the identity route is off
    mapping(bytes32 => address) public responder;  // governance-assigned; exclusive once set
    mapping(bytes32 => mapping(address => Response)) private _responses; // per (key, author)
    mapping(bytes32 => address[]) private _authors;                      // authors with a response, least recently updated first
    uint128 public appealBond;
    uint64 public appealWindow = 14 days;
    address public communityFund;                  // zero: appeals off
    address public fundPayee;                      // the last non-zero communityFund: where payFund sends
    mapping(bytes32 => Appeal) public appeals;
    mapping(bytes32 => uint32) public appealCount; // appeal ids per key, from 1
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public appealVoted;
    mapping(address => uint32) public strikes;
    mapping(address => uint256) public owed;       // refunds, taken with withdraw()
    uint256 public fundOwed;                       // the community fund's share, sent with payFund()

    event Voted(bytes32 indexed fingerprint, address indexed runner, bool flag, Reason reason, bytes32 reportHash, string uri);
    event Flagged(bytes32 indexed fingerprint, Reason reason);
    event Cleared(bytes32 indexed fingerprint);
    event Protected(bytes32 indexed key, bool on);
    event EnforceDelaySet(uint64 delay);
    event GovernanceSet(address governance);
    event Supported(bytes32 indexed key, address indexed runner, uint8 support, bytes32 reportHash);
    event FastEnforced(bytes32 indexed key, address indexed by);
    event FastQuorumSet(uint8 fastQuorum);
    event GuardianSet(address indexed who, bool on);
    event Responded(bytes32 indexed key, address indexed by, uint256 chainId, address account, string text);
    event ResponderSet(bytes32 indexed key, address responder);
    event IdentitySet(address identity);
    event AppealsSet(uint128 bond, uint64 window, address fund);
    event Appealed(bytes32 indexed key, uint32 indexed id, address indexed appellant, uint128 bond);
    event AppealVoted(bytes32 indexed key, uint32 indexed id, address indexed runner, bool clear, bytes32 reportHash, string uri);
    event AppealClosed(bytes32 indexed key, uint32 indexed id, uint8 outcome); // 1 cleared, 2 kept, 3 expired, 4 flag cleared otherwise
    event Struck(address indexed runner, bytes32 indexed key, uint32 strikes);
    event Paid(address indexed to, uint256 amount);
    event HoldDelaySet(uint64 delay);
    event HeldNow(bytes32 indexed key, address indexed by);

    error NotRunner();
    error AlreadyVoted();
    error NoChange();
    error NotGovernance();
    error ProtectedKey(bytes32 key);
    error NotGuardian();
    error NotFlagged();
    error NoEvidence();
    error TooLong();
    error NotResponder();
    error AppealsOff();
    error BadBond(uint256 bond);
    error AppealOpen();
    error NoAppeal();
    error AppealExpired();
    error NotYet();
    error NotFresh();
    error PayFailed();
    error NoFund();

    constructor(IRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_, uint64 enforceDelay_) {
        require(quorum_ >= 2, "quorum");
        require(governance_ != address(0), "governance");
        require(enforceDelay_ <= MAX_ENFORCE_DELAY, "delay");
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
        enforceDelay = enforceDelay_;
        fastQuorum = quorum_ > 127 ? 255 : quorum_ * 2;
        holdDelay = enforceDelay_ >= 20 minutes ? 10 minutes : enforceDelay_ / 2;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    /// Applies to flags already standing too (they are measured from when they were set).
    function setEnforceDelay(uint64 d) external onlyGov {
        require(d <= MAX_ENFORCE_DELAY, "delay");
        require(holdDelay == 0 || d > holdDelay, "holdDelay"); // holds start before enforcement
        enforceDelay = d;
        emit EnforceDelaySet(d);
    }

    /// Seconds before a flag holds bridging (is*Held), unless fast or held now.
    /// Below enforceDelay (or 0: a flag holds at once). Applies to standing flags too.
    function setHoldDelay(uint64 d) external onlyGov {
        require(d == 0 || d < enforceDelay, "holdDelay");
        holdDelay = d;
        emit HoldDelaySet(d);
    }

    /// Fast lane: this many distinct runners behind a flag enforce it at once.
    /// Above quorum (a supermajority), or 0 to turn the fast lane off.
    function setFastQuorum(uint8 f) external onlyGov {
        require(f == 0 || f > quorum, "fastQuorum");
        fastQuorum = f;
        emit FastQuorumSet(f);
    }

    function setGuardian(address who, bool on) external onlyGov {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// NeuroIdentity, for the identity route of the right of reply (zero: off).
    function setIdentity(IIdentityOwners i) external onlyGov {
        identity = i;
        emit IdentitySet(address(i));
    }

    /// The only party that may answer for `key` (zero: the on-chain routes again).
    function setResponder(bytes32 key, address who) external onlyGov {
        responder[key] = who;
        emit ResponderSet(key, who);
    }

    /// Appeal bond, window and the community fund that keeps bonds of appeals
    /// that confirmed the flag. A zero fund turns appeals off (open ones still
    /// close normally); a new bond applies to new appeals only.
    function setAppeals(uint128 bond, uint64 window, address fund) external onlyGov {
        require(bond <= MAX_APPEAL_BOND, "bond");
        require(window >= MIN_APPEAL_WINDOW && window <= MAX_APPEAL_WINDOW, "window");
        appealBond = bond;
        appealWindow = window;
        communityFund = fund;
        if (fund != address(0)) fundPayee = fund;
        emit AppealsSet(bond, window, fund);
    }

    /// Governance or a guardian enforces a standing flag at once (money moving
    /// now). Only a flag the runners' quorum already set; protected keys can
    /// never be flagged, so never enforced either.
    function enforceNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast) revert NoChange();
        _fast(e, key);
    }

    /// Governance or a guardian holds a standing flag at once (no holdDelay):
    /// bridging of its party stops now, as reversible as any hold. Only a flag
    /// the runners' quorum already set; it ends with the flag (clear / protect).
    function holdNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast || heldNow[key].round == e.round) revert NoChange();
        heldNow[key] = HoldNow(e.round, uint64(block.timestamp));
        emit HeldNow(key, msg.sender);
    }

    function _fast(Entry storage e, bytes32 key) private {
        e.fast = true;
        e.fastAt = uint64(block.timestamp);
        emit FastEnforced(key, msg.sender);
    }

    /// Protect (or unprotect) keys. Protecting clears a flag at once and drops
    /// any votes in progress; unprotecting does not flag anything back.
    function setProtected(bytes32[] calldata keys, bool on) external onlyGov {
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            protectedKey[k] = on;
            emit Protected(k, on);
            if (!on) continue;
            Entry storage e = entries[k];
            if (e.flagged || e.votes != 0) {
                bool was = e.flagged;
                _reset(e, k);
                e.round += 1;
                e.updatedAt = uint64(block.timestamp);
                if (was) emit Cleared(k);
            }
        }
    }

    /// keccak256 of empty code: every account without code has it, so it is never a threat.
    bytes32 public constant EMPTY_CODEHASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    /// The key under which EVM code with this extcodehash is flagged.
    function codeKey(bytes32 codeHash) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.code", codeHash));
    }

    /// The key under which an address on a given chain (EVM chain id) is flagged.
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.address", chainId, who));
    }

    function _checkRunner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function _checkEvidence(bool required, bytes32 reportHash, string calldata uri) private pure {
        if (required && reportHash == bytes32(0)) revert NoEvidence();
        if (bytes(uri).length > MAX_URI) revert TooLong();
    }

    /// Vote to flag (flag = true, with a reason and its evidence) or to clear
    /// (flag = false; evidence optional). `fingerprint` is any key: a fp1
    /// fingerprint, codeKey(..) or addressKey(..).
    function vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && protectedKey[fingerprint]) revert ProtectedKey(fingerprint);
        if (!_vote(fingerprint, flag, reason, reportHash, uri)) revert NoChange();
    }

    /// One runner's votes on several keys at once, e.g. a fingerprint plus the
    /// code hashes and addresses of its copies, with one evidence for the batch.
    /// Keys already in that state, or already voted on by this runner this
    /// round, are skipped (not an error), so the same list can be sent again as
    /// copies are found. Protected keys are skipped when flagging. On a key
    /// already flagged, a flag vote adds this runner's support (toward
    /// fastQuorum) once.
    function voteBatch(bytes32[] calldata keys, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external returns (uint256 counted) {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && reason == Reason.None) revert NoChange();
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            Entry storage e = entries[k];
            if (flag && protectedKey[k]) continue;
            if (flag && e.flagged) { if (_support(e, k, reportHash)) counted++; continue; }
            if (e.flagged == flag || voted[k][e.round][msg.sender]) continue;
            _vote(k, flag, reason, reportHash, uri);
            counted++;
        }
        if (counted == 0) revert NoChange();
    }

    /// A flag vote on a standing flag: one more runner behind it (once per
    /// runner, counting the quorum that set it). False when nothing changed.
    function _support(Entry storage e, bytes32 key, bytes32 reportHash) private returns (bool) {
        if (e.fast || e.support == type(uint8).max) return false;
        uint32 r = e.round - 1; // the round that set the flag
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender]) return false;
        backed[key][r][msg.sender] = true;
        e.support += 1;
        emit Supported(key, msg.sender, e.support, reportHash);
        if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, key);
        return true;
    }

    /// The flag (or the votes in progress) is gone: an open appeal ends with its bond refunded.
    function _reset(Entry storage e, bytes32 key) private {
        e.flagged = false;
        e.reason = Reason.None;
        e.votes = 0;
        e.fast = false;
        e.support = 0;
        e.fastAt = 0;
        delete _evidence[key];
        if (appeals[key].appellant != address(0)) _closeAppeal(key, 4);
    }

    function _vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) private returns (bool) {
        Entry storage e = entries[fingerprint];
        if (flag && reason == Reason.None) return false;
        if (flag && e.flagged) {
            if (voted[fingerprint][e.round - 1][msg.sender] || backed[fingerprint][e.round - 1][msg.sender]) revert AlreadyVoted();
            return _support(e, fingerprint, reportHash);
        }
        if (e.flagged == flag) return false;
        if (voted[fingerprint][e.round][msg.sender]) revert AlreadyVoted();
        voted[fingerprint][e.round][msg.sender] = true;
        e.votes += 1;
        if (flag) {
            _flaggers[fingerprint][e.round].push(msg.sender);
            if (e.reason == Reason.None) { // the round's first flag vote: its reason and evidence are what the flag shows
                e.reason = reason;
                _evidence[fingerprint] = Evidence(reportHash, msg.sender, uint64(block.timestamp), uri);
            }
        }
        emit Voted(fingerprint, msg.sender, flag, reason, reportHash, uri);
        if (e.votes >= quorum) {
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            if (flag) {
                e.flagged = true;
                e.support = e.votes;
                e.votes = 0;
                flaggedList.push(fingerprint);
                emit Flagged(fingerprint, e.reason);
                if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, fingerprint);
            } else {
                _reset(e, fingerprint);
                emit Cleared(fingerprint);
            }
        }
        return true;
    }

    // ---- right of reply ----

    /// "eip155:<chainId>:0x<lowercase hex>", NeuroIdentity's spelling of an EVM target.
    function _caip10(uint256 chainId, address a) private pure returns (bytes memory out) {
        bytes memory digits = new bytes(78);
        uint256 n = 78;
        uint256 v = chainId;
        do { digits[--n] = bytes1(uint8(48 + v % 10)); v /= 10; } while (v != 0);
        bytes memory id = new bytes(78 - n);
        for (uint256 i = 0; i < id.length; i++) id[i] = digits[n + i];
        bytes memory hexa = new bytes(40);
        uint160 x = uint160(a);
        for (uint256 i = 40; i > 0; i--) { hexa[i - 1] = HEX[x & 15]; x >>= 4; }
        out = abi.encodePacked("eip155:", id, ":0x", hexa);
    }

    /// The claimed owner of the identity of `account` on chain `chainId` (zero: none, unclaimed or off).
    function _identityOwner(uint256 chainId, address account) private view returns (address) {
        IIdentityOwners idr = identity;
        if (address(idr) == address(0)) return address(0);
        try idr.agentOfTarget(keccak256(_caip10(chainId, account))) returns (uint256 agentId) {
            if (agentId == 0) return address(0);
            try idr.ownerOf(agentId) returns (address o) { return o == address(idr) ? address(0) : o; } catch { return address(0); }
        } catch { return address(0); }
    }

    /// The `owner()` of a contract on this chain (zero: none).
    function _ownerOf(address a) private view returns (address) {
        if (a.code.length == 0) return address(0);
        (bool ok, bytes memory r) = a.staticcall{gas: 50_000}(abi.encodeWithSignature("owner()"));
        if (!ok || r.length < 32) return address(0);
        uint256 w = abi.decode(r, (uint256));
        return w >> 160 == 0 ? address(uint160(w)) : address(0);
    }

    /// May `who` answer for `key` as the party behind (chainId, account)? (See the notice.)
    /// Code keys and fp1 keys: only their governance-assigned responder.
    function mayAnswer(bytes32 key, uint256 chainId, address account, address who) public view returns (bool) {
        address r = responder[key];
        if (r != address(0) || chainId == 0) return r != address(0) && who == r;
        if (who == address(0) || key != addressKey(chainId, account)) return false;
        if (chainId == block.chainid && (who == account || who == _ownerOf(account))) return true;
        return who == _identityOwner(chainId, account);
    }

    /// Post or replace msg.sender's own response to the flag on `key`, as the
    /// party behind (chainId, account) (see the notice). Empty text removes
    /// msg.sender's own response (always allowed to its author). Never changes the flag.
    function respond(bytes32 key, uint256 chainId, address account, string calldata text) external {
        if (bytes(text).length > MAX_RESPONSE) revert TooLong();
        Response storage cur = _responses[key][msg.sender];
        bool had = cur.by != address(0);
        if (bytes(text).length == 0) {
            if (!had) revert NoChange();
            emit Responded(key, msg.sender, cur.chainId, cur.account, text);
            delete _responses[key][msg.sender];
            _dropAuthor(key, msg.sender);
            return;
        }
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        if (had) _dropAuthor(key, msg.sender);
        else if (_authors[key].length >= MAX_RESPONSES) _evictOldest(key);
        _authors[key].push(msg.sender);
        _responses[key][msg.sender] = Response(msg.sender, uint64(block.timestamp), chainId, account, text);
        emit Responded(key, msg.sender, chainId, account, text);
    }

    function _dropAuthor(bytes32 key, address who) private {
        address[] storage a = _authors[key];
        uint256 n = a.length;
        for (uint256 i = 0; i < n; i++) {
            if (a[i] != who) continue;
            for (uint256 j = i + 1; j < n; j++) a[j - 1] = a[j]; // keep the order
            a.pop();
            return;
        }
    }

    /// Full: the least recently updated response goes, never the assigned responder's.
    function _evictOldest(bytes32 key) private {
        address[] storage a = _authors[key];
        address keep = responder[key];
        for (uint256 i = 0; i < a.length; i++) {
            if (a[i] == keep) continue;
            address old = a[i];
            delete _responses[key][old];
            _dropAuthor(key, old);
            return;
        }
    }

    /// How many responses `key` has (at most MAX_RESPONSES, plus none).
    function responseCount(bytes32 key) external view returns (uint256) {
        return _authors[key].length;
    }

    /// The i-th response to `key`: the governance-assigned responder's first (if
    /// it posted one), then the others newest first. Past the end: all zero.
    function responseAt(bytes32 key, uint256 i) public view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        address[] storage a = _authors[key];
        address r = responder[key];
        bool rFirst = r != address(0) && _responses[key][r].by != address(0);
        address who;
        if (rFirst && i == 0) who = r;
        else {
            uint256 k = rFirst ? i - 1 : i; // index among the others, newest first
            for (uint256 j = a.length; j > 0; j--) {
                if (rFirst && a[j - 1] == r) continue;
                if (k == 0) { who = a[j - 1]; break; }
                k--;
            }
        }
        if (who == address(0)) return ("", address(0), 0, 0, address(0));
        Response storage x = _responses[key][who];
        return (x.text, x.by, x.at, x.chainId, x.account);
    }

    /// The first response (responseAt(key, 0)): the assigned responder's, else the newest.
    function responseOf(bytes32 key) external view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        return responseAt(key, 0);
    }

    /// `who`'s own response to `key` (empty: none).
    function responseBy(bytes32 key, address who) external view returns (string memory text, uint64 at, uint256 chainId, address account) {
        Response storage x = _responses[key][who];
        return (x.text, x.at, x.chainId, x.account);
    }

    /// The evidence of the flag on `key` (of the round's first flag vote; while
    /// a flag round is still open, that vote's). Zero when there is none.
    function evidenceOf(bytes32 key) external view returns (bytes32 reportHash, string memory uri, address by, uint64 at) {
        Evidence storage v = _evidence[key];
        return (v.reportHash, v.uri, v.by, v.at);
    }

    // ---- appeal ----

    /// Appeal the standing flag on `key` as the party behind (chainId, account),
    /// paying exactly appealBond. Opens an appeal round (voteAppeal).
    function appeal(bytes32 key, uint256 chainId, address account) external payable returns (uint32 id) {
        if (communityFund == address(0)) revert AppealsOff();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (appeals[key].appellant != address(0)) revert AppealOpen();
        if (msg.value != appealBond) revert BadBond(appealBond);
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        id = ++appealCount[key];
        appeals[key] = Appeal(msg.sender, uint64(block.timestamp), e.round - 1, 0, 0, uint128(msg.value));
        emit Appealed(key, id, msg.sender, uint128(msg.value));
    }

    /// A fresh runner's vote in the open appeal on `key`: clear the flag (clear =
    /// true) or keep it, with its own evidence (the reproduction it ran).
    /// Runners who voted for or backed the flag, and the appellant, cannot vote.
    function voteAppeal(bytes32 key, bool clear, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(true, reportHash, uri);
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp >= uint256(a.openedAt) + appealWindow) revert AppealExpired();
        uint32 r = a.flagRound;
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender] || msg.sender == a.appellant) revert NotFresh();
        uint32 id = appealCount[key];
        if (appealVoted[key][id][msg.sender]) revert AlreadyVoted();
        appealVoted[key][id][msg.sender] = true;
        emit AppealVoted(key, id, msg.sender, clear, reportHash, uri);
        if (clear) {
            if (++a.clearVotes < quorum) return;
            address[] storage fl = _flaggers[key][r];
            for (uint256 i = 0; i < fl.length; i++) emit Struck(fl[i], key, ++strikes[fl[i]]);
            _closeAppeal(key, 1);
            Entry storage e = entries[key];
            _reset(e, key);
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            emit Cleared(key);
        } else if (++a.keepVotes >= quorum) {
            _closeAppeal(key, 2);
        }
    }

    /// Nobody decided within appealWindow: the bond is refunded, the flag stands.
    function expireAppeal(bytes32 key) external {
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp < uint256(a.openedAt) + appealWindow) revert NotYet();
        _closeAppeal(key, 3);
    }

    /// outcome 2 (kept): the bond to the community fund; otherwise refunded.
    function _closeAppeal(bytes32 key, uint8 outcome) private {
        Appeal memory a = appeals[key];
        delete appeals[key];
        if (outcome == 2) fundOwed += a.bond;
        else owed[a.appellant] += a.bond;
        emit AppealClosed(key, appealCount[key], outcome);
    }

    /// Take refunded bonds.
    function withdraw() external {
        uint256 amount = owed[msg.sender];
        owed[msg.sender] = 0;
        _pay(msg.sender, amount);
    }

    /// Send kept bonds to the community fund (anyone may call it): the last
    /// non-zero fund governance set, even after appeals were turned off.
    function payFund() external {
        uint256 amount = fundOwed;
        if (amount == 0) return;
        address to = fundPayee;
        if (to == address(0)) revert NoFund();
        fundOwed = 0;
        _pay(to, amount);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
        emit Paid(to, amount);
    }

    // ---- warning views: true as soon as the quorum flagged (Neuro warns on these) ----

    function isFlagged(bytes32 fingerprint) public view returns (bool, Reason) {
        Entry storage e = entries[fingerprint];
        return (e.flagged, e.reason);
    }

    /// EVM code with this code hash (extcodehash) is flagged. Empty code never is.
    function isCodeFlagged(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isFlagged(codeKey(codeHash));
    }

    function isAddressFlagged(uint256 chainId, address who) public view returns (bool, Reason) {
        return isFlagged(addressKey(chainId, who));
    }

    /// For contracts on this chain: `who` itself is flagged, or the code at it is.
    function isContractFlagged(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressFlagged(block.chainid, who);
        if (f) return (f, r);
        return isCodeFlagged(who.codehash);
    }

    // ---- hold views: true once the flag is holdDelay old, at once through the fast
    //      lane or holdNow (these hold bridging, reversibly) ----

    /// When a standing flag starts to hold (0: not flagged).
    function heldFrom(bytes32 key) public view returns (uint64 from) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        from = e.updatedAt + holdDelay;
        if (e.fast && e.fastAt < from) from = e.fastAt;
        HoldNow storage h = heldNow[key];
        if (h.round == e.round && h.at < from) from = h.at;
    }

    function isHeld(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged) return (false, Reason.None);
        if (e.fast || heldNow[key].round == e.round || block.timestamp >= uint256(e.updatedAt) + holdDelay) return (true, e.reason);
        return (false, Reason.None);
    }

    function isCodeHeld(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isHeld(codeKey(codeHash));
    }

    function isAddressHeld(uint256 chainId, address who) public view returns (bool, Reason) {
        return isHeld(addressKey(chainId, who));
    }

    function isContractHeld(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressHeld(block.chainid, who);
        if (f) return (f, r);
        return isCodeHeld(who.codehash);
    }

    // ---- enforcement views: true only once the flag is enforceDelay old, or at once
    //      through the fast lane (these block) ----

    /// When a standing flag starts to be enforced (0: not flagged).
    function enforcedFrom(bytes32 key) public view returns (uint64) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        uint64 normal = e.updatedAt + enforceDelay;
        return e.fast && e.fastAt < normal ? e.fastAt : normal;
    }

    function isEnforced(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged || (!e.fast && block.timestamp < uint256(e.updatedAt) + enforceDelay)) return (false, Reason.None);
        return (true, e.reason);
    }

    function isCodeEnforced(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isEnforced(codeKey(codeHash));
    }

    function isAddressEnforced(uint256 chainId, address who) public view returns (bool, Reason) {
        return isEnforced(addressKey(chainId, who));
    }

    function isContractEnforced(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressEnforced(block.chainid, who);
        if (f) return (f, r);
        return isCodeEnforced(who.codehash);
    }

    function flaggedCount() external view returns (uint256) {
        return flaggedList.length;
    }
}

contracts/ThreatReports.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The parts of ThreatRegistry this contract reads.
interface IThreatRegistryView {
    function governance() external view returns (address);
    function quorum() external view returns (uint8);
    function voted(bytes32 key, uint32 round, address runner) external view returns (bool);
    function entries(bytes32 key) external view returns (
        bool flagged, uint8 reason, uint64 updatedAt, uint32 round, uint8 votes, bool fast, uint8 support, uint64 fastAt);
}

/// @title ThreatReports: anyone can point the Neuro runners at a contract to check
/// @notice A user who wants a contract's code checked pays a small fee and
///         reports it: report(key, chainKey, target, note). Runners' tools
///         watch the Reported event, run Neuro on the target and, if a
///         reproducible code fact shows up (ThreatRegistry.Reason, with its
///         evidence), flag the key in the ThreatRegistry (the usual quorum;
///         reports never flag anything by themselves, and a report is a request
///         to check, not a finding).
///         The fee is the anti-spam and the runners' reward:
///           - the key is flagged after the report: the runners who set that
///             flag (the registry's quorum of that round) share the fee; each
///             claims its share (claim);
///           - not flagged within `ttl`: the fee goes to the community fund.
///         settle(id) decides which (anyone may call it).
///         Input is bounded: a note of at most MAX_NOTE bytes, one key per report.
///         Governance is the ThreatRegistry's governance.
contract ThreatReports {
    struct Report {
        bytes32 key;          // ThreatRegistry key: fp1, codeKey(..) or addressKey(..)
        bytes32 chainKey;     // where the target lives, e.g. "eip155:56" or "bsc" (bytes32 string)
        address target;       // the contract on that chain (zero: none given)
        address reporter;
        uint64 createdAt;
        uint8 state;          // 0 open, 1 flagged (runners claim), 2 not flagged (to the fund)
        uint32 flagRound;     // the registry round whose voters share the fee
        uint128 fee;          // what was paid
        uint128 share;        // each voter's share once flagged
        uint8 claims;         // shares paid (at most the registry's quorum)
    }

    uint256 public constant MAX_NOTE = 280;
    uint256 public constant MAX_FEE = 100 ether;
    uint64 public constant MIN_TTL = 1 days;
    uint64 public constant MAX_TTL = 365 days;

    IThreatRegistryView public immutable registry;
    uint256 public fee;
    uint64 public ttl;
    address public communityFund;
    Report[] public reports;
    mapping(uint256 => mapping(address => bool)) public claimed;

    event Reported(uint256 indexed id, bytes32 indexed key, bytes32 indexed chainKey, address target, address reporter, uint256 fee, string note);
    event Settled(uint256 indexed id, bool flagged, uint256 share);
    event Claimed(uint256 indexed id, address indexed runner, uint256 amount);
    event FeeSet(uint256 fee);
    event TtlSet(uint64 ttl);
    event CommunityFundSet(address fund);

    error NotGovernance();
    error BadFee(uint256 fee);
    error NoteTooLong();
    error BadKey();
    error AlreadyFlagged();
    error NotSettled();
    error AlreadySettled();
    error NotYet();
    error NotVoter();
    error PayFailed();

    constructor(IThreatRegistryView registry_, address communityFund_, uint256 fee_, uint64 ttl_) {
        require(communityFund_ != address(0), "fund");
        require(fee_ <= MAX_FEE, "fee");
        require(ttl_ >= MIN_TTL && ttl_ <= MAX_TTL, "ttl");
        registry = registry_;
        communityFund = communityFund_;
        fee = fee_;
        ttl = ttl_;
    }

    modifier onlyGov() { if (msg.sender != registry.governance()) revert NotGovernance(); _; }

    function setFee(uint256 f) external onlyGov { require(f <= MAX_FEE, "fee"); fee = f; emit FeeSet(f); }
    function setTtl(uint64 t) external onlyGov { require(t >= MIN_TTL && t <= MAX_TTL, "ttl"); ttl = t; emit TtlSet(t); }
    function setCommunityFund(address f) external onlyGov { require(f != address(0), "fund"); communityFund = f; emit CommunityFundSet(f); }

    /// Ask the runners to check a contract. `key` is the registry key the runners
    /// would flag; send exactly `fee`. A key that is already flagged needs no
    /// report (and would pay nobody for new work), so it is refused.
    function report(bytes32 key, bytes32 chainKey, address target, string calldata note) external payable returns (uint256 id) {
        if (msg.value != fee) revert BadFee(fee);
        if (bytes(note).length > MAX_NOTE) revert NoteTooLong();
        if (key == bytes32(0)) revert BadKey();
        (bool flagged, , , , , , , ) = registry.entries(key);
        if (flagged) revert AlreadyFlagged();
        id = reports.length;
        reports.push(Report(key, chainKey, target, msg.sender, uint64(block.timestamp), 0, 0, uint128(msg.value), 0, 0));
        emit Reported(id, key, chainKey, target, msg.sender, msg.value, note);
    }

    /// Flagged since the report: the voters of that flag share the fee. Not
    /// flagged and older than ttl: the fee goes to the community fund.
    function settle(uint256 id) external {
        Report storage r = reports[id];
        if (r.state != 0) revert AlreadySettled();
        (bool flagged, , uint64 updatedAt, uint32 round, , , , ) = registry.entries(r.key);
        if (flagged && updatedAt >= r.createdAt) {
            uint256 q = registry.quorum();
            r.state = 1;
            r.flagRound = round - 1; // the round that set the standing flag
            r.share = uint128(r.fee / q);
            uint256 dust = r.fee - r.share * q;
            if (dust != 0) _pay(communityFund, dust);
            emit Settled(id, true, r.share);
        } else if (block.timestamp >= uint256(r.createdAt) + ttl) {
            r.state = 2;
            _pay(communityFund, r.fee);
            emit Settled(id, false, 0);
        } else revert NotYet();
    }

    /// A runner who voted for the flag that settled this report takes its share.
    function claim(uint256 id) external {
        Report storage r = reports[id];
        if (r.state != 1) revert NotSettled();
        if (claimed[id][msg.sender]) revert AlreadySettled();
        if (!registry.voted(r.key, r.flagRound, msg.sender)) revert NotVoter();
        if (r.claims >= registry.quorum()) revert AlreadySettled(); // never more than the fee
        r.claims += 1;
        claimed[id][msg.sender] = true;
        _pay(msg.sender, r.share);
        emit Claimed(id, msg.sender, r.share);
    }

    function reportCount() external view returns (uint256) {
        return reports.length;
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
    }
}

contracts/TrainingMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ITMIssuance {
    function draw(uint256 amount) external returns (uint256 paid);
}

interface ITMReputation {
    function record(address worker, uint8 kind, bytes32 ref) external;
}

interface ITMEpochs {
    function current() external view returns (bool found, uint256 index, bytes32 hash, uint64 activation, string memory uri);
}

interface ITMPool {
    function eligible(address w) external view returns (bool);
    function size() external view returns (uint256);
    function members(uint256 i) external view returns (address);
    function exitDelay() external view returns (uint32);
    function lock(address w, bool on) external;
    function slash(address w, uint256 amount) external returns (uint256 got);
}

interface ITMMinDelay {
    function getMinDelay() external view returns (uint256);
}

/// @title TrainingMarket: proof of useful work for AI training (testnet)
/// @notice The network's compute trains Neuro (the scam-detection model) and is paid only for work it can
///         check (docs/future/useful-work-training.md). One TASK is one training round:
///           1. A poster escrows a budget for a spec (keccak of the spec file: data shards, base model, seed,
///              hyper-parameters) and commits to a secret held-out seed.
///           2. Pool members (staked) take seats; seat j trains shard j DETERMINISTICALLY (bit-reproducible
///              JS, zetaphy-hub/train-core.js) and commits keccak(root, treesHash, worker, salt, task): root
///              is the hash of its per-segment checkpoint digests. Then it reveals root, treesHash and where
///              its trees are published.
///           3. Randomness from a FUTURE block (requestDraw, then draw) picks `checksPerJob` segments of every
///              job and `verifiersPerCheck` verifiers for each (never the job's trainer), and the evaluators
///              (never a trainer with a revealed job).
///           4. Spot-checks: verifiers re-run their segment and commit their own digest, sealed; then the
///              trainer opens its digests (checked against root) and verifiers reveal. The majority decides:
///              a mismatch FAILS the job and slashes `trainSlash` from the trainer (a share goes to the
///              verifiers who caught it); verifiers in the minority or silent lose `missSlash`.
///           5. The poster reveals its secret; held-out seed = keccak(secret, randomness), known to nobody
///              before the draw. Evaluators compute AUC and recall at 1% FPR of the base model and of the
///              candidate (base + the passed jobs' trees) on the held-out rows that seed picks, sealed then
///              revealed. The majority's numbers decide: ACCEPTED only if AUC rises by >= minGainAuc and
///              recall does not fall.
///           6. Payouts (pull): verifiers and evaluators in the majority are paid whatever the outcome (so they
///              have no reason to favour acceptance); trainers of passed jobs are paid ONLY if accepted (plus
///              a subsidy from UsefulIssuance on a feeder's task). The rest returns to the poster.
///         The accepted candidate id (keccak(baseModel ‖ treesHash of each passed job)) is recorded; the new
///         model version is then scheduled by governance through ModelEpochs (a timelock vote), and a task
///         must start from the version in force (`epochs`). No admin key: governance must be a timelock with
///         at least MIN_DELAY; the contract starts paused until governance opens it.
contract TrainingMarket {
    uint256 public constant MIN_DELAY = 2 days;
    uint256 public constant MAX_JOBS = 8;
    uint256 public constant MAX_SEGMENTS = 64;
    bytes32 public constant UNAVAILABLE = keccak256("zetaphy-train/1 unavailable");

    // WorkerReputation.Kind
    uint8 internal constant AGREED = 0;
    uint8 internal constant DISAGREED = 1;
    uint8 internal constant MISSED = 2;
    uint8 internal constant SLASHED = 3;

    // job status
    uint8 public constant JOB_PENDING = 0;
    uint8 public constant JOB_PASSED = 1;
    uint8 public constant JOB_FAILED = 2;
    uint8 public constant JOB_INCONCLUSIVE = 3;
    uint8 public constant JOB_MISSED = 4;
    /// The job number of the evaluation check (the last check of a drawn task).
    uint8 public constant EVAL_JOB = 255;

    // task stage
    uint8 public constant OPEN = 0;
    uint8 public constant VERIFY = 1;
    uint8 public constant EVAL = 2;
    uint8 public constant DONE = 3;

    struct Params {
        uint128 trainSlash;        // a trainer whose checkpoint fails a spot-check
        uint128 missSlash;         // a missed reveal, a verifier / evaluator in the minority
        uint128 maxSubsidy;        // most a feeder's task may draw from UsefulIssuance
        uint32 seatWindow;         // seats are taken during this
        uint32 commitWindow;       // then the trained results are committed
        uint32 revealWindow;       // then revealed
        uint32 verifyCommitWindow; // after the draw: verifiers commit
        uint32 verifyRevealWindow; // then trainers open their digests and verifiers reveal
        uint32 evalCommitWindow;   // after judging: evaluators commit
        uint32 evalRevealWindow;   // then reveal
        uint8 checksPerJob;        // segments re-run per job (1..4)
        uint8 verifiersPerCheck;   // verifiers per segment (1..5)
        uint8 evaluators;          // evaluators per task (1..7)
        uint16 trainBps;           // budget shares (sum <= 10,000)
        uint16 checkBps;
        uint16 evalBps;
        uint16 catchBps;           // share of a trainer's slash paid to the verifiers who caught it
        uint16 minGainAuc;         // in 1/10,000 AUC
    }

    struct Task {
        address poster;
        uint8 stage;
        uint8 jobCount;
        uint8 taken;
        uint8 passed;
        uint16 segments;
        bool heldoutRevealed;
        bool accepted;
        uint64 postedAt;
        uint64 drawBlock;
        uint64 verifyAt;
        uint64 evalAt;
        uint128 budget;
        uint128 spent;
        uint128 subsidy;
        uint32 baseAuc;
        uint32 candAuc;
        uint32 baseRecall;
        uint32 candRecall;
        bytes32 specHash;
        bytes32 baseModel;
        bytes32 heldoutCommit;
        bytes32 heldoutSeed;
        bytes32 randomness;
        bytes32 candidate;
    }

    struct Job {
        address trainer;
        uint8 status;
        bool revealed;
        bool opened;
        bytes32 commitment;
        bytes32 root;
        bytes32 treesHash;
    }

    struct Check {
        uint8 job;
        uint16 segment;
        uint8 status; // 0 open, 1 pass, 2 fail, 3 inconclusive
        bytes32 majority;
    }

    address public governance;
    ITMPool public pool;
    ITMIssuance public issuance;
    ITMReputation public reputation;
    ITMEpochs public epochs;
    Params private _params;
    bool public paused;

    uint256 public reserve;     // slashes and plain transfers: pays feeder subsidies first
    uint256 public escrow;      // budgets of tasks not finished
    uint256 public totalOwed;
    mapping(address => uint256) public owed;
    mapping(address => bool) public feeders;
    /// candidate id => task id + 1 of the task that accepted it
    mapping(bytes32 => uint256) public acceptedBy;

    Task[] private _tasks;
    mapping(uint256 => Job[]) private _jobs;
    mapping(uint256 => mapping(address => uint256)) public seatOf; // job index + 1
    mapping(uint256 => mapping(uint256 => bytes32[])) private _digests;
    mapping(uint256 => Check[]) private _checks;
    mapping(uint256 => mapping(uint256 => address[])) private _verifiers;
    mapping(uint256 => mapping(uint256 => mapping(address => bytes32))) public commits;
    mapping(uint256 => mapping(uint256 => mapping(address => bytes32))) public answers;

    event Posted(uint256 indexed id, address indexed poster, bytes32 specHash, bytes32 baseModel, uint256 budget, string specURI);
    event SeatTaken(uint256 indexed id, uint256 job, address indexed trainer);
    event TrainRevealed(uint256 indexed id, uint256 job, bytes32 root, bytes32 treesHash, string uri);
    event Drawn(uint256 indexed id, bytes32 randomness, uint256 checks);
    event CheckAssigned(uint256 indexed id, uint256 indexed check, uint256 job, uint256 segment, address[] verifiers);
    event Answered(uint256 indexed id, uint256 indexed check, address indexed who, bytes32 answer);
    event HeldoutRevealed(uint256 indexed id, bytes32 seed);
    event CheckJudged(uint256 indexed id, uint256 indexed check, uint8 status, bytes32 majority, bytes32 claimed);
    event JobJudged(uint256 indexed id, uint256 job, uint8 status, uint256 slashed);
    event Judged(uint256 indexed id, uint256 passed, bytes32 candidate, bytes32 heldoutSeed);
    event Finalized(uint256 indexed id, bool accepted, bytes32 candidate, uint256 refund);
    event ModelAccepted(uint256 indexed id, bytes32 indexed candidate, bytes32 baseModel);
    event Paid(uint256 indexed id, address indexed to, uint256 amount, uint8 role); // 0 trainer, 1 verifier, 2 evaluator, 3 catch bounty
    event Slashed(uint256 indexed id, address indexed who, uint256 amount, uint8 kind);
    event Withdrawn(address indexed to, uint256 amount);
    event ParamsSet();
    event FeederSet(address indexed feeder, bool on);
    event PausedSet(bool paused);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotTimelock();
    error BadParams();
    error BadValue();
    error BadTask();
    error Paused();
    error WrongPhase();
    error NotEligible();
    error Full();
    error AlreadyIn();
    error NotSeated();
    error BadReveal();
    error StaleBase();
    error NotFeeder();
    error Nothing();

    constructor(address governance_, ITMPool pool_, ITMIssuance issuance_, ITMReputation reputation_, ITMEpochs epochs_, Params memory p) {
        _checkTimelock(governance_);
        governance = governance_;
        pool = pool_;
        issuance = issuance_;
        reputation = reputation_;
        epochs = epochs_;
        _setParams(p);
        paused = true; // closed until governance opens it
        emit PausedSet(true);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    modifier notPaused() {
        if (paused) revert Paused();
        _;
    }

    /// Money in from UsefulIssuance.draw() or anyone: into the reserve.
    receive() external payable {
        reserve += msg.value;
    }

    // ---------------------------------------------------------------- posting

    /// Anyone: a training round of `jobs` shards, `segments` checkpoints each, paid from msg.value. A feeder
    /// (named by governance) may add a `subsidy` the trainers of an accepted round share (from UsefulIssuance).
    function post(bytes32 specHash, string calldata specURI, bytes32 baseModel, uint8 jobs, uint16 segments, bytes32 heldoutCommit, uint128 subsidy)
        external payable notPaused returns (uint256 id)
    {
        if (subsidy > 0 && (!feeders[msg.sender] || subsidy > _params.maxSubsidy)) revert NotFeeder();
        if (msg.value == 0 || msg.value > type(uint128).max) revert BadValue();
        if (specHash == 0 || baseModel == 0 || heldoutCommit == 0 || bytes(specURI).length == 0 || bytes(specURI).length > 256) revert BadTask();
        if (jobs == 0 || jobs > MAX_JOBS || segments < _params.checksPerJob || segments > MAX_SEGMENTS) revert BadTask();
        _checkBase(baseModel);
        id = _tasks.length;
        Task storage t = _tasks.push();
        t.poster = msg.sender;
        t.jobCount = jobs;
        t.segments = segments;
        t.postedAt = uint64(block.timestamp);
        t.budget = uint128(msg.value);
        t.subsidy = subsidy;
        t.specHash = specHash;
        t.baseModel = baseModel;
        t.heldoutCommit = heldoutCommit;
        escrow += msg.value;
        emit Posted(id, msg.sender, specHash, baseModel, msg.value, specURI);
    }

    /// Rounds improve the model in force (ModelEpochs), when there is one.
    function _checkBase(bytes32 baseModel) internal view {
        if (address(epochs) == address(0)) return;
        (bool found,, bytes32 cur,,) = epochs.current();
        if (found && cur != baseModel) revert StaleBase();
    }

    // ---------------------------------------------------------------- training: seats, commit, reveal

    function takeSeat(uint256 id) external notPaused returns (uint256 job) {
        Task storage t = _task(id);
        if (t.stage != OPEN || block.timestamp >= _seatEnd(t)) revert WrongPhase();
        if (t.taken >= t.jobCount) revert Full();
        if (!pool.eligible(msg.sender)) revert NotEligible();
        if (seatOf[id][msg.sender] != 0) revert AlreadyIn();
        job = t.taken++;
        Job storage j = _jobs[id].push();
        j.trainer = msg.sender;
        seatOf[id][msg.sender] = job + 1;
        pool.lock(msg.sender, true);
        emit SeatTaken(id, job, msg.sender);
    }

    function _trainCommitment(bytes32 root, bytes32 treesHash, address worker, bytes32 salt, uint256 id) internal pure returns (bytes32) {
        return keccak256(abi.encode(root, treesHash, worker, salt, id));
    }

    function commitTraining(uint256 id, bytes32 commitment) external {
        Task storage t = _task(id);
        if (t.stage != OPEN || block.timestamp >= _commitEnd(t)) revert WrongPhase();
        Job storage j = _seat(id);
        if (j.commitment != 0) revert AlreadyIn();
        if (commitment == 0) revert BadValue();
        j.commitment = commitment;
    }

    function revealTraining(uint256 id, bytes32 root, bytes32 treesHash, string calldata uri, bytes32 salt) external {
        Task storage t = _task(id);
        if (t.stage != OPEN || block.timestamp < _commitEnd(t) || block.timestamp >= _revealEnd(t)) revert WrongPhase();
        Job storage j = _seat(id);
        if (j.revealed) revert AlreadyIn();
        if (j.commitment == 0 || root == 0 || treesHash == 0 || bytes(uri).length > 256) revert BadReveal();
        if (_trainCommitment(root, treesHash, msg.sender, salt, id) != j.commitment) revert BadReveal();
        j.revealed = true;
        j.root = root;
        j.treesHash = treesHash;
        emit TrainRevealed(id, seatOf[id][msg.sender] - 1, root, treesHash, uri);
    }

    // ---------------------------------------------------------------- the draw (future block hash)

    /// Anyone, once the reveals closed: fixes the block whose hash decides the checks.
    function requestDraw(uint256 id) external {
        Task storage t = _task(id);
        if (t.stage != OPEN || block.timestamp < _revealEnd(t)) revert WrongPhase();
        if (t.drawBlock != 0 && block.number <= uint256(t.drawBlock) + 256) revert AlreadyIn();
        t.drawBlock = uint64(block.number + 1);
    }

    /// Anyone, once that block exists (within 256 blocks; else requestDraw again).
    function draw(uint256 id) external {
        Task storage t = _task(id);
        if (t.stage != OPEN || t.drawBlock == 0 || block.number <= t.drawBlock) revert WrongPhase();
        bytes32 bh = blockhash(t.drawBlock);
        if (bh == 0) revert WrongPhase();
        bytes32 rnd = keccak256(abi.encode(bh, id, address(this)));
        t.randomness = rnd;
        Job[] storage js = _jobs[id];
        uint256 revealed;
        for (uint256 j = 0; j < js.length; j++) {
            if (!js[j].revealed) {
                js[j].status = JOB_MISSED;
                pool.lock(js[j].trainer, false);
                _slash(id, js[j].trainer, _params.missSlash, MISSED);
                emit JobJudged(id, j, JOB_MISSED, _params.missSlash);
                continue;
            }
            revealed++;
            uint256 n = _params.checksPerJob;
            for (uint256 c = 0; c < n; c++) _assignCheck(id, t, rnd, j, c);
        }
        t.verifyAt = uint64(block.timestamp);
        emit Drawn(id, rnd, _checks[id].length);
        if (revealed == 0) {
            _finish(id, t);
            return;
        }
        // the evaluation is the last check (job EVAL_JOB); its evaluators are never a trainer whose result is in
        // this round
        uint256 e = _checks[id].length;
        _checks[id].push(Check(EVAL_JOB, 0, 0, 0));
        address[] storage ev = _verifiers[id][e];
        for (uint256 v = 0; v < _params.evaluators; v++) {
            address w = _pick(keccak256(abi.encode(rnd, uint256(3), e, v)), id, type(uint256).max, ev);
            if (w == address(0)) break;
            ev.push(w);
            pool.lock(w, true);
        }
        t.stage = VERIFY;
    }

    function _assignCheck(uint256 id, Task storage t, bytes32 rnd, uint256 j, uint256 c) internal {
        uint256 seg;
        for (uint256 nonce = 0; ; nonce++) {
            seg = uint256(keccak256(abi.encode(rnd, uint256(1), j, c, nonce))) % t.segments;
            bool dup;
            Check[] storage cs = _checks[id];
            for (uint256 q = cs.length; q > 0 && cs[q - 1].job == j; q--) if (cs[q - 1].segment == seg) dup = true;
            if (!dup) break;
        }
        uint256 ch = _checks[id].length;
        _checks[id].push(Check(uint8(j), uint16(seg), 0, 0));
        address[] storage vs = _verifiers[id][ch];
        for (uint256 v = 0; v < _params.verifiersPerCheck; v++) {
            address w = _pick(keccak256(abi.encode(rnd, uint256(2), ch, v)), id, j, vs);
            if (w == address(0)) break;
            vs.push(w);
            pool.lock(w, true);
        }
        emit CheckAssigned(id, ch, j, seg, vs);
    }

    /// A random eligible member not in `chosen`, not the trainer of `exceptJob` (or, for evaluators —
    /// exceptJob = max — not any trainer with a revealed job). address(0) when nobody fits.
    /// key = keccak(abi.encode(randomness, tag, a, b)); try k: pool[keccak(abi.encode(key, k)) % pool size].
    function _pick(bytes32 key, uint256 id, uint256 exceptJob, address[] storage chosen) internal view returns (address) {
        uint256 n = pool.size();
        for (uint256 nonce = 0; n > 0 && nonce < 8 * n + 8; nonce++) {
            address w = pool.members(uint256(keccak256(abi.encode(key, nonce))) % n);
            if (_fits(w, id, exceptJob) && !_assigned(chosen, w)) return w;
        }
        return address(0);
    }

    function _fits(address w, uint256 id, uint256 exceptJob) internal view returns (bool) {
        if (!pool.eligible(w)) return false;
        uint256 seat = seatOf[id][w];
        if (seat == 0) return true;
        return exceptJob == type(uint256).max ? !_jobs[id][seat - 1].revealed : seat - 1 != exceptJob;
    }

    // ---------------------------------------------------------------- spot-checks

    /// A sealed answer: a verifier's segment digest, or an evaluator's keccak(abi.encode(baseAuc, candAuc,
    /// baseRecall, candRecall)) (uint32 each, in 1/10,000) on the evaluation check.
    function _answerCommitment(bytes32 answer, address who, bytes32 salt, uint256 id, uint256 check) internal pure returns (bytes32) {
        return keccak256(abi.encode(answer, who, salt, id, check));
    }

    function commitAnswer(uint256 id, uint256 check, bytes32 commitment) external {
        Task storage t = _task(id);
        bool ev = _checks[id][check].job == EVAL_JOB;
        if (ev ? (t.stage != EVAL || block.timestamp >= _ecEnd(t)) : (t.stage != VERIFY || block.timestamp >= _vcEnd(t))) revert WrongPhase();
        if (!_assigned(_verifiers[id][check], msg.sender)) revert NotSeated();
        if (commits[id][check][msg.sender] != 0) revert AlreadyIn();
        if (commitment == 0) revert BadValue();
        commits[id][check][msg.sender] = commitment;
    }

    /// The trainer opens its per-segment digests once the verifiers are sealed.
    function openCheckpoints(uint256 id, bytes32[] calldata digests) external {
        Task storage t = _task(id);
        if (t.stage != VERIFY || block.timestamp < _vcEnd(t) || block.timestamp >= _vrEnd(t)) revert WrongPhase();
        Job storage j = _seat(id);
        uint256 job = seatOf[id][msg.sender] - 1;
        if (!j.revealed || j.opened) revert AlreadyIn();
        if (digests.length != t.segments || keccak256(abi.encodePacked(digests)) != j.root) revert BadReveal();
        j.opened = true;
        _digests[id][job] = digests;
    }

    function revealAnswer(uint256 id, uint256 check, bytes32 answer, bytes32 salt) external {
        Task storage t = _task(id);
        bool ev = _checks[id][check].job == EVAL_JOB;
        if (ev ? (t.stage != EVAL || block.timestamp < _ecEnd(t) || block.timestamp >= _erEnd(t))
               : (t.stage != VERIFY || block.timestamp < _vcEnd(t) || block.timestamp >= _vrEnd(t))) revert WrongPhase();
        bytes32 c = commits[id][check][msg.sender];
        if (c == 0) revert NotSeated();
        if (answers[id][check][msg.sender] != 0) revert AlreadyIn();
        if (answer == 0 || _answerCommitment(answer, msg.sender, salt, id, check) != c) revert BadReveal();
        answers[id][check][msg.sender] = answer;
        emit Answered(id, check, msg.sender, answer);
    }

    /// The poster opens its held-out secret (any time after the draw, before judging).
    function revealHeldout(uint256 id, bytes32 secret) external {
        Task storage t = _task(id);
        if (t.stage != VERIFY || t.heldoutRevealed) revert WrongPhase();
        if (msg.sender != t.poster || keccak256(abi.encode(secret, msg.sender)) != t.heldoutCommit) revert BadReveal();
        t.heldoutRevealed = true;
        t.heldoutSeed = keccak256(abi.encode(secret, t.randomness));
        emit HeldoutRevealed(id, t.heldoutSeed);
    }

    /// Anyone, after the verify window: decides every check and job, pays the verifiers, fixes the candidate.
    function judge(uint256 id) external {
        Task storage t = _task(id);
        if (t.stage != VERIFY || block.timestamp < _vrEnd(t)) revert WrongPhase();
        uint256 units;
        uint256 e = _checks[id].length - 1; // the evaluation check
        for (uint256 c = 0; c < e; c++) units += _judgeCheck(id, c);
        if (units > 0) _payChecks(id, t, ((uint256(t.budget) * _params.checkBps) / 10_000) / units);
        _judgeJobs(id, t);
        if (!t.heldoutRevealed) t.heldoutSeed = keccak256(abi.encode(bytes32(0), t.randomness));
        t.evalAt = uint64(block.timestamp);
        emit Judged(id, t.passed, t.candidate, t.heldoutSeed);
        if (t.passed == 0) {
            address[] storage ev = _verifiers[id][e];
            for (uint256 v = 0; v < ev.length; v++) pool.lock(ev[v], false);
            _finish(id, t);
        } else {
            t.stage = EVAL;
        }
    }

    /// The check pool, split among every verifier answer in a majority.
    function _payChecks(uint256 id, Task storage t, uint256 each) internal {
        Check[] storage cs = _checks[id];
        for (uint256 c = 0; c < cs.length; c++) {
            if (cs[c].status == 3 || cs[c].job == EVAL_JOB) continue;
            address[] storage vs = _verifiers[id][c];
            for (uint256 v = 0; v < vs.length; v++) if (answers[id][c][vs[v]] == cs[c].majority) _pay(id, t, vs[v], each, 1);
        }
    }

    /// A job passes when every check of it passed; one failed check fails it (and slashes its trainer).
    function _judgeJobs(uint256 id, Task storage t) internal {
        Job[] storage js = _jobs[id];
        bytes memory cand = abi.encodePacked(t.baseModel);
        uint8 passed;
        for (uint256 j = 0; j < js.length; j++) {
            if (js[j].status == JOB_MISSED) continue;
            uint8 st = _jobStatus(id, j);
            js[j].status = st;
            pool.lock(js[j].trainer, false);
            uint256 slashed;
            if (st == JOB_FAILED) slashed = _slashTrainer(id, j);
            else if (st == JOB_PASSED) {
                passed++;
                cand = abi.encodePacked(cand, js[j].treesHash);
            }
            emit JobJudged(id, j, st, slashed);
        }
        t.passed = passed;
        t.candidate = passed > 0 ? keccak256(cand) : bytes32(0);
    }

    function _jobStatus(uint256 id, uint256 j) internal view returns (uint8 st) {
        Check[] storage cs = _checks[id];
        st = JOB_PASSED;
        for (uint256 c = 0; c < cs.length; c++) {
            if (cs[c].job != j) continue;
            if (cs[c].status == 2) return JOB_FAILED;
            if (cs[c].status == 3) st = JOB_INCONCLUSIVE;
        }
    }

    /// Decides one check; returns how many verifier answers are in its majority (0 if none).
    function _judgeCheck(uint256 id, uint256 c) internal returns (uint256 agreed) {
        Check storage ck = _checks[id][c];
        address[] storage vs = _verifiers[id][c];
        bytes32 maj;
        uint256 quorum = vs.length / 2 + 1;
        for (uint256 v = 0; v < vs.length && maj == 0; v++) {
            bytes32 a = answers[id][c][vs[v]];
            if (a == 0) continue;
            uint256 n;
            for (uint256 q = 0; q < vs.length; q++) if (answers[id][c][vs[q]] == a) n++;
            if (n >= quorum) maj = a;
        }
        bytes32 claimed;
        if (ck.job != EVAL_JOB && _jobs[id][ck.job].opened) claimed = _digests[id][ck.job][ck.segment];
        ck.majority = maj;
        ck.status = maj == 0 ? 3 : (maj == claimed || ck.job == EVAL_JOB ? 1 : 2);
        for (uint256 v = 0; v < vs.length; v++) {
            address w = vs[v];
            pool.lock(w, false);
            bytes32 a = answers[id][c][w];
            if (a == 0) _slash(id, w, _params.missSlash, MISSED);
            else if (maj == 0) continue;
            else if (a == maj) {
                agreed++;
                _rep(w, AGREED, id);
            } else _slash(id, w, _params.missSlash, DISAGREED);
        }
        emit CheckJudged(id, c, ck.status, maj, claimed);
    }

    /// Slashes a trainer whose checkpoint failed; catchBps of it goes to the verifiers who caught it.
    function _slashTrainer(uint256 id, uint256 job) internal returns (uint256 slashed) {
        address tr = _jobs[id][job].trainer;
        slashed = pool.slash(tr, _params.trainSlash); // arrives through receive(): in the reserve
        emit Slashed(id, tr, slashed, SLASHED);
        _rep(tr, SLASHED, id);
        uint256 bounty = (slashed * _params.catchBps) / 10_000;
        Check[] storage cs = _checks[id];
        uint256 catchers;
        for (uint256 c = 0; c < cs.length; c++) {
            if (cs[c].job == job && cs[c].status == 2) {
                address[] storage vs = _verifiers[id][c];
                for (uint256 v = 0; v < vs.length; v++) if (answers[id][c][vs[v]] == cs[c].majority) catchers++;
            }
        }
        uint256 each = catchers > 0 ? bounty / catchers : 0;
        uint256 given;
        for (uint256 c = 0; c < cs.length && each > 0; c++) {
            if (cs[c].job == job && cs[c].status == 2) {
                address[] storage vs = _verifiers[id][c];
                for (uint256 v = 0; v < vs.length; v++) {
                    if (answers[id][c][vs[v]] == cs[c].majority) {
                        _credit(vs[v], each);
                        given += each;
                        emit Paid(id, vs[v], each, 3);
                    }
                }
            }
        }
        reserve -= given;
    }

    // ---------------------------------------------------------------- evaluation

    /// Anyone, after the evaluation window, with the numbers the evaluators' majority revealed (ignored when
    /// there is no majority): accepts or rejects the candidate and pays.
    function finalize(uint256 id, uint32[4] calldata r) external {
        Task storage t = _task(id);
        if (t.stage != EVAL || block.timestamp < _erEnd(t)) revert WrongPhase();
        uint256 e = _checks[id].length - 1;
        uint256 agreed = _judgeCheck(id, e);
        bytes32 maj = _checks[id][e].majority;
        if (maj != 0) {
            if (keccak256(abi.encode(r)) != maj) revert BadReveal();
            (t.baseAuc, t.candAuc, t.baseRecall, t.candRecall) = (r[0], r[1], r[2], r[3]);
            uint256 each = ((uint256(t.budget) * _params.evalBps) / 10_000) / agreed;
            address[] storage ev = _verifiers[id][e];
            for (uint256 v = 0; v < ev.length; v++) if (answers[id][e][ev[v]] == maj) _pay(id, t, ev[v], each, 2);
            t.accepted = uint256(r[1]) >= uint256(r[0]) + _params.minGainAuc && r[3] >= r[2];
        }
        if (t.accepted) _payTrainers(id, t);
        _finish(id, t);
    }

    function _payTrainers(uint256 id, Task storage t) internal {
        uint256 subsidy = t.subsidy > 0 ? _subsidy(t.subsidy) : 0;
        uint256 fromBudget = (uint256(t.budget) * _params.trainBps) / 10_000;
        uint256 each = fromBudget / t.passed;
        uint256 subEach = subsidy / t.passed;
        reserve += subsidy - subEach * t.passed;
        Job[] storage js = _jobs[id];
        for (uint256 j = 0; j < js.length; j++) {
            if (js[j].status != JOB_PASSED) continue;
            _pay(id, t, js[j].trainer, each, 0);
            if (subEach > 0) {
                _credit(js[j].trainer, subEach);
                emit Paid(id, js[j].trainer, subEach, 0);
            }
            _rep(js[j].trainer, AGREED, id);
        }
        acceptedBy[t.candidate] = id + 1;
        emit ModelAccepted(id, t.candidate, t.baseModel);
    }

    /// Ends a task: what the budget did not pay goes back to the poster (to the reserve if it never opened its
    /// held-out secret: withholding it to choose between two seeds costs the whole refund).
    function _finish(uint256 id, Task storage t) internal {
        t.stage = DONE;
        uint256 refund = uint256(t.budget) - t.spent;
        escrow -= t.budget;
        if (t.heldoutRevealed || t.randomness == 0 || t.passed == 0) _credit(t.poster, refund);
        else reserve += refund;
        emit Finalized(id, t.accepted, t.candidate, refund);
    }

    // ---------------------------------------------------------------- money

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        totalOwed -= a;
        _send(msg.sender, a);
        emit Withdrawn(msg.sender, a);
    }

    function _pay(uint256 id, Task storage t, address to, uint256 amount, uint8 role) internal {
        if (amount == 0) return;
        t.spent += uint128(amount);
        _credit(to, amount);
        emit Paid(id, to, amount, role);
    }

    function _credit(address to, uint256 amount) internal {
        owed[to] += amount;
        totalOwed += amount;
    }

    function _slash(uint256 id, address w, uint256 amount, uint8 kind) internal {
        uint256 got = pool.slash(w, amount); // arrives through receive(): in the reserve
        emit Slashed(id, w, got, kind);
        _rep(w, kind, id);
    }

    function _rep(address w, uint8 kind, uint256 id) internal {
        if (address(reputation) == address(0)) return;
        try reputation.record(w, kind, bytes32(id)) {} catch {}
    }

    /// Takes up to `want` from the reserve, then from UsefulIssuance.
    function _subsidy(uint256 want) internal returns (uint256 got) {
        got = want < reserve ? want : reserve;
        reserve -= got;
        if (got < want && address(issuance) != address(0)) {
            uint256 before = address(this).balance;
            try issuance.draw(want - got) returns (uint256) {} catch {}
            uint256 arrived = address(this).balance - before;
            reserve -= arrived; // receive() counted it into the reserve
            got += arrived;
        }
    }

    function _send(address to, uint256 amount) internal {
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert Nothing();
    }

    // ---------------------------------------------------------------- governance (a timelock)

    function setParams(Params calldata p) external onlyGovernance {
        _setParams(p);
    }

    function setFeeder(address f, bool on) external onlyGovernance {
        feeders[f] = on;
        emit FeederSet(f, on);
    }

    function setPaused(bool p) external onlyGovernance {
        paused = p;
        emit PausedSet(p);
    }

    /// The next governance must also be a timelock with at least MIN_DELAY.
    function setGovernance(address next) external onlyGovernance {
        _checkTimelock(next);
        governance = next;
        emit GovernanceSet(next);
    }

    function _setParams(Params memory p) internal {

        if (p.checksPerJob == 0 || p.checksPerJob > 4 || p.verifiersPerCheck == 0 || p.verifiersPerCheck > 5) revert BadParams();
        if (p.evaluators == 0 || p.evaluators > 7) revert BadParams();
        if (uint256(p.trainBps) + p.checkBps + p.evalBps > 10_000 || p.catchBps > 10_000) revert BadParams();
        uint256 life = uint256(p.seatWindow) + p.commitWindow + p.revealWindow + p.verifyCommitWindow + p.verifyRevealWindow + p.evalCommitWindow + p.evalRevealWindow;
        if (p.seatWindow == 0 || p.commitWindow == 0 || p.revealWindow == 0 || p.verifyCommitWindow == 0 || p.verifyRevealWindow == 0) revert BadParams();
        if (p.evalCommitWindow == 0 || p.evalRevealWindow == 0 || pool.exitDelay() < life) revert BadParams();
        _params = p;
        emit ParamsSet();
    }

    function _checkTimelock(address t) internal view {
        if (t.code.length == 0) revert NotTimelock();
        try ITMMinDelay(t).getMinDelay() returns (uint256 d) {
            if (d < MIN_DELAY) revert NotTimelock();
        } catch {
            revert NotTimelock();
        }
    }

    // ---------------------------------------------------------------- reads

    function params() external view returns (Params memory) {
        return _params;
    }

    function taskCount() external view returns (uint256) {
        return _tasks.length;
    }

    function getTask(uint256 id) external view returns (Task memory) {
        return _task(id);
    }

    function getJob(uint256 id, uint256 job) external view returns (Job memory) {
        return _jobs[id][job];
    }

    function checksOf(uint256 id) external view returns (Check[] memory) {
        return _checks[id];
    }

    function verifiersOf(uint256 id, uint256 check) external view returns (address[] memory) {
        return _verifiers[id][check];
    }

    function digestsOf(uint256 id, uint256 job) external view returns (bytes32[] memory) {
        return _digests[id][job];
    }

    // ---------------------------------------------------------------- internals

    function _task(uint256 id) internal view returns (Task storage) {
        if (id >= _tasks.length) revert BadTask();
        return _tasks[id];
    }

    function _seat(uint256 id) internal view returns (Job storage) {
        uint256 s = seatOf[id][msg.sender];
        if (s == 0) revert NotSeated();
        return _jobs[id][s - 1];
    }

    function _assigned(address[] storage list, address w) internal view returns (bool) {
        for (uint256 i = 0; i < list.length; i++) if (list[i] == w) return true;
        return false;
    }

    function _seatEnd(Task storage t) internal view returns (uint256) {
        return uint256(t.postedAt) + _params.seatWindow;
    }

    function _commitEnd(Task storage t) internal view returns (uint256) {
        return _seatEnd(t) + _params.commitWindow;
    }

    function _revealEnd(Task storage t) internal view returns (uint256) {
        return _commitEnd(t) + _params.revealWindow;
    }

    function _vcEnd(Task storage t) internal view returns (uint256) {
        return uint256(t.verifyAt) + _params.verifyCommitWindow;
    }

    function _vrEnd(Task storage t) internal view returns (uint256) {
        return _vcEnd(t) + _params.verifyRevealWindow;
    }

    function _ecEnd(Task storage t) internal view returns (uint256) {
        return uint256(t.evalAt) + _params.evalCommitWindow;
    }

    function _erEnd(Task storage t) internal view returns (uint256) {
        return _ecEnd(t) + _params.evalRevealWindow;
    }
}

contracts/TrainingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ITPMinDelay {
    function getMinDelay() external view returns (uint256);
}

/// @title TrainingPool: the staked workers of the training market (testnet)
/// @notice Workers that train, spot-check and evaluate Neuro's model (TrainingMarket,
///         docs/future/useful-work-training.md) stake here first. The stake is what a fake checkpoint or a
///         wrong / missing answer costs: a market that governance names (`markets`) may lock a member while
///         it holds a seat or an assignment (`busy`) and slash it (the slashed coins go to that market).
///         A member who leaves stops being drawn at once and gets its stake back after `exitDelay`, once
///         nothing is locked (longer than a whole task, so a cheater cannot leave before it is judged).
///         No admin key: governance must be a timelock with at least MIN_DELAY.
contract TrainingPool {
    uint256 public constant MIN_DELAY = 2 days;

    struct Member {
        uint128 stake;
        uint64 exitAt;
        uint32 busy;
        uint32 index; // position in `members` + 1 (0: not in the pool)
    }

    address public governance;
    uint128 public minStake;
    uint32 public exitDelay;
    uint256 public totalStake;
    mapping(address => bool) public markets;
    mapping(address => Member) public memberOf;
    address[] public members;

    event Joined(address indexed member, uint256 stake);
    event Exiting(address indexed member, uint64 at);
    event Withdrawn(address indexed member, uint256 amount);
    event Slashed(address indexed member, address indexed market, uint256 amount);
    event MarketSet(address indexed market, bool on);
    event ParamsSet(uint128 minStake, uint32 exitDelay);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotMarket();
    error NotTimelock();
    error BadValue();
    error WrongPhase();
    error Busy();

    constructor(address governance_, uint128 minStake_, uint32 exitDelay_) {
        _checkTimelock(governance_);
        governance = governance_;
        _setParams(minStake_, exitDelay_);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    modifier onlyMarket() {
        if (!markets[msg.sender]) revert NotMarket();
        _;
    }

    // ---------------------------------------------------------------- members

    /// Stakes (or adds stake); a member who was leaving is back in the draw.
    function join() external payable {
        Member storage m = memberOf[msg.sender];
        m.stake += uint128(msg.value);
        totalStake += msg.value;
        if (m.stake < minStake) revert BadValue();
        m.exitAt = 0;
        if (m.index == 0) {
            members.push(msg.sender);
            m.index = uint32(members.length);
        }
        emit Joined(msg.sender, m.stake);
    }

    /// Leaves the draw now; the stake comes back after exitDelay (it can still be slashed until then).
    function exit() external {
        Member storage m = memberOf[msg.sender];
        if (m.index == 0 || m.exitAt != 0) revert WrongPhase();
        m.exitAt = uint64(block.timestamp + exitDelay);
        emit Exiting(msg.sender, m.exitAt);
    }

    function withdrawStake() external {
        Member storage m = memberOf[msg.sender];
        if (m.exitAt == 0 || block.timestamp < m.exitAt) revert WrongPhase();
        if (m.busy != 0) revert Busy();
        uint256 amount = m.stake;
        m.stake = 0;
        m.exitAt = 0;
        totalStake -= amount;
        uint256 i = m.index - 1;
        address last = members[members.length - 1];
        members[i] = last;
        memberOf[last].index = uint32(i + 1);
        members.pop();
        m.index = 0;
        (bool ok, ) = msg.sender.call{value: amount}("");
        if (!ok) revert BadValue();
        emit Withdrawn(msg.sender, amount);
    }

    /// In the draw: staked at least minStake and not leaving.
    function eligible(address w) external view returns (bool) {
        Member storage m = memberOf[w];
        return m.index != 0 && m.exitAt == 0 && m.stake >= minStake;
    }

    function size() external view returns (uint256) {
        return members.length;
    }

    // ---------------------------------------------------------------- markets

    /// Locks (+1) or releases (-1) a member while a market holds a seat or an assignment of it.
    function lock(address w, bool on) external onlyMarket {
        if (on) memberOf[w].busy++;
        else memberOf[w].busy--;
    }

    /// Takes up to `amount` of a member's stake (what is there) and sends it to the calling market.
    function slash(address w, uint256 amount) external onlyMarket returns (uint256 got) {
        Member storage m = memberOf[w];
        got = amount < m.stake ? amount : m.stake;
        if (got == 0) return 0;
        m.stake -= uint128(got);
        totalStake -= got;
        emit Slashed(w, msg.sender, got);
        (bool ok, ) = msg.sender.call{value: got}("");
        if (!ok) revert NotMarket();
    }

    // ---------------------------------------------------------------- governance (a timelock)

    function setMarket(address market, bool on) external onlyGovernance {
        markets[market] = on;
        emit MarketSet(market, on);
    }

    function setParams(uint128 minStake_, uint32 exitDelay_) external onlyGovernance {
        _setParams(minStake_, exitDelay_);
    }

    function setGovernance(address next) external onlyGovernance {
        _checkTimelock(next);
        governance = next;
        emit GovernanceSet(next);
    }

    function _setParams(uint128 minStake_, uint32 exitDelay_) internal {
        if (minStake_ == 0 || exitDelay_ == 0) revert BadValue();
        minStake = minStake_;
        exitDelay = exitDelay_;
        emit ParamsSet(minStake_, exitDelay_);
    }

    function _checkTimelock(address t) internal view {
        if (t.code.length == 0) revert NotTimelock();
        try ITPMinDelay(t).getMinDelay() returns (uint256 d) {
            if (d < MIN_DELAY) revert NotTimelock();
        } catch {
            revert NotTimelock();
        }
    }
}

contracts/TwapRecorder.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The Uniswap-V2 pair surface (ZetaphyPair) the recorder reads.
interface ITwapPair {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function price0CumulativeLast() external view returns (uint256);
    function price1CumulativeLast() external view returns (uint256);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

/// @title TwapRecorder: observations of DEX pairs' cumulative prices, for TWAPs
/// @notice A Uniswap-V2 pair (ZetaphyPair) keeps price0/price1CumulativeLast:
///         the running sum of its price times the seconds it held, updated at
///         the FIRST trade of a block with the reserves from before it. A TWAP
///         over [t0, t1] is (cumulative(t1) - cumulative(t0)) / (t1 - t0); it
///         needs cumulative(t0) remembered, which is what this contract does.
///         No owner, no settings after deployment. Anyone (a keeper, the relay,
///         a user) may call record(pair):
///           - at most one observation per pair every `minSpacing` seconds and
///             never two in one block, so pokes cannot flood the ring;
///           - an observation is the cumulative price as of now, counted with
///             the reserves from before this block's first trade (the pair's
///             own rule), so a swap in the same transaction or block as the
///             record (or as the read) adds nothing to the average;
///           - it also keeps sqrt(reserve0 * reserve1) (pool depth that swaps
///             cannot lower), so a reader can require depth at every observation
///             of its window, not only at the moment it reads.
///         consult() returns the window's average and what a reader needs to
///         judge it (oldest time, observation count, smallest depth, the
///         largest gap of one segment's average from the window's average).
contract TwapRecorder {
    struct Observation {
        uint64 time;
        uint128 depth;   // sqrt(reserve0 * reserve1), raw units
        uint256 cum0;    // price0Cumulative (UQ112x112 seconds), wraps by design
        uint256 cum1;
    }

    uint16 public constant CAPACITY = 96;
    uint32 public immutable minSpacing;

    mapping(address => Observation[CAPACITY]) private _obs;
    mapping(address => uint16) public nextIndex;
    mapping(address => uint16) public count;

    event Observed(address indexed pair, uint64 time, uint256 cum0, uint256 cum1, uint128 depth);

    error NotEnoughHistory();
    error EmptyPool();

    constructor(uint32 minSpacing_) {
        require(minSpacing_ >= 1, "spacing");
        minSpacing = minSpacing_;
    }

    /// Records an observation if minSpacing has passed since the last one. Returns whether it did.
    function record(address pair) external returns (bool) {
        uint16 n = count[pair];
        if (n != 0) {
            Observation storage last = _obs[pair][(nextIndex[pair] + CAPACITY - 1) % CAPACITY];
            if (block.timestamp < uint256(last.time) + minSpacing) return false;
        }
        (uint256 c0, uint256 c1, uint128 d) = current(pair);
        if (d == 0) revert EmptyPool();
        uint16 i = nextIndex[pair];
        _obs[pair][i] = Observation(uint64(block.timestamp), d, c0, c1);
        nextIndex[pair] = (i + 1) % CAPACITY;
        if (n < CAPACITY) count[pair] = n + 1;
        emit Observed(pair, uint64(block.timestamp), c0, c1, d);
        return true;
    }

    /// The pair's cumulative prices as of now (Uniswap's currentCumulativePrices) and its depth.
    function current(address pair) public view returns (uint256 c0, uint256 c1, uint128 depth) {
        c0 = ITwapPair(pair).price0CumulativeLast();
        c1 = ITwapPair(pair).price1CumulativeLast();
        (uint112 r0, uint112 r1, uint32 last) = ITwapPair(pair).getReserves();
        uint32 nowTs = uint32(block.timestamp);
        if (last != nowTs && r0 != 0 && r1 != 0) {
            unchecked {
                uint32 elapsed = nowTs - last; // wraps, as in the pair
                c0 += ((uint256(r1) << 112) / r0) * elapsed;
                c1 += ((uint256(r0) << 112) / r1) * elapsed;
            }
        }
        depth = uint128(_sqrt(uint256(r0) * uint256(r1)));
    }

    /// The i-th newest observation (0 = newest).
    function observation(address pair, uint16 i) public view returns (Observation memory) {
        require(i < count[pair], "index");
        return _obs[pair][(nextIndex[pair] + CAPACITY - 1 - i) % CAPACITY];
    }

    struct Twap {
        uint256 avg0;          // UQ112x112: token1 per token0 (raw units), over [from, now]
        uint256 avg1;          // token0 per token1
        uint64 from;           // the observation the window starts at (at least `window` old)
        uint64 newest;         // the newest observation's time
        uint16 observations;   // observations in [from, now], `from` included
        uint128 minDepth;      // smallest depth at those observations and now
        uint256 maxSegmentGapBps; // largest |segment average - window average| / window average of avg0, in bps
    }

    /// The average over the newest observation that is at least `window` seconds old up to now.
    /// Reverts NotEnoughHistory if there is none.
    function consult(address pair, uint32 window) external view returns (Twap memory t) {
        uint16 n = count[pair];
        uint256 nowTs = block.timestamp;
        // newest first: find the first one at least `window` old
        uint16 k = type(uint16).max;
        for (uint16 i = 0; i < n; i++) {
            if (nowTs >= uint256(observation(pair, i).time) + window) { k = i; break; }
        }
        if (k == type(uint16).max) revert NotEnoughHistory();
        Observation memory start = observation(pair, k);
        (uint256 c0, uint256 c1, uint128 d) = current(pair);
        uint256 span = nowTs - start.time;
        if (span == 0) revert NotEnoughHistory();
        unchecked {
            t.avg0 = (c0 - start.cum0) / span;
            t.avg1 = (c1 - start.cum1) / span;
        }
        t.from = start.time;
        t.newest = n == 0 ? 0 : observation(pair, 0).time;
        t.observations = k + 1;
        (t.minDepth, t.maxSegmentGapBps) = _segments(pair, k, start, Observation(uint64(nowTs), d, c0, c1), t.avg0);
    }

    /// Walks start -> ... -> newest -> now: the smallest depth, and the largest gap of a
    /// segment's average (avg0) from the window's average, in bps.
    function _segments(address pair, uint16 k, Observation memory prev, Observation memory last, uint256 avg)
        private view returns (uint128 minDepth, uint256 maxGapBps)
    {
        minDepth = prev.depth < last.depth ? prev.depth : last.depth;
        for (uint16 j = k + 1; j > 0; j--) {
            Observation memory o = j == 1 ? last : observation(pair, j - 2);
            if (o.depth < minDepth) minDepth = o.depth;
            uint256 dt = uint256(o.time) - prev.time;
            if (dt != 0 && avg != 0) {
                uint256 seg;
                unchecked { seg = (o.cum0 - prev.cum0) / dt; }
                uint256 bps = _mulDiv(seg > avg ? seg - avg : avg - seg, 10_000, avg);
                if (bps > maxGapBps) maxGapBps = bps;
            }
            prev = o;
        }
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        z = x;
        uint256 y = x / 2 + 1;
        while (y < z) { z = y; y = (x / y + y) / 2; }
    }

    /// floor(a * b / d) with a 512-bit product (Remco Bloemen's mulDiv, MIT).
    function _mulDiv(uint256 a, uint256 b, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) return prod0 / d;
            require(d > prod1, "mulDiv");
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }
            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            result = prod0 * inv;
        }
    }
}

contracts/UsefulIssuance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// A timelock (ZetaphyTimelock = OpenZeppelin TimelockController) reports its delay.
interface IMinDelay {
    function getMinDelay() external view returns (uint256);
}

/// @title UsefulIssuance: a share of new rewards goes to verified useful work
/// @notice "Security-backed issuance", testnet. It mints NOTHING: it is a RewardVault
///         recipient (`fund()`), so the share of new rewards it receives is set where every
///         other share is (RewardVault.proposeShares: governance + the vault's own 7-day delay).
///         What arrives is split into buckets, one per kind of verified work:
///           - each bucket names a sink contract (UsefulWork scan jobs, BugBounty, a future
///             model-evaluation market) and a share in basis points;
///           - a sink can only PULL (`draw`) what its bucket has accrued, and only when it pays
///             for work its own rules verified (agreement of independent workers, a runner
///             quorum on a bug). Nothing is pushed, so unverified work is never paid;
///           - each bucket has a cap. What would accrue beyond it, and the share no bucket
///             takes (10,000 - sum of bps), goes to `overflow` (e.g. the PoW faucet account
///             or the validators), so rewards are not hoarded when there is little useful work.
///         Every parameter (buckets, caps, overflow, governance itself) is set by `governance`,
///         which must be a timelock whose minimum delay is at least MIN_DELAY: changes are
///         public before they apply. There is no withdraw and no mint.
contract UsefulIssuance {
    uint256 public constant MIN_DELAY = 2 days;
    uint256 public constant MAX_BUCKETS = 6;

    struct Bucket {
        address sink;    // the market that pays verified work (calls draw)
        uint16 bps;      // share of each arrival, out of 10,000
        uint128 cap;     // most this bucket may hold unspent; the rest goes to overflow
        uint128 accrued; // received and not yet drawn
    }

    address public governance;
    address public overflow;
    uint256 public pendingOverflow;
    Bucket[] private _buckets;

    event Funded(address indexed from, uint256 amount);
    event Drawn(address indexed sink, uint256 amount);
    event OverflowPaid(address indexed to, uint256 amount, bool ok);
    event BucketsSet(uint256 count);
    event OverflowSet(address overflow);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotSink();
    error BadBuckets();
    error NotTimelock();
    error ZeroAddress();

    constructor(address governance_, address overflow_) {
        _checkTimelock(governance_);
        if (overflow_ == address(0)) revert ZeroAddress();
        governance = governance_;
        overflow = overflow_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---------------------------------------------------------------- money in

    /// RewardVault pays here (Share.callFund = true); anyone may add more.
    function fund() public payable {
        uint256 amount = msg.value;
        if (amount == 0) return;
        uint256 left = amount;
        for (uint256 i = 0; i < _buckets.length; i++) {
            Bucket storage b = _buckets[i];
            uint256 part = (amount * b.bps) / 10_000;
            left -= part;
            uint256 room = b.cap > b.accrued ? b.cap - b.accrued : 0;
            uint256 keep = part < room ? part : room;
            b.accrued += uint128(keep);
            pendingOverflow += part - keep;
        }
        pendingOverflow += left;
        emit Funded(msg.sender, amount);
    }

    receive() external payable {
        fund();
    }

    // ---------------------------------------------------------------- money out

    /// A sink takes up to `amount` of its bucket to pay work it verified. Returns what it got.
    function draw(uint256 amount) external returns (uint256 paid) {
        uint256 i = _indexOf(msg.sender);
        Bucket storage b = _buckets[i];
        paid = amount < b.accrued ? amount : b.accrued;
        if (paid == 0) return 0;
        b.accrued -= uint128(paid);
        emit Drawn(msg.sender, paid);
        (bool ok, ) = msg.sender.call{value: paid}("");
        if (!ok) revert NotSink(); // a sink that cannot receive is misconfigured: undo
    }

    /// What a sink could draw now.
    function available(address sink) external view returns (uint256) {
        for (uint256 i = 0; i < _buckets.length; i++) if (_buckets[i].sink == sink) return _buckets[i].accrued;
        return 0;
    }

    /// Anyone: pays the overflow out. A recipient that refuses keeps nothing (it stays pending).
    function sweepOverflow() external returns (uint256 amount) {
        amount = pendingOverflow;
        if (amount == 0) return 0;
        pendingOverflow = 0;
        (bool ok, ) = overflow.call{value: amount}("");
        if (!ok) pendingOverflow = amount;
        emit OverflowPaid(overflow, ok ? amount : 0, ok);
    }

    // ---------------------------------------------------------------- governance (timelocked)

    function buckets() external view returns (Bucket[] memory) {
        return _buckets;
    }

    /// Replaces the bucket list. Unspent money of a sink that stays keeps its balance (capped
    /// by the new cap, the excess to overflow); a removed sink's unspent money goes to overflow.
    function setBuckets(Bucket[] calldata next) external onlyGovernance {
        if (next.length > MAX_BUCKETS) revert BadBuckets();
        uint256 total;
        for (uint256 i = 0; i < next.length; i++) {
            if (next[i].sink == address(0) || next[i].bps == 0) revert BadBuckets();
            for (uint256 k = 0; k < i; k++) if (next[k].sink == next[i].sink) revert BadBuckets();
            total += next[i].bps;
        }
        if (total > 10_000) revert BadBuckets();
        uint256 free;
        uint128[] memory carry = new uint128[](next.length);
        for (uint256 i = 0; i < _buckets.length; i++) {
            Bucket memory old = _buckets[i];
            bool kept;
            for (uint256 k = 0; k < next.length; k++) {
                if (next[k].sink == old.sink) {
                    uint128 c = old.accrued < next[k].cap ? old.accrued : next[k].cap;
                    carry[k] = c;
                    free += old.accrued - c;
                    kept = true;
                }
            }
            if (!kept) free += old.accrued;
        }
        delete _buckets;
        for (uint256 i = 0; i < next.length; i++) {
            _buckets.push(Bucket(next[i].sink, next[i].bps, next[i].cap, carry[i]));
        }
        pendingOverflow += free;
        emit BucketsSet(next.length);
    }

    function setOverflow(address next) external onlyGovernance {
        if (next == address(0)) revert ZeroAddress();
        overflow = next;
        emit OverflowSet(next);
    }

    /// The next governance must also be a timelock with at least MIN_DELAY.
    function setGovernance(address next) external onlyGovernance {
        _checkTimelock(next);
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---------------------------------------------------------------- internals

    function _indexOf(address sink) internal view returns (uint256) {
        for (uint256 i = 0; i < _buckets.length; i++) if (_buckets[i].sink == sink) return i;
        revert NotSink();
    }

    function _checkTimelock(address t) internal view {
        if (t.code.length == 0) revert NotTimelock();
        try IMinDelay(t).getMinDelay() returns (uint256 d) {
            if (d < MIN_DELAY) revert NotTimelock();
        } catch {
            revert NotTimelock();
        }
    }
}

contracts/UsefulWork.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IUWReputation {
    function scoreOf(address worker) external view returns (uint256);
    function record(address worker, uint8 kind, bytes32 ref) external;
}

interface IUWIssuance {
    function draw(uint256 amount) external returns (uint256 paid);
}

/// @title UsefulWork: proof of useful work for browsers (Neuro scan jobs)
/// @notice Small Neuro jobs that a web browser can do: a rules scan of one contract's
///         bytecode (zetaphy-neuro's reader in a Web Worker, sourcify and trade simulation
///         off, so the verdict depends only on the code). Unlike NeuroJobs it needs no
///         100 ZETAPHY bond; instead:
///           - Sybil cost: a worker first posts a PoW STAMP (`stamp`): sha256 over the chain
///             id, a recent block's seed, its own address and a nonce must start with
///             `stampBits` zero bits (the same puzzle as the PoW faucet, under another seed
///             so a faucet proof is not a stamp). A stamp buys `stampSeats` seats for
///             `stampLife` seconds, at most `seatsPerDay` a day per address.
///           - Each seat takes a small deposit (`seatDeposit`), returned when the worker's
///             answer is accepted, kept (into the subsidy reserve) when it is not.
///           - Redundancy: every job has `seats` (2..5) independent seats and pays only
///             answers that at least `quorum` seats agree on. Answers are commit-reveal
///             (keccak(verdict, worker, salt, jobId)), so nobody can copy another's answer.
///           - Canaries: a feeder (an address governance trusts to post jobs, e.g. the Neuro
///             watch-list Action) can post a known-answer job with a hidden commitment to the
///             right verdict. After the commits close it reveals it; seats that answered
///             otherwise are slashed even when they agreed with each other.
///           - Reputation (WorkerReputation): every settled seat is recorded. A job may ask
///             a minimum score (`minScore`), and during the first `priorityWindow` seconds
///             only workers with at least `priorityScore` may take seats, so important
///             jobs go to proven workers first.
///         Rewards: the poster's fee is split among the agreeing seats; feeder jobs marked
///         `subsidized` also pay `subsidy` per agreeing seat, from the forfeited deposits
///         and then from UsefulIssuance (a RewardVault share). No new minting.
///         Results are signed by being transactions of the worker's own key; the accepted
///         verdict is on-chain (`getJob(id).result`).
contract UsefulWork {
    // WorkerReputation.Kind
    uint8 internal constant AGREED = 0;
    uint8 internal constant DISAGREED = 1;
    uint8 internal constant MISSED = 2;
    uint8 internal constant SLASHED = 3;

    struct Params {
        uint8 stampBits;        // leading zero bits a stamp needs (8..48)
        uint16 stampSeats;      // seats one stamp buys
        uint32 stampLife;       // seconds a stamp's seats stay usable
        uint16 seatsPerDay;     // most seats one address takes per UTC day
        uint8 seats;            // seats per job (2..5)
        uint8 quorum;           // agreeing seats needed (> seats/2)
        uint32 commitWindow;    // seconds seats can be taken
        uint32 revealWindow;    // seconds to reveal after the commits close
        uint128 seatDeposit;    // per seat, returned on an accepted answer
        uint128 subsidy;        // per agreeing seat of a subsidized job
        uint16 priorityScore;   // score needed during the priority window (0 = none)
        uint32 priorityWindow;  // seconds after posting reserved for proven workers
    }

    struct Job {
        address poster;
        uint64 createdAt;
        uint64 closedAt;        // when the seats filled (0: closes at createdAt + commitWindow)
        uint32 commitWindow;
        uint32 revealWindow;
        uint8 seats;
        uint8 quorum;
        uint8 taken;
        uint8 revealed;
        bool subsidized;
        bool settled;
        bool canaryRevealed;
        uint16 minScore;
        uint128 fee;
        uint128 deposit;
        bytes32 chain;          // Neuro chain key, e.g. "zetaphy", "bsc"
        bytes32 codeHash;       // keccak256 of the runtime bytecode the poster saw
        bytes32 canary;         // keccak(verdict, salt, jobId) of the known answer, or 0
        bytes32 canaryVerdict;
        bytes32 result;         // the accepted verdict (0 = none)
        string target;          // the contract address on that chain
    }

    struct Credit {
        uint32 seats;
        uint64 until;
    }

    address public governance;
    IUWReputation public reputation;
    IUWIssuance public issuance;
    Params public params;
    uint256 public reserve;              // forfeited deposits + fund(): pays subsidies first
    mapping(address => bool) public feeders;
    mapping(address => Credit) public credits;
    mapping(bytes32 => bool) public usedStamp;
    mapping(address => mapping(uint256 => uint256)) public seatsOnDay;
    mapping(address => uint256) public owed;
    /// Stamps, new jobs and new seats stop while paused (reveals, canaries, settling and withdrawals go
    /// on, so no deposit is stuck). `zetaphy deploy-useful-work` deploys it paused; governance opens it.
    bool public paused;
    address public guardian;             // may pause (never unpause): a fast brake for governance

    Job[] private _jobs;
    mapping(uint256 => address[]) private _seats;
    mapping(uint256 => mapping(address => bytes32)) public commitments;
    mapping(uint256 => mapping(address => bytes32)) public verdicts;

    event Funded(address indexed from, uint256 amount);
    event Stamped(address indexed worker, bytes32 stamp, uint32 seats, uint64 until);
    event Posted(uint256 indexed id, address indexed poster, bytes32 indexed chain, string target, bytes32 codeHash, uint256 fee, bool subsidized, bool canary);
    event Committed(uint256 indexed id, address indexed worker);
    event Revealed(uint256 indexed id, address indexed worker, bytes32 verdict);
    event CanaryRevealed(uint256 indexed id, bytes32 verdict);
    event Settled(uint256 indexed id, bytes32 result, uint256 agreed, uint256 paidEach);
    event SeatOutcome(uint256 indexed id, address indexed worker, uint8 kind);
    event ParamsSet();
    event FeederSet(address indexed feeder, bool on);
    event Withdrawn(address indexed to, uint256 amount);
    event PausedSet(bool paused);
    event GuardianSet(address guardian);
    event GovernanceSet(address governance);

    error Paused();
    error NotGovernance();
    error NotFeeder();
    error BadParams();
    error BadValue();
    error BadJob();
    error StampTooOld();
    error StampUsed();
    error StampWeak();
    error NoCredit();
    error DayFull();
    error LowScore();
    error Closed();
    error AlreadyIn();
    error NotSeated();
    error TooEarly();
    error BadReveal();
    error Nothing();

    constructor(address governance_, IUWReputation reputation_, IUWIssuance issuance_, Params memory p) {
        governance = governance_;
        reputation = reputation_;
        issuance = issuance_;
        _setParams(p);
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    receive() external payable {
        fund();
    }

    /// Adds to the subsidy reserve (anyone; RewardVault can pay here directly too).
    function fund() public payable {
        reserve += msg.value;
        emit Funded(msg.sender, msg.value);
    }

    // ---------------------------------------------------------------- stamp (PoW)

    /// The 32 bytes the stamp hashes in place of a block hash: keccak(blockhash(height), this).
    function stampSeed(uint256 height) public view returns (bytes32) {
        bytes32 bh = blockhash(height);
        if (bh == bytes32(0)) return bytes32(0);
        return keccak256(abi.encodePacked(bh, address(this)));
    }

    /// sha256(chainId u64 BE || seed || worker || nonce u64 BE): the PoW faucet's layout.
    function stampHash(address worker, uint256 height, uint64 nonce) public view returns (bytes32) {
        return sha256(abi.encodePacked(uint64(block.chainid), stampSeed(height), worker, nonce));
    }

    function stamp(uint256 height, uint64 nonce) external {
        if (paused) revert Paused();
        if (height >= block.number || block.number - height > 256 || stampSeed(height) == bytes32(0)) revert StampTooOld();
        bytes32 h = stampHash(msg.sender, height, nonce);
        if (usedStamp[h]) revert StampUsed();
        if (uint256(h) >> (256 - params.stampBits) != 0) revert StampWeak();
        usedStamp[h] = true;
        Credit storage c = credits[msg.sender];
        if (c.until < block.timestamp) c.seats = 0;
        c.seats += params.stampSeats;
        c.until = uint64(block.timestamp + params.stampLife);
        emit Stamped(msg.sender, h, c.seats, c.until);
    }

    // ---------------------------------------------------------------- posting

    /// Anyone posts a scan job and pays the fee the agreeing seats share.
    function post(bytes32 chain, string calldata target, bytes32 codeHash, uint16 minScore) external payable returns (uint256) {
        if (msg.value == 0) revert BadValue();
        return _post(chain, target, codeHash, minScore, false, bytes32(0));
    }

    /// A feeder posts a job that may be subsidized and may carry a hidden known answer.
    function postFeeder(bytes32 chain, string calldata target, bytes32 codeHash, uint16 minScore, bool subsidized, bytes32 canary)
        external payable returns (uint256)
    {
        if (!feeders[msg.sender]) revert NotFeeder();
        return _post(chain, target, codeHash, minScore, subsidized, canary);
    }

    function _post(bytes32 chain, string calldata target, bytes32 codeHash, uint16 minScore, bool subsidized, bytes32 canary)
        internal returns (uint256 id)
    {
        if (paused) revert Paused();
        if (chain == bytes32(0) || codeHash == bytes32(0) || bytes(target).length == 0 || bytes(target).length > 128) revert BadJob();
        Params memory p = params;
        id = _jobs.length;
        Job storage j = _jobs.push();
        j.poster = msg.sender;
        j.createdAt = uint64(block.timestamp);
        j.commitWindow = p.commitWindow;
        j.revealWindow = p.revealWindow;
        j.seats = p.seats;
        j.quorum = p.quorum;
        j.subsidized = subsidized;
        j.minScore = minScore;
        j.fee = uint128(msg.value);
        j.deposit = p.seatDeposit;
        j.chain = chain;
        j.codeHash = codeHash;
        j.canary = canary;
        j.target = target;
        emit Posted(id, msg.sender, chain, target, codeHash, msg.value, subsidized, canary != bytes32(0));
    }

    // ---------------------------------------------------------------- commit / reveal

    function commitmentOf(bytes32 verdict, address worker, bytes32 salt, uint256 id) public pure returns (bytes32) {
        return keccak256(abi.encode(verdict, worker, salt, id));
    }

    function commit(uint256 id, bytes32 commitment) external payable {
        if (msg.value != _job(id).deposit) revert BadValue();
        _commit(id, commitment);
    }

    /// Several seats in one transaction (one wallet prompt in the browser).
    function commitMany(uint256[] calldata ids, bytes32[] calldata cs) external payable {
        if (ids.length != cs.length) revert BadValue();
        uint256 total;
        for (uint256 i = 0; i < ids.length; i++) {
            total += _job(ids[i]).deposit;
            _commit(ids[i], cs[i]);
        }
        if (msg.value != total) revert BadValue();
    }

    function _commit(uint256 id, bytes32 commitment) internal {
        if (paused) revert Paused();
        Job storage j = _jobs[id];
        if (j.settled || j.taken >= j.seats || block.timestamp >= _closeTime(j)) revert Closed();
        if (commitments[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        if (commitment == bytes32(0)) revert BadValue();
        Credit storage c = credits[msg.sender];
        if (c.seats == 0 || c.until < block.timestamp) revert NoCredit();
        uint256 day = block.timestamp / 1 days;
        if (seatsOnDay[msg.sender][day] >= params.seatsPerDay) revert DayFull();
        if (address(reputation) != address(0)) {
            uint256 score = reputation.scoreOf(msg.sender);
            if (score < j.minScore) revert LowScore();
            if (block.timestamp < j.createdAt + params.priorityWindow && score < params.priorityScore) revert LowScore();
        }
        c.seats--;
        seatsOnDay[msg.sender][day]++;
        commitments[id][msg.sender] = commitment;
        _seats[id].push(msg.sender);
        j.taken++;
        if (j.taken == j.seats) j.closedAt = uint64(block.timestamp);
        emit Committed(id, msg.sender);
    }

    function reveal(uint256 id, bytes32 verdict, bytes32 salt) external {
        _reveal(id, verdict, salt);
    }

    function revealMany(uint256[] calldata ids, bytes32[] calldata vs, bytes32[] calldata salts) external {
        if (ids.length != vs.length || ids.length != salts.length) revert BadValue();
        for (uint256 i = 0; i < ids.length; i++) _reveal(ids[i], vs[i], salts[i]);
    }

    function _reveal(uint256 id, bytes32 verdict, bytes32 salt) internal {
        Job storage j = _job(id);
        if (j.settled) revert Closed();
        if (!_commitsClosed(j)) revert TooEarly();
        if (block.timestamp >= _closeTime(j) + j.revealWindow) revert Closed();
        bytes32 c = commitments[id][msg.sender];
        if (c == bytes32(0)) revert NotSeated();
        if (verdicts[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        if (verdict == bytes32(0) || commitmentOf(verdict, msg.sender, salt, id) != c) revert BadReveal();
        verdicts[id][msg.sender] = verdict;
        j.revealed++;
        emit Revealed(id, msg.sender, verdict);
    }

    /// The feeder reveals a canary's known answer once nobody can commit any more.
    function revealCanary(uint256 id, bytes32 verdict, bytes32 salt) external {
        Job storage j = _job(id);
        if (msg.sender != j.poster) revert NotFeeder();
        if (j.settled || j.canary == bytes32(0) || j.canaryRevealed) revert Closed();
        if (!_commitsClosed(j)) revert TooEarly();
        if (keccak256(abi.encode(verdict, salt, id)) != j.canary) revert BadReveal();
        j.canaryVerdict = verdict;
        j.canaryRevealed = true;
        emit CanaryRevealed(id, verdict);
    }

    // ---------------------------------------------------------------- settle

    /// Anyone, once every seat revealed (and the canary, if any) or the reveal window ended.
    function settle(uint256 id) external {
        Job storage j = _job(id);
        if (j.settled) revert Closed();
        bool allIn = _commitsClosed(j) && j.taken == j.seats && j.revealed == j.taken && (j.canary == bytes32(0) || j.canaryRevealed);
        if (!allIn && block.timestamp < _closeTime(j) + j.revealWindow) revert TooEarly();
        j.settled = true;
        address[] memory seats = _seats[id];
        bytes32 accepted;
        bool canary = j.canaryRevealed;
        if (canary) accepted = j.canaryVerdict;
        else accepted = _majority(id, seats, j.quorum);
        j.result = accepted;

        uint256 agreed;
        for (uint256 i = 0; i < seats.length; i++) if (accepted != bytes32(0) && verdicts[id][seats[i]] == accepted) agreed++;

        // the pot of the agreeing seats: the fee, plus the subsidy of a subsidized job
        uint256 pot;
        if (agreed > 0) {
            pot = j.fee;
            if (j.subsidized) pot += _subsidy(params.subsidy * agreed);
        } else if (j.fee > 0) {
            owed[j.poster] += j.fee; // nobody agreed: the poster gets the fee back
        }
        uint256 each = agreed > 0 ? pot / agreed : 0;
        reserve += agreed > 0 ? pot - each * agreed : 0;
        for (uint256 i = 0; i < seats.length; i++) _judgeSeat(id, seats[i], accepted, canary, j.deposit, each);
        emit Settled(id, accepted, agreed, each);
    }

    function _judgeSeat(uint256 id, address w, bytes32 accepted, bool canary, uint256 deposit, uint256 each) internal {
        bytes32 v = verdicts[id][w];
        uint8 kind;
        if (v == bytes32(0)) {
            kind = MISSED;
            reserve += deposit;
        } else if (accepted == bytes32(0)) {
            owed[w] += deposit; // no accepted answer: nobody is judged
            emit SeatOutcome(id, w, 255);
            return;
        } else if (v == accepted) {
            kind = AGREED;
            owed[w] += deposit + each;
        } else {
            kind = canary ? SLASHED : DISAGREED;
            reserve += deposit;
        }
        emit SeatOutcome(id, w, kind);
        if (address(reputation) != address(0)) {
            try reputation.record(w, kind, bytes32(id)) {} catch {}
        }
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: a}("");
        if (!ok) revert Nothing();
        emit Withdrawn(msg.sender, a);
    }

    // ---------------------------------------------------------------- governance

    function setParams(Params calldata p) external onlyGovernance {
        _setParams(p);
    }

    function setFeeder(address f, bool on) external onlyGovernance {
        feeders[f] = on;
        emit FeederSet(f, on);
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceSet(next);
    }

    /// Governance pauses or unpauses; the guardian may only pause.
    function setPaused(bool p) external {
        if (msg.sender != governance && !(p && msg.sender == guardian && guardian != address(0))) revert NotGovernance();
        paused = p;
        emit PausedSet(p);
    }

    function setGuardian(address g) external onlyGovernance {
        guardian = g;
        emit GuardianSet(g);
    }

    function _setParams(Params memory p) internal {
        if (p.stampBits < 8 || p.stampBits > 48 || p.stampSeats == 0 || p.stampLife == 0 || p.seatsPerDay == 0) revert BadParams();
        if (p.seats < 2 || p.seats > 5 || p.quorum * 2 <= p.seats || p.quorum > p.seats) revert BadParams();
        if (p.commitWindow == 0 || p.revealWindow == 0 || p.priorityWindow >= p.commitWindow) revert BadParams();
        params = p;
        emit ParamsSet();
    }

    // ---------------------------------------------------------------- reads

    function jobCount() external view returns (uint256) {
        return _jobs.length;
    }

    function getJob(uint256 id) external view returns (Job memory) {
        return _job(id);
    }

    function seatsOf(uint256 id) external view returns (address[] memory) {
        return _seats[id];
    }

    /// Up to `max` job ids from `from` on that still take seats now.
    function openJobs(uint256 from, uint256 max) external view returns (uint256[] memory ids) {
        uint256[] memory buf = new uint256[](max);
        uint256 n;
        for (uint256 i = from; i < _jobs.length && n < max; i++) {
            Job storage j = _jobs[i];
            if (!j.settled && j.taken < j.seats && block.timestamp < _closeTime(j)) buf[n++] = i;
        }
        ids = new uint256[](n);
        for (uint256 i = 0; i < n; i++) ids[i] = buf[i];
    }

    /// Phase of a job: 0 taking seats, 1 revealing, 2 ready to settle, 3 settled.
    function phase(uint256 id) external view returns (uint8) {
        Job storage j = _job(id);
        if (j.settled) return 3;
        if (!_commitsClosed(j)) return 0;
        bool allIn = j.taken == j.seats && j.revealed == j.taken && (j.canary == bytes32(0) || j.canaryRevealed);
        if (allIn || block.timestamp >= _closeTime(j) + j.revealWindow) return 2;
        return 1;
    }

    // ---------------------------------------------------------------- internals

    function _job(uint256 id) internal view returns (Job storage) {
        if (id >= _jobs.length) revert BadJob();
        return _jobs[id];
    }

    function _closeTime(Job storage j) internal view returns (uint256) {
        return j.closedAt != 0 ? j.closedAt : uint256(j.createdAt) + j.commitWindow;
    }

    function _commitsClosed(Job storage j) internal view returns (bool) {
        return j.taken == j.seats || block.timestamp >= _closeTime(j);
    }

    function _majority(uint256 id, address[] memory seats, uint8 quorum) internal view returns (bytes32) {
        for (uint256 i = 0; i < seats.length; i++) {
            bytes32 v = verdicts[id][seats[i]];
            if (v == bytes32(0)) continue;
            uint256 n;
            for (uint256 k = 0; k < seats.length; k++) if (verdicts[id][seats[k]] == v) n++;
            if (n >= quorum) return v; // quorum > seats/2: at most one verdict can reach it
        }
        return bytes32(0);
    }

    /// Takes up to `want` from the reserve, then from UsefulIssuance. Returns what it got.
    function _subsidy(uint256 want) internal returns (uint256 got) {
        if (want == 0) return 0;
        got = want < reserve ? want : reserve;
        reserve -= got;
        if (got < want && address(issuance) != address(0)) {
            uint256 before = address(this).balance;
            try issuance.draw(want - got) returns (uint256) {} catch {}
            uint256 arrived = address(this).balance - before;
            // draw() pays through receive(), which counts it into the reserve: move it out again
            reserve -= arrived;
            got += arrived;
        }
    }
}

contracts/VaultTestRecipients.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Test-only recipients for RewardVault.

/// Refuses every payment.
contract RefusingRecipient {
    receive() external payable { revert("no"); }
}

interface IVault {
    function applyShares() external;
    function release() external returns (uint256);
}

/// Tries to re-enter the vault while being paid.
contract ReentrantRecipient {
    IVault public vault;
    uint256 public attempts;
    function setVault(address v) external { vault = IVault(v); }
    receive() external payable {
        attempts += 1;
        try vault.applyShares() {} catch {}
        try vault.release() {} catch {}
    }
}

contracts/VulnerableVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title VulnerableVault: a DELIBERATELY VULNERABLE contract for the bug-hunting prototype
/// @notice TEST ONLY. Never deploy it with anything of value. It is the target of the first
///         BugBounty on the testnet (zetaphy-hub/bounties/vulnerable-vault.json), so that the
///         browser fuzzer, the commit-reveal of findings and the runners' verification can be
///         shown end to end on a bug that really exists.
///
///         The bug: `initialize()` was meant to run once, from the deployment script, but the
///         deployment never calls it and it has no access control. Whoever calls it first
///         becomes the owner and can `sweep` every depositor's money.
contract VulnerableVault {
    address public owner;
    mapping(address => uint256) public balances;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw(uint256 amount) external {
        require(balances[msg.sender] >= amount, "balance");
        balances[msg.sender] -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "send");
    }

    /// BUG (deliberate): anyone may call this while no owner is set.
    function initialize() external {
        require(owner == address(0), "done");
        owner = msg.sender;
    }

    function sweep(address to) external {
        require(msg.sender == owner, "owner");
        (bool ok, ) = to.call{value: address(this).balance}("");
        require(ok, "send");
    }
}

contracts/WebAuthnVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title WebAuthnVerifier: checks a passkey (WebAuthn) assertion on chain
/// @notice Stateless helper shared by LabelRegistry (human labels) and
///         AgentPolicyWallet (emergency freeze by the owner's passkey).
///         The P-256 (secp256r1) signature is checked by the precompile at
///         0x…0100 that cosmos/evm ships (RIP-7212 interface: input
///         hash ‖ r ‖ s ‖ x ‖ y, output 32 bytes = 1 when valid, empty
///         otherwise). ZETAPHY's genesis enables it (active_static_precompiles
///         in zetaphy-chain/setup-node.sh).
///
///         What is checked, as a relying party would (WebAuthn §7.2):
///           - clientDataJSON has "type":"webauthn.get" and
///             "challenge":"<base64url of the 32-byte challenge>";
///           - authenticatorData starts with rpIdHash (sha256 of the site's
///             host name; 0 = any site) and has the user-present flag, and
///             the user-verified flag when requireUV;
///           - the signature is over sha256(authenticatorData ‖ sha256(clientDataJSON)).
///         Not checked: the origin inside clientDataJSON (rpIdHash already
///         binds the site), the signature counter (passkeys that sync keep it
///         at 0), and attestation (who made the authenticator).
contract WebAuthnVerifier {
    address public constant P256 = 0x0000000000000000000000000000000000000100;

    bytes1 private constant FLAG_UP = 0x01;
    bytes1 private constant FLAG_UV = 0x04;

    /// A passkey's answer to navigator.credentials.get(): the authenticator
    /// data, the client data JSON and the signature as (r, s).
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    /// True when `a` is a valid assertion of the passkey (x, y) over `challenge`.
    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool)
    {
        if (!_flagsOk(a.authenticatorData, rpIdHash, requireUV)) return false;
        if (!_contains(a.clientDataJSON, bytes('"type":"webauthn.get"'))) return false;
        if (!_contains(a.clientDataJSON, abi.encodePacked('"challenge":"', base64url(challenge), '"'))) return false;
        bytes32 h = sha256(abi.encodePacked(a.authenticatorData, sha256(a.clientDataJSON)));
        (bool ok, bytes memory ret) = P256.staticcall(abi.encode(h, a.r, a.s, x, y));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _flagsOk(bytes calldata authData, bytes32 rpIdHash, bool requireUV) private pure returns (bool) {
        if (authData.length < 37) return false;
        if (rpIdHash != bytes32(0) && bytes32(authData[0:32]) != rpIdHash) return false;
        bytes1 flags = authData[32];
        if (flags & FLAG_UP == 0) return false;
        if (requireUV && flags & FLAG_UV == 0) return false;
        return true;
    }

    /// base64url without padding of 32 bytes (43 characters), as WebAuthn
    /// writes the challenge in clientDataJSON.
    function base64url(bytes32 data) public pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
        bytes memory out = new bytes(43);
        uint256 v = uint256(data);
        // 32 bytes = 256 bits = 42 full 6-bit groups + 4 bits (padded with 2 zero bits)
        for (uint256 i = 0; i < 42; i++) {
            out[i] = table[(v >> (250 - 6 * i)) & 63];
        }
        out[42] = table[(v & 15) << 2];
        return string(out);
    }

    function _contains(bytes calldata hay, bytes memory needle) private pure returns (bool) {
        uint256 n = needle.length;
        if (hay.length < n) return false;
        bytes32 nh = keccak256(needle);
        for (uint256 i = 0; i + n <= hay.length; i++) {
            if (hay[i] == needle[0] && keccak256(hay[i:i + n]) == nh) return true;
        }
        return false;
    }
}
